/*JAVA implementation of tree using array
numbering starting from 0 to n-1.*/

import java.util.*;
import java.lang.*;
import java.io.*;
class Array_imp {
    static int root = 0;
    static String[] str = new String[10];

/*create root*/

    public void Root(String key)
    {
        str[0] = key;
    }

/*create left son of root*/

    public void set_Left(String key, int root)
    {
        int t = (root * 2) + 1;
        if (str[root] == null) {
            System.out.printf("Can't set child at %d, no parent found\n", t);
        }
        else {
            str[t] = key;
        }
    }

/*create right son of root*/

    public void set_Right(String key, int root)
    {
        int t = (root * 2) + 2;
        if (str[root] == null) {
            System.out.printf("Can't set child at %d, no parent found\n", t);
        }
        else {
            str[t] = key;
        }
    }

/*Print tree*/

    public void print_Tree()
    {
        for (int i = 0; i < 10; i++) {
            if (str[i] != null)
                System.out.print(str[i]);
            else
                System.out.print("-");
        }
    }
}

/*Driver Code*/

class Tree {
    public static void main(String[] args)
    {
        Array_imp obj = new Array_imp();
        obj.Root("A");
        obj.set_Right("C", 0);
        obj.set_Left("D", 1);
        obj.set_Right("E", 1);
        obj.set_Left("F", 2);
        obj.print_Tree();
    }
}

/*Java program to construct an expression tree*/

import java.util.Stack;

/*Java program for expression tree*/

class Node {
    char value;
    Node left, right;
    Node(char item) {
        value = item;
        left = right = null;
    }
}
class ExpressionTree {

/*    A utility function to check if 'c'
    is an operator*/

    boolean isOperator(char c) {
        if (c == '+' || c == '-'
                || c == '*' || c == '/'
                || c == '^') {
            return true;
        }
        return false;
    }

/*    Utility function to do inorder traversal*/

    void inorder(Node t) {
        if (t != null) {
            inorder(t.left);
            System.out.print(t.value + " ");
            inorder(t.right);
        }
    }

/*    Returns root of constructed tree for given
    postfix expression*/

    Node constructTree(char postfix[]) {
        Stack<Node> st = new Stack<Node>();
        Node t, t1, t2;

/*        Traverse through every character of
        input expression*/

        for (int i = 0; i < postfix.length; i++) {

/*            If operand, simply push into stack*/

            if (!isOperator(postfix[i])) {
                t = new Node(postfix[i]);
                st.push(t);

/*operator*/

} else 
            {
                t = new Node(postfix[i]);

/*                Pop two top nodes
                Store top
Remove top*/

t1 = st.pop();      
                t2 = st.pop();

/*                  make them children*/

                t.right = t1;
                t.left = t2;

/*                System.out.println(t1 + "" + t2);
                Add this subexpression to stack*/

                st.push(t);
            }
        }

/*          only element will be root of expression
        tree*/

        t = st.peek();
        st.pop();
        return t;
    }

/*Driver program to test above*/

    public static void main(String args[]) {
        ExpressionTree et = new ExpressionTree();
        String postfix = "ab+ef*g*-";
        char[] charArray = postfix.toCharArray();
        Node root = et.constructTree(charArray);
        System.out.println("infix expression is");
        et.inorder(root);
    }
}

/*Java program to print postorder
traversal from preorder and
inorder traversals*/

import java.util.Arrays;
class GFG
{

/*A utility function to search x in arr[] of size n*/

static int search(int arr[], int x, int n)
{
    for (int i = 0; i < n; i++)
        if (arr[i] == x)
            return i;
    return -1;
}

/*Prints postorder traversal from
given inorder and preorder traversals*/

static void printPostOrder(int in1[],
                    int pre[], int n)
{

/*    The first element in pre[] is
    always root, search it in in[]
    to find left and right subtrees*/

    int root = search(in1, pre[0], n);

/*    If left subtree is not empty,
    print left subtree*/

    if (root != 0)
        printPostOrder(in1, Arrays.copyOfRange(pre, 1, n), root);

/*    If right subtree is not empty,
    print right subtree*/

    if (root != n - 1)
        printPostOrder(Arrays.copyOfRange(in1, root+1, n),
            Arrays.copyOfRange(pre, 1+root, n), n - root - 1);

/*    Print root*/

    System.out.print( pre[0] + " ");
}

/*Driver code*/

public static void main(String args[])
{
    int in1[] = { 4, 2, 5, 1, 3, 6 };
    int pre[] = { 1, 2, 4, 5, 3, 6 };
    int n = in1.length;
    System.out.println("Postorder traversal " );
    printPostOrder(in1, pre, n);
}
}

/*Java program to print Postorder traversal from
given Inorder and Preorder traversals.*/

import java.util.*;
public class PrintPost {
    static int preIndex = 0;
    void printPost(int[] in, int[] pre, int inStrt,
               int inEnd, HashMap<Integer, Integer> hm)
    {
        if (inStrt > inEnd)
            return;

/*        Find index of next item in preorder traversal in
        inorder.*/

        int inIndex = hm.get(pre[preIndex++]);

/*        traverse left tree*/

        printPost(in, pre, inStrt, inIndex - 1, hm);

/*        traverse right tree*/

        printPost(in, pre, inIndex + 1, inEnd, hm);

/*        print root node at the end of traversal*/

        System.out.print(in[inIndex] + " ");
    }
    void printPostMain(int[] in, int[] pre)
    {
        int n = pre.length;
        HashMap<Integer, Integer> hm = new HashMap<Integer, Integer>();
        for (int i=0; i<n; i++)
           hm.put(in[i], i);
        printPost(in, pre, 0, n-1, hm);
    }

/*    Driver code*/

    public static void main(String ars[])
    {
        int in[] = { 4, 2, 5, 1, 3, 6 };
        int pre[] = { 1, 2, 4, 5, 3, 6 };
        PrintPost tree = new PrintPost();
        tree.printPostMain(in, pre);
    }
}

/*        run loop from 1 to length of pre*/
import java.io.*;
class GFG {
    public void getPostOrderBST(int pre[])
    {
        int pivotPoint = 0;

/*        print from pivot length -1 to zero*/

        for (int i = 1; i < pre.length; i++)
        {
            if (pre[0] <= pre[i])
            {
                pivotPoint = i;
                break;
            }
        }

/*        print from end to pivot length*/

        for (int i = pivotPoint - 1; i > 0; i--)
        {
            System.out.print(pre[i] + " ");
        }

/*    Driver Code*/

        for (int i = pre.length - 1; i >= pivotPoint; i--)
        {
            System.out.print(pre[i] + " ");
        }
        System.out.print(pre[0]);
    }

/*Java program to find binary tree with given inorder
traversal*/

import java.util.Vector;

/* Class containing left and right child of current 
 node and key value*/

class Node {
    int data;
    Node left, right;
    public Node(int item) {
        data = item;
        left = null;
        right = null;
    }
}

/* Class to print Level Order Traversal */

class BinaryTree {
    Node root;

/*    A utility function to do preorder traversal of BST*/

    void preOrder(Node node) {
        if (node != null) {
            System.out.print(node.data + " "    );
            preOrder(node.left);
            preOrder(node.right);
        }
    }

/*    Function for constructing all possible trees with
    given inorder traversal stored in an array from
    arr[start] to arr[end]. This function returns a
    vector of trees.*/

    Vector<Node> getTrees(int arr[], int start, int end) {

/*        List to store all possible trees*/

        Vector<Node> trees= new Vector<Node>();

/* if start > end then subtree will be empty so
         returning NULL in the list */

        if (start > end) {
            trees.add(null);
            return trees;
        }

/* Iterating through all values from start to end
         for constructing left and right subtree
         recursively */

        for (int i = start; i <= end; i++) {

/* Constructing left subtree */

            Vector<Node> ltrees = getTrees(arr, start, i - 1);

/* Constructing right subtree */

            Vector<Node> rtrees = getTrees(arr, i + 1, end);

/* Now looping through all left and right subtrees
             and connecting them to ith root below */

            for (int j = 0; j < ltrees.size(); j++) {
                for (int k = 0; k < rtrees.size(); k++) {

/*                    Making arr[i] as root*/

                    Node node = new Node(arr[i]);

/*                    Connecting left subtree*/

                    node.left = ltrees.get(j);

/*                    Connecting right subtree*/

                    node.right = rtrees.get(k);

/*                    Adding this tree to list*/

                    trees.add(node);
                }
            }
        }
        return trees;
    }

/*Driver Program to test above functions*/

public static void main(String args[]) {
        int in[] = {4, 5, 7};
        int n = in.length;
        BinaryTree tree = new BinaryTree();
        Vector<Node> trees = tree.getTrees(in, 0, n - 1);
        System.out.println("Preorder traversal of different "+
                           " binary trees are:");
        for (int i = 0; i < trees.size(); i++) {
            tree.preOrder(trees.get(i));
            System.out.println("");
        }
    }
}

/*Java program to print Zig-Zag traversal
in groups of size 2.*/

import java.util.*;
class GFG
{

/*A Binary Tree Node*/

static class Node
{
    Node left;
    int data;
    Node right;
};

/* Function to print the level order of
given binary tree. Direction of printing
level order traversal of binary tree changes
after every two levels */

static void modifiedLevelOrder(Node node)
{

/*    For null root*/

    if (node == null)
        return;
    if (node.left == null && node.right == null)
    {
        System.out.print(node.data);
        return;
    }

/*    Maintain a queue for normal
    level order traversal*/

    Queue<Node> myQueue = new LinkedList<>();

/* Maintain a stack for
    printing nodes in reverse
    order after they are popped
    out from queue.*/

    Stack<Node> myStack = new Stack<>();
    Node temp = null;

/*    sz is used for storing
    the count of nodes in a level*/

    int sz;

/*    Used for changing the direction
    of level order traversal*/

    int ct = 0;

/*    Used for changing the direction
    of level order traversal*/

    boolean rightToLeft = false;

/*    Push root node to the queue*/

    myQueue.add(node);

/*    Run this while loop till queue got empty*/

    while (!myQueue.isEmpty())
    {
        ct++;
        sz = myQueue.size();

/*        Do a normal level order traversal*/

        for (int i = 0; i < sz; i++)
        {
            temp = myQueue.peek();
            myQueue.remove();

/*For printing nodes from left to right,
            simply print the nodes in the order in which
            they are being popped out from the queue.*/

            if (rightToLeft == false)
                System.out.print(temp.data + " ");

/* For printing nodes from right to left,
            push the nodes to stack instead of printing them.*/

            else
                myStack.push(temp);        
            if (temp.left != null)
                myQueue.add(temp.left);
            if (temp.right != null)
                myQueue.add(temp.right);
        }
        if (rightToLeft == true)
        {

/*            for printing the nodes in order
            from right to left*/

            while (!myStack.isEmpty())
            {
                temp = myStack.peek();
                myStack.pop();
                System.out.print(temp.data + " ");
            }
        }

/*Change the direction of printing
        nodes after every two levels.*/

        if (ct == 2)
        {
            rightToLeft = !rightToLeft;
            ct = 0;
        }
        System.out.print("\n");
    }
}

/*Utility function to create a new tree node*/

static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.left = temp.right = null;
    return temp;
}

/*Driver Code*/

public static void main(String[] args)
{

/*    Let us create binary tree*/

    Node root = newNode(1);
    root.left = newNode(2);
    root.right = newNode(3);
    root.left.left = newNode(4);
    root.left.right = newNode(5);
    root.right.left = newNode(6);
    root.right.right = newNode(7);
    root.left.left.left = newNode(8);
    root.left.left.right = newNode(9);
    root.left.right.left = newNode(3);
    root.left.right.right = newNode(1);
    root.right.left.left = newNode(4);
    root.right.left.right = newNode(2);
    root.right.right.left = newNode(7);
    root.right.right.right = newNode(2);
    root.left.right.left.left = newNode(16);
    root.left.right.left.right = newNode(17);
    root.right.left.right.left = newNode(18);
    root.right.right.left.right = newNode(19);
    modifiedLevelOrder(root);
}
}

/*Java program for the above approach*/

import java.util.*;
class GFG
{
static class Node {
    int data;
    Node left;
    Node right;
    Node(int value)
    { this.data = value; }
};

/*Function to print inorder
traversal of the tree*/

static void inorder(Node temp)
{
    if (temp == null)
        return;
    inorder(temp.left);
    System.out.print(temp.data+" ");
    inorder(temp.right);
}

/*Utility function to track
root to leaf paths*/

static void reverseTreePathUtil(Node root, ArrayList<Node> path,
                         int pathLen, int key)
{

/*    Check if root is null then return*/

    if (root == null)
        return;

/*    Store the node in path array*/

    path.set(pathLen, root);
    pathLen++;

/*    Check if we find the node upto
    which oath needs to be
    reversed*/

    if (root.data == key) {

/*        Current path array contains
        the path which needs
        to be reversed*/

        int i = 0, j = pathLen - 1;

/*        Swap the data of two nodes*/

        while (i < j)
        {
            int temp = path.get(i).data;
            path.get(i).data = path.get(j).data;
            path.get(j).data = temp;
            i++;
            j--;
        }
    }

/*    Check if the node is a
    leaf node then return*/

    if (root.left == null && root.right == null)
        return;

/*    Call utility function for
    left and right subtree
    recursively*/

    reverseTreePathUtil(root.left, path,
                             pathLen, key);
    reverseTreePathUtil(root.right, path,
                              pathLen, key);
}

/*Function to reverse tree path*/

static void reverseTreePath(Node root, int key)
{
    if (root == null)
        return;

/*    Initialize a vector to store paths*/

    ArrayList<Node> path = new ArrayList<Node>();
    for(int i = 0; i < 50; i++)
    {
        path.add(null);
    }
    reverseTreePathUtil(root, path, 0, key);
}

/*Driver Code*/

public static void main(String []args)
{
    Node root = new Node(7);
    root.left = new Node(6);
    root.right = new Node(5);
    root.left.left = new Node(4);
    root.left.right = new Node(3);
    root.right.left = new Node(2);
    root.right.right = new Node(1);

/*     7
         /    \
        6       5
       / \     / \
      4  3     2  1          */

    int key = 4;
    reverseTreePath(root, key);
    inorder(root);
}
}

/*Java program for special order traversal*/

import java.util.*;
class GFG
{

/* A binary tree node has data,
pointer to left child and
a pointer to right child */

static class Node
{
    int data;
    Node left;
    Node right;

/* Helper function that allocates 
    a new node with the given data and
    null left and right pointers. */

    Node(int value)
    {
        data = value;
        left = null;
        right = null;
    }
};

/* Given a perfect binary tree,
print its nodes in specific level order */

static void specific_level_order_traversal(Node root)
{

/*    for level order traversal*/

    Queue <Node> q= new LinkedList<>();

/*    Stack to print reverse*/

    Stack <Vector<Integer>> s = new Stack<Vector<Integer>>();
    q.add(root);
    int sz;
    while(q.size() > 0)
    {

/*        vector to store the level*/

        Vector<Integer> v = new Vector<Integer>();

/*considering size of the level*/

sz = q.size(); 
        for(int i = 0; i < sz; ++i)
        {
            Node temp = q.peek();
            q.remove();

/*            push data of the node of a
            particular level to vector*/

            v.add(temp.data);
            if(temp.left != null)
            q.add(temp.left);
            if(temp.right != null)
                q.add(temp.right);
        }

/*        push vector containing a level in Stack*/

        s.push(v);
    }

/*    print the Stack*/

    while(s.size() > 0)
    {

/*        Finally pop all Nodes from Stack
        and prints them.*/

        Vector <Integer> v = s.peek();
        s.pop();
        for(int i = 0, j = v.size() - 1; i < j; ++i)
            {
                System.out.print(v.get(i) + " " +
                                 v.get(j) + " ");
                j--;
            }
    }

/*    finally print root;*/

    System.out.println(root.data);
}

/*Driver code*/

public static void main(String args[])
{
    Node root = new Node(1);
    root.left = new Node(2);
    root.right = new Node(3);    System.out.println("Specific Level Order traversal" +
                                   " of binary tree is");
    specific_level_order_traversal(root);
}
}

/* Java program to construct tree using inorder
   and preorder traversals */

import java.io.*;
import java.util.*;

/* A binary tree node has data, pointer to left child
and a pointer to right child */

class Node
{
  char data;
  Node left,right;
  Node(char item)
  {
    data = item;
    left = right = null;
  }
}
class Tree
{
  public static Node root;

/*  Store indexes of all items so that we
  we can quickly find later*/

  static HashMap<Character,Integer> mp = new HashMap<>();
  static int preIndex = 0;

/* Recursive function to construct binary of size
    len from Inorder traversal in[] and Preorder traversal
    pre[]. Initial values of inStrt and inEnd should be
    0 and len -1. The function doesn't do any error
    checking for cases where inorder and preorder
    do not form a tree */

  public static Node buildTree(char[] in, char[] pre, int inStrt, int inEnd)
  {
    if(inStrt > inEnd)
    {
      return null;
    }

/* Pick current node from Preorder traversal using preIndex
        and increment preIndex */

    char curr = pre[preIndex++];
    Node tNode;
    tNode = new Node(curr);

/* If this node has no children then return */

    if (inStrt == inEnd)
    {
      return tNode;
    }

/* Else find the index of this node in Inorder traversal */

    int inIndex = mp.get(curr);

/* Using index in Inorder traversal, construct left and
        right subtress */

    tNode.left = buildTree(in, pre, inStrt, inIndex - 1);
    tNode.right = buildTree(in, pre, inIndex + 1, inEnd);
    return tNode;
  }

/*  This function mainly creates an unordered_map, then
  calls buildTree()*/

  public static Node buldTreeWrap(char[] in, char[] pre, int len)
  {
    for(int i = 0; i < len; i++)
    {
      mp.put(in[i], i);
    }
    return buildTree(in, pre, 0, len - 1);
  }

/* This funtcion is here just to test buildTree() */

  static void printInorder(Node node)
  {
    if(node == null)
    {
      return;
    }
    printInorder(node.left);
    System.out.print(node.data + " ");
    printInorder(node.right);
  }

/* Driver code */

  public static void main (String[] args)
  {
    char[] in = {'D', 'B', 'E', 'A', 'F', 'C'};
    char[] pre = {'A', 'B', 'D', 'E', 'C', 'F'};
    int len = in.length;
    Tree.root=buldTreeWrap(in, pre, len);

/* Let us test the built tree by printing
        Insorder traversal */

    System.out.println("Inorder traversal of the constructed tree is");
    printInorder(root);
  }
}

/*Java program to construct a tree using inorder and preorder traversal*/

import java.util.*;
public class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int x) { val = x; }
}
class BinaryTree {
    static Set<TreeNode> set = new HashSet<>();
    static Stack<TreeNode> stack = new Stack<>();

/*    Function to build tree using given traversal*/

    public TreeNode buildTree(int[] preorder, int[] inorder)
    {
        TreeNode root = null;
        for (int pre = 0, in = 0; pre < preorder.length;) {
            TreeNode node = null;
            do {
                node = new TreeNode(preorder[pre]);
                if (root == null) {
                    root = node;
                }
                if (!stack.isEmpty()) {
                    if (set.contains(stack.peek())) {
                        set.remove(stack.peek());
                        stack.pop().right = node;
                    }
                    else {
                        stack.peek().left = node;
                    }
                }
                stack.push(node);
            } while (preorder[pre++] != inorder[in] && pre < preorder.length);
            node = null;
            while (!stack.isEmpty() && in < inorder.length &&
                    stack.peek().val == inorder[in]) {
                node = stack.pop();
                in++;
            }
            if (node != null) {
                set.add(node);
                stack.push(node);
            }
        }
        return root;
    }

/*    Function to print tree in Inorder*/

    void printInorder(TreeNode node)
    {
        if (node == null)
            return;

/* first recur on left child */

        printInorder(node.left);

/* then print the data of node */

        System.out.print(node.val + " ");

/* now recur on right child */

        printInorder(node.right);
    }

/*    driver program to test above functions*/

    public static void main(String args[])
    {
        BinaryTree tree = new BinaryTree();
        int in[] = new int[] { 9, 8, 4, 2, 10, 5, 10, 1, 6, 3, 13, 12, 7 };
        int pre[] = new int[] { 1, 2, 4, 8, 9, 5, 10, 10, 3, 6, 7, 12, 13 };
        int len = in.length;
        TreeNode root = tree.buildTree(pre, in);
        tree.printInorder(root);
    }
}

/*Java program to construct a binary tree from parent array*/

/*A binary tree node*/

class Node 
{
    int key;
    Node left, right;
    public Node(int key) 
    {
        this.key = key;
        left = right = null;
    }
}
class BinaryTree 
{
    Node root;

/*    Creates a node with key as 'i'.  If i is root, then it changes
    root.  If parent of i is not created, then it creates parent first*/

    void createNode(int parent[], int i, Node created[]) 
    {

/*        If this node is already created*/

        if (created[i] != null)
            return;

/*        Create a new node and set created[i]*/

        created[i] = new Node(i);

/*        If 'i' is root, change root pointer and return*/

        if (parent[i] == -1) 
        {
            root = created[i];
            return;
        }

/*        If parent is not created, then create parent first*/

        if (created[parent[i]] == null)
            createNode(parent, parent[i], created);

/*        Find parent pointer*/

        Node p = created[parent[i]];

/*        If this is first child of parent*/

        if (p.left == null)
            p.left = created[i];

/*If second child*/

else 
            p.right = created[i];
    }

/* Creates tree from parent[0..n-1] and returns root of 
       the created tree */

    Node createTree(int parent[], int n) 
    {

/*        Create an array created[] to keep track
        of created nodes, initialize all entries
        as NULL*/

        Node[] created = new Node[n];
        for (int i = 0; i < n; i++) 
            created[i] = null;
        for (int i = 0; i < n; i++)
            createNode(parent, i, created);
        return root;
    }

/*    For adding new line in a program*/

    void newLine() 
    {
        System.out.println("");
    }

/*    Utility function to do inorder traversal*/

    void inorder(Node node) 
    {
        if (node != null) 
        {
            inorder(node.left);
            System.out.print(node.key + " ");
            inorder(node.right);
        }
    }

/*    Driver method*/

    public static void main(String[] args) 
    {
        BinaryTree tree = new BinaryTree();
