/* Java program to contree using inorder and
postorder traversals */

import java.util.*;
class GFG
{

/* A binary tree node has data, pointer to left
child and a pointer to right child */

static class Node
{
    int data;
    Node left, right;
};

/*Utility function to create a new node*/

/* Recursive function to conbinary of size n
from Inorder traversal in[] and Postorder traversal
post[]. Initial values of inStrt and inEnd should
be 0 and n -1. The function doesn't do any error
checking for cases where inorder and postorder
do not form a tree */

static Node buildUtil(int in[], int post[],
                      int inStrt, int inEnd)
{

/*    Base case*/

    if (inStrt > inEnd)
        return null;

/* Pick current node from Postorder traversal 
    using postIndex and decrement postIndex */

    int curr = post[index];
    Node node = newNode(curr);
    (index)--;

/* If this node has no children then return */

    if (inStrt == inEnd)
        return node;

/* Else find the index of this node in Inorder
    traversal */

    int iIndex = mp.get(curr);

/* Using index in Inorder traversal, con
    left and right subtress */

    node.right = buildUtil(in, post, iIndex + 1,
                            inEnd);
    node.left = buildUtil(in, post, inStrt,
                           iIndex - 1);
    return node;
}
static  HashMap<Integer,Integer> mp = new HashMap<Integer,Integer>();
static int index;

/*This function mainly creates an unordered_map, then
calls buildTreeUtil()*/

static Node buildTree(int in[], int post[], int len)
{

/*    Store indexes of all items so that we
    we can quickly find later*/

    for (int i = 0; i < len; i++)
        mp.put(in[i],  i);

/*Index in postorder*/

index = len - 1; 
    return buildUtil(in, post, 0, len - 1 );
}

/* Helper function that allocates a new node */

static Node newNode(int data)
{
    Node node = new Node();
    node.data = data;
    node.left = node.right = null;
    return (node);
}

/* This funtcion is here just to test */

static void preOrder(Node node)
{
    if (node == null)
        return;
    System.out.printf("%d ", node.data);
    preOrder(node.left);
    preOrder(node.right);
}

/*Driver code*/

public static void main(String[] args)
{
    int in[] = { 4, 8, 2, 5, 1, 6, 3, 7 };
    int post[] = { 8, 4, 5, 2, 6, 7, 3, 1 };
    int n = in.length;
    Node root = buildTree(in, post, n);
    System.out.print("Preorder of the constructed tree : \n");
    preOrder(root);
}
}

/*Java program for above approach*/

import java.io.*;
import java.util.*;
class GFG {

/*    Node class*/

    static class Node {
        int data;
        Node left, right;

/*        Constructor*/

        Node(int x)
        {
            data = x;
            left = right = null;
        }
    }

/*    Tree building function*/

    static Node buildTree(int in[], int post[], int n)
    {

/*        Create Stack of type Node**/

        Stack<Node> st = new Stack<>();

/*        Create HashSet of type Node**/

        HashSet<Node> s = new HashSet<>();

/*        Initialise postIndex with n - 1*/

        int postIndex = n - 1;

/*        Initialise root with null*/

        Node root = null;
        for (int p = n - 1, i = n - 1; p >= 0 {

/*            Initialise node with NULL*/

            Node node = null;

/*            Run do-while loop*/

            do {

/*                Initialise node with
                new Node(post[p]);*/

                node = new Node(post[p]);

/*                Check is root is
                equal to NULL*/

                if (root == null) {
                    root = node;
                }

/*                If size of set
                is greater than 0*/

                if (st.size() > 0) {

/*                    If st.peek() is present in the
                    set s*/

                    if (s.contains(st.peek())) {
                        s.remove(st.peek());
                        st.peek().left = node;
                        st.pop();
                    }
                    else {
                        st.peek().right = node;
                    }
                }
                st.push(node);
            } while (post[p--] != in[i] && p >= 0);
            node = null;

/*            If the stack is not empty and
            st.top().data is equal to in[i]*/

            while (st.size() > 0 && i >= 0
                   && st.peek().data == in[i]) {
                node = st.peek();

/*                Pop elements from stack*/

                st.pop();
                i--;
            }

/*            If node not equal to NULL*/

            if (node != null) {
                s.add(node);
                st.push(node);
            }
        }

/*        Return root*/

        return root;
    }

/*    For print preOrder Traversal*/

    static void preOrder(Node node)
    {
        if (node == null)
            return;
        System.out.printf("%d ", node.data);
        preOrder(node.left);
        preOrder(node.right);
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        int in[] = { 4, 8, 2, 5, 1, 6, 3, 7 };
        int post[] = { 8, 4, 5, 2, 6, 7, 3, 1 };
        int n = in.length;

/*        Function Call*/

        Node root = buildTree(in, post, n);
        System.out.print(
            "Preorder of the constructed tree : \n");

/*        Function Call for preOrder*/

        preOrder(root);
    }
}

/*Java program to construct tree from given Prufer Code*/

class GFG {

/*    Prints edges of tree represented by give Prufer code*/

    static void printTreeEdges(int prufer[], int m)
    {
        int vertices = m + 2;
        int vertex_set[] = new int[vertices];

/*        Initialize the array of vertices*/

        for (int i = 0; i < vertices; i++)
            vertex_set[i] = 0;

/*        Number of occurrences of vertex in code*/

        for (int i = 0; i < vertices - 2; i++)
            vertex_set[prufer[i] - 1] += 1;
        System.out.print("\nThe edge set E(G) is :\n");

/*        Find the smallest label not present in
        prufer[].*/

        int j = 0;
        for (int i = 0; i < vertices - 2; i++) {
            for (j = 0; j < vertices; j++) {

/*                If j+1 is not present in prufer set*/

                if (vertex_set[j] == 0) {

/*                    Remove from Prufer set and print
                    pair.*/

                    vertex_set[j] = -1;
                    System.out.print("(" + (j + 1) + ", "
                                     + prufer[i] + ") ");
                    vertex_set[prufer[i] - 1]--;
                    break;
                }
            }
        }
        j = 0;

/*        For the last element*/

        for (int i = 0; i < vertices; i++) {
            if (vertex_set[i] == 0 && j == 0) {
                System.out.print("(" + (i + 1) + ", ");
                j++;
            }
            else if (vertex_set[i] == 0 && j == 1)
                System.out.print((i + 1) + ")\n");
        }
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int prufer[] = { 4, 1, 3, 4 };
        int n = prufer.length;
        printTreeEdges(prufer, n);
    }
}

/*Java program to build full k-ary tree from
its preorder traversal and to print the
postorder traversal of the tree.*/

import java.util.*;
class GFG
{

/*Structure of a node of an n-ary tree*/

static class Node 
{
    int key;
    Vector<Node> child;
};

/*Utility function to create a new tree 
node with k children*/

static Node newNode(int value)
{
    Node nNode = new Node();
    nNode.key = value;
    nNode.child= new Vector<Node>();
    return nNode;
}
static int ind;

/*Function to build full k-ary tree*/

static Node BuildKaryTree(int A[], int n, 
                          int k, int h)
{

/*    For null tree*/

    if (n <= 0)
        return null;
    Node nNode = newNode(A[ind]);
    if (nNode == null)
    {
        System.out.println("Memory error" );
        return null;
    }

/*    For adding k children to a node*/

    for (int i = 0; i < k; i++)
    {

/*        Check if ind is in range of array
        Check if height of the tree is greater than 1*/

        if (ind < n - 1 && h > 1) 
        {
            ind++;

/*            Recursively add each child*/

            nNode.child.add(BuildKaryTree(A, n, k, h - 1));
        } 
        else
        {
            nNode.child.add(null);
        }
    }
    return nNode;
}

/*Function to find the height of the tree*/

static Node BuildKaryTree_1(int[] A, int n, int k, int in)
{
    int height = (int)Math.ceil(Math.log((double)n * (k - 1) + 1) / 
                                Math.log((double)k));
    ind = in;
    return BuildKaryTree(A, n, k, height);
}

/*Function to print postorder traversal of the tree*/

static void postord(Node root, int k)
{
    if (root == null)
        return;
    for (int i = 0; i < k; i++)
        postord(root.child.get(i), k);
    System.out.print(root.key + " ");
}

/*Driver Code*/

public static void main(String args[])
{
    int ind = 0;
    int k = 3, n = 10;
    int preorder[] = { 1, 2, 5, 6, 7, 3, 8, 9, 10, 4 };
    Node root = BuildKaryTree_1(preorder, n, k, ind);
    System.out.println("Postorder traversal of " + 
                       "constructed full k-ary tree is: ");
    postord(root, k);
    System.out.println();
}
}

/* Java program to cona binary tree from
   the given String */

import java.util.*;
class GFG
{

/* A binary tree node has data, pointer to left
   child and a pointer to right child */

  static class Node
  {
    int data;
    Node left, right;
  };

/* Helper function that allocates a new node */

  static Node newNode(int data)
  {
    Node node = new Node();
    node.data = data;
    node.left = node.right = null;
    return (node);
  }

/* This funtcion is here just to test  */

  static void preOrder(Node node)
  {
    if (node == null)
      return;
    System.out.printf("%d ", node.data);
    preOrder(node.left);
    preOrder(node.right);
  }

/*  function to return the index of close parenthesis*/

  static int findIndex(String str, int si, int ei)
  {
    if (si > ei)
      return -1;

/*    Inbuilt stack*/

    Stack<Character> s = new Stack<>();
    for (int i = si; i <= ei; i++)
    {

/*      if open parenthesis, push it*/

      if (str.charAt(i) == '(')
        s.add(str.charAt(i));

/*      if close parenthesis*/

      else if (str.charAt(i) == ')')
      {
        if (s.peek() == '(')
        {
          s.pop();

/*          if stack is empty, this is
          the required index*/

          if (s.isEmpty())
            return i;
        }
      }
    }

/*    if not found return -1*/

    return -1;
  }

/*  function to contree from String*/

  static Node treeFromString(String str, int si, int ei)
  {

/*    Base case*/

    if (si > ei)
      return null;

/*    new root*/

    Node root = newNode(str.charAt(si) - '0');
    int index = -1;

/*    if next char is '(' find the index of
    its complement ')'*/

    if (si + 1 <= ei && str.charAt(si+1) == '(')
      index = findIndex(str, si + 1, ei);

/*    if index found*/

    if (index != -1)
    {

/*      call for left subtree*/

      root.left = treeFromString(str, si + 2, index - 1);

/*      call for right subtree*/

      root.right
        = treeFromString(str, index + 2, ei - 1);
    }
    return root;
  }

/*  Driver Code*/

  public static void main(String[] args)
  {
    String str = "4(2(3)(1))(6(5))";
    Node root = treeFromString(str, 0, str.length() - 1);
    preOrder(root);
  }
}

/*Java program to find maximum number to be removed
to convert a tree into forest containing trees of
even number of nodes*/

import java.util.*;
class GFG
{
    static int N = 12,ans;
    static Vector<Vector<Integer>> tree=new Vector<Vector<Integer>>();

/*    Return the number of nodes of subtree having
    node as a root.*/

    static int dfs( int visit[], int node)
    {
        int num = 0, temp = 0;

/*        Mark node as visited.*/

        visit[node] = 1;

/*        Traverse the adjacency list to find non-
        visited node.*/

        for (int i = 0; i < tree.get(node).size(); i++)
        {
            if (visit[tree.get(node).get(i)] == 0)
            {

/*                Finding number of nodes of the subtree
                of a subtree.*/

                temp = dfs( visit, tree.get(node).get(i));

/*                If nodes are even, increment number of
                edges to removed.
                Else leave the node as child of subtree.*/

                if(temp%2!=0)
                num += temp;
                else
                ans++;
            }
        }
        return num+1;
    }

/*    Return the maximum number of edge to remove
    to make forest.*/

    static int minEdge( int n)
    {
        int visit[] = new int[n+2];
        ans = 0;
        dfs( visit, 1);
        return ans;
    }

/*    Driven Program*/

    public static void main(String args[])
    {
        int n = 10;
        for(int i = 0; i < n + 2;i++)
        tree.add(new Vector<Integer>());
        tree.get(1).add(3);
        tree.get(3).add(1);
        tree.get(1).add(6);
        tree.get(6).add(1);
        tree.get(1).add(2);
        tree.get(2).add(1);
        tree.get(3).add(4);
        tree.get(4).add(3);
        tree.get(6).add(8);
        tree.get(8).add(6);
        tree.get(2).add(7);
        tree.get(7).add(2);
        tree.get(2).add(5);
        tree.get(5).add(2);
        tree.get(4).add(9);
        tree.get(9).add(4);
        tree.get(4).add(10);
        tree.get(10).add(4);
        System.out.println( minEdge( n));
    }
}

/* Java program to check if all three given
traversals are of the same tree */

import java.util.*;
class GfG {
    static int preIndex = 0;

/*A Binary Tree Node*/

static class Node
{
    int data;
    Node left, right;
}

/*Utility function to create a new tree node*/

static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.left = null;
    temp.right = null;
    return temp;
}

/* Function to find index of value in arr[start...end]
The function assumes that value is present in in[] */

static int search(int arr[], int strt, int end, int value)
{
    for (int i = strt; i <= end; i++)
    {
        if(arr[i] == value)
            return i;
    }
    return -1;
}

/* Recursive function to construct binary tree
of size len from Inorder traversal in[] and
Preorder traversal pre[]. Initial values
of inStrt and inEnd should be 0 and len -1.
The function doesn't do any error checking for
cases where inorder and preorder do not form a
tree */

static Node buildTree(int in[], int pre[], int inStrt, int inEnd)
{
    if(inStrt > inEnd)
        return null;

/* Pick current node from Preorder traversal
    using preIndex and increment preIndex */

    Node tNode = newNode(pre[preIndex++]);

/* If this node has no children then return */

    if (inStrt == inEnd)
        return tNode;

/* Else find the index of this node in
    Inorder traversal */

    int inIndex = search(in, inStrt, inEnd, tNode.data);

/* Using index in Inorder traversal,
    construct left and right subtress */

    tNode.left = buildTree(in, pre, inStrt, inIndex-1);
    tNode.right = buildTree(in, pre, inIndex+1, inEnd);
    return tNode;
}

/* function to compare Postorder traversal
on constructed tree and given Postorder */

static int checkPostorder(Node node, int postOrder[], int index)
{
    if (node == null)
        return index;

/* first recur on left child */

    index = checkPostorder(node.left,postOrder,index);

/* now recur on right child */

    index = checkPostorder(node.right,postOrder,index);

/* Compare if data at current index in
    both Postorder traversals are same */

    if (node.data == postOrder[index])
        index++;
    else
        return -1;
    return index;
}

/*Driver program to test above functions*/

public static void main(String[] args)
{
    int inOrder[] = {4, 2, 5, 1, 3};
    int preOrder[] = {1, 2, 4, 5, 3};
    int postOrder[] = {4, 5, 2, 3, 1};
    int len = inOrder.length;

/*    build tree from given
    Inorder and Preorder traversals*/

    Node root = buildTree(inOrder, preOrder, 0, len - 1);

/*    compare postorder traversal on constructed
    tree with given Postorder traversal*/

    int index = checkPostorder(root,postOrder,0);

/*    If both postorder traversals are same*/

    if (index == len)
        System.out.println("Yes");
    else
        System.out.println("No");
}
}

/*Java program to check if a given tree is
Binary Heap or not*/

import java.io.*;
import java.util.*;
public class detheap
{

/*    Returns true if given level order traversal
    is Min Heap.*/

    static boolean isMinHeap(int []level)
    {
        int n = level.length - 1;

/*        First non leaf node is at index (n/2-1).
        Check whether each parent is greater than child*/

        for (int i=(n/2-1) ; i>=0 ; i--)
        {

/*            Left child will be at index 2*i+1
            Right child will be at index 2*i+2*/

            if (level[i] > level[2 * i + 1])
                return false;
            if (2*i + 2 < n)
            {

/*                If parent is greater than right child*/

                if (level[i] > level[2 * i + 2])
                   return false;
            }
        }
        return true;
    }

/*    Driver code*/

    public static void main(String[] args) 
                              throws IOException
    {
        int[] level = new int[]{10, 15, 14, 25, 30};
        if  (isMinHeap(level))
            System.out.println("True");
        else
            System.out.println("False");
    }
}

/*Java program to print all root to leaf
paths with there relative position*/

import java.util.ArrayList;
class Graph{
static final int MAX_PATH_SIZE = 1000;

/*tree structure*/

static class Node
{
    char data;
    Node left, right;
};

/*Function create new node*/

static Node newNode(char data)
{
    Node temp = new Node();
    temp.data = data;
    temp.left = temp.right = null;
    return temp;
}

/*Store path information*/

static class PATH
{
    int Hd;
    char key;
    public PATH(int Hd, char key)
    {
        this.Hd = Hd;
        this.key = key;
    }
    public PATH()
    {}
};

/*Prints given root to leaf path with underscores*/

static void printPath(ArrayList<PATH> path, int size)
{

/*    Find the minimum horizontal distance value
    in current root to leaf path*/

    int minimum_Hd = Integer.MAX_VALUE;
    PATH p;

/*    Find minimum horizontal distance*/

    for(int it = 0; it < size; it++)
    {
        p = path.get(it);
        minimum_Hd = Math.min(minimum_Hd, p.Hd);
    }

/*    Print the root to leaf path with "_"
    that indicate the related position*/

    for(int it = 0; it < size; it++)
    {

/*        Current tree node*/

        p = path.get(it);
        int noOfUnderScores = Math.abs(
            p.Hd - minimum_Hd);

/*        Print underscore*/

        for(int i = 0; i < noOfUnderScores; i++)
            System.out.print("_");

/*        Print current key*/

        System.out.println(p.key);
    }
    System.out.println("==============================");
}

/*A utility function print all path from root to leaf
working of this function is similar to function of
"Print_vertical_order" : Print paths of binary tree
in vertical order
www.geeksforgeeks.org/print-binary-tree-vertical-order-set-2/
https:*/

static void printAllPathsUtil(Node root,
                              ArrayList<PATH> AllPath,
                              int HD, int order)
{

/*    Base case*/

    if (root == null)
        return;

/*    Leaf node*/

    if (root.left == null && root.right == null)
    {

/*        Add leaf node and then print path*/

        AllPath.set(order, new PATH(HD, root.data));
        printPath(AllPath, order + 1);
        return;
    }

/*    Store current path information*/

    AllPath.set(order, new PATH(HD, root.data));

/*Call left sub_tree*/

    printAllPathsUtil(root.left, AllPath,
                      HD - 1, order + 1);

/*    Call left sub_tree*/

    printAllPathsUtil(root.right, AllPath,
                      HD + 1, order + 1);
}
static void printAllPaths(Node root)
{

/*    Base case*/

    if (root == null)
        return;
    ArrayList<PATH> Allpaths = new ArrayList<>();
    for(int i = 0; i < MAX_PATH_SIZE; i++)
    {
        Allpaths.add(new PATH());
    }
    printAllPathsUtil(root, Allpaths, 0, 0);
}

/*Driver code*/

public static void main(String[] args)
{
    Node root = newNode('A');
    root.left = newNode('B');
    root.right = newNode('C');
    root.left.left = newNode('D');
    root.left.right = newNode('E');
    root.right.left = newNode('F');
    root.right.right = newNode('G');
    printAllPaths(root);
}
}

/*Java program to implement
the above approach*/

import java.util.*;
class GFG
{

/*function to find sum of
all of the nodes of given
perfect binary tree*/

static int sumNodes(int l)
{

/*    no of leaf nodes*/

    int leafNodeCount = (int)Math.pow(2, l - 1);

/*    list of vector to store
    nodes of all of the levels*/

    Vector<Vector
          <Integer>> vec = new Vector<Vector
                                     <Integer>>();

/*    initialize*/

    for (int i = 1; i <= l; i++)
    vec.add(new Vector<Integer>());

/*    store the nodes of last level
    i.e., the leaf nodes*/

    for (int i = 1;
             i <= leafNodeCount; i++)
        vec.get(l - 1).add(i);

/*    store nodes of rest of
    the level by moving in
    bottom-up manner*/

    for (int i = l - 2; i >= 0; i--)
    {
        int k = 0;

/*        loop to calculate values
        of parent nodes from the
        children nodes of lower level*/

        while (k < vec.get(i + 1).size() - 1)
        {

/*            store the value of parent
            node as sum of children nodes*/

            vec.get(i).add(vec.get(i + 1).get(k) +
                           vec.get(i + 1).get(k + 1));
            k += 2;
        }
    }
    int sum = 0;

/*    traverse the list of vector
    and calculate the sum*/

    for (int i = 0; i < l; i++)
    {
        for (int j = 0;
                 j < vec.get(i).size(); j++)
            sum += vec.get(i).get(j);
    }
    return sum;
}

/*Driver Code*/

public static void main(String args[])
{
    int l = 3;
    System.out.println(sumNodes(l));
}
}

/*Java program to print all paths with sum k. */

import java.util.*;
class GFG
{

/*utility function to print contents of 
a vector from index i to it's end */

static void printVector( Vector<Integer> v, int i) 
{ 
    for (int j = i; j < v.size(); j++) 
        System.out.print( v.get(j) + " "); 
        System.out.println(); 
}

/*binary tree node */

static class Node 
{ 
    int data; 
    Node left,right; 
    Node(int x) 
    { 
        data = x; 
        left = right = null; 
    } 
}; 
static Vector<Integer> path = new Vector<Integer>();

/*This function prints all paths that have sum k */

static void printKPathUtil(Node root, int k) 
{

/*    empty node */

    if (root == null) 
        return;

/*    add current node to the path */

    path.add(root.data);

/*    check if there's any k sum path 
    in the left sub-tree. */

    printKPathUtil(root.left, k);

/*    check if there's any k sum path 
    in the right sub-tree. */

    printKPathUtil(root.right, k);

/*    check if there's any k sum path that 
    terminates at this node 
    Traverse the entire path as 
    there can be negative elements too */

    int f = 0; 
    for (int j = path.size() - 1; j >= 0; j--) 
    { 
        f += path.get(j);

/*        If path sum is k, print the path */

        if (f == k) 
            printVector(path, j); 
    }

/*    Remove the current element from the path */

    path.remove(path.size() - 1); 
}

/*A wrapper over printKPathUtil() */

static void printKPath(Node root, int k) 
{ 
    path = new Vector<Integer>();
    printKPathUtil(root, k); 
}

/*Driver code */

public static void main(String args[])
{ 
    Node root = new Node(1); 
    root.left = new Node(3); 
    root.left.left = new Node(2); 
    root.left.right = new Node(1); 
    root.left.right.left = new Node(1); 
    root.right = new Node(-1); 
    root.right.left = new Node(4); 
    root.right.left.left = new Node(1); 
    root.right.left.right = new Node(2); 
    root.right.right = new Node(5); 
    root.right.right.right = new Node(2); 
    int k = 5; 
    printKPath(root, k); 
}
}

/*Java implementation to find maximum spiral sum*/

import java.util.ArrayList;
import java.util.Stack;
public class MaxSpiralSum {

/* A binary tree node has data, pointer to left child 
   and a pointer to right child */

class Node 
{ 
    int data ; 
    Node  left,  right ; 
    Node(int data)
    {
        this.data=data;
        left=right=null;
    }
};

/*    function to find the maximum sum contiguous subarray. 
    implements kadane's algorithm */

    static int maxSum(ArrayList<Integer> arr) 
    {

/*        to store the maximum value that is ending 
        up to the current index */

        int max_ending_here = Integer.MIN_VALUE;

/*        to store the maximum value encountered so far */

        int max_so_far = Integer.MIN_VALUE;

/*        traverse the array elements */

        for (int i = 0; i < arr.size(); i++) 
        {

/*            if max_ending_here < 0, then it could 
            not possibly contribute to the maximum  
            sum further */

            if (max_ending_here < 0) 
                max_ending_here = arr.get(i);

/*            else add the value arr[i] to max_ending_here */

            else
                max_ending_here +=arr.get(i);

/*            update max_so_far */

            max_so_far = Math.max(max_so_far, max_ending_here); 
        }

/*        required maxium sum contiguous subarray value */

        return max_so_far; 
    }

/*    Function to find maximum spiral sum */

    public static int maxSpiralSum(Node root) 
    {

/*        if tree is empty */

        if (root == null) 
            return 0;

/*        Create two stacks to store alternate levels 
For levels from right to left */

Stack<Node> s1=new Stack<>();

/*For levels from left to right */

Stack<Node> s2=new Stack<>();

/*        ArrayList to store spiral order traversal 
        of the binary tree */

        ArrayList<Integer> arr=new ArrayList<>();

/*        Push first level to first stack 's1' */

        s1.push(root);

/*        traversing tree in spiral form until  
        there are elements in any one of the  
        stacks */

        while (!s1.isEmpty() || !s2.isEmpty()) 
        {

/*            traverse current level from s1 and 
            push nodes of next level to s2 */

            while (!s1.isEmpty()) 
            { 
                Node temp = s1.pop();

/*                push temp-data to 'arr' */

                arr.add(temp.data);

/*                Note that right is pushed before left */

                if (temp.right!=null) 
                    s2.push(temp.right); 
                if (temp.left!=null) 
                    s2.push(temp.left); 
            }

/*            traverse current level from s2 and 
            push nodes of next level to s1 */

            while (!s2.isEmpty()) 
            { 
                Node temp = s2.pop();

/*                push temp-data to 'arr' */

                arr.add(temp.data);

/*                Note that left is pushed before right */

                if (temp.left!=null) 
                    s1.push(temp.left); 
                if (temp.right!=null) 
                    s1.push(temp.right); 
            } 
        }

/*        required maximum spiral sum */

        return maxSum(arr); 
    }

/*Driver program to test above*/

    public static void main(String args[]) {
        Node root = new Node(-2); 
        root.left = new Node(-3); 
        root.right = new Node(4); 
        root.left.left = new Node(5); 
        root.left.right = new Node(1); 
        root.right.left = new Node(-2); 
        root.right.right = new Node(-1); 
        root.left.left.left = new Node(-3); 
        root.right.right.right = new Node(2); 
        System.out.print("Maximum Spiral Sum = "+maxSpiralSum(root));
    }
}

/*Find root of tree where children
sum for every node id is given.*/

class GFG
{
    static class pair
    {
        int first, second;
        public pair(int first, int second)
        {
            this.first = first;
            this.second = second;
        }
    }
    static int findRoot(pair arr[], int n)
    {

/*        Every node appears once as an id, and
        every node except for the root appears
        once in a sum. So if we subtract all
        the sums from all the ids, we're left
        with the root id.*/

        int root = 0;
        for (int i = 0; i < n; i++)
        {
            root += (arr[i].first - arr[i].second);
        }
        return root;
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        pair arr[] = {new pair(1, 5), new pair(2, 0),
                    new pair(3, 0), new pair(4, 0),
                    new pair(5, 5), new pair(6, 5)};
        int n = arr.length;
        System.out.printf("%d\n", findRoot(arr, n));
    }
}

/*JAVA code to find LCA of given
two nodes in a tree*/

import java.util.*;
public class GFG
{
  static int maxn = 100005;
  static  int left(int i)
  {
    return  (2 * i + 1);
  }
  static  int right(int i) { return 2 * i + 2;}

/*  the graph*/

  static Vector<Integer> []g = new Vector[maxn];

/*  level of each node*/

  static int []level = new int[maxn];
  static Vector<Integer> e = new Vector<>();
  static Vector<Integer> l= new Vector<>();
  static int []h = new int[maxn];

/*  the segment tree*/

  static int []st = new int[5 * maxn];

/*  adding edges to the graph(tree)*/

  static void add_edge(int u, int v)
  {
    g[u].add(v);
    g[v].add(u);
  }

/*  assigning level to nodes*/

  static void levelling(int src)
  {
    for (int i = 0; i < (g[src].size()); i++)
    {
      int des = g[src].get(i);
      if (level[des] != 0)
      {
        level[des] = level[src] + 1;
        leveling(des);
      }
    }
  }
  static boolean []visited = new boolean[maxn];

/*  storing the dfs traversal
  in the array e*/

  static void dfs(int src)
  {
    e.add(src);
    visited[src] = true;
    for (int i = 0; i < (g[src]).size(); i++)
    {
      int des = g[src].get(i);
      if (!visited[des])
      {
        dfs(des);
        e.add(src);
      }
    }
  }

/*  making the array l*/

  static void setting_l(int n)
  {
    for (int i = 0; i < e.size(); i++)
      l.add(level[e.get(i)]);
  }

/*  making the array h*/

  static void setting_h(int n)
  {
    for (int i = 0; i <= n; i++)
      h[i] = -1;
    for (int i = 0; i < e.size(); i++)
    {

/*      if is already stored*/

      if (h[e.get(i)] == -1)
        h[e.get(i)] = i;
    }
  }

/*  Range minimum query to return the index
  of minimum in the subarray L[qs:qe]*/

  static int RMQ(int ss, int se, int qs, int qe, int i)
  {
    if (ss > se)
      return -1;

/*    out of range*/

    if (se < qs || qe < ss)
      return -1;

/*    in the range*/

    if (qs <= ss && se <= qe)
      return st[i];
    int mid = (ss + se)/2 ;
    int st = RMQ(ss, mid, qs, qe, left(i));
    int en = RMQ(mid + 1, se, qs, qe, right(i));
    if (st != -1 && en != -1)
    {
      if (l.get(st) < l.get(en))
        return st;
      return en;
    } else if (st != -1)
      return st-2;
    else if (en != -1)
      return en-1;
    return 0;
  }

/*  constructs the segment tree*/

  static void SegmentTreeConstruction(int ss,
                                      int se, int i)
  {
    if (ss > se)
      return;

/*leaf*/

if (ss == se) 
    {
      st[i] = ss;
      return;
    }
    int mid = (ss + se) /2;
    SegmentTreeConstruction(ss, mid, left(i));
    SegmentTreeConstruction(mid + 1, se, right(i));
    if (l.get(st[left(i)]) < l.get(st[right(i)]))
      st[i] = st[left(i)];
    else
      st[i] = st[right(i)];
  }

/*  Function to get LCA*/

  static int LCA(int x, int y)
  {
    if (h[x] > h[y])
    {
      int t = x;
      x = y;
      y = t;
    }
    return e.get(RMQ(0, l.size() - 1, h[x], h[y], 0));
  }

/*  Driver code*/

  public static void main(String[] args)
  {

/*    n=number of nodes in the tree
    q=number of queries to answer*/

    int n = 15, q = 5;
    for (int i = 0; i < g.length; i++)
      g[i] = new Vector<Integer>();

/*    making the tree*/

/*
                   1
                 / | \
                2  3  4
                   |   \
                   5    6
                 / |  \
               8   7    9 (right of 5)
                 / | \   | \
               10 11 12 13 14
                      |
                      15
  */

    add_edge(1, 2);
    add_edge(1, 3);
    add_edge(1, 4);
    add_edge(3, 5);
    add_edge(4, 6);
    add_edge(5, 7);
    add_edge(5, 8);
    add_edge(5, 9);
    add_edge(7, 10);
    add_edge(7, 11);
    add_edge(7, 12);
    add_edge(9, 13);
    add_edge(9, 14);
    add_edge(12, 15);
    level[1] = 1;
    leveling(1);
    dfs(1);
    setting_l(n);
    setting_h(n);
    SegmentTreeConstruction(0, l.size() - 1, 0);
    System.out.print(LCA(10, 15) +"\n");
    System.out.print(LCA(11, 14) +"\n");
  }
}

/*Java implementation to print the path common to the 
two paths from the root to the two given nodes*/

import java.util.ArrayList;
public class PrintCommonPath {

/*    Initialize n1 and n2 as not visited*/

    static boolean v1 = false, v2 = false;

/* Class containing left and right child of current
 node and key value*/

class Node
{
    int data;
    Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}

/*    This function returns pointer to LCA of two given
    values n1 and n2. This function assumes that n1 and
    n2 are present in Binary Tree*/

    static Node findLCAUtil(Node node, int n1, int n2)
    {

/*        Base case*/

        if (node == null)
            return null;

/*        Store result in temp, in case of key match so that we can search for other key also.*/

        Node temp=null;

/*        If either n1 or n2 matches with root's key, report the presence
        by setting v1 or v2 as true and return root (Note that if a key
        is ancestor of other, then the ancestor key becomes LCA)*/

        if (node.data == n1)
        {
            v1 = true;
            temp = node;
        }
        if (node.data == n2)
        {
            v2 = true;
            temp = node;
        }

/*        Look for keys in left and right subtrees*/

        Node left_lca = findLCAUtil(node.left, n1, n2);
        Node right_lca = findLCAUtil(node.right, n1, n2);
        if (temp != null)
            return temp;

/*        If both of the above calls return Non-NULL, then one key
        is present in once subtree and other is present in other,
        So this node is the LCA*/

        if (left_lca != null && right_lca != null)
            return node;

/*        Otherwise check if left subtree or right subtree is LCA*/

        return (left_lca != null) ? left_lca : right_lca;
    }

/*    Returns true if key k is present in tree rooted with root*/

    static boolean find(Node root, int k)
    {

/*        Base Case*/

        if (root == null)
            return false;

/*        If key k is present at root, or in left subtree 
        or right subtree, return true*/

        if (root.data == k || find(root.left, k) ||  find(root.right, k))
            return true;

/*        Else return false*/

        return false;
    }

/*    This function returns LCA of n1 and n2 only if both n1 and n2 
    are present in tree, otherwise returns null*/

    static Node findLCA(Node root, int n1, int n2)
    {

/*        Find lca of n1 and n2*/

        Node lca = findLCAUtil(root, n1, n2);

/*        Return LCA only if both n1 and n2 are present in tree*/

        if (v1 && v2 || v1 && find(lca, n2) || v2 && find(lca, n1))
            return lca;

/*        Else return null*/

        return null;
    }

/*    function returns true if 
    there is a path from root to 
    the given node. It also populates 
    'arr' with the given path*/

    static boolean hasPath(Node root, ArrayList<Integer> arr, int x)
    {

/*        if root is null
        there is no path*/

        if (root==null)
            return false;

/*        push the node's value in 'arr'*/

        arr.add(root.data);

/*        if it is the required node
        return true*/

        if (root.data == x)    
            return true;

/*        else check whether there    the required node lies in the
        left subtree or right subtree of the current node*/

        if (hasPath(root.left, arr, x) ||
            hasPath(root.right, arr, x))
            return true;

/*        required node does not lie either in the 
        left or right subtree of the current node
        Thus, remove current node's value from 'arr'
        and then return false;    */

        arr.remove(arr.size()-1);
        return false;            
    }

/*    function to print the path common
    to the two paths from the root 
    to the two given nodes if the nodes 
    lie in the binary tree*/

    static void printCommonPath(Node root, int n1, int n2)
    {

/*        ArrayList to store the common path*/

        ArrayList<Integer> arr=new ArrayList<>();

/*        LCA of node n1 and n2*/

        Node lca = findLCA(root, n1, n2);

/*        if LCA of both n1 and n2 exists*/

        if (lca!=null)
        {

/*            then print the path from root to
            LCA node*/

            if (hasPath(root, arr, lca.data))
            {
                for (int i=0; i<arr.size()-1; i++)    
                    System.out.print(arr.get(i)+"->");
                    System.out.print(arr.get(arr.size() - 1));    
            }    
        }

/*        LCA is not present in the binary tree 
        either n1 or n2 or both are not present*/

        else
            System.out.print("No Common Path");
    }

/*    Driver code*/

    public static void main(String args[])
    {
        Node root = new Node(1);
        root.left = new Node(2);
        root.right = new Node(3);
        root.left.left = new Node(4);
        root.left.right = new Node(5);
        root.right.left = new Node(6);
        root.right.right = new Node(7);
        root.left.right.left = new Node(8);
        root.right.left.right = new Node(9);
        int n1 = 4, n2 = 8;
        printCommonPath(root, n1, n2);
        }
}

/*Java program to query whether two node has
ancestor-descendant relationship or not*/

import java.util.Vector;
class GFG
{
  static int cnt;

/*  Utility dfs method to assign in and out time
  to each node*/

  static void dfs(Vector<Integer> []g, int u, int parent,
                  int []timeIn, int []timeOut)
  {

/*    Assign In-time to node u*/

    timeIn[u] = cnt++;

/*    Call dfs over all neighbors except parent*/

    for(int i = 0; i < g[u].size(); i++)
    {
      int v = g[u].get(i);       
      if (v != parent)
        dfs(g, v, u, timeIn, timeOut);
    }

/*    Assign Out-time to node u*/

    timeOut[u] = cnt++;
  }

/*  Method to preprocess all nodes for assigning time*/

  static void preProcess(int [][]edges, int V,
                         int []timeIn, int []timeOut)
  {
    @SuppressWarnings("unchecked")
    Vector<Integer> []g = new Vector[V];
    for (int i = 0; i < g.length; i++)
      g[i] = new Vector<Integer>();

/*    Conarray of vector data structure
    for tree*/

    for(int i = 0; i < V - 1; i++)
    {
      int u = edges[i][0];
      int v = edges[i][1];
      g[u].add(v);
      g[v].add(u);
    }
    cnt = 0;

/*    Call dfs method from root*/

    dfs(g, 0, -1, timeIn, timeOut);
  }

/*  Method returns "yes" if u is a ancestor
  node of v*/

  static String isAncestor(int u, int v, int []timeIn,
                           int []timeOut)
  {
    boolean b = (timeIn[u] <= timeIn[v] &&
                 timeOut[v] <= timeOut[u]);
    return (b ? "yes" : "no");
  }

/*  Driver code   */

  public static void main(String[] args)
  {
    int edges[][] = { { 0, 1 },
                     { 0, 2 },
                     { 1, 3 },
                     { 1, 4 },
                     { 2, 5 },
                     { 4, 6 },
                     { 5, 7 } };   
    int E = edges.length;
    int V = E + 1;  
    int []timeIn = new int[V];
    int []timeOut = new int[V];  
    preProcess(edges, V, timeIn, timeOut);   
    int u = 1;
    int v = 6;
    System.out.println(isAncestor(u, v, timeIn,
                                  timeOut));   
    u = 1;
    v = 7;
    System.out.println(isAncestor(u, v, timeIn,
                                  timeOut));
  }
}

/*Java implementation to print the path from root 
to a given node in a binary tree */

import java.util.ArrayList;
public class PrintPath {

/*A node of binary tree */

class Node 
{ 
    int data; 
    Node left, right; 
    Node(int data)
    {
        this.data=data;
        left=right=null;
    }
};

/*    Returns true if there is a path from root 
    to the given node. It also populates  
    'arr' with the given path */

    public static boolean hasPath(Node root, ArrayList<Integer> arr, int x) 
    {

/*        if root is NULL 
        there is no path */

        if (root==null) 
            return false;

/*        push the node's value in 'arr' */

        arr.add(root.data);

/*        if it is the required node 
        return true */

        if (root.data == x)     
            return true;

/*        else check whether the required node lies 
        in the left subtree or right subtree of  
        the current node */

        if (hasPath(root.left, arr, x) || 
            hasPath(root.right, arr, x)) 
            return true;

/*        required node does not lie either in the  
        left or right subtree of the current node 
        Thus, remove current node's value from  
        'arr'and then return false     */

        arr.remove(arr.size()-1); 
        return false;             
    }

/*    function to print the path from root to the 
    given node if the node lies in the binary tree */

    public static void printPath(Node root, int x) 
    {

/*        ArrayList to store the path */

        ArrayList<Integer> arr=new ArrayList<>();

/*        if required node 'x' is present 
        then print the path */

        if (hasPath(root, arr, x)) 
        { 
            for (int i=0; i<arr.size()-1; i++)     
                System.out.print(arr.get(i)+"->");
            System.out.print(arr.get(arr.size() - 1));    
        }

/*        'x' is not present in the binary tree  */

        else
            System.out.print("No Path"); 
    }

/*Driver program to test above*/

    public static void main(String args[]) {

/*    binary tree formation*/

        Node root=new Node(1);
        root.left = new Node(2); 
        root.right = new Node(3); 
        root.left.left = new Node(4); 
        root.left.right = new Node(5); 
        root.right.left = new Node(6); 
        root.right.right = new Node(7); 
        int x=5;
        printPath(root, x);
    }
}

/*Java program to demonstrate Range Update 
and Point Queries Without using BIT */

class GfG {

/*Updates such that getElement() gets an increased 
value when queried from l to r. */

static void update(int arr[], int l, int r, int val) 
{ 
    arr[l] += val;
    if(r + 1 < arr.length)
    arr[r+1] -= val; 
}

/*Get the element indexed at i */

static int getElement(int arr[], int i) 
{

/*    To get ith element sum of all the elements 
    from 0 to i need to be computed */

    int res = 0; 
    for (int j = 0 ; j <= i; j++) 
        res += arr[j]; 
    return res; 
}

/*Driver program to test above function */

public static void main(String[] args) 
{ 
    int arr[] = {0, 0, 0, 0, 0}; 
    int n = arr.length; 
    int l = 2, r = 4, val = 2; 
    update(arr, l, r, val);

/*    Find the element at Index 4 */

    int index = 4; 
    System.out.println("Element at index " + index + " is " +getElement(arr, index)); 
    l = 0;
    r = 3;
    val = 4; 
    update(arr,l,r,val);

/*    Find the element at Index 3 */

    index = 3; 
    System.out.println("Element at index " + index + " is " +getElement(arr, index)); 
}
}

/* Java code to demonstrate Range Update and
* Point Queries on a Binary Index Tree.
* This method only works when all array
* values are initially 0.*/

class GFG
{

/*    Max tree size*/

    final static int MAX = 1000;
    static int BITree[] = new int[MAX];

/*    Updates a node in Binary Index
    Tree (BITree) at given index
    in BITree. The given value 'val'
    is added to BITree[i] and
    all of its ancestors in tree.*/

    public static void updateBIT(int n, 
                                 int index, 
                                 int val)
    {

/*        index in BITree[] is 1 
        more than the index in arr[]*/

        index = index + 1;

/*        Traverse all ancestors 
        and add 'val'*/

        while (index <= n)
        {

/*            Add 'val' to current 
            node of BITree*/

            BITree[index] += val;

/*            Update index to that 
            of parent in update View*/

            index += index & (-index);
        }
    }

/*    Constructs Binary Indexed Tree 
    for given array of size n.*/

    public static void constructBITree(int arr[],
                                       int n)
    {

/*        Initialize BITree[] as 0*/

        for(int i = 1; i <= n; i++)
            BITree[i] = 0;

/*        Store the actual values 
        in BITree[] using update()*/

        for(int i = 0; i < n; i++)
            updateBIT(n, i, arr[i]);

    }

/*    SERVES THE PURPOSE OF getElement()
    Returns sum of arr[0..index]. This 
    function assumes that the array is
    preprocessed and partial sums of
    array elements are stored in BITree[]*/

    public static int getSum(int index)
    {

/*Initialize result*/

int sum = 0;

/*        index in BITree[] is 1 more 
        than the index in arr[]*/

        index = index + 1;

/*        Traverse ancestors
        of BITree[index]*/

        while (index > 0)
        {

/*            Add current element 
            of BITree to sum*/

            sum += BITree[index];

/*            Move index to parent 
            node in getSum View*/

            index -= index & (-index);
        }

/*        Return the sum*/

        return sum;
    }

/*    Updates such that getElement() 
    gets an increased value when 
    queried from l to r.*/

    public static void update(int l, int r, 
                              int n, int val)
    {

/*        Increase value at 
        'l' by 'val'*/

        updateBIT(n, l, val);

/*        Decrease value at
        'r+1' by 'val'*/

        updateBIT(n, r + 1, -val);
    }

/*    Driver Code*/

    public static void main(String args[])
    {
        int arr[] = {0, 0, 0, 0, 0};
        int n = arr.length;
        constructBITree(arr,n);

/*        Add 2 to all the
        element from [2,4]*/

        int l = 2, r = 4, val = 2;
        update(l, r, n, val);

/*    Find the element at Index 4*/

        int index = 4;
        System.out.println("Element at index "+ 
                                index + " is "+ 
                                getSum(index));

/*        Add 2 to all the 
        element from [0,3]*/

        l = 0; r = 3; val = 4;
        update(l, r, n, val);

/*        Find the element
        at Index 3*/

        index = 3;
        System.out.println("Element at index "+ 
                                index + " is "+ 
                                getSum(index));
    }
}

/*Java program to find height using parent array*/

class BinaryTree {

/*    This function fills depth of i'th element in parent[].  The depth is
    filled in depth[i].*/

    void fillDepth(int parent[], int i, int depth[]) {

/*        If depth[i] is already filled*/

        if (depth[i] != 0) {
            return;
        }

/*        If node at index i is root*/

        if (parent[i] == -1) {
            depth[i] = 1;
            return;
        }

/*        If depth of parent is not evaluated before, then evaluate
        depth of parent first*/

        if (depth[parent[i]] == 0) {
            fillDepth(parent, parent[i], depth);
        }

/*        Depth of this node is depth of parent plus 1*/

        depth[i] = depth[parent[i]] + 1;
    }

/*    This function returns height of binary tree represented by
    parent array*/

    int findHeight(int parent[], int n) {

/*        Create an array to store depth of all nodes/ and
        initialize depth of every node as 0 (an invalid
        value). Depth of root is 1*/

        int depth[] = new int[n];
        for (int i = 0; i < n; i++) {
            depth[i] = 0;
        }

/*        fill depth of all nodes*/

        for (int i = 0; i < n; i++) {
            fillDepth(parent, i, depth);
        }

/*        The height of binary tree is maximum of all depths.
        Find the maximum value in depth[] and assign it to ht.*/

        int ht = depth[0];
        for (int i = 1; i < n; i++) {
            if (ht < depth[i]) {
                ht = depth[i];
            }
        }
        return ht;
    }

/*    Driver program to test above functions*/

    public static void main(String args[]) {
        BinaryTree tree = new BinaryTree();

/*        int parent[] = {1, 5, 5, 2, 2, -1, 3};*/

        int parent[] = new int[]{-1, 0, 0, 1, 1, 3, 5};
        int n = parent.length;
        System.out.println("Height is  " + tree.findHeight(parent, n));
    }
}

/*Java program to construct tree for given count
width and height.*/

class GfG {

/*Function to construct the tree*/

static void constructTree(int n, int d, int h)
{
    if (d == 1) {

/*        Special case when d == 2, only one edge*/

        if (n == 2 && h == 1) {
            System.out.println("1 2");
            return;
        }

/*Tree is not possible*/

System.out.println("-1"); 
        return;
    }
    if (d > 2 * h) {
        System.out.println("-1");
        return;
    }

/*    Satisfy the height condition by add
    edges up to h*/

    for (int i = 1; i <= h; i++)    
        System.out.println(i + " " + (i + 1));
    if (d > h) {

/*        Add d - h edges from 1 to
        satisfy diameter condition*/

        System.out.println("1" + " " + (h + 2));
        for (int i = h + 2; i <= d; i++) {
            System.out.println(i + " " + (i + 1));
        }
    }

/*    Remaining edges at vertex 1 or 2(d == h)*/

    for (int i = d + 1; i < n; i++)
    {
        int k = 1;
        if (d == h)
            k = 2;
        System.out.println(k + " " + (i + 1));
    }
}

/*Driver Code*/

public static void main(String[] args)
{
    int n = 5, d = 3, h = 2;
    constructTree(n, d, h);
}
}

import java.util.*;
import java.io.*;
class Node {
    int data;
    Node left, right, nextRight;
    Node(int item)
    {
        data = item;
        left = right = nextRight = null;
    }
}
public class BinaryTree {
    Node root;
    void connect(Node p)
    {

/*        initialize queue to hold nodes at same level */

        Queue<Node> q = new LinkedList<>();

/*adding nodes to tehe queue*/

q.add(root);

/*initializing prev to null*/

Node temp = null; 
        while (!q.isEmpty()) {
            int n = q.size();
            for (int i = 0; i < n; i++) {
                Node prev = temp;
                temp = q.poll();

/*                i > 0 because when i is 0 prev points
                the last node of previous level, 
                so we skip it*/

                if (i > 0)
                    prev.nextRight = temp; 
                if (temp.left != null)
                    q.add(temp.left);
                if (temp.right != null)
                    q.add(temp.right);
            }

/*            pointing last node of the nth level to null*/

            temp.nextRight = null; 
        }
    }

/*    Driver program to test above functions*/

    public static void main(String args[])
    {
        BinaryTree tree = new BinaryTree();

/* Constructed binary tree is 
             10 
            /  \ 
          8     2 
         / 
        3 
        */

        tree.root = new Node(10);
        tree.root.left = new Node(8);
        tree.root.right = new Node(2);
        tree.root.left.left = new Node(3);

/*        Populates nextRight pointer in all nodes*/

        tree.connect(tree.root);

/*        Let us check the values of nextRight pointers*/

        System.out.println("Following are populated nextRight pointers in "
                           + "the tree"
                           + "(-1 is printed if there is no nextRight)");
        int a = tree.root.nextRight != null ? tree.root.nextRight.data : -1;
        System.out.println("nextRight of " + tree.root.data + " is "
                           + a);
        int b = tree.root.left.nextRight != null ? tree.root.left.nextRight.data : -1;
        System.out.println("nextRight of " + tree.root.left.data + " is "
                           + b);
        int c = tree.root.right.nextRight != null ? tree.root.right.nextRight.data : -1;
        System.out.println("nextRight of " + tree.root.right.data + " is "
                           + c);
        int d = tree.root.left.left.nextRight != null ? tree.root.left.left.nextRight.data : -1;
        System.out.println("nextRight of " + tree.root.left.left.data + " is "
                           + d);
    }
}

/*Java program to Get Level of a node in a Binary Tree*/

/* A tree node structure */

class Node {
    int data;
    Node left, right;
    public Node(int d)
    {
        data = d;
        left = right = null;
    }
}
class BinaryTree {
    Node root;

/* Helper function for getLevel().
       It returns level of
       the data if data is present in tree,
       otherwise returns
       0.*/

    int getLevelUtil(Node node, int data, int level)
    {
        if (node == null)
            return 0;
        if (node.data == data)
            return level;
        int downlevel
            = getLevelUtil(node.left, data, level + 1);
        if (downlevel != 0)
            return downlevel;
        downlevel
            = getLevelUtil(node.right, data, level + 1);
        return downlevel;
    }

/* Returns level of given data value */

    int getLevel(Node node, int data)
    {
        return getLevelUtil(node, data, 1);
    }

/* Driver code */

    public static void main(String[] args)
    {
        BinaryTree tree = new BinaryTree();

/* Constructing tree given in the above figure */

        tree.root = new Node(3);
        tree.root.left = new Node(2);
        tree.root.right = new Node(5);
        tree.root.left.left = new Node(1);
        tree.root.left.right = new Node(4);
        for (int x = 1; x <= 5; x++)
        {
            int level = tree.getLevel(tree.root, x);
            if (level != 0)
                System.out.println(
                    "Level of " + x + " is "
                    + tree.getLevel(tree.root, x));
            else
                System.out.println(
                    x + " is not present in tree");
        }
    }
}

/*Java program to find closest leaf of a given key in Binary Tree*/

/* Class containing left and right child of current 
   node and key value*/

class Node 
{
    int data;
    Node left, right;
    public Node(int item) 
    {
        data = item;
        left = right = null;
    }
}
class BinaryTree 
{
    Node root;

/*    A utility function to find minimum of x and y*/

    int getMin(int x, int y) 
    {
        return (x < y) ? x : y;
    }

/*    A utility function to find distance of closest leaf of the tree
    rooted under given root*/

    int closestDown(Node node) 
    {

/*        Base cases*/

        if (node == null)
            return Integer.MAX_VALUE;
        if (node.left == null && node.right == null)
            return 0;

/*        Return minimum of left and right, plus one*/

        return 1 + getMin(closestDown(node.left), closestDown(node.right));
    }

/*    Returns distance of the cloest leaf to a given key 'k'.  The array
    ancestors is used to keep track of ancestors of current node and
    'index' is used to keep track of curremt index in 'ancestors[]'*/

    int findClosestUtil(Node node, char k, Node ancestors[], int index) 
    {

/*        Base case*/

        if (node == null)
            return Integer.MAX_VALUE;

/*        If key found*/

        if (node.data == k) 
        {

/*              Find the cloest leaf under the subtree rooted with given key*/

            int res = closestDown(node);

/*            Traverse all ancestors and update result if any parent node
            gives smaller distance*/

            for (int i = index - 1; i >= 0; i--)
                res = getMin(res, index - i + closestDown(ancestors[i]));
            return res;
        }

/*        If key node found, store current node and recur for left and
        right childrens*/

        ancestors[index] = node;
        return getMin(findClosestUtil(node.left, k, ancestors, index + 1),
                findClosestUtil(node.right, k, ancestors, index + 1));
    }

/*    The main function that returns distance of the closest key to 'k'. It
    mainly uses recursive function findClosestUtil() to find the closes
    distance.*/

    int findClosest(Node node, char k) 
    {

/*        Create an array to store ancestors
        Assumptiom: Maximum height of tree is 100*/

        Node ancestors[] = new Node[100];
        return findClosestUtil(node, k, ancestors, 0);
    }

/*    Driver program to test for above functions*/

    public static void main(String args[]) 
    {

/*    Let us construct the BST shown in the above figure*/

        BinaryTree tree = new BinaryTree();
        tree.root = new Node('A');
        tree.root.left = new Node('B');
        tree.root.right = new Node('C');
        tree.root.right.left = new Node('E');
        tree.root.right.right = new Node('F');
        tree.root.right.left.left = new Node('G');
        tree.root.right.left.left.left = new Node('I');
        tree.root.right.left.left.right = new Node('J');
        tree.root.right.right.right = new Node('H');
        tree.root.right.right.right.left = new Node('H');
        char k = 'H';
        System.out.println("Distance of the closest key from " + k + " is "
                            + tree.findClosest(tree.root, k));
        k = 'C';
        System.out.println("Distance of the closest key from " + k + " is "
                            + tree.findClosest(tree.root, k));
        k = 'E';
        System.out.println("Distance of the closest key from " + k + " is "
                            + tree.findClosest(tree.root, k));
        k = 'B';
        System.out.println("Distance of the closest key from " + k + " is "
                             + tree.findClosest(tree.root, k));
    }
}

/*Java program to conFactor Tree for
a given number*/

import java.util.*;
class GFG
{

/*  Tree node*/

  static class Node
  {
    Node left, right;
    int key;
  };
  static Node root;

/*  Utility function to create a new tree Node*/

  static Node newNode(int key)
  {
    Node temp = new Node();
    temp.key = key;
    temp.left = temp.right = null;
    return temp;
  }

/*  Constructs factor tree for given value and stores
  root of tree at given reference.*/

  static Node createFactorTree(Node node_ref, int v)
  {
    (node_ref) = newNode(v);

/*    the number is factorized*/

    for (int i = 2 ; i < v/2 ; i++)
    {
      if (v % i != 0)
        continue;

/*      If we found a factor, we conleft
      and right subtrees and return. Since we
      traverse factors starting from smaller
      to greater, left child will always have
      smaller factor*/

      node_ref.left = createFactorTree(((node_ref).left), i);
      node_ref.right =  createFactorTree(((node_ref).right), v/i);
      return node_ref;
    }
    return node_ref;
  }

/*  Iterative method to find the height of Binary Tree*/

  static void printLevelOrder(Node root)
  {

/*    Base Case*/

    if (root == null)  return;
    Queue<Node > q = new LinkedList<>();
    q.add(root);
    while (q.isEmpty() == false)
    {

/*      Print front of queue and remove
      it from queue*/

      Node node = q.peek();
      System.out.print(node.key + " ");
      q.remove();
      if (node.left != null)
        q.add(node.left);
      if (node.right != null)
        q.add(node.right);
    }
  }

/*  Driver program*/

  public static void main(String[] args)
  {

/*    int val = 48;sample value*/

    root = null;
    root = createFactorTree(root, val);
    System.out.println("Level order traversal of "+
                       "constructed factor tree");
    printLevelOrder(root);
  }
}

/*Java program to find number of full 
binary tree such that each node is 
product of its children.*/

import java.util.Arrays;
class GFG {

/*    Return the number of all possible 
    full binary tree with given product
    property.*/

    static int numoffbt(int arr[], int n)
    {

/*        Finding the minimum and maximum
        values in given array.*/

        int maxvalue = -2147483647;
        int minvalue = 2147483647;
        for (int i = 0; i < n; i++)
        {
            maxvalue = Math.max(maxvalue, arr[i]);
            minvalue = Math.min(minvalue, arr[i]);
        }
        int mark[] = new int[maxvalue + 2];
        int value[] = new int[maxvalue + 2];
        Arrays.fill(mark, 0);
        Arrays.fill(value, 0);

/*        Marking the presence of each array element
        and initialising the number of possible
        full binary tree for each integer equal
        to 1 because single node will also
        contribute as a full binary tree.*/

        for (int i = 0; i < n; i++)
        {
            mark[arr[i]] = 1;
            value[arr[i]] = 1;
        }

/*        From minimum value to maximum value of array
        finding the number of all possible Full
        Binary Trees.*/

        int ans = 0;
        for (int i = minvalue; i <= maxvalue; i++)
        {

/*            Find if value present in the array*/

            if (mark[i] != 0)
            {

/*                For each multiple of i, less than
                equal to maximum value of array*/

                for (int j = i + i;
                    j <= maxvalue && j/i <= i; j += i)
                {

/*                    If multiple is not present in
                    the array then continue.*/

                    if (mark[j] == 0)
                        continue;

/*                    Finding the number of possible
                    Full binary trees for multiple
                    j by multiplying number of 
                    possible Full binary tree from 
                    the number i and number of 
                    possible Full binary tree from i/j.*/

                    value[j] = value[j] + (value[i] 
                                          * value[j/i]);

/*                    Condition for possiblity when 
                    left chid became right child 
                    and vice versa.*/

                    if (i != j / i)
                        value[j] = value[j] + (value[i]
                                         * value[j/i]);
                }
            }
            ans += value[i];
        }
        return ans;
    }

/*    driver code*/

    public static void main (String[] args)
    {
        int arr[] = { 2, 3, 4, 6 };
        int n = arr.length;
        System.out.print(numoffbt(arr, n));
    }
}

/*Java program to find minimum number of
iterations to pass information from
root to all nodes in an n-ary tree*/

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
class GFG
{

/*    No. of nodes*/

    private static int N;

/*    Adjacency list containing
    list of children*/

    private static List<List<Integer>> adj;
    GFG(int N)
    {
        this.N = N;
        adj = new ArrayList<>(N);
        for (int i = 0; i < N; i++)
            adj.add(new ArrayList<>());
    }

/*    function to add a child w to v*/

    void addChild(int v, int w)
    {
        adj.get(v).add(w);
    }

/*    Main function to find the
    minimum iterations*/

    private int getMinIteration()
    {

/*        Base case : if height = 0 or 1;*/

        if (N == 0 || N == 1)
            return 0;
        int[] mintItr = new int[N];

/*        Start Post Order Traversal from Root*/

        getMinIterUtil(0, mintItr);
        return mintItr[0];
    }

/* A recursive function to used by getMinIter().
    This function mainly does postorder traversal
    and get minimum iteration of all children
    of parent node, sort them in decreasing order
    and then get minimum iteration of parent node
    1. Get minItr(B) of all children (B) of a node (A)
    2. Sort all minItr(B) in descending order
    3. Get minItr of A based on all minItr(B)
        minItr(A) = child(A) -->> child(A)
        is children count of node A
        For children B from i = 0 to child(A)
                minItr(A) = max (minItr(A),
                                 minItr(B) + i + 1)
    Base cases would be:
    If node is leaf, minItr = 0
    If node's height is 1, minItr = children count
    */

    private void getMinIterUtil(int u, int[] minItr)
    {

/*        Base case : Leaf node*/

        if (adj.get(u).size() == 0)
            return;
        minItr[u] = adj.get(u).size();
        Integer[] minItrTemp = new Integer[minItr[u]];
        int k = 0;
        Iterator itr = adj.get(u).iterator();
        while (itr.hasNext())
        {
            int currentChild = (int) itr.next();
            getMinIterUtil(currentChild, minItr);
            minItrTemp[k++] = minItr[currentChild];
        }
        Arrays.sort(minItrTemp, Collections.reverseOrder());
        for (k = 0; k < adj.get(u).size(); k++)
        {
            int temp = minItrTemp[k] + k + 1;
            minItr[u] = Math.max(minItr[u], temp);
        }
    }

/*    Driver Code*/

    public static void main(String args[])
    {

/*        TestCase1*/

        GFG testCase1 = new GFG(17);
        testCase1.addChild(0, 1);
        testCase1.addChild(0, 2);
        testCase1.addChild(0, 3);
        testCase1.addChild(0, 4);
        testCase1.addChild(0, 5);
        testCase1.addChild(0, 6);
        testCase1.addChild(1, 7);
        testCase1.addChild(1, 8);
        testCase1.addChild(1, 9);
        testCase1.addChild(4, 10);
        testCase1.addChild(4, 11);
        testCase1.addChild(6, 12);
