list using HashMap and TreeSet
representation of graphs using sets*/

import java.util.*;
class Graph{

/*TreeSet is used to get clear
understand of graph.*/

HashMap<Integer, TreeSet<Integer>> graph;
static int v;
public Graph()
{
    graph = new HashMap<>();
    for(int i = 0; i < v; i++)
    {
        graph.put(i, new TreeSet<>());
    }
}

/*Adds an edge to an undirected graph*/

public void addEdge(int src, int dest)
{

/*    Add an edge from src to dest into the set*/

    graph.get(src).add(dest);

/*    Since graph is undirected, add an edge
    from dest to src into the set*/

    graph.get(dest).add(src);
}

/*A utility function to print the graph*/

public void printGraph()
{
    for(int i = 0; i < v; i++)
    {
        System.out.println("Adjacency list of vertex " + i);
        Iterator set = graph.get(i).iterator();
        while (set.hasNext())
            System.out.print(set.next() + " ");
        System.out.println();
        System.out.println();
    }
}

/*Searches for a given edge in the graph*/

public void searchEdge(int src, int dest)
{
    Iterator set = graph.get(src).iterator();
    if (graph.get(src).contains(dest))
        System.out.println("Edge from " + src + " to " +
                           dest + " found");
    else
        System.out.println("Edge from " + src + " to " +
                           dest + " not found");
    System.out.println();
}

/*Driver code*/

public static void main(String[] args)
{

/*    Create the graph given in the above figure*/

    v = 5;
    Graph graph = new Graph();
    graph.addEdge(0, 1);
    graph.addEdge(0, 4);
    graph.addEdge(1, 2);
    graph.addEdge(1, 3);
    graph.addEdge(1, 4);
    graph.addEdge(2, 3);
    graph.addEdge(3, 4);

/*    Print the adjacency list representation of
    the above graph*/

    graph.printGraph();

/*    Search the given edge in the graph*/

    graph.searchEdge(2, 1);
    graph.searchEdge(0, 3);
}
}

/*Java program to find K-Cores of a graph*/

import java.util.*;
class GFG
{

/*    This class represents a undirected graph using adjacency
    list representation*/

    static class Graph
    {

/*No. of vertices*/

int V;

/*        Pointer to an array containing adjacency lists*/

        Vector<Integer>[] adj;
        @SuppressWarnings("unchecked")
        Graph(int V)
        {
            this.V = V;
            this.adj = new Vector[V];
            for (int i = 0; i < V; i++)
                adj[i] = new Vector<>();
        }

/*        function to add an edge to graph*/

        void addEdge(int u, int v)
        {
            this.adj[u].add(v);
            this.adj[v].add(u);
        }

/*        A recursive function to print DFS starting from v.
        It returns true if degree of v after processing is less
        than k else false
        It also updates degree of adjacent if degree of v
        is less than k. And if degree of a processed adjacent
        becomes less than k, then it reduces of degree of v also,*/

        boolean DFSUtil(int v, boolean[] visited, int[] vDegree, int k)
        {

/*            Mark the current node as visited and print it*/

            visited[v] = true;

/*            Recur for all the vertices adjacent to this vertex*/

            for (int i : adj[v])
            {

/*                degree of v is less than k, then degree of adjacent
                must be reduced*/

                if (vDegree[v] < k)
                    vDegree[i]--;

/*                If adjacent is not processed, process it*/

                if (!visited[i])
                {

/*                    If degree of adjacent after processing becomes
                    less than k, then reduce degree of v also.*/

                    DFSUtil(i, visited, vDegree, k);
                }
            }

/*            Return true if degree of v is less than k*/

            return (vDegree[v] < k);
        }

/*        Prints k cores of an undirected graph*/

        void printKCores(int k)
        {

/*            INITIALIZATION
            Mark all the vertices as not visited and not
            processed.*/

            boolean[] visited = new boolean[V];
            boolean[] processed = new boolean[V];
            Arrays.fill(visited, false);
            Arrays.fill(processed, false);
            int mindeg = Integer.MAX_VALUE;
            int startvertex = 0;

/*            Store degrees of all vertices*/

            int[] vDegree = new int[V];
            for (int i = 0; i < V; i++)
            {
                vDegree[i] = adj[i].size();
                if (vDegree[i] < mindeg)
                {
                    mindeg = vDegree[i];
                    startvertex = i;
                }
            }
            DFSUtil(startvertex, visited, vDegree, k);

/*            DFS traversal to update degrees of all
            vertices.*/

            for (int i = 0; i < V; i++)
                if (!visited[i])
                    DFSUtil(i, visited, vDegree, k);

/*            PRINTING K CORES*/

            System.out.println("K-Cores : ");
            for (int v = 0; v < V; v++)
            {

/*                Only considering those vertices which have degree
                >= K after BFS*/

                if (vDegree[v] >= k)
                {
                    System.out.printf("\n[%d]", v);

/*                    Traverse adjacency list of v and print only
                    those adjacent which have vDegree >= k after
                    BFS.*/

                    for (int i : adj[v])
                        if (vDegree[i] >= k)
                            System.out.printf(" -> %d", i);
                }
            }
        }
    }

/*    Driver Code*/

    public static void main(String[] args)
    {

/*        Create a graph given in the above diagram*/

        int k = 3;
        Graph g1 = new Graph(9);
        g1.addEdge(0, 1);
        g1.addEdge(0, 2);
        g1.addEdge(1, 2);
        g1.addEdge(1, 5);
        g1.addEdge(2, 3);
        g1.addEdge(2, 4);
        g1.addEdge(2, 5);
        g1.addEdge(2, 6);
        g1.addEdge(3, 4);
        g1.addEdge(3, 6);
        g1.addEdge(3, 7);
        g1.addEdge(4, 6);
        g1.addEdge(4, 7);
        g1.addEdge(5, 6);
        g1.addEdge(5, 8);
        g1.addEdge(6, 7);
        g1.addEdge(6, 8);
        g1.printKCores(k);
        System.out.println();
        Graph g2 = new Graph(13);
        g2.addEdge(0, 1);
        g2.addEdge(0, 2);
        g2.addEdge(0, 3);
        g2.addEdge(1, 4);
        g2.addEdge(1, 5);
        g2.addEdge(1, 6);
        g2.addEdge(2, 7);
        g2.addEdge(2, 8);
        g2.addEdge(2, 9);
        g2.addEdge(3, 10);
        g2.addEdge(3, 11);
        g2.addEdge(3, 12);
        g2.printKCores(k);
    }
}

/*Java Program to determine level of each node 
and print level */

import java.util.*;
class GFG
{

/*function to determine level of each node starting 
from x using BFS */

static void printLevels(Vector<Vector<Integer>> graph, int V, int x) 
{

/*    array to store level of each node */

    int level[] = new int[V]; 
    boolean marked[] = new boolean[V];

/*    create a queue */

    Queue<Integer> que = new LinkedList<Integer>();

/*    enqueue element x */

    que.add(x);

/*    initialize level of source node to 0 */

    level[x] = 0;

/*    marked it as visited */

    marked[x] = true;

/*    do until queue is empty */

    while (que.size() > 0) 
    {

/*        get the first element of queue */

        x = que.peek();

/*        dequeue element */

        que.remove();

/*        traverse neighbors of node x */

        for (int i = 0; i < graph.get(x).size(); i++) 
        {

/*            b is neighbor of node x */

            int b = graph.get(x).get(i);

/*            if b is not marked already */

            if (!marked[b])
            {

/*                enqueue b in queue */

                que.add(b);

/*                level of b is level of x + 1 */

                level[b] = level[x] + 1;

/*                mark b */

                marked[b] = true; 
            } 
        } 
    }

/*    display all nodes and their levels */

    System.out.println( "Nodes"
                        + " "
                        + "Level"); 
    for (int i = 0; i < V; i++) 
        System.out.println(" " + i +" --> " + level[i] ); 
}

/*Driver Code */

public static void main(String args[])
{

/*    adjacency graph for tree */

    int V = 8; 
    Vector<Vector<Integer>> graph=new Vector<Vector<Integer>>(); 
    for(int i = 0; i < V + 1; i++)
    graph.add(new Vector<Integer>());
    graph.get(0).add(1); 
    graph.get(0).add(2); 
    graph.get(1).add(3); 
    graph.get(1).add(4); 
    graph.get(1).add(5); 
    graph.get(2).add(5); 
    graph.get(2).add(6); 
    graph.get(6).add(7);

/*    call levels function with source as 0 */

    printLevels(graph, V, 0); 
} 
}

/*JAVA code to form binary palindrome*/

import java.util.*;
class GFG
{

/*function to apply DFS*/

static void dfs(int parent, int ans[], 
                Vector<Integer> connectchars[])
{

/*    set the parent marked*/

    ans[parent] = 1;

/*    if the node has not been visited set it and
    its children marked*/

    for (int i = 0; i < connectchars[parent].size(); i++) 
    {
        if (ans[connectchars[parent].get(i)] != 1)
            dfs(connectchars[parent].get(i), ans, connectchars);
    }
}
static void printBinaryPalindrome(int n, int k)
{
    int []arr = new int[n];
    int []ans = new int[n];

/*    link which digits must be equal*/

    Vector<Integer> []connectchars = new Vector[k];
    for (int i = 0; i < k; i++)
        connectchars[i] = new Vector<Integer>();
    for (int i = 0; i < n; i++)
        arr[i] = i % k;

/*    connect the two indices*/

    for (int i = 0; i < n / 2; i++) 
    {
        connectchars[arr[i]].add(arr[n - i - 1]);
        connectchars[arr[n - i - 1]].add(arr[i]);
    }

/*    set everything connected to 
    first character as 1*/

    dfs(0, ans, connectchars);
    for (int i = 0; i < n; i++)
        System.out.print(ans[arr[i]]);
}

/*Driver code*/

public static void main(String[] args)
{
    int n = 10, k = 4;
    printBinaryPalindrome(n, k);
}
}

/*JAVA Code For DFS for a n-ary tree (acyclic graph)
represented as adjacency list*/

import java.util.*;
class GFG {

/*    DFS on tree*/

    public static void dfs(LinkedList<Integer> list[],
                             int node, int arrival)
    {

/*        Printing traversed node*/

        System.out.println(node);

/*        Traversing adjacent edges*/

        for (int i = 0; i < list[node].size(); i++) {

/*            Not traversing the parent node*/

            if (list[node].get(i) != arrival)
                dfs(list, list[node].get(i), node);
        }
    }

/* Driver program to test above function */

    public static void main(String[] args) 
    {

/*        Number of nodes*/

        int nodes = 5;

/*        Adjacency list*/

        LinkedList<Integer> list[] = new LinkedList[nodes+1];     
        for (int i = 0; i < list.length; i ++){
            list[i] = new LinkedList<Integer>();
        }

/*        Designing the tree*/

        list[1].add(2);
        list[2].add(1);
        list[1].add(3);
        list[3].add(1);
        list[2].add(4);
        list[4].add(2);
        list[3].add(5);
        list[5].add(3);

/*        Function call*/

        dfs(list, 1, 0);
    }
}

/*Java code to print maximum edges such that
Tree remains a Bipartite graph*/

import java.util.*;
class GFG
{

/*To store counts of nodes with two colors*/

static long []count_color = new long[2];
static void dfs(Vector<Integer> adj[], int node, 
                      int parent, boolean color)
{

/*    Increment count of nodes with current
    color*/

    count_color[color == false ? 0 : 1]++;

/*    Traversing adjacent nodes*/

    for (int i = 0; i < adj[node].size(); i++) 
    {

/*        Not recurring for the parent node*/

        if (adj[node].get(i) != parent)
            dfs(adj, adj[node].get(i), node, !color);
    }
}

/*Finds maximum number of edges that can be added
without violating Bipartite property.*/

static int findMaxEdges(Vector<Integer> adj[], int n)
{

/*    Do a DFS to count number of nodes
    of each color*/

    dfs(adj, 1, 0, false);
    return (int) (count_color[0] * 
                  count_color[1] - (n - 1));
}

/*Driver code*/

public static void main(String[] args)
{
    int n = 5;
    Vector<Integer>[] adj = new Vector[n + 1];
    for (int i = 0; i < n + 1; i++) 
        adj[i] = new Vector<Integer>();
    adj[1].add(2);
    adj[1].add(3);
    adj[2].add(4);
    adj[3].add(5);
    System.out.println(findMaxEdges(adj, n));
}
}

/*Java program to print all paths of source to
destination in given graph*/

import java.io.*;
import java.util.*;
class Graph{

/*utility function for printing
the found path in graph*/

private static void printPath(List<Integer> path)
{
    int size = path.size();
    for(Integer v : path)
    {
        System.out.print(v + " ");
    }
    System.out.println();
}

/*Utility function to check if current
vertex is already present in path*/

private static boolean isNotVisited(int x,
                                    List<Integer> path)
{
    int size = path.size();
    for(int i = 0; i < size; i++)
        if (path.get(i) == x)
            return false;
    return true;
}

/*Utility function for finding paths in graph
from source to destination*/

private static void findpaths(List<List<Integer> > g,
                              int src, int dst, int v)
{

/*    Create a queue which stores
    the paths*/

    Queue<List<Integer> > queue = new LinkedList<>();

/*    Path vector to store the current path*/

    List<Integer> path = new ArrayList<>();
    path.add(src);
    queue.offer(path);
    while (!queue.isEmpty())
    {
        path = queue.poll();
        int last = path.get(path.size() - 1);

/*        If last vertex is the desired destination
        then print the path*/

        if (last == dst)
        {
            printPath(path);
        }

/*        Traverse to all the nodes connected to
        current vertex and push new path to queue*/

        List<Integer> lastNode = g.get(last);
        for(int i = 0; i < lastNode.size(); i++)
        {
            if (isNotVisited(lastNode.get(i), path))
            {
                List<Integer> newpath = new ArrayList<>(path);
                newpath.add(lastNode.get(i));
                queue.offer(newpath);
            }
        }
    }
}

/*Driver code*/

public static void main(String[] args)
{
    List<List<Integer> > g = new ArrayList<>();

/*    number of vertices*/

    int v = 4;
    for(int i = 0; i < 4; i++)
    {
        g.add(new ArrayList<>());
    }

/*    Construct a graph*/

    g.get(0).add(3);
    g.get(0).add(1);
    g.get(0).add(2);
    g.get(1).add(3);
    g.get(2).add(0);
    g.get(2).add(1);
    int src = 2, dst = 3;
    System.out.println("path from src " + src +
                       " to dst " + dst + " are ");

/*    Function for finding the paths                  */

    findpaths(g, src, dst, v);
}
}

/*Java program to find minimum edge
between given two vertex of Graph*/

import java.util.LinkedList;
import java.util.Queue;
import java.util.Vector;
class Test
{

/*    Method for finding minimum no. of edge
    using BFS*/

    static int minEdgeBFS(Vector <Integer> edges[], int u,
                                  int v, int n)
    {

/*        visited[n] for keeping track of visited
        node in BFS*/

        Vector<Boolean> visited = new Vector<Boolean>(n);
        for (int i = 0; i < n; i++) {
            visited.addElement(false);
        }

/*        Initialize distances as 0*/

        Vector<Integer> distance = new Vector<Integer>(n);
        for (int i = 0; i < n; i++) {
            distance.addElement(0);
        }

/*        queue to do BFS.*/

        Queue<Integer> Q = new LinkedList<>();
        distance.setElementAt(0, u);
        Q.add(u);
        visited.setElementAt(true, u);
        while (!Q.isEmpty())
        {
            int x = Q.peek();
            Q.poll();
            for (int i=0; i<edges[x].size(); i++)
            {
                if (visited.elementAt(edges[x].get(i)))
                    continue;

/*                update distance for i*/

                distance.setElementAt(distance.get(x) + 1,edges[x].get(i));
                Q.add(edges[x].get(i));
                visited.setElementAt(true,edges[x].get(i));
            }
        }
        return distance.get(v);
    }

/*    method for addition of edge*/

    static void addEdge(Vector <Integer> edges[], int u, int v)
    {
       edges[u].add(v);
       edges[v].add(u);
    }

/*    Driver method*/

    public static void main(String args[])
    {

/*        To store adjacency list of graph*/

        int n = 9;
        Vector <Integer> edges[] = new Vector[9];
        for (int i = 0; i < edges.length; i++) {
            edges[i] = new Vector<>();
        }
        addEdge(edges, 0, 1);
        addEdge(edges, 0, 7);
        addEdge(edges, 1, 7);
        addEdge(edges, 1, 2);
        addEdge(edges, 2, 3);
        addEdge(edges, 2, 5);
        addEdge(edges, 2, 8);
        addEdge(edges, 3, 4);
        addEdge(edges, 3, 5);
        addEdge(edges, 4, 5);
        addEdge(edges, 5, 6);
        addEdge(edges, 6, 7);
        addEdge(edges, 7, 8);
        int u = 0;
        int v = 5;
        System.out.println(minEdgeBFS(edges, u, v, n));
    }
}

/*Java program to find min edge reversal to
make every node reachable from root*/

import java.util.*;
class GFG
{

/*    pair class*/

    static class pair
    {
        int first,second;
        pair(int a ,int b)
        {
            first = a;
            second = b;
        }
    }

/*method to dfs in tree and populates disRev values*/

static int dfs(Vector<Vector< pair >> g,
        pair disRev[], boolean visit[], int u)
{

/*    visit current node*/

    visit[u] = true;
    int totalRev = 0;

/*    looping over all neighbors*/

    for (int i = 0; i < g.get(u).size(); i++)
    {
        int v = g.get(u).get(i).first;
        if (!visit[v])
        {

/*            distance of v will be one more than distance of u*/

            disRev[v].first = disRev[u].first + 1;

/*            initialize back edge count same as
            parent node's count*/

            disRev[v].second = disRev[u].second;

/*            if there is a reverse edge from u to i,
            then only update*/

            if (g.get(u).get(i).second!=0)
            {
                disRev[v].second = disRev[u].second + 1;
                totalRev++;
            }
            totalRev += dfs(g, disRev, visit, v);
        }
    }

/*    return total reversal in subtree rooted at u*/

    return totalRev;
}

/*method prints root and minimum number of edge reversal*/

static void printMinEdgeReverseForRootNode(int edges[][], int e)
{

/*    number of nodes are one more than number of edges*/

    int V = e + 1;

/*    data structure to store directed tree*/

    Vector<Vector< pair >> g=new Vector<Vector< pair >>();
    for(int i = 0; i < V + 1; i++)
    g.add(new Vector<pair>());

/*    disRev stores two values - distance and back
    edge count from root node*/

    pair disRev[] = new pair[V];
    for(int i = 0; i < V; i++)
    disRev[i] = new pair(0, 0);
    boolean visit[] = new boolean[V];
    int u, v;
    for (int i = 0; i < e; i++)
    {
        u = edges[i][0];
        v = edges[i][1];

/*        add 0 weight in direction of u to v*/

        g.get(u).add(new pair(v, 0));

/*        add 1 weight in reverse direction*/

        g.get(v).add(new pair(u, 1));
    }

/*    initialize all variables*/

    for (int i = 0; i < V; i++)
    {
        visit[i] = false;
        disRev[i].first = disRev[i].second = 0;
    }
    int root = 0;

/*    dfs populates disRev data structure and
    store total reverse edge counts*/

    int totalRev = dfs(g, disRev, visit, root);

/*    UnComment below lines to print each node's
    distance and edge reversal count from root node*/

/*
    for (int i = 0; i < V; i++)
    {
        cout << i << " : " << disRev[i].first
            << " " << disRev[i].second << endl;
    }
    */

    int res = Integer.MAX_VALUE;

/*    loop over all nodes to choose minimum edge reversal*/

    for (int i = 0; i < V; i++)
    {

/*        (reversal in path to i) + (reversal
        in all other tree parts)*/

        int edgesToRev = (totalRev - disRev[i].second) +
                        (disRev[i].first - disRev[i].second);

/*        choose minimum among all values*/

        if (edgesToRev < res)
        {
            res = edgesToRev;
            root = i;
        }
    }

/*    print the designated root and total
    edge reversal made*/

    System.out.println(root + " " + res );
}

/*Driver code*/

public static void main(String args[])
{
    int edges[][] =
    {
        {0, 1},
        {2, 1},
        {3, 2},
        {3, 4},
        {5, 4},
        {5, 6},
        {7, 6}
    };
    int e = edges.length;
    printMinEdgeReverseForRootNode(edges, e);
}
}

/*Java program to print weights for alternating 
the weighting scale*/

class GFG 
{

/*    DFS method to traverse among 
    states of weighting scales*/

    static boolean dfs(int residue, int curStep, 
                       int[] wt, int[] arr,
                       int N, int steps) 
    {

/*        If we reach to more than required steps,
        return true*/

        if (curStep >= steps)
            return true;

/*        Try all possible weights and 
        choose one which returns 1 afterwards*/

        for (int i = 0; i < N; i++) 
        {

/*
            * Try this weight only if it is 
            * greater than current residue 
            * and not same as previous chosen weight
            */

            if (curStep - 1 < 0 || 
               (arr[i] > residue &&
                arr[i] != wt[curStep - 1]))
            {

/*                assign this weight to array and 
                recur for next state*/

                wt[curStep] = arr[i];
                if (dfs(arr[i] - residue, curStep + 1,
                                   wt, arr, N, steps))
                    return true;
            }
        }

/*        if any weight is not possible,
        return false*/

        return false;
    }

/*    method prints weights for alternating scale 
    and if not possible prints 'not possible'*/

    static void printWeightOnScale(int[] arr, 
                                   int N, int steps) 
    {
        int[] wt = new int[steps];

/*        call dfs with current residue as 0 
        and current steps as 0*/

        if (dfs(0, 0, wt, arr, N, steps)) 
        {
            for (int i = 0; i < steps; i++)
                System.out.print(wt[i] + " ");
            System.out.println();
        } 
        else
            System.out.println("Not Possible");
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        int[] arr = { 2, 3, 5, 6 };
        int N = arr.length;
        int steps = 10;
        printWeightOnScale(arr, N, steps);
    }
}

/*Java program to count number of 
pair of positions in matrix
which are not accessible*/

import java.util.*;
class GFG
{
static int k;

/*Counts number of vertices connected 
in a component containing x.
Stores the count in k.*/

static void dfs(Vector<Integer> graph[], 
                boolean visited[], int x)
{
    for (int i = 0; i < graph[x].size(); i++)
    {
        if (!visited[graph[x].get(i)])
        {

/*            Incrementing the number of node in
            a connected component.*/

            (k)++;
            visited[graph[x].get(i)] = true;
            dfs(graph, visited, graph[x].get(i));
        }
    }
}

/*Return the number of count of non-accessible cells.*/

static int countNonAccessible(Vector<Integer> graph[], int N)
{
    boolean []visited = new boolean[N * N + N];
    int ans = 0;
    for (int i = 1; i <= N * N; i++)
    {
        if (!visited[i])
        {
            visited[i] = true;

/*            Initialize count of connected
            vertices found by DFS starting
            from i.*/

            int k = 1;
            dfs(graph, visited, i);

/*            Update result*/

            ans += k * (N * N - k);
        }
    }
    return ans;
}

/*Inserting the edge between edge.*/

static void insertpath(Vector<Integer> graph[], 
                       int N, int x1, int y1,
                       int x2, int y2)
{

/*    Mapping the cell coordinate into node number.*/

    int a = (x1 - 1) * N + y1;
    int b = (x2 - 1) * N + y2;

/*    Inserting the edge.*/

    graph[a].add(b);
    graph[b].add(a);
}

/*Driver Code*/

public static void main(String args[])
{
    int N = 2;
    Vector[] graph = new Vector[N * N + 1];
    for (int i = 1; i <= N * N; i++)
        graph[i] = new Vector<Integer>();
    insertpath(graph, N, 1, 1, 1, 2);
    insertpath(graph, N, 1, 2, 2, 2);
    System.out.println(countNonAccessible(graph, N));
}
}

/*Java program to find maximum product
of two non-intersecting paths*/

import java.util.*;
class GFG{
static int curMax;

/*Returns maximum length path in
subtree rooted at u after
removing edge connecting u and v*/

static int dfs(Vector<Integer> g[], 
               int u, int v)
{

/*    To find lengths of first and
    second maximum in subtrees.
    currMax is to store overall
    maximum.*/

    int max1 = 0, max2 = 0, total = 0;

/*    Loop through all neighbors of u*/

    for(int i = 0; i < g[u].size(); i++)
    {

/*        If neighbor is v, then skip it*/

        if (g[u].get(i) == v)
            continue;

/*        Call recursively with current
        neighbor as root*/

        total = Math.max(total, dfs(
            g, g[u].get(i), u));

/*        Get max from one side and update*/

        if (curMax > max1)
        {
            max2 = max1;
            max1 = curMax;
        }
        else
            max2 = Math.max(max2, curMax);
    }

/*    Store total length by adding max
    and second max*/

    total = Math.max(total, max1 + max2);

/*    Update current max by adding 1, i.e.
    current node is included*/

    curMax = max1 + 1;
    return total;
}

/*Method returns maximum product of
length of two non-intersecting paths*/

static int maxProductOfTwoPaths(Vector<Integer> g[],
                                int N)
{
    int res = Integer.MIN_VALUE;
    int path1, path2;

/*    One by one removing all edges and
    calling dfs on both subtrees*/

    for(int i = 1; i < N + 2; i++)
    {
        for(int j = 0; j < g[i].size(); j++)
        {

/*            Calling dfs on subtree rooted at
            g[i][j], excluding edge from g[i][j]
            to i.*/

            curMax = 0;
            path1 = dfs(g, g[i].get(j), i);

/*            Calling dfs on subtree rooted at
            i, edge from i to g[i][j]*/

            curMax = 0;
            path2 = dfs(g,i, g[i].get(j));
            res = Math.max(res, path1 * path2);
        }
    }
    return res;
}

/*Utility function to add an
undirected edge (u,v)*/

static void addEdge(Vector<Integer> g[],
                    int u, int v)
{
    g[u].add(v);
    g[v].add(u);
}

/*  Driver code*/

public static void main(String[] args)
{
    int edges[][] = { { 1, 8 }, { 2, 6 },
                      { 3, 1 }, { 5, 3 },
                      { 7, 8 }, { 8, 4 },
                      { 8, 6 } };
    int N = edges.length;

/*    There are N edges, so +1 for nodes
    and +1 for 1-based indexing*/

    @SuppressWarnings("unchecked")
    Vector<Integer> []g = new Vector[N + 2];
    for(int i = 0; i < g.length; i++)
        g[i] = new Vector<Integer>();
    for(int i = 0; i < N; i++)
         addEdge(g, edges[i][0], edges[i][1]);
    System.out.print(maxProductOfTwoPaths(g, N) + "\n");
}
}

/*Java program to minimize subtree sum
difference by one edge deletion*/

import java.util.ArrayList;
class Graph{
static int res;

/*DFS method to traverse through edges,
calculating subtree sum at each node
and updating the difference between subtrees*/

static void dfs(int u, int parent, int totalSum,
                ArrayList<Integer>[] edge, int subtree[])
{
    int sum = subtree[u];

/*    Loop for all neighbors except parent
    and aggregate sum over all subtrees*/

    for(int i = 0; i < edge[u].size(); i++)
    {
        int v = edge[u].get(i);
        if (v != parent)
        {
            dfs(v, u, totalSum, edge, subtree);
            sum += subtree[v];
        }
    }

/*    Store sum in current node's subtree index*/

    subtree[u] = sum;

/*    At one side subtree sum is 'sum' and other
    side subtree sum is 'totalSum - sum' so
    their difference will be totalSum - 2*sum,
    by which we'll update res*/

    if (u != 0 && Math.abs(totalSum - 2 * sum) < res)
        res = Math.abs(totalSum - 2 * sum);
}

/*Method returns minimum subtree sum difference*/

static int getMinSubtreeSumDifference(int vertex[],
                                      int[][] edges,
                                      int N)
{
    int totalSum = 0;
    int[] subtree = new int[N];

/*    Calculating total sum of tree and
    initializing subtree sum's by
    vertex values*/

    for(int i = 0; i < N; i++)
    {
        subtree[i] = vertex[i];
        totalSum += vertex[i];
    }

/*    Filling edge data structure*/

    @SuppressWarnings("unchecked")
    ArrayList<Integer>[] edge = new ArrayList[N];
    for(int i = 0; i < N; i++)
    {
        edge[i] = new ArrayList<>();
    }
    for(int i = 0; i < N - 1; i++)
    {
        edge[edges[i][0]].add(edges[i][1]);
        edge[edges[i][1]].add(edges[i][0]);
    }

/* Calling DFS method at node 0, with
    parent as -1*/

    dfs(0, -1, totalSum, edge, subtree);
    return res;
}

/*Driver code*/

public static void main(String[] args)
{
    res = Integer.MAX_VALUE;
    int[] vertex = { 4, 2, 1, 6, 3, 5, 2 };
    int[][] edges = { { 0, 1 }, { 0, 2 },
                      { 0, 3 }, { 2, 4 },
                      { 2, 5 }, { 3, 6 } };
    int N = vertex.length;
    System.out.println(getMinSubtreeSumDifference(
        vertex, edges, N));
}
}

/*A Java program to find all the Stepping Number in [n, m]*/

class Main
{

/*    This Method checks if an integer n
    is a Stepping Number*/

    public static boolean isStepNum(int n)
    {

/*        Initalize prevDigit with -1*/

        int prevDigit = -1;

/*        Iterate through all digits of n and compare
        difference between value of previous and
        current digits*/

        while (n > 0)
        {

/*            Get Current digit*/

            int curDigit = n % 10;

/*            Single digit is consider as a
            Stepping Number*/

            if (prevDigit != -1)
            {

/*                Check if absolute difference between
                prev digit and current digit is 1*/

                if (Math.abs(curDigit-prevDigit) != 1)
                    return false;
            }
            n /= 10;
            prevDigit = curDigit;
        }
        return true;
    }

/*    A brute force approach based function to find all
    stepping numbers.*/

    public static void displaySteppingNumbers(int n,int m)
    {

/*        Iterate through all the numbers from [N,M]
        and check if it is a stepping number.*/

        for (int i = n; i <= m; i++)
            if (isStepNum(i))
                System.out.print(i+ " ");
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int n = 0, m = 21;

/*        Display Stepping Numbers in the range [n,m]*/

        displaySteppingNumbers(n,m);
    }
}

/*A Java program to find all the Stepping Number in
range [n, m]*/

import java.util.*;
class Main
{

/*    Prints all stepping numbers reachable from num
    and in range [n, m]*/

    public static void bfs(int n,int m,int num)
    {

/*        Queue will contain all the stepping Numbers*/

        Queue<Integer> q = new LinkedList<Integer> ();
        q.add(num);
        while (!q.isEmpty())
        {

/*            Get the front element and pop from
            the queue*/

            int stepNum = q.poll();

/*            If the Stepping Number is in
            the range [n,m] then display*/

            if (stepNum <= m && stepNum >= n)
            {
                System.out.print(stepNum + " ");
            }

/*            If Stepping Number is 0 or greater
            then m, no need to explore the neighbors*/

            if (stepNum == 0 || stepNum > m)
                continue;

/*            Get the last digit of the currently
            visited Stepping Number*/

            int lastDigit = stepNum % 10;

/*            There can be 2 cases either digit
            to be appended is lastDigit + 1 or
            lastDigit - 1*/

            int stepNumA = stepNum * 10 + (lastDigit- 1);
            int stepNumB = stepNum * 10 + (lastDigit + 1);

/*            If lastDigit is 0 then only possible
            digit after 0 can be 1 for a Stepping
            Number*/

            if (lastDigit == 0)
                q.add(stepNumB);

/*            If lastDigit is 9 then only possible
            digit after 9 can be 8 for a Stepping
            Number*/

            else if (lastDigit == 9)
                q.add(stepNumA);
            else
            {
                q.add(stepNumA);
                q.add(stepNumB);
            }
        }
    }

/*    Prints all stepping numbers in range [n, m]
    using BFS.*/

    public static void displaySteppingNumbers(int n,int m)
    {

/*        For every single digit Number 'i'
        find all the Stepping Numbers
        starting with i*/

        for (int i = 0 ; i <= 9 ; i++)
            bfs(n, m, i);
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int n = 0, m = 21;

/*        Display Stepping Numbers in
        the range [n,m]*/

        displaySteppingNumbers(n,m);
    }
}

/*A Java program to find all the Stepping Numbers
in range [n, m] using DFS Approach*/

import java.util.*;
class Main
{

/*    Method display's all the stepping numbers
    in range [n, m]*/

    public static void dfs(int n,int m,int stepNum)
    {

/*        If Stepping Number is in the
        range [n,m] then display*/

        if (stepNum <= m && stepNum >= n)
            System.out.print(stepNum + " ");

/*        If Stepping Number is 0 or greater
        than m then return*/

        if (stepNum == 0 || stepNum > m)
            return ;

/*        Get the last digit of the currently
        visited Stepping Number*/

        int lastDigit = stepNum % 10;

/*        There can be 2 cases either digit
        to be appended is lastDigit + 1 or
        lastDigit - 1*/

        int stepNumA = stepNum*10 + (lastDigit-1);
        int stepNumB = stepNum*10 + (lastDigit+1);

/*        If lastDigit is 0 then only possible
        digit after 0 can be 1 for a Stepping
        Number*/

        if (lastDigit == 0)
            dfs(n, m, stepNumB);

/*        If lastDigit is 9 then only possible
        digit after 9 can be 8 for a Stepping
        Number*/

        else if(lastDigit == 9)
            dfs(n, m, stepNumA);
        else
        {
            dfs(n, m, stepNumA);
            dfs(n, m, stepNumB);
        }
    }

/*    Prints all stepping numbers in range [n, m]
    using DFS.*/

    public static void displaySteppingNumbers(int n, int m)
    {

