/* Java program to check if linked list is palindrome */

class LinkedList {

/* Linked list Node*/

    class Node {
        char data;
        Node next;
        Node(char d)
        {
            data = d;
            next = null;
        }
    }

/*head of list*/

Node head; 
    Node slow_ptr, fast_ptr, second_half;

/* Function to check if given linked list is
       palindrome or not */

    boolean isPalindrome(Node head)
    {
        slow_ptr = head;
        fast_ptr = head;
        Node prev_of_slow_ptr = head;

/*To handle odd size list*/

Node midnode = null;

/*initialize result*/

boolean res = true; 
        if (head != null && head.next != null) {

/* Get the middle of the list. Move slow_ptr by 1
               and fast_ptrr by 2, slow_ptr will have the middle
               node */

            while (fast_ptr != null && fast_ptr.next != null) {
                fast_ptr = fast_ptr.next.next;

/*We need previous of the slow_ptr for
                  linked lists  with odd elements */

                prev_of_slow_ptr = slow_ptr;
                slow_ptr = slow_ptr.next;
            }

/* fast_ptr would become NULL when there are even elements
               in the list and not NULL for odd elements. We need to skip 
               the middle node for odd case and store it somewhere so that
               we can restore the original list */

            if (fast_ptr != null) {
                midnode = slow_ptr;
                slow_ptr = slow_ptr.next;
            }

/*            Now reverse the second half and compare it with first half*/

            second_half = slow_ptr;

/*NULL terminate first half*/

prev_of_slow_ptr.next = null;

/*Reverse the second half*/

reverse();

/*compare*/

res = compareLists(head, second_half);

/* Construct the original list back */

/*Reverse the second half again*/

reverse(); 
            if (midnode != null) {

/*                If there was a mid node (odd size case) which
                was not part of either first half or second half.*/

                prev_of_slow_ptr.next = midnode;
                midnode.next = second_half;
            }
            else
                prev_of_slow_ptr.next = second_half;
        }
        return res;
    }

/* Function to reverse the linked list  Note that this
       function may change the head */

    void reverse()
    {
        Node prev = null;
        Node current = second_half;
        Node next;
        while (current != null) {
            next = current.next;
            current.next = prev;
            prev = current;
            current = next;
        }
        second_half = prev;
    }

/* Function to check if two input lists have same data*/

    boolean compareLists(Node head1, Node head2)
    {
        Node temp1 = head1;
        Node temp2 = head2;
        while (temp1 != null && temp2 != null) {
            if (temp1.data == temp2.data) {
                temp1 = temp1.next;
                temp2 = temp2.next;
            }
            else
                return false;
        }

/* Both are empty reurn 1*/

        if (temp1 == null && temp2 == null)
            return true;

/* Will reach here when one is NULL
           and other is not */

        return false;
    }

/* Push a node to linked list. Note that this function
       changes the head */

    public void push(char new_data)
    {

/* Allocate the Node &
           Put in the data */

        Node new_node = new Node(new_data);

/* link the old list off the new one */

        new_node.next = head;

/* Move the head to point to new Node */

        head = new_node;
    }

/*    A utility function to print a given linked list*/

    void printList(Node ptr)
    {
        while (ptr != null) {
            System.out.print(ptr.data + "->");
            ptr = ptr.next;
        }
        System.out.println("NULL");
    }

/* Driver program to test the above functions */

    public static void main(String[] args)
    {

/* Start with the empty list */

        LinkedList llist = new LinkedList();
        char str[] = { 'a', 'b', 'a', 'c', 'a', 'b', 'a' };
        String string = new String(str);
        for (int i = 0; i < 7; i++) {
            llist.push(str[i]);
            llist.printList(llist.head);
            if (llist.isPalindrome(llist.head) != false) {
                System.out.println("Is Palindrome");
                System.out.println("");
            }
            else {
                System.out.println("Not Palindrome");
                System.out.println("");
            }
        }
    }
}

/*Java Code to find the last man Standing*/

public class GFG {

/*    Node class to store data*/

    static class Node
    {
        public int data ;
        public Node next;
        public Node( int data )
        {
            this.data = data;
        }
    }

/* Function to find the only person left
    after one in every m-th node is killed
    in a circle of n nodes */

    static void getJosephusPosition(int m, int n)
    {

/*        Create a circular linked list of
        size N.*/

        Node head = new Node(1);
        Node prev = head;
        for(int i = 2; i <= n; i++)
        {
            prev.next = new Node(i);
            prev = prev.next;
        }

/*        Connect last node to first*/

        prev.next = head;

/* while only one node is left in the
        linked list*/

        Node ptr1 = head, ptr2 = head;
        while(ptr1.next != ptr1)
        {

/*            Find m-th node*/

            int count = 1;
            while(count != m)
            {
                ptr2 = ptr1;
                ptr1 = ptr1.next;
                count++;
            }

/* Remove the m-th node */

            ptr2.next = ptr1.next;
            ptr1 = ptr2.next;
        }
        System.out.println ("Last person left standing " +
                 "(Josephus Position) is " + ptr1.data);
    }

/* Driver program to test above functions */

    public static void main(String args[])
    {
        int n = 14, m = 2;
        getJosephusPosition(m, n);
    }
}

/*A Java program to swap kth
node from the beginning with
kth node from the end*/

/*A Linked List node*/

class Node {
    int data;
    Node next;
    Node(int d)
    {
        data = d;
        next = null;
    }
}
class LinkedList {
    Node head;

/* Utility function to insert
       a node at the beginning */

    void push(int new_data)
    {
        Node new_node = new Node(new_data);
        new_node.next = head;
        head = new_node;
    }

/* Utility function for displaying linked list */

    void printList()
    {
        Node node = head;
        while (node != null) {
            System.out.print(node.data + " ");
            node = node.next;
        }
        System.out.println("");
    }

/* Utility function for calculating
       length of linked list */

    int countNodes()
    {
        int count = 0;
        Node s = head;
        while (s != null) {
            count++;
            s = s.next;
        }
        return count;
    }

/* Function for swapping kth nodes from
       both ends of linked list */

    void swapKth(int k)
    {

/*        Count nodes in linked list*/

        int n = countNodes();

/*        Check if k is valid*/

        if (n < k)
            return;

/*        If x (kth node from start) and
        y(kth node from end) are same*/

        if (2 * k - 1 == n)
            return;

/*        Find the kth node from beginning of linked list.
        We also find previous of kth node because we need
        to update next pointer of the previous.*/

        Node x = head;
        Node x_prev = null;
        for (int i = 1; i < k; i++) {
            x_prev = x;
            x = x.next;
        }

/*        Similarly, find the kth node from end and its
        previous. kth node from end is (n-k+1)th node
        from beginning*/

        Node y = head;
        Node y_prev = null;
        for (int i = 1; i < n - k + 1; i++) {
            y_prev = y;
            y = y.next;
        }

/*        If x_prev exists, then new next of it will be y.
        Consider the case when y->next is x, in this case,
        x_prev and y are same. So the statement
        "x_prev->next = y" creates a self loop. This self
        loop will be broken when we change y->next.*/

        if (x_prev != null)
            x_prev.next = y;

/*        Same thing applies to y_prev*/

        if (y_prev != null)
            y_prev.next = x;

/*        Swap next pointers of x and y. These statements
        also break self loop if x->next is y or y->next
        is x*/

        Node temp = x.next;
        x.next = y.next;
        y.next = temp;

/*        Change head pointers when k is 1 or n*/

        if (k == 1)
            head = y;
        if (k == n)
            head = x;
    }

/*    Driver code to test above*/

    public static void main(String[] args)
    {
        LinkedList llist = new LinkedList();
        for (int i = 8; i >= 1; i--)
            llist.push(i);
        System.out.print("Original linked list: ");
        llist.printList();
        System.out.println("");
        for (int i = 1; i < 9; i++) {
            llist.swapKth(i);
            System.out.println("Modified List for k = " + i);
            llist.printList();
            System.out.println("");
        }
    }
}

/*Java program to print reverse of list*/

import java.io.*;
import java.util.*;

/*Represents node of a linkedlist*/

class Node {
      int data;
      Node next;
      Node(int val)
      {
          data = val;
          next = null;
      }
}
public class GFG 
{

/* Function to reverse the linked list */

   static void printReverse(Node head, int n)
   {
          int j = 0;
          Node current = head;
          while (current != null) {

/*             For each node, print proper number 
             of spaces before printing it */

             for (int i = 0; i < 2 * (n - j); i++)
                  System.out.print(" ");

/*             use of carriage return to move back 
             and print.*/

             System.out.print("\r" + current.data);
             current = current.next;
             j++; 
          }
   }

/* Function to push a node */

   static Node push(Node head, int data) 
   {
          Node new_node = new Node(data);
          new_node.next = head;
          head = new_node;
          return head;
   }

/* Function to print linked list and find its 
   length */

   static int printList(Node head)
   {

/*          i for finding length of list */

          int i = 0;
          Node temp = head;
          while (temp != null)
          {
                 System.out.print(temp.data + " ");
                 temp = temp.next;
                 i++;
          }
          return i;
   }

/*   Driver code*/

   public static void main(String args[])
   {

/* Start with the empty list */

          Node head = null;

/*          list nodes are as 6 5 4 3 2 1*/

          head = push(head, 1);
          head = push(head, 2);
          head = push(head, 3);
          head = push(head, 4);
          head = push(head, 5);
          head = push(head, 6);
          System.out.println("Given linked list: ");

/*          printlist print the list and 
          return the size of list */

          int n = printList(head);

/*          print reverse list with help 
          of carriage return function*/

          System.out.println("Reversed Linked list: ");
          printReverse(head, n); 
          System.out.println();
   }
}

/*Construct a BST from given pre-order traversal
for example if the given traversal is {10, 5, 1, 7, 40, 50},
then the output should be the root of the following tree.
     10
   /   \
  5     40
 /  \      \
1    7      50 */

class Node {
    int data;
    Node left, right;
    Node(int data)
    {
        this.data = data;
        this.left = this.right = null;
    }
}
class CreateBSTFromPreorder {
    private static Node node;

/*    This will create the BST*/

    public static Node createNode(Node node, int data)
    {
        if (node == null)
            node = new Node(data);
        if (node.data > data)
            node.left = createNode(node.left, data);
        if (node.data < data)
            node.right = createNode(node.right, data);
        return node;
    }

/*    A wrapper function of createNode*/

    public static void create(int data)
    {
        node = createNode(node, data);
    }

/*    A function to print BST in inorder*/

    public static void inorderRec(Node root)
    {
        if (root != null) {
            inorderRec(root.left);
            System.out.println(root.data);
            inorderRec(root.right);
        }
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        int[] nodeData = { 10, 5, 1, 7, 40, 50 };
        for (int i = 0; i < nodeData.length; i++) {
            create(nodeData[i]);
        }
        inorderRec(node);
    }
}

/*Java implementation to construct a BST
from its level order traversal*/

class GFG
{

/*node of a BST*/

static class Node
{
    int data;
    Node left, right;
};

/*function to get a new node*/

static Node getNode(int data)
{

/*    Allocate memory*/

    Node newNode = new Node();

/*    put in the data */

    newNode.data = data;
    newNode.left = newNode.right = null; 
    return newNode;
}

/*function to construct a BST from
its level order traversal*/

static Node LevelOrder(Node root , int data) 
{
    if(root == null)
    { 
        root = getNode(data);
        return root;
    }
    if(data <= root.data)
    root.left = LevelOrder(root.left, data);
    else
    root.right = LevelOrder(root.right, data);
    return root;     
}
static Node constructBst(int arr[], int n)
{
    if(n == 0)return null;
    Node root = null;
    for(int i = 0; i < n; i++)
    root = LevelOrder(root , arr[i]);
    return root;
}

/*function to print the inorder traversal*/

static void inorderTraversal(Node root)
{
    if (root == null)
        return;
    inorderTraversal(root.left);
    System.out.print( root.data + " ");
    inorderTraversal(root.right); 
}

/*Driver code*/

public static void main(String args[])
{
    int arr[] = {7, 4, 12, 3, 6, 8, 1, 5, 10};
    int n = arr.length;
    Node root = constructBst(arr, n);
    System.out.print( "Inorder Traversal: ");
    inorderTraversal(root);
}
}

/*Java program to Check given array
can represent BST or not*/

class GFG 
{

/*    structure for Binary Node*/

    static class Node 
    {
        int key;
        Node right, left;
    };
    static Node newNode(int num) 
    {
        Node temp = new Node();
        temp.key = num;
        temp.left = null;
        temp.right = null;
        return temp;
    }

/*    To create a Tree with n levels. We always
    insert new node to left if it is less than
    previous value.*/

    static Node createNLevelTree(int arr[], int n) 
    {
        Node root = newNode(arr[0]);
        Node temp = root;
        for (int i = 1; i < n; i++)
        {
            if (temp.key > arr[i]) 
            {
                temp.left = newNode(arr[i]);
                temp = temp.left;
            } 
            else 
            {
                temp.right = newNode(arr[i]);
                temp = temp.right;
            }
        }
        return root;
    }

/*    Please refer below post for details of this
    function.
www.geeksforgeeks.org/a-program-to-check-if-a-binary-tree-is-bst-or-not/
https:*/

    static boolean isBST(Node root, int min, int max) 
    {
        if (root == null) 
        {
            return true;
        }
        if (root.key < min || root.key > max) 
        {
            return false;
        }

/*        Allow only distinct values*/

        return (isBST(root.left, min,
                (root.key) - 1)
                && isBST(root.right,
                        (root.key) + 1, max));
    }

/*    Returns tree if given array of size n can
    represent a BST of n levels.*/

    static boolean canRepresentNLevelBST(int arr[], int n) 
    {
        Node root = createNLevelTree(arr, n);
        return isBST(root, Integer.MIN_VALUE, Integer.MAX_VALUE);
    }

/*    Driver code*/

    public static void main(String[] args) 
    {
        int arr[] = {512, 330, 78, 11, 8};
        int n = arr.length;
        if (canRepresentNLevelBST(arr, n)) 
        {
            System.out.println("Yes");
        } 
        else 
        {
            System.out.println("No");
        }
    }
}

/*Java program to Check given array 
can represent BST or not */

class Solution
{

/*Driver code */

public static void main(String args[]) 
{ 
    int arr[] = { 5123, 3300, 783, 1111, 890 }; 
    int n = arr.length; 
    int max = Integer.MAX_VALUE; 
    int min = Integer.MIN_VALUE; 
    boolean flag = true; 
    for (int i = 1; i < n; i++) {

/*        This element can be inserted to the right 
        of the previous element, only if it is greater 
        than the previous element and in the range. */

        if (arr[i] > arr[i - 1] && arr[i] > min && arr[i] < max) {

/*            max remains same, update min */

            min = arr[i - 1]; 
        }

/*        This element can be inserted to the left 
        of the previous element, only if it is lesser 
        than the previous element and in the range. */

        else if (arr[i] < arr[i - 1] && arr[i] > min && arr[i] < max) {

/*            min remains same, update max */

            max = arr[i - 1]; 
        } 
        else { 
            flag = false; 
            break; 
        } 
    } 
    if (flag) { 
        System.out.println("Yes"); 
    } 
    else {

/*        if the loop completed successfully without encountering else condition */

        System.out.println("No"); 
    } 
} 
}

/*Check if each internal node of BST has only one child*/

class BinaryTree {
    boolean hasOnlyOneChild(int pre[], int size) {
        int nextDiff, lastDiff;
        for (int i = 0; i < size - 1; i++) {
            nextDiff = pre[i] - pre[i + 1];
            lastDiff = pre[i] - pre[size - 1];
            if (nextDiff * lastDiff < 0) {
                return false;
            };
        }
        return true;
    }

/*  Driver code*/

    public static void main(String[] args) {
        BinaryTree tree = new BinaryTree();
        int pre[] = new int[]{8, 3, 5, 7, 6};
        int size = pre.length;
        if (tree.hasOnlyOneChild(pre, size) == true) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }
}

/*Check if each internal node of BST has only one child*/

class BinaryTree {
    boolean hasOnlyOneChild(int pre[], int size) {

/*        Initialize min and max using last two elements*/

        int min, max;
        if (pre[size - 1] > pre[size - 2]) {
            max = pre[size - 1];
            min = pre[size - 2];
        } else {
            max = pre[size - 2];
            min = pre[size - 1];
        }

/*        Every element must be either smaller than min or
        greater than max*/

        for (int i = size - 3; i >= 0; i--) {
            if (pre[i] < min) {
                min = pre[i];
            } else if (pre[i] > max) {
                max = pre[i];
            } else {
                return false;
            }
        }
        return true;
    }

/*Driver program to test above function*/

    public static void main(String[] args) {
        BinaryTree tree = new BinaryTree();
        int pre[] = new int[]{8, 3, 5, 7, 6};
        int size = pre.length;
        if (tree.hasOnlyOneChild(pre, size) == true) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }
}

/*Java program to check if a given array is sorted
or not.*/

class GFG {

/*Function that returns true if array is Inorder
traversal of any Binary Search Tree or not.*/

    static boolean isInorder(int[] arr, int n) {

/*        Array has one or no element*/

        if (n == 0 || n == 1) {
            return true;
        }

/*Unsorted pair found*/

for (int i = 1; i < n; i++) 
        {
            if (arr[i - 1] > arr[i]) {
                return false;
            }
        }

/*        No unsorted pair found*/

        return true;
    }

