/*Java program to rotate a matrix
right by k times*/

class GFG
{

/*    size of matrix*/

    static final int M=3;
    static final int N=3;

/*    function to rotate matrix by k times*/

    static void rotateMatrix(int matrix[][], int k)
    {

/*        temporary array of size M*/

        int temp[]=new int[M];

/*        within the size of matrix*/

        k = k % M;
        for (int i = 0; i < N; i++)
        {

/*            copy first M-k elements
            to temporary array*/

            for (int t = 0; t < M - k; t++)
            temp[t] = matrix[i][t];

/*            copy the elements from k
            to end to starting*/

            for (int j = M - k; j < M; j++)
            matrix[i][j - M + k] = matrix[i][j];

/*            copy elements from
            temporary array to end*/

            for (int j = k; j < M; j++)
            matrix[i][j] = temp[j - k];
        }
    }

/*    function to display the matrix*/

    static void displayMatrix(int matrix[][])
    {
        for (int i = 0; i < N; i++)
        {
            for (int j = 0; j < M; j++)
            System.out.print(matrix[i][j] + " ");
            System.out.println();
        }
    }

/*    Driver code*/

    public static void main (String[] args)
    {
        int matrix[][] = {{12, 23, 34},
                        {45, 56, 67},
                        {78, 89, 91}};
    int k = 2;

/*    rotate matrix by k*/

    rotateMatrix(matrix, k);

/*    display rotated matrix*/

    displayMatrix(matrix);
    }
}

/*Java  Program to implement 
involutory matrix.*/

import java.io.*;
class GFG {
    static int N = 3;

/*    Function for matrix multiplication.*/

    static void multiply(int mat[][], int res[][])
    {
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                res[i][j] = 0;
                for (int k = 0; k < N; k++)
                    res[i][j] += mat[i][k] * mat[k][j];
            }
        }
    }

/*    Function to check involutory matrix.*/

    static boolean InvolutoryMatrix(int mat[][])
    {
        int res[][] = new int[N][N];

/*        multiply function call.*/

        multiply(mat, res);
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (i == j && res[i][j] != 1)
                    return false;
                if (i != j && res[i][j] != 0)
                    return false;
            }
        }
        return true;
    }

/*    Driver function.*/

    public static void main (String[] args) 
    {
        int mat[][] = { { 1, 0, 0 },
                        { 0, -1, 0 },
                        { 0, 0, -1 } };

/*        Function call. If function return
        true then if part will execute 
        otherwise else part will execute.*/

        if (InvolutoryMatrix(mat))
            System.out.println ( "Involutory Matrix");
        else
            System.out.println ( "Not Involutory Matrix");
    }
}

/*Java code to swap the element of first
and last row and display the result*/

import java.io.*;
public class Interchange {
    static void interchangeFirstLast(int m[][])
    {
        int rows = m.length;

/*        swapping of element between first
        and last rows*/

        for (int i = 0; i < m[0].length; i++) {
            int t = m[0][i];
            m[0][i] = m[rows-1][i];
            m[rows-1][i] = t;
        }
    }

/*    Driver code*/

    public static void main(String args[]) throws IOException
    {

/*        input in the array*/

        int m[][] = { { 8, 9, 7, 6 },
                    { 4, 7, 6, 5 },
                    { 3, 2, 1, 8 },
                    { 9, 9, 7, 7 } };
        interchangeFirstLast(m);

/*        printing the interchanged matrix*/

        for (int i = 0; i < m.length; i++) {
            for (int j = 0; j < m[0].length; j++)
                System.out.print(m[i][j] + " ");
            System.out.println();
        }
    }
}

/*Java code to sort 2D matrix row-wise*/

import java.io.*;
public class Sort2DMatrix {
    static int sortRowWise(int m[][])
    {

/*        loop for rows of matrix*/

        for (int i = 0; i < m.length; i++) {

/*            loop for column of matrix*/

            for (int j = 0; j < m[i].length; j++) {

/*                loop for comparison and swapping*/

                for (int k = 0; k < m[i].length - j - 1; k++) {
                    if (m[i][k] > m[i][k + 1]) {

/*                        swapping of elements*/

                        int t = m[i][k];
                        m[i][k] = m[i][k + 1];
                        m[i][k + 1] = t;
                    }
                }
            }
        }

/*        printing the sorted matrix*/

        for (int i = 0; i < m.length; i++) {
            for (int j = 0; j < m[i].length; j++)
                System.out.print(m[i][j] + " ");
            System.out.println();
        }
        return 0;
    }

/*    driver code*/

    public static void main(String args[])
    {
        int m[][] = { { 9, 8, 7, 1 },
                      { 7, 3, 0, 2 },
                      { 9, 5, 3, 2 },
                      { 6, 3, 1, 2 } };
        sortRowWise(m);
    }
}

