}

/*Java code to check Markov Matrix*/

import java.io.*;
public class markov
{
    static boolean checkMarkov(double m[][])
    {

/*        outer loop to access rows
        and inner to access columns*/

        for (int i = 0; i < m.length; i++) {

/*            Find sum of current row*/

            double sum = 0;
            for (int j = 0; j < m[i].length; j++)
                sum = sum + m[i][j];
            if (sum != 1)
               return false;
        }
        return true;
    }

