                          Qposy, obstPosx, obstPosy));
    }
}

/*Java program to find out the
maximum product in the matrix
which four elements are adjacent
to each other in one direction*/

class GFG {
    static final int n = 5;

/*    function to find max product*/

    static int FindMaxProduct(int arr[][], int n)
    {
        int max = 0, result;

/*        iterate the rows.*/

        for (int i = 0; i < n; i++)
        {

/*            iterate the columns.*/

            for (int j = 0; j < n; j++)
            {

/*                check the maximum product
                in horizontal row.*/

                if ((j - 3) >= 0)
                {
                    result = arr[i][j] * arr[i][j - 1]
                             * arr[i][j - 2]
                             * arr[i][j - 3];
                    if (max < result)
                        max = result;
                }

/*                check the maximum product
                in vertical row.*/

                if ((i - 3) >= 0)
                {
                    result = arr[i][j] * arr[i - 1][j]
                             * arr[i - 2][j]
                             * arr[i - 3][j];
                    if (max < result)
                        max = result;
                }

/*                check the maximum product in
                diagonal (going through down - right)*/

                if ((i - 3) >= 0 && (j - 3) >= 0)
                {
                    result = arr[i][j] * arr[i - 1][j - 1]
                             * arr[i - 2][j - 2]
                             * arr[i - 3][j - 3];
                    if (max < result)
                        max = result;
                }

/*                check the maximum product in
                diagonal (going through up - right)*/

                if ((i - 3) >= 0 && (j - 1) <= 0)
                {
                    result = arr[i][j] * arr[i - 1][j + 1]
                             * arr[i - 2][j + 2]
                             * arr[i - 3][j + 3];
                    if (max < result)
                        max = result;
                }
            }
        }
        return max;
    }

/*    Driver code*/

    public static void main(String[] args)
    {
                int arr[][] = { { 1, 2, 3, 4, 5 },
                        { 6, 7, 8, 9, 1 },
                        { 2, 3, 4, 5, 6 },
                        { 7, 8, 9, 1, 0 },
                        { 9, 6, 4, 2, 3 } };
        System.out.print(FindMaxProduct(arr, n));
    }
}

/*Java implementation of the above approach*/

import java.io.*;
class GFG {
    public static int maxPro(int[][] a,
                             int n, int m,
                             int k)
    {
        int maxi = 1, mp = 1;
        for (int i = 0; i < n; ++i)
        {

/*            Window Product for each row.*/

            int wp = 1;
            for (int l = 0; l < k; ++l)
            {
                wp *= a[i][l];
            }

/*            Maximum window product for each row*/

            mp = wp;
            for (int j = k; j < m; ++j)
            {
                wp = wp * a[i][j] / a[i][j - k];

/*                Global maximum
                window product*/

                maxi = Math.max(
                    maxi,
                    Math.max(mp, wp));
            }
        }
        return maxi;
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        int n = 6, m = 5, k = 4;
        int[][] a = new int[][] {
            { 1, 2, 3, 4, 5 }, { 6, 7, 8, 9, 1 },
            { 2, 3, 4, 5, 6 }, { 7, 8, 9, 1, 0 },
            { 9, 6, 4, 2, 3 }, { 1, 1, 2, 1, 1 }
        };

/*        Function call*/

        int maxpro = maxPro(a, n, m, k);
        System.out.println(maxpro);
    }
}

/*Java Program to find minimum flip
required to make Binary Matrix
symmetric along main diagonal*/

import java.util.*;
class GFG {

/*    Return the minimum flip required
    to make Binary Matrix symmetric
    along main diagonal.*/

    static int minimumflip(int mat[][], int n)
    {
        int transpose[][] = new int[n][n];

/*        finding the transpose of the matrix*/

        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                transpose[i][j] = mat[j][i];

/*        Finding the number of position
        where element are not same.*/

        int flip = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (transpose[i][j] != mat[i][j])
                    flip++;
        return flip / 2;
    }

/* Driver program to test above function */

    public static void main(String[] args)
    {
        int n = 3;
        int mat[][] = {{ 0, 0, 1 },
                       { 1, 1, 1 },
                       { 1, 0, 0 }};
        System.out.println(minimumflip(mat, n));
    }
}

