/*function for calculating frequency*/

static void freq(int ar[][], int m, int n) {
    int even = 0, odd = 0;
    for (int i = 0; i < m; ++i)
    {
        for (int j = 0; j < n; ++j)
        {

/*            modulo by 2 to check
            even and odd*/

            if ((ar[i][j] % 2) == 0)
                ++even;
            else
