/*Java code to demonstrate the working.*/

import java.io.*;
class GFG {

/*Function to print alternating
rectangles of 0 and X*/

 static void fill0X(int m, int n)
{

/* k - starting row index
        m - ending row index
        l - starting column index
        n - ending column index
        i - iterator */

    int i, k = 0, l = 0;

/*    Store given number of rows
        and columns for later use*/

    int r = m, c = n;

/*    A 2D array to store
        the output to be printed*/

    char a[][] = new char[m][n];

/*        Iniitialize the character
        to be stoed in a[][]*/

    char x = 'X';

/*    Fill characters in a[][] in spiral
        form. Every iteration fills
    one rectangle of either Xs or Os*/

    while (k < m && l < n)
    {

/* Fill the first row from the remaining rows */

        for (i = l; i < n; ++i)
            a[k][i] = x;
        k++;

/* Fill the last column from the remaining columns */

        for (i = k; i < m; ++i)
            a[i][n-1] = x;
        n--;

/* Fill the last row from the remaining rows */

        if (k < m)
        {
            for (i = n-1; i >= l; --i)
                a[m-1][i] = x;
            m--;
        }

/* Print the first column
/*                from the remaining columns */
*/
        if (l < n)
        {
            for (i = m-1; i >= k; --i)
                a[i][l] = x;
            l++;
        }

/*        Flip character for next iteration*/

        x = (x == '0')? 'X': '0';
    }

/*    Print the filled matrix*/

    for (i = 0; i < r; i++)
    {
        for (int j = 0; j < c; j++)
            System.out.print(a[i][j] + " ");
        System.out.println();
    }
}

/* Driver program to test above functions */

public static void main (String[] args) {
    System.out.println("Output for m = 5, n = 6");
    fill0X(5, 6);
    System.out.println("Output for m = 4, n = 4");
    fill0X(4, 4);
    System.out.println("Output for m = 3, n = 4");
    fill0X(3, 4);
    }
}

import java.util.*;
import java.io.*;
class GFG
{
  public static int R = 5, C = 4;
  public static void diagonalOrder(int[][] arr, int n, int m)
  {

/*    we will use a 2D vector to
    store the diagonals of our array
    the 2D vector will have (n+m-1)
    rows that is equal to the number of
    diagnols*/

    ArrayList<ArrayList<Integer>> ans = new ArrayList<ArrayList<Integer>>(n+m-1);
    for(int i = 0; i < n + m - 1; i++)
    {
      ans.add(new ArrayList<Integer>());
    }
    for (int i = 0; i < n; i++)
    {
      for (int j = 0; j < m; j++)
      {
        (ans.get(i+j)).add(arr[i][j]);
      }
    }
    for (int i = 0; i < ans.size(); i++)
    {
      for (int j = ans.get(i).size() - 1; j >= 0; j--)
      {    System.out.print(ans.get(i).get(j)+ " ");
      }  
      System.out.println();
    }
