                           + " is " + sum);
    }
}

/*Java program to interchange
the diagonals of matrix*/

import java.io.*;
class GFG
{
    public static int N = 3;

/*    Function to interchange diagonals*/

    static void interchangeDiagonals(int array[][])
    {

/*        swap elements of diagonal*/

        for (int i = 0; i < N; ++i)
            if (i != N / 2)
            {
                int temp = array[i][i];
                array[i][i] = array[i][N - i - 1];
                array[i][N - i - 1] = temp;
            }
        for (int i = 0; i < N; ++i)
        {
            for (int j = 0; j < N; ++j)
                System.out.print(array[i][j]+" ");
            System.out.println();
        }
    }

/*    Driver Code*/

    public static void main (String[] args)
    {
        int array[][] = { {4, 5, 6},
                        {1, 2, 3},
                        {7, 8, 9}
                        };
        interchangeDiagonals(array);
    }
}

/*JAVA Code for Find difference between sums
of two diagonals*/

class GFG {
    public static int difference(int arr[][], int n)
    {

/*        Initialize sums of diagonals*/

        int d1 = 0, d2 = 0;
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n; j++)
            {

/*                finding sum of primary diagonal*/

                if (i == j)
                    d1 += arr[i][j];

/*                finding sum of secondary diagonal*/

                if (i == n - j - 1)
                    d2 += arr[i][j];
            }
        }

/*        Absolute difference of the sums
        across the diagonals*/

        return Math.abs(d1 - d2);
    }

/* Driver program to test above function */

    public static void main(String[] args)
    {
        int n = 3;
        int arr[][] =
        {
            {11, 2, 4},
            {4 , 5, 6},
            {10, 8, -12}
        };
        System.out.print(difference(arr, n));
    }
  }

