    together and prints the final sorted output.*/

    public static void mergeKArrays(int[][] arr, int a,
                                    int[] output)
    {
        int c = 0;

/*        traverse the matrix*/

        for (int i = 0; i < a; i++) {
            for (int j = 0; j < 4; j++)
                output[c++] = arr[i][j];
