/*Java program to merge k sorted arrays of size n each.*/

import java.util.*;
class GFG{
  static final int n = 4;

/*  Merge arr1[0..n1-1] and arr2[0..n2-1] into
  arr3[0..n1+n2-1]*/

  static void mergeArrays(int arr1[], int arr2[], int n1,
                          int n2, int arr3[])
  {
    int i = 0, j = 0, k = 0;

/*    Traverse both array*/

    while (i<n1 && j <n2)
    {

/*      Check if current element of first
      array is smaller than current element
      of second array. If yes, store first
      array element and increment first array
      index. Otherwise do same with second array*/

      if (arr1[i] < arr2[j])
        arr3[k++] = arr1[i++];
      else
        arr3[k++] = arr2[j++];
    }

/*    Store remaining elements of first array*/

    while (i < n1)
      arr3[k++] = arr1[i++];

/*    Store remaining elements of second array*/

    while (j < n2)
      arr3[k++] = arr2[j++];
  }

/*  A utility function to print array elements*/

  static void printArray(int arr[], int size)
  {
    for (int i = 0; i < size; i++)
      System.out.print(arr[i]+  " ");
  }

/*  This function takes an array of arrays as an argument and
  All arrays are assumed to be sorted. It merges them together
  and prints the final sorted output.*/

  static void mergeKArrays(int arr[][], int i, int j, int output[])
  {

/*    if one array is in range*/

    if(i == j)
    {
      for(int p = 0; p < n; p++)
        output[p] = arr[i][p];
      return;
    }

/*    if only two arrays are left them merge them*/

    if(j - i == 1)
    {
      mergeArrays(arr[i], arr[j], n, n, output);
      return;
    }

/*    output arrays*/

    int []out1 = new int[n*(((i + j) / 2) - i + 1)];
    int []out2 = new int[n*(j - ((i + j) / 2))];

/*    divide the array into halves*/

    mergeKArrays(arr, i, (i + j) / 2, out1);
    mergeKArrays(arr, (i + j) / 2 + 1, j, out2);

/*    merge the output array*/

    mergeArrays(out1, out2, n * (((i + j) / 2) - i + 1), n * (j - ((i + j) / 2)), output);
  }

/*  Driver program to test above functions*/

  public static void main(String[] args)
  {

/*    Change n at the top to change number of elements
    in an array*/

    int arr[][] =  {{2, 6, 12, 34},
                    {1, 9, 20, 1000},
                    {23, 34, 90, 2000}};
    int k = arr.length;
    int []output = new int[n*k];
    mergeKArrays(arr,0,2, output);
    System.out.print("Merged array is " +"\n");
    printArray(output, n*k);
  }
}

/*Java program to generate
smallest derangement
using priority queue.*/

import java.util.*;
class GFG{
static void generate_derangement(int N)
{

/*  Generate Sequence and insert
  into a priority queue.*/

  int []S = new int[N + 1];
  PriorityQueue<Integer> PQ =
                new PriorityQueue <>();
  for (int i = 1; i <= N; i++)
  {
    S[i] = i;
    PQ.add(S[i]);
  }

/*  Generate Least Derangement*/

  int []D = new int[N + 1];
  for (int i = 1; i <= N; i++)
  {
    int d = PQ.peek();
    PQ.remove();
    if (d != S[i] || i == N)
    {
      D[i] = d;
    }
    else
    {
      D[i] = PQ.peek();
      PQ.remove();
      PQ.add(d);
    }
  }
  if (D[N] == S[N])
  {
    int t = D[N - 1];
    D[N - 1] = D[N];
    D[N] = t;
  }

/*  Print Derangement*/

  for (int i = 1; i <= N; i++)
    System.out.printf("%d ", D[i]);   
  System.out.printf("\n");
}

/*Driver code*/

public static void main(String[] args)
{
  generate_derangement(10);
}
}

/*Efficient Java program to find
smallest derangement.*/

class GFG
{
static void generate_derangement(int N)
{

/*    Generate Sequence S*/

    int S[] = new int[N + 1];
    for (int i = 1; i <= N; i++)
        S[i] = i;

/*    Generate Derangement*/

    int D[] = new int[N + 1];
    for (int i = 1; i <= N; i += 2)
    {
        if (i == N)
        {

/*            Only if i is odd
            Swap S[N-1] and S[N]*/

            D[N] = S[N - 1];
            D[N - 1] = S[N];
        }
        else
        {
            D[i] = i + 1;
            D[i + 1] = i;
        }
    }

/*    Print Derangement*/

    for (int i = 1; i <= N; i++)
        System.out.print(D[i] + " ");
    System.out.println();
}

/*Driver Program*/

public static void main(String[] args)
{
    generate_derangement(10);
}
}

/*Java program to find the largest derangement*/

import java.io.*;
import java.util.Collections;
import java.util.PriorityQueue;
class GFG{
public static void printLargest(int a[],int n)
{
     PriorityQueue<Integer> pq = new PriorityQueue<>(
         Collections.reverseOrder());

/*    Stores result*/

      int res[] = new int[n];

/*      Insert all elements into a priority queue*/

      for(int i = 0; i < n; i++)
    {
        pq.add(a[i]);
    }

/*      Fill Up res[] from left to right*/

    for(int i = 0; i < n; i++)
    {
        int p = pq.peek();
        pq.remove();
        if (p != a[i] || i == n - 1)
        {
            res[i] = p;
        }
        else
        {

/*            New Element poped equals the element
            in original sequence. Get the next
            largest element*/

            res[i] = pq.peek();
            pq.remove();
            pq.add(p);
        }
    }

/*      If given sequence is in descending
      order then we need to swap last two
      elements again*/

      if (res[n - 1] == a[n - 1])
    {
        res[n - 1] = res[n - 2];
        res[n - 2] = a[n - 1];
    }
      System.out.println("Largest Derangement");
    for(int i = 0; i < n; i++)
    {
        System.out.print(res[i] + " ");
    }
}

/*Driver code*/

public static void main(String[] args)
{
      int n = 7;
    int seq[] = { 92, 3, 52, 13, 2, 31, 1 };
      printLargest(seq, n);
}
}

/*Java program for implementation of Heap Sort*/

import java.io.*;
class GFG {

/*    To heapify a subtree rooted with node i which is
    an index in arr[]. n is size of heap*/

    static void heapify(int arr[], int n, int i)
    {

/*Initialize smalles as root*/

int smallest = i;

/*left = 2*i + 1*/

int l = 2 * i + 1;

/*right = 2*i + 2*/

int r = 2 * i + 2;

/*        If left child is smaller than root*/

        if (l < n && arr[l] < arr[smallest])
            smallest = l;

/*        If right child is smaller than smallest so far*/

        if (r < n && arr[r] < arr[smallest])
            smallest = r;

/*        If smallest is not root*/

        if (smallest != i) {
            int temp = arr[i];
            arr[i] = arr[smallest];
            arr[smallest] = temp;

/*            Recursively heapify the affected sub-tree*/

            heapify(arr, n, smallest);
        }
    }

/*    main function to do heap sort*/

    static void heapSort(int arr[], int n)
    {

/*        Build heap (rearrange array)*/

        for (int i = n / 2 - 1; i >= 0; i--)
            heapify(arr, n, i);

/*        One by one extract an element from heap*/

        for (int i = n - 1; i >= 0; i--) {

/*            Move current root to end*/

            int temp = arr[0];
            arr[0] = arr[i];
            arr[i] = temp;

/*            call max heapify on the reduced heap*/

            heapify(arr, i, 0);
        }
    }

/* A utility function to print array of size n */

    static void printArray(int arr[], int n)
    {
        for (int i = 0; i < n; ++i)
            System.out.print(arr[i] + " ");
        System.out.println();
    }

/*    Driver program*/

    public static void main(String[] args)
    {
        int arr[] = { 4, 6, 3, 2, 9 };
        int n = arr.length;
        heapSort(arr, n);
        System.out.println("Sorted array is ");
        printArray(arr, n);
    }
}

/*Java program to rearrange characters in a string
so that no two adjacent characters are same.*/

import java.io.*;
import java.util.*;
class KeyComparator implements Comparator<Key> {

/*    Overriding compare()method of Comparator*/

    public int compare(Key k1, Key k2)
    {
        if (k1.freq < k2.freq)
            return 1;
        else if (k1.freq > k2.freq)
            return -1;
        return 0;
    }
}
class Key {

/*store frequency of character*/

int freq; 
    char ch;
    Key(int val, char c)
    {
        freq = val;
        ch = c;
    }
}
class GFG {
    static int MAX_CHAR = 26;

/*    Function to rearrange character of a string
    so that no char repeat twice*/

    static void rearrangeString(String str)
    {
        int n = str.length();

/*        Store frequencies of all characters in string*/

        int[] count = new int[MAX_CHAR];
        for (int i = 0; i < n; i++)
            count[str.charAt(i) - 'a']++;

/*        Insert all characters with their frequencies
        into a priority_queue*/

        PriorityQueue<Key> pq
            = new PriorityQueue<>(new KeyComparator());
        for (char c = 'a'; c <= 'z'; c++) {
            int val = c - 'a';
            if (count[val] > 0)
                pq.add(new Key(count[val], c));
        }

/*        'str' that will store resultant value*/

        str = "";

/*        work as the previous visited element
        initial previous element be. ( '#' and
        it's frequency '-1' )*/

        Key prev = new Key(-1, '#');

/*        traverse queue*/

        while (pq.size() != 0) {

/*            pop top element from queue and add it
            to string.*/

            Key k = pq.peek();
            pq.poll();
            str = str + k.ch;

/*            If frequency of previous character is less
            than zero that means it is useless, we
            need not to push it*/

            if (prev.freq > 0)
                pq.add(prev);

/*            make current character as the previous 'char'
            decrease frequency by 'one'*/

            (k.freq)--;
            prev = k;
        }

/*        If length of the resultant string and original
        string is not same then string is not valid*/

        if (n != str.length())
            System.out.println(" Not valid String ");

/*valid string*/

        else
            System.out.println(str);
    }

/*    Driver program to test above function*/

    public static void main(String args[])
    {
        String str = "bbbaa";
        rearrangeString(str);
    }
}

