/*Java program to find given two array
are equal or not*/

import java.io.*;
import java.util.*;
class GFG {

/*    Returns true if arr1[0..n-1] and arr2[0..m-1]
    contain same elements.*/

    public static boolean areEqual(int arr1[], int arr2[])
    {
        int n = arr1.length;
        int m = arr2.length;

/*        If lengths of array are not equal means
        array are not equal*/

        if (n != m)
            return false;

/*        Sort both arrays*/

        Arrays.sort(arr1);
        Arrays.sort(arr2);

/*        Linearly compare elements*/

        for (int i = 0; i < n; i++)
            if (arr1[i] != arr2[i])
                return false;

/*        If all elements were same.*/

        return true;
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr1[] = { 3, 5, 2, 5, 2 };
        int arr2[] = { 2, 3, 5, 5, 2 };
        if (areEqual(arr1, arr2))
            System.out.println("Yes");
        else
            System.out.println("No");
    }
}

/*Java code to find maximum shortest distance
from endpoints*/

import java.util.*;
class GFG
{
static void makePermutation(int []a, int n)
{

/*    Store counts of all elements.*/

    HashMap<Integer,
            Integer> count = new HashMap<Integer,
                                         Integer>();
    for (int i = 0; i < n; i++)
    {
        if(count.containsKey(a[i]))
        {
            count.put(a[i], count.get(a[i]) + 1);
        }
        else
        {
            count.put(a[i], 1);
        }
    }
}

/*function to find maximum shortest distance*/

static int find_maximum(int a[], int n, int k)
{

/*    stores the shortest distance of every
    element in original array.*/

    HashMap<Integer,
            Integer> b = new HashMap<Integer,
                                     Integer>();
    for (int i = 0; i < n; i++)
    {
        int x = a[i];

/*        shortest distance from ends*/

        int d = Math.min(1 + i, n - i);
        if (!b.containsKey(x))
            b.put(x, d);
        else
        {

/* if duplicates are found, b[x]
            is replaced with minimum of the
            previous and current position's
            shortest distance*/

            b. put(x, Math.min(d, b.get(x)));
        }
    }
    int ans = Integer.MAX_VALUE;
    for (int i = 0; i < n; i++)
    {
        int x = a[i];

/*        similar elements ignore them
        cause we need distinct elements*/

        if (x != k - x && b.containsKey(k - x))        
            ans = Math.min(Math.max(b.get(x),
                                    b.get(k - x)), ans);    
    }
    return ans;
}

/*Driver Code*/

public static void main(String[] args)
{
    int a[] = { 3, 5, 8, 6, 7 };
    int K = 11;
    int n = a.length;
    System.out.println(find_maximum(a, n, K));
}
}

/*Java program to find if there is a pair
with given product.*/

class GFG
{

/*    Returns true if there is a pair in
    arr[0..n-1] with product equal to x. */

    boolean isProduct(int arr[], int n, int x)
    {

/*    Consider all possible
    pairs and check for
    every pair.*/

        for (int i=0; i<n-1; i++)
            for (int j=i+1; j<n; j++)
                if (arr[i]*arr[j] == x)
                    return true;
        return false;
    }

