    public static void main(String[] args)
    {
        GFG g = new GFG();
        int arr[] = {10, 20, 9, 40};
        int x = 400;
        int n = arr.length;
        if (g.isProduct(arr, n, x))
            System.out.println("Yes");
        else
            System.out.println("No");
        x = 190;
        if (g.isProduct(arr, n, x))
            System.out.println("Yes");
        else
            System.out.println("No");
    }
}

/*Java program if there exists a pair for given product*/

import java.util.HashSet;
class GFG
{

/*    Returns true if there is a pair in arr[0..n-1]
    with product equal to x.*/

    static boolean isProduct(int arr[], int n, int x)
    {

/*        Create an empty set and insert first
        element into it*/

        HashSet<Integer> hset = new HashSet<>();
        if(n < 2)
            return false;

/*        Traverse remaining elements*/

        for(int i = 0; i < n; i++)
        {

/*            0 case must be handles explicitly as
            x % 0 is undefined*/

            if(arr[i] == 0)
            {
                if(x == 0)
                    return true;
                else
                    continue;
            }

/*            x/arr[i] exists in hash, then we
            found a pair*/

            if(x % arr[i] == 0)
            {
                if(hset.contains(x / arr[i]))
                    return true;

/*            Insert arr[i]*/

            hset.add(arr[i]);
            }
        }
        return false;
    }

/*    driver code*/

    public static void main(String[] args)
    {
        int arr[] = {10, 20, 9, 40};
        int x = 400;
        int n = arr.length;
        if(isProduct(arr, arr.length, x))
        System.out.println("Yes");
        else
        System.out.println("No");
        x = 190;
        if(isProduct(arr, arr.length, x))
        System.out.println("Yes");
        else
        System.out.println("No");
    }
}

/*An array based Java program
to find missing elements from
an array*/

import java.util.Arrays;
public class Print {

/*    Print all elements of range
    [low, high] that are not present
    in arr[0..n-1]*/

    static void printMissing(
        int arr[], int low,
        int high)
    {

/*        Create boolean array of
        size high-low+1, each index i
        representing wether (i+low)th
        element found or not.*/

        boolean[] points_of_range = new boolean
            [high - low + 1];
        for (int i = 0; i < arr.length; i++) {

/*            if ith element of arr is in
            range low to high then mark
            corresponding index as true in array*/

            if (low <= arr[i] && arr[i] <= high)
                points_of_range[arr[i] - low] = true;
        }

/*        Traverse through the range and print all
        elements whose value is false*/

        for (int x = 0; x <= high - low; x++) {
            if (points_of_range[x] == false)
                System.out.print((low + x) + " ");
        }
    }

/*    Driver program to test above function*/

    public static void main(String[] args)
    {
        int arr[] = { 1, 3, 5, 4 };
        int low = 1, high = 10;
        printMissing(arr, low, high);
    }
}

