import java.util.*;
class GFG
{

/*Function to print common Strings with minimum index sum*/

static void find(Vector<String> list1, Vector<String> list2)
{

/*resultant list*/

Vector<String> res = new Vector<>(); 
    int max_possible_sum = list1.size() + list2.size() - 2;

/*    iterating over sum in ascending order*/

    for (int sum = 0; sum <= max_possible_sum ; sum++)
    {

/*        iterating over one list and check index
        (Corresponding to given sum) in other list*/

        for (int i = 0; i <= sum; i++)

/*            put common Strings in resultant list*/

            if (i < list1.size() &&
                (sum - i) < list2.size() &&
                list1.get(i) == list2.get(sum - i))
                res.add(list1.get(i));

/*        if common String found then break as we are
        considering index sums in increasing order.*/

        if (res.size() > 0)
            break;
    }

/*    print the resultant list*/

    for (int i = 0; i < res.size(); i++)
        System.out.print(res.get(i)+" ");
}

/*Driver code*/

public static void main(String[] args)
{

/*    Creating list1*/

    Vector<String> list1 = new Vector<>();
    list1.add("GeeksforGeeks");
    list1.add("Udemy");
    list1.add("Coursera");
    list1.add("edX");

/*    Creating list2*/

    Vector<String> list2= new Vector<>();
    list2.add("Codecademy");
    list2.add("Khan Academy");
    list2.add("GeeksforGeeks");
    find(list1, list2);
}
}

/*Hashing based Java program to find common elements
with minimum index sum.*/

import java.util.*;
class GFG
{

/*    Function to print common Strings with minimum index sum*/

    static void find(Vector<String> list1, Vector<String> list2)
    {

/*        mapping Strings to their indices*/

        Map<String, Integer> map = new HashMap<>();
        for (int i = 0; i < list1.size(); i++)
            map.put(list1.get(i), i);

/*resultant list*/

Vector<String> res = new Vector<String>(); 
        int minsum = Integer.MAX_VALUE;
        for (int j = 0; j < list2.size(); j++)
        {
            if (map.containsKey(list2.get(j)))
            {

/*                If current sum is smaller than minsum*/

                int sum = j + map.get(list2.get(j));
                if (sum < minsum)
                {
                    minsum = sum;
                    res.clear();
                    res.add(list2.get(j));
                }

/*                if index sum is same then put this
                String in resultant list as well*/

                else if (sum == minsum)
                    res.add(list2.get(j));
            }
        }

/*        Print result*/

        for (int i = 0; i < res.size(); i++)
            System.out.print(res.get(i) + " ");
    }

/*    Driver code*/

    public static void main(String[] args)
    {

/*        Creating list1*/

        Vector<String> list1 = new Vector<String>();
        list1.add("GeeksforGeeks");
        list1.add("Udemy");
        list1.add("Coursera");
        list1.add("edX");

/*        Creating list2*/

        Vector<String> list2 = new Vector<String>();
        list2.add("Codecademy");
        list2.add("Khan Academy");
        list2.add("GeeksforGeeks");
        find(list1, list2);
    }
}

/*Java program to make a permutation of numbers
from 1 to n using minimum changes.*/

import java.util.*;
class GFG
{
static void makePermutation(int []a, int n)
{

/*    Store counts of all elements.*/

    HashMap<Integer,
            Integer> count = new HashMap<Integer,
                                         Integer>();
    for (int i = 0; i < n; i++)
    {
        if(count.containsKey(a[i]))
        {
            count.put(a[i], count.get(a[i]) + 1);
        }
        else
        {
            count.put(a[i], 1);
        }
    }
    int next_missing = 1;
    for (int i = 0; i < n; i++)
    {
        if (count.containsKey(a[i]) &&
            count.get(a[i]) != 1 ||
            a[i] > n || a[i] < 1)
        {
            count.put(a[i], count.get(a[i]) - 1);

/*            Find next missing element to put
            in place of current element.*/

            while (count.containsKey(next_missing))
                next_missing++;

/*            Replace with next missing and insert
            the missing element in hash.*/

            a[i] = next_missing;
            count. put(next_missing, 1);
        }
    }
}

/*Driver Code*/

public static void main(String[] args)
{
    int A[] = { 2, 2, 3, 3 };
    int n = A.length;
    makePermutation(A, n);
    for (int i = 0; i < n; i++)
        System.out.print(A[i] + " ");
    }
}

/*Java implementation of simple method to find count of
pairs with given sum.*/

public class find {

/*    Prints number of pairs in arr[0..n-1] with sum equal
    to 'sum'*/

    public static void getPairsCount(int[] arr, int sum)
    {

/*Initialize result*/

int count = 0;

/*        Consider all possible pairs and check their sums*/

        for (int i = 0; i < arr.length; i++)
            for (int j = i + 1; j < arr.length; j++)
                if ((arr[i] + arr[j]) == sum)
                    count++;
        System.out.printf("Count of pairs is %d", count);
    }

/*Driver function to test the above function*/

    public static void main(String args[])
    {
        int[] arr = { 1, 5, 7, -1, 5 };
        int sum = 6;
        getPairsCount(arr, sum);
    }
}

/* Java implementation of simple method to find count of
pairs with given sum*/

import java.util.HashMap;
class Test {
    static int arr[] = new int[] { 1, 5, 7, -1, 5 };

/*    Returns number of pairs in arr[0..n-1] with sum equal
    to 'sum'*/

    static int getPairsCount(int n, int sum)
    {
        HashMap<Integer, Integer> hm = new HashMap<>();

/*        Store counts of all elements in map hm*/

        for (int i = 0; i < n; i++) {

/*            initializing value to 0, if key not found*/

            if (!hm.containsKey(arr[i]))
                hm.put(arr[i], 0);
            hm.put(arr[i], hm.get(arr[i]) + 1);
        }
        int twice_count = 0;

/*        iterate through each element and increment the
        count (Notice that every pair is counted twice)*/

        for (int i = 0; i < n; i++) {
            if (hm.get(sum - arr[i]) != null)
                twice_count += hm.get(sum - arr[i]);

/*            if (arr[i], arr[i]) pair satisfies the
            condition, then we need to ensure that the
            count is decreased by one such that the
            (arr[i], arr[i]) pair is not considered*/

            if (sum - arr[i] == arr[i])
                twice_count--;
        }

/*        return the half of twice_count*/

        return twice_count / 2;
    }

/*    Driver method to test the above function*/

    public static void main(String[] args)
    {
        int sum = 6;
        System.out.println(
            "Count of pairs is "
            + getPairsCount(arr.length, sum));
    }
}

