/*Java implementation to count quadruples from
four sorted arrays whose sum is equal to a
given value x*/

class GFG
{

/*    find the 'value' in the given array 'arr[]'
    binary search technique is applied*/

    static boolean isPresent(int[] arr, int low,
                            int high, int value)
    {
        while (low <= high)
        {
            int mid = (low + high) / 2;

/*            'value' found*/

            if (arr[mid] == value)
                return true;
            else if (arr[mid] > value)
                high = mid - 1;
            else
                low = mid + 1;
        }

/*        'value' not found*/

        return false;
    }

/*    function to count all quadruples from four
    sorted arrays whose sum is equal to a given value x*/

    static int countQuadruples(int[] arr1, int[] arr2,
                               int[] arr3, int[] arr4,
                               int n, int x)
    {
        int count = 0;

/*        generate all triplets from the 1st three arrays*/

        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                for (int k = 0; k < n; k++)
                {

/*                    calculate the sum of elements in
                    the triplet so generated*/

                    int T = arr1[i] + arr2[j] + arr3[k];

/*                    check if 'x-T' is present in 4th
                    array or not*/

                    if (isPresent(arr4, 0, n-1, x - T))

/*                        increment count*/

                        count++;
                }

/*        required count of quadruples*/

        return count;
    }

/*    Driver code*/

    public static void main(String[] args)
    {

/*        four sorted arrays each of size 'n'*/

        int[] arr1 = { 1, 4, 5, 6 };
        int[] arr2 = { 2, 3, 7, 8 };
        int[] arr3 = { 1, 4, 6, 10 };
        int[] arr4 = { 2, 4, 7, 8 };
        int n = 4;
        int x = 30;
        System.out.println( "Count = "
        + countQuadruples(arr1, arr2, arr3, arr4, n, x));
    }
}

/*Java implementation to count quadruples from
four sorted arrays whose sum is equal to a
given value x*/

class GFG {

/*count pairs from the two sorted array whose sum
is equal to the given 'value'*/

static int countPairs(int arr1[], int arr2[], int n, int value)
{
    int count = 0;
    int l = 0, r = n - 1;

/*    traverse 'arr1[]' from left to right
    traverse 'arr2[]' from right to left*/

    while (l < n & r >= 0) {
        int sum = arr1[l] + arr2[r];

/*        if the 'sum' is equal to 'value', then
        increment 'l', decrement 'r' and
        increment 'count'*/

        if (sum == value) {
            l++; r--;
            count++;
        }

/*        if the 'sum' is greater than 'value', then
        decrement r*/

        else if (sum > value)
            r--;

/*        else increment l*/

        else
            l++;
    }

/*    required count of pairs*/

    return count;
}

/*function to count all quadruples from four sorted arrays
whose sum is equal to a given value x*/

static int countQuadruples(int arr1[], int arr2[], int arr3[],
                    int arr4[], int n, int x)
{
    int count = 0;

/*    generate all pairs from arr1[] and arr2[]*/

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) {

/*            calculate the sum of elements in
            the pair so generated*/

            int p_sum = arr1[i] + arr2[j];

/*            count pairs in the 3rd and 4th array
            having value 'x-p_sum' and then
            accumulate it to 'count'*/

            count += countPairs(arr3, arr4, n, x - p_sum);
        }

/*    required count of quadruples*/

    return count;
}

/*Driver program to test above*/

    static public void main(String[] args) {

/*        four sorted arrays each of size 'n'*/

        int arr1[] = {1, 4, 5, 6};
        int arr2[] = {2, 3, 7, 8};
        int arr3[] = {1, 4, 6, 10};
        int arr4[] = {2, 4, 7, 8};
        int n = arr1.length;
        int x = 30;
        System.out.println("Count = "
                + countQuadruples(arr1, arr2, arr3, arr4, n, x));
    }
}

/*Java implementation to count quadruples from
four sorted arrays whose sum is equal to a
given value x*/

import java.util.*;
class GFG
{

/*function to count all quadruples from four sorted
arrays whose sum is equal to a given value x*/

static int countQuadruples(int arr1[], int arr2[], int arr3[],
                                    int arr4[], int n, int x)
{
    int count = 0;

/*    unordered_map 'um' implemented as hash table
    for <sum, frequency> tuples*/

    Map<Integer,Integer> m = new HashMap<>();

/*    count frequency of each sum obtained from the
    pairs of arr1[] and arr2[] and store them in 'um'*/

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if(m.containsKey(arr1[i] + arr2[j]))
                m.put((arr1[i] + arr2[j]), m.get((arr1[i] + arr2[j]))+1);
            else
                m.put((arr1[i] + arr2[j]), 1);

/*    generate pair from arr3[] and arr4[]*/

    for (int k = 0; k < n; k++)
        for (int l = 0; l < n; l++)
        {

/*            calculate the sum of elements in
            the pair so generated*/

            int p_sum = arr3[k] + arr4[l];

/*            if 'x-p_sum' is present in 'um' then
            add frequency of 'x-p_sum' to 'count'*/

            if (m.containsKey(x - p_sum))
                count += m.get(x - p_sum);
        }

/*    required count of quadruples*/

    return count;
}

/*Driver program to test above*/

public static void main(String[] args)
{

/*    four sorted arrays each of size 'n'*/

    int arr1[] = { 1, 4, 5, 6 };
    int arr2[] = { 2, 3, 7, 8 };
    int arr3[] = { 1, 4, 6, 10 };
    int arr4[] = { 2, 4, 7, 8 };
    int n = arr1.length;
    int x = 30;
    System.out.println("Count = "
        + countQuadruples(arr1, arr2, arr3, arr4, n, x));
}
}

/*Java program for
the above approach*/

import java.util.*;
class Solution {
    public static void main(String[] args)
    {
        int arr[] = { 10, 2, -2, -20, 10 };
        int k = -10;
        int n = arr.length;
        int res = 0;

/*        calculate all subarrays*/

        for (int i = 0; i < n; i++) {
            int sum = 0;
            for (int j = i; j < n; j++) {

/*                calculate required sum*/

                sum += arr[j];

/*                check if sum is equal to
                required sum*/

                if (sum == k)
                    res++;
            }
        }
        System.out.println(res);
    }
}

/*Java program to find number of subarrays
with sum exactly equal to k.*/

import java.util.HashMap;
import java.util.Map;
public class GfG {

/*    Function to find number of subarrays
    with sum exactly equal to k.*/

    static int findSubarraySum(int arr[], int n, int sum)
    {

/*        HashMap to store number of subarrays
        starting from index zero having
        particular value of sum.*/

        HashMap<Integer, Integer> prevSum = new HashMap<>();
        int res = 0;

/*        Sum of elements so far.*/

        int currsum = 0;
        for (int i = 0; i < n; i++) {

/*            Add current element to sum so far.*/

            currsum += arr[i];

/*            If currsum is equal to desired sum,
            then a new subarray is found. So
            increase count of subarrays.*/

            if (currsum == sum)
                res++;

/*            currsum exceeds given sum by currsum
              - sum. Find number of subarrays having
            this sum and exclude those subarrays
            from currsum by increasing count by
            same amount.*/

            if (prevSum.containsKey(currsum - sum))
                res += prevSum.get(currsum - sum);

/*            Add currsum value to count of
            different values of sum.*/

            Integer count = prevSum.get(currsum);
            if (count == null)
                prevSum.put(currsum, 1);
            else
                prevSum.put(currsum, count + 1);
        }
        return res;
    }

/*    Driver Code*/

public static void main(String[] args)
    {
        int arr[] = { 10, 2, -2, -20, 10 };
        int sum = -10;
        int n = arr.length;
        System.out.println(findSubarraySum(arr, n, sum));
    }
}

/*Java program to count pairs
whose product exist in array*/

import java.io.*;
class GFG
{

/*Returns count of pairs
whose product exists in arr[]*/

static int countPairs(int arr[],
                      int n)
{
    int result = 0;
    for (int i = 0; i < n ; i++)
    {
        for (int j = i + 1 ; j < n ; j++)
        {
            int product = arr[i] * arr[j] ;

/*            find product
            in an array*/

            for (int k = 0; k < n; k++)
            {

/*                if product found
                increment counter*/

                if (arr[k] == product)
                {
                    result++;
                    break;
                }
            }
        }
    }

/*    return Count of all pair
    whose product exist in array*/

    return result;
}

/*Driver Code*/

public static void main (String[] args)
{
int arr[] = {6, 2, 4, 12, 5, 3} ;
int n = arr.length;
System.out.println(countPairs(arr, n));
}
}

/*A hashing based Java program to count pairs whose product
exists in arr[]*/

import java.util.*;
class GFG
{

/*    Returns count of pairs whose product exists in arr[]*/

    static int countPairs(int arr[], int n) {
        int result = 0;

/*        Create an empty hash-set that store all array element*/

        HashSet< Integer> Hash = new HashSet<>();

/*        Insert all array element into set*/

        for (int i = 0; i < n; i++)
        {
            Hash.add(arr[i]);
        }

/*        Generate all pairs and check is exist in 'Hash' or not*/

        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                int product = arr[i] * arr[j];

/*                if product exists in set then we increment
                count by 1*/

                if (Hash.contains(product))
                {
                    result++;
                }
            }
        }

/*        return count of pairs whose product exist in array*/

        return result;
    }

/*    Driver program*/

    public static void main(String[] args)
    {
        int arr[] = {6, 2, 4, 12, 5, 3};
        int n = arr.length;
        System.out.println(countPairs(arr, n));
    }
}

/*Java program to find all pairs in both arrays
whose sum is equal to given value x*/

import java.io.*;
class GFG {

/*    Function to print all pairs in both arrays
    whose sum is equal to given value x*/

    static void findPairs(int arr1[], int arr2[], int n,
                          int m, int x)
    {
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
