    public static void main(String args[])
    {
        int arr[] = { 2, 3, 5, 4, 7 };
        int k = 3;
        if (printPairs(arr, arr.length, k) == false)
            System.out.println("No such pair exists");
    }
}

/*Java program to find all pairs such that
a % b = k.*/

import java.util.HashMap;
import java.util.Vector;
class Test {

/*    Utility method to find the divisors of
    n and store in vector v[]*/

    static Vector<Integer> findDivisors(int n)
    {
        Vector<Integer> v = new Vector<>();

/*        Vector is used to store  the divisors*/

        for (int i = 1; i <= Math.sqrt(n); i++) {
            if (n % i == 0) {

/*                If n is a square number, push
                only one occurrence*/

                if (n / i == i)
                    v.add(i);
                else {
                    v.add(i);
                    v.add(n / i);
                }
            }
        }
        return v;
    }

/*    method to find pairs such that (a%b = k)*/

    static boolean printPairs(int arr[], int n, int k)
    {

/*        Store all the elements in the map
        to use map as hash for finding elements
        in O(1) time.*/

        HashMap<Integer, Boolean> occ = new HashMap<>();
        for (int i = 0; i < n; i++)
            occ.put(arr[i], true);
        boolean isPairFound = false;
        for (int i = 0; i < n; i++) {

/*            Print all the pairs with (a, b) as
            (k, numbers greater than k) as
            k % (num (> k)) = k i.e. 2%4 = 2*/

            if (occ.get(k) && k < arr[i]) {
                System.out.print("(" + k + ", " + arr[i] + ") ");
                isPairFound = true;
            }

/*            Now check for the current element as 'a'
            how many b exists such that a%b = k*/

            if (arr[i] >= k) {

/*                find all the divisors of (arr[i]-k)*/

                Vector<Integer> v = findDivisors(arr[i] - k);

/*                Check for each divisor i.e. arr[i] % b = k
                or not, if yes then print that pair.*/

                for (int j = 0; j < v.size(); j++) {
                    if (arr[i] % v.get(j) == k && arr[i] != v.get(j) && occ.get(v.get(j))) {
                        System.out.print("(" + arr[i] + ", "
                                         + v.get(j) + ") ");
                        isPairFound = true;
                    }
                }

/*                Clear vector*/

                v.clear();
            }
        }
        return isPairFound;
    }

/*    Driver method*/

    public static void main(String args[])
    {
        int arr[] = { 3, 1, 2, 5, 4 };
        int k = 2;
        if (printPairs(arr, arr.length, k) == false)
            System.out.println("No such pair exists");
    }
}

/*Java Program to convert an Array
to reduced form*/

import java.util.*;
class GFG
{
    public static void convert(int arr[], int n)
    {

/*        Create a temp array and copy contents
        of arr[] to temp*/

        int temp[] = arr.clone();

/*        Sort temp array*/

        Arrays.sort(temp);

/*        Create a hash table.*/

        HashMap<Integer, Integer> umap = new HashMap<>();

/*        One by one insert elements of sorted
        temp[] and assign them values from 0
        to n-1*/

        int val = 0;
        for (int i = 0; i < n; i++)
            umap.put(temp[i], val++);

/*        Convert array by taking positions from
        umap*/

        for (int i = 0; i < n; i++)
            arr[i] = umap.get(arr[i]);
    }
    public static void printArr(int arr[], int n)
    {
        for (int i = 0; i < n; i++)
            System.out.print(arr[i] + " ");
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = {10, 20, 15, 12, 11, 50};
        int n = arr.length;
        System.out.println("Given Array is ");
        printArr(arr, n);
        convert(arr , n);
        System.out.println("\n\nConverted Array is ");
        printArr(arr, n);
    }
}

/*Java program to output the maximum occurring character
in a string*/

public class GFG
{
    static final int ASCII_SIZE = 256;
    static char getMaxOccuringChar(String str)
    {

/*        Create array to keep the count of individual
        characters and initialize the array as 0*/

        int count[] = new int[ASCII_SIZE];

/*        Construct character count array from the input
        string.*/

        int len = str.length();
        for (int i=0; i<len; i++)
            count[str.charAt(i)]++;

/*Initialize max count*/

int max = -1;

/*Initialize result*/

char result = ' ';

/*        Traversing through the string and maintaining
        the count of each character*/

        for (int i = 0; i < len; i++) {
            if (max < count[str.charAt(i)]) {
                max = count[str.charAt(i)];
                result = str.charAt(i);
            }
        }
        return result;
    }

/*    Driver Method*/

    public static void main(String[] args)
    {
        String str = "sample string";
        System.out.println("Max occurring character is " +
                            getMaxOccuringChar(str));
    }
}

/*Java program to print all words that have
the same unique character set*/

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map.Entry;
public class GFG {
    static final int MAX_CHAR = 26;

/*    Generates a key from given string. The key
    contains all unique characters of given string
    in sorted order consisting of only distinct elements.*/

    static String getKey(String str)
    {
        boolean[] visited = new boolean[MAX_CHAR];
        Arrays.fill(visited, false);

/*        store all unique characters of current
        word in key*/

        for (int j = 0; j < str.length(); j++)
            visited[str.charAt(j) - 'a'] = true ;
        String key = "";
        for (int j=0; j < MAX_CHAR; j++)
            if (visited[j])
                key = key + (char)('a'+j);
        return key;
    }

/*    Print all words together with same character sets.*/

    static void wordsWithSameCharSet(String words[], int n)
    {

/*        Stores indexes of all words that have same
        set of unique characters.
        unordered_map <string, vector <int> > Hash;*/

        HashMap<String, ArrayList<Integer>> Hash = new HashMap<>();

/*        Traverse all words*/

        for (int i=0; i<n; i++)
        {
            String key = getKey(words[i]);

/*            if the key is already in the map
            then get its corresponding value
            and update the list and put it in the map*/

            if(Hash.containsKey(key))
            {
                ArrayList<Integer> get_al = Hash.get(key);
                get_al.add(i);
                Hash.put(key, get_al);
            }

/*            if key is not present in the map
            then create a new list and add
            both key and the list*/

            else
            {
                ArrayList<Integer> new_al = new ArrayList<>();
                new_al.add(i);
                Hash.put(key, new_al);
            }
        }

/*        print all words that have the same unique character set*/

        for (Entry<String, ArrayList<Integer>> it : Hash.entrySet())
        {
            ArrayList<Integer> get =it.getValue();
            for (Integer v:get)
                System.out.print( words[v] + ", ");
            System.out.println();
        }
    }

/*    Driver program to test above function*/

    public static void main(String args[])
    {
        String words[] = { "may", "student", "students", "dog",
                     "studentssess", "god", "cat", "act", "tab",
                     "bat", "flow", "wolf", "lambs", "amy", "yam",
                     "balms", "looped", "poodle"};
        int n = words.length;
        wordsWithSameCharSet(words, n);
    }
}

/*Java program to find out the second
most repeated word*/

import java.util.*;
class GFG 
{

/*    Method to find the word*/

    static String secMostRepeated(Vector<String> seq)
    {

/*        Store all the words with its occurrence*/

        HashMap<String, Integer> occ = new HashMap<String,Integer>(seq.size()){
            @Override
            public Integer get(Object key) {
                 return containsKey(key) ? super.get(key) : 0;
            }
        };
        for (int i = 0; i < seq.size(); i++)
            occ.put(seq.get(i), occ.get(seq.get(i))+1);

/*        find the second largest occurrence*/

       int first_max = Integer.MIN_VALUE, sec_max = Integer.MIN_VALUE;
       Iterator<Map.Entry<String, Integer>> itr = occ.entrySet().iterator();
       while (itr.hasNext()) 
       {
           Map.Entry<String, Integer> entry = itr.next();
           int v = entry.getValue();
           if( v > first_max) {
                sec_max = first_max;
                first_max = v;
            }
            else if (v > sec_max && 
                     v != first_max)
                sec_max = v;
       }

/*       Return string with occurrence equals
        to sec_max*/

       itr = occ.entrySet().iterator();
       while (itr.hasNext()) 
       {
           Map.Entry<String, Integer> entry = itr.next();
           int v = entry.getValue();
           if (v == sec_max)
                return entry.getKey();
       }
       return null;
    }

/*    Driver method*/

    public static void main(String[] args) 
    {
        String arr[] = { "ccc", "aaa", "ccc",
                         "ddd", "aaa", "aaa" };
        List<String> seq =  Arrays.asList(arr);
        System.out.println(secMostRepeated(new Vector<>(seq)));
    }    
}

/*Java program to find the smallest element
with frequency exactly k.*/

import java.util.*;
class GFG {
    public static int smallestKFreq(int a[], int n, int k)
    {
        HashMap<Integer, Integer> m = new HashMap<Integer, Integer>();

/*        Map is used to store the count of
        elements present in the array*/

        for (int i = 0; i < n; i ++)
            if (m.containsKey(a[i]))
                m.put(a[i], m.get(a[i]) + 1);
           else m.put(a[i], 1);

/*        Traverse the map and find minimum
        element with frequency k.*/

        int res = Integer.MAX_VALUE;
        Set<Integer> s = m.keySet();
        for (int temp : s)
            if (m.get(temp) == k)
               res = Math.min(res, temp);
        return (res != Integer.MAX_VALUE)? res : -1;
    }

/* Driver program to test above function */

    public static void main(String[] args) 
    {
        int arr[] = { 2, 2, 1, 3, 1 };
        int k = 2;
        System.out.println(smallestKFreq(arr, arr.length, k));
    }
  }

/* Java program to find first repeating element in arr[] */

import java.util.*;
class Main
{

/*    This function prints the first repeating element in arr[]*/

    static void printFirstRepeating(int arr[])
    {

/*        Initialize index of first repeating element*/

        int min = -1;

/*        Creates an empty hashset*/

        HashSet<Integer> set = new HashSet<>();

/*        Traverse the input array from right to left*/

        for (int i=arr.length-1; i>=0; i--)
        {

/*            If element is already in hash set, update min*/

            if (set.contains(arr[i]))
                min = i;

/*Else add element to hash set*/

else   
                set.add(arr[i]);
        }

/*        Print the result*/

        if (min != -1)
          System.out.println("The first repeating element is " + arr[min]);
        else
          System.out.println("There are no repeating elements");
    }

/*    Driver method to test above method*/

    public static void main (String[] args) throws java.lang.Exception
    {
        int arr[] = {10, 5, 3, 4, 3, 5, 6};
        printFirstRepeating(arr);
    }
}

/* Java program to find first
repeating element in arr[] */

public class GFG
{

/*  This function prints the
  first repeating element in arr[]*/

  static void printFirstRepeating(int[] arr, int n)
  {

/*    This will set k=1, if any
    repeating element found*/

    int k = 0;

/*    max = maximum from (all elements & n)*/

    int max = n;
    for (int i = 0; i < n; i++)
      if (max < arr[i])
        max = arr[i];

/*    Array a is for storing
    1st time occurence of element
    initialized by 0*/

    int[] a = new int[max + 1];

/*    Store 1 in array b
    if element is duplicate
    initialized by 0*/

    int[] b = new int[max + 1];
    for (int i = 0; i < n; i++)
    {

/*      Duplicate element found*/

      if (a[arr[i]] != 0)
      {
        b[arr[i]] = 1;
        k = 1;
        continue;
      }
      else

/*        storing 1st occurence of arr[i]*/

        a[arr[i]] = i;
    }
    if (k == 0)
      System.out.println("No repeating element found");
    else
    {
      int min = max + 1;

/*      trace array a & find repeating element
      with min index*/

      for (int i = 0; i < max + 1; i++)
        if (a[i] != 0 && min > a[i] && b[i] != 0)
          min = a[i];
      System.out.print(arr[min]);
    }
    System.out.println();
  }

/*  Driver code*/

  public static void main(String[] args)
  {
    int[] arr = { 10, 5, 3, 4, 3, 5, 6 };
    int n = arr.length;
    printFirstRepeating(arr, n);
  }
}

/*Java Find the sum of all non-repeated
elements in an array*/
import java.util.Arrays;
public class GFG {

/*Find the sum of all non-repeated elements
in an array*/

    static int findSum(int arr[], int n) {

/*        sort all elements of array*/

        Arrays.sort(arr);
        int sum = arr[0];
        for (int i = 0; i < n-1; i++) {
            if (arr[i] != arr[i + 1]) {
                sum = sum + arr[i+1];
            }
        }
        return sum;
    }

/*Driver code*/

    public static void main(String[] args) {
        int arr[] = {1, 2, 3, 1, 1, 4, 5, 6};
        int n = arr.length;
        System.out.println(findSum(arr, n));
    }
}

/*Java Find the sum of all non- repeated
elements in an array*/

import java.util.*;
class GFG
{

/*    Find the sum of all non-repeated elements
    in an array*/

    static int findSum(int arr[], int n)
    {
        int sum = 0;

/*        Hash to store all element of array*/

        HashSet<Integer> s = new HashSet<Integer>();
        for (int i = 0; i < n; i++)
        {
            if (!s.contains(arr[i]))
            {
                sum += arr[i];
                s.add(arr[i]);
            }
        }
        return sum;
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = {1, 2, 3, 1, 1, 4, 5, 6};
        int n = arr.length;
        System.out.println(findSum(arr, n));
    }
}

/*Java program to find first non-repeating
element.*/

class GFG {
    static int firstNonRepeating(int arr[], int n)
    {
        for (int i = 0; i < n; i++) {
            int j;
            for (j = 0; j < n; j++)
                if (i != j && arr[i] == arr[j])
                    break;
            if (j == n)
                return arr[i];
        }
        return -1;
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = { 9, 4, 9, 6, 7, 4 };
        int n = arr.length;
        System.out.print(firstNonRepeating(arr, n));
    }
}

/*Efficient Java program to find first non-
repeating element.*/

import java.util.*;
class GFG {
    static int firstNonRepeating(int arr[], int n)
    {

/*        Insert all array elements in hash
        table*/

        Map<Integer, Integer> m = new HashMap<>();
        for (int i = 0; i < n; i++) {
            if (m.containsKey(arr[i])) {
                m.put(arr[i], m.get(arr[i]) + 1);
            }
            else {
                m.put(arr[i], 1);
            }
        }

/*        Traverse array again and return
        first element with count 1.*/

        for (int i = 0; i < n; i++)
            if (m.get(arr[i]) == 1)
                return arr[i];
        return -1;
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = { 9, 4, 9, 6, 7, 4 };
        int n = arr.length;
        System.out.println(firstNonRepeating(arr, n));
    }
}

/*Efficient Java program to print all non-
repeating elements.*/

import java.util.*;
class GFG {
    static void firstNonRepeating(int arr[], int n)
    {

/*        Insert all array elements in hash
        table*/

        Map<Integer, Integer> m = new HashMap<>();
        for (int i = 0; i < n; i++) {
            if (m.containsKey(arr[i])) {
                m.put(arr[i], m.get(arr[i]) + 1);
            }
            else {
                m.put(arr[i], 1);
            }
        }

/*        Traverse through map only and
        using for-each loop for iteration over Map.entrySet()*/

        for (Map.Entry<Integer, Integer> x : m.entrySet())
            if (x.getValue() == 1)
                System.out.print(x.getKey() + " ");
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = { 9, 4, 9, 6, 7, 4 };
        int n = arr.length;
        firstNonRepeating(arr, n);
    }
}

/*Java program to print k-th distinct
element in a given array*/

class GFG
{

/*    Returns k-th distinct element in arr.*/

    static int printKDistinct(int arr[],
                                  int n,
                                  int k)
    {
        int dist_count = 0;
        for (int i = 0; i < n; i++)
        {

/*            Check if current element is
            present somewhere else.*/

            int j;
            for (j = 0; j < n; j++)
                if (i != j && arr[j] == arr[i])
                    break;

/*            If element is unique*/

            if (j == n)
                dist_count++;
            if (dist_count == k)
                return arr[i];
        }
        return -1;
    }

/*    Driver code*/

    public static void main (String[] args)
    {
        int ar[] = {1, 2, 1, 3, 4, 2};
        int n = ar.length;
        int k = 2;
        System.out.print(printKDistinct(ar, n, k));
    }
}

/*Java program to find pairs of positive
and negative values present in an array.*/

import java.util.*;
import java.lang.*;
class GFG {

/*    Print pair with negative and positive value*/

    public static void printPairs(int arr[] , int n)
    {
        Vector<Integer> v = new Vector<Integer>();

/*        For each element of array.*/

        for (int i = 0; i < n; i++)

/*            Try to find the negative value of
            arr[i] from i + 1 to n*/

            for (int j = i + 1; j < n; j++)

/*                If absolute values are equal
                print pair.*/

                if (Math.abs(arr[i]) ==
                                  Math.abs(arr[j]))
                    v.add(Math.abs(arr[i]));

/*        If size of vector is 0, therefore there
        is no element with positive negative
        value, print "0"*/

        if (v.size() == 0)
            return;

/*        Sort the vector*/

        Collections.sort(v);

/*        Print the pair with negative positive
        value.*/

        for (int i = 0; i < v.size(); i++)
