        a.findPairs(arr);
    }
}

/*A Java program to find maximum length subarray with 0 sum*/

import java.util.HashMap;
class MaxLenZeroSumSub {

/*    Returns length of the maximum length subarray with 0 sum*/

    static int maxLen(int arr[])
    {

/*        Creates an empty hashMap hM*/

        HashMap<Integer, Integer> hM = new HashMap<Integer, Integer>();

/*Initialize sum of elements*/

int sum = 0;

/*Initialize result*/

int max_len = 0;

/*        Traverse through the given array*/

        for (int i = 0; i < arr.length; i++) {

/*            Add current element to sum*/

            sum += arr[i];
            if (arr[i] == 0 && max_len == 0)
                max_len = 1;
            if (sum == 0)
                max_len = i + 1;

/*            Look this sum in hash table*/

            Integer prev_i = hM.get(sum);
            if (prev_i != null)
                max_len = Math.max(max_len, i - prev_i);

/*Else put this sum in hash table*/

else 
                hM.put(sum, i);
        }
        return max_len;
    }

/*    Drive method*/

    public static void main(String arg[])
    {
        int arr[] = { 15, -2, 2, -8, 1, 7, 10, 23 };
        System.out.println("Length of the longest 0 sum subarray is "
                           + maxLen(arr));
    }
}

/*Java program to find length of the
longest increasing subsequence
whose adjacent element differ by 1*/

import java.util.*;
class lics {

/*function that returns the length of the
longest increasing subsequence
whose adjacent element differ by 1*/

    static int LongIncrConseqSubseq(int arr[], int n)
    {

/*        create hashmap to save latest consequent
        number as "key" and its length as "value"*/

        HashMap<Integer, Integer> map = new HashMap<>();

/*        put first element as "key" and its length as "value"*/

        map.put(arr[0], 1);

/*    iterate for all element*/

        for (int i = 1; i < n; i++) {

/*            check if last consequent of arr[i] exist or not*/

            if (map.containsKey(arr[i] - 1)) {

/*                put the updated consequent number
                and increment its value(length)*/

                map.put(arr[i], map.get(arr[i] - 1) + 1);
                map.remove(arr[i] - 1);
            }
            else {
                map.put(arr[i], 1);
            }
        }
        return Collections.max(map.values());
    }

/*    driver code*/

    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int arr[] = new int[n];
        for (int i = 0; i < n; i++)
            arr[i] = sc.nextInt();
        System.out.println(LongIncrConseqSubseq(arr, n));
    }
}

/*Java implementation to find longest subsequence
such that difference between adjacents is one*/

import java.util.*;
class GFG
{

/*function to find longest subsequence such
that difference between adjacents is one*/

static int longLenSub(int []arr, int n)
{

/*    hash table to map the array element with the
    length of the longest subsequence of which
    it is a part of and is the last element of
    that subsequence*/

    HashMap<Integer,
            Integer> um = new HashMap<Integer,
                                      Integer>();

/*    to store the longest length subsequence*/

    int longLen = 0;

/*    traverse the array elements*/

    for (int i = 0; i < n; i++)
    {

/*        initialize current length
        for element arr[i] as 0*/

        int len = 0;

/*        if 'arr[i]-1' is in 'um' and its length
        of subsequence is greater than 'len'*/

        if (um.containsKey(arr[i] - 1) &&
              len < um.get(arr[i] - 1))
              len = um.get(arr[i] - 1);

/*        if 'arr[i]+1' is in 'um' and its length
        of subsequence is greater than 'len'    */

        if (um.containsKey(arr[i] + 1) &&
              len < um.get(arr[i] + 1))
              len = um.get(arr[i] + 1);

/*        update arr[i] subsequence length in 'um'*/

        um. put(arr[i], len + 1);

/*        update longest length*/

        if (longLen < um.get(arr[i]))
            longLen = um.get(arr[i]);
    }

/*    required longest length subsequence*/

    return longLen;    
}

/*Driver Code*/

public static void main(String[] args)
{
    int[] arr = {1, 2, 3, 4, 5, 3, 2};
    int n = arr.length;
    System.out.println("Longest length subsequence = " +
                                    longLenSub(arr, n));
}
}

/*Java program to find longest
contiguous subsequence*/

import java.io.*;
import java.util.*;
class GFG
{

/*Returns length of the longest
contiguous subsequence*/

    static int findLongestConseqSubseq(int arr[],
                                           int n)
    {

/*        Sort the array*/

        Arrays.sort(arr);
        int ans = 0, count = 0;
        ArrayList<Integer> v = new ArrayList<Integer>();
        v.add(10);

/*        Insert repeated elements
        only once in the vector*/

        for (int i = 1; i < n; i++)
        {
            if (arr[i] != arr[i - 1])
                v.add(arr[i]);
        }

/*        Find the maximum length
        by traversing the array*/

        for (int i = 0; i < v.size(); i++)
        {

/*            Check if the current element is
            equal to previous element +1*/

            if (i > 0 &&v.get(i) == v.get(i - 1) + 1)
                count++;
            else
                count = 1;

/*            Update the maximum*/

            ans = Math.max(ans, count);
        }
        return ans;
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = { 1, 9, 3, 10, 4, 20, 2 };
        int n = arr.length;
        System.out.println(
            "Length of the Longest "
            + "contiguous subsequence is "
            + findLongestConseqSubseq(arr, n));
    }
}

/*Java program to find longest
consecutive subsequence*/

import java.io.*;
import java.util.*;
class ArrayElements {

/*    Returns length of the longest
    consecutive subsequence*/

    static int findLongestConseqSubseq(int arr[], int n)
    {
        HashSet<Integer> S = new HashSet<Integer>();
        int ans = 0;

/*        Hash all the array elements*/

        for (int i = 0; i < n; ++i)
            S.add(arr[i]);

/*        check each possible sequence from the start
        then update optimal length*/

        for (int i = 0; i < n; ++i)
        {

/*            if current element is the starting
            element of a sequence*/

            if (!S.contains(arr[i] - 1))
            {

/*                Then check for next elements
                in the sequence*/

                int j = arr[i];
                while (S.contains(j))
                    j++;

/*                update  optimal length if this
                length is more*/

                if (ans < j - arr[i])
                    ans = j - arr[i];
            }
        }
        return ans;
    }

/*    Driver Code*/

    public static void main(String args[])
    {
        int arr[] = { 1, 9, 3, 10, 4, 20, 2 };
        int n = arr.length;
        System.out.println(
            "Length of the Longest consecutive subsequence is "
            + findLongestConseqSubseq(arr, n));
    }
}

/*Java Program to find longest consecutive
subsequence This Program uses Priority Queue*/

import java.io.*;
import java.util.PriorityQueue;
public class Longset_Sub
{

/*    return the length of the longest
    subsequence of consecutive integers*/

    static int findLongestConseqSubseq(int arr[], int N)
    {
        PriorityQueue<Integer> pq
            = new PriorityQueue<Integer>();
        for (int i = 0; i < N; i++)
        {

/*            adding element from
            array to PriorityQueue*/

            pq.add(arr[i]);
        }

/*        Storing the first element
        of the Priority Queue
        This first element is also
        the smallest element*/

        int prev = pq.poll();

/*        Taking a counter variable with value 1*/

        int c = 1;

/*        Storing value of max as 1
        as there will always be
        one element*/

        int max = 1;
        for (int i = 1; i < N; i++)
        {

/*            check if current peek
            element minus previous
            element is greater then
            1 This is done because
            if it's greater than 1
            then the sequence
            doesn't start or is broken here*/

            if (pq.peek() - prev > 1)
            {

/*                Store the value of counter to 1
                As new sequence may begin*/

                c = 1;

/*                Update the previous position with the
                current peek And remove it*/

                prev = pq.poll();
            }

/*            Check if the previous
              element and peek are same*/

            else if (pq.peek() - prev == 0)
            {

/*                Update the previous position with the
                current peek And remove it*/

                prev = pq.poll();
            }

/*            if the difference
            between previous element and peek is 1*/

            else
            {

/*                Update the counter
                These are consecutive elements*/

                c++;

/*                Update the previous position
                  with the current peek And remove it*/

                prev = pq.poll();
            }

/*            Check if current longest
            subsequence is the greatest*/

            if (max < c)
            {

/*                Store the current subsequence count as
                max*/

                max = c;
            }
        }
        return max;
    }

/*    Driver Code*/

    public static void main(String args[])
        throws IOException
    {
        int arr[] = { 1, 9, 3, 10, 4, 20, 2 };
        int n = arr.length;
        System.out.println(
            "Length of the Longest consecutive subsequence is "
            + findLongestConseqSubseq(arr, n));
    }
}

/*Java implementation of longest continuous increasing
subsequence*/

import java.util.*;
class GFG 
{

/*Function for LIS*/

static void findLIS(int A[], int n)
{
    Map<Integer, Integer> hash = new HashMap<Integer, Integer>();

/*    Initialize result*/

    int LIS_size = 1;
    int LIS_index = 0;
    hash.put(A[0], 1);

/*    iterate through array and find
    end index of LIS and its Size*/

    for (int i = 1; i < n; i++) 
    {
        hash.put(A[i], hash.get(A[i] - 1)==null? 1:hash.get(A[i] - 1)+1);
        if (LIS_size < hash.get(A[i])) 
        {
            LIS_size = hash.get(A[i]);
            LIS_index = A[i];
        }
    }

/*    print LIS size*/

    System.out.println("LIS_size = " + LIS_size);

/*    print LIS after setting start element*/

    System.out.print("LIS : ");
    int start = LIS_index - LIS_size + 1;
    while (start <= LIS_index)
    {
        System.out.print(start + " ");
        start++;
    }
}

/*Driver code*/

public static void main(String[] args)
{
    int A[] = { 2, 5, 3, 7, 4, 8, 5, 13, 6 };
    int n = A.length;
    findLIS(A, n);
}
}

/*Java implementation to count subsets having
even numbers only and all are distinct*/

import java.util.*;
class GFG 
{

/*function to count the
required subsets*/

static int countSubsets(int arr[], int n)
{
    HashSet<Integer> us = new HashSet<>();
    int even_count = 0;

/*    inserting even numbers in the set 'us'
    single copy of each number is retained*/

    for (int i = 0; i < n; i++)
        if (arr[i] % 2 == 0)
            us.add(arr[i]);

/*    counting distinct even numbers*/

    even_count=us.size();

/*    total count of required subsets*/

    return (int) (Math.pow(2, even_count) - 1);
}

/*Driver code*/

public static void main(String[] args) 
{
    int arr[] = {4, 2, 1, 9, 2, 6, 5, 3};
    int n = arr.length;
    System.out.println("Number of subsets = "
        + countSubsets(arr, n));
}
}

/*Simple Java program to count distinct elements in every
window of size k*/

import java.util.Arrays;
class Test {

/*    Counts distinct elements in window of size k*/

    static int countWindowDistinct(int win[], int k)
    {
        int dist_count = 0;

/*        Traverse the window*/

        for (int i = 0; i < k; i++) {

/*            Check if element arr[i] exists in arr[0..i-1]*/

            int j;
            for (j = 0; j < i; j++)
                if (win[i] == win[j])
                    break;
            if (j == i)
                dist_count++;
        }
        return dist_count;
    }

/*    Counts distinct elements in all windows of size k*/

    static void countDistinct(int arr[], int n, int k)
    {

/*        Traverse through every window*/

        for (int i = 0; i <= n - k; i++)
            System.out.println(countWindowDistinct(Arrays.copyOfRange(arr, i, arr.length), k));
    }

/*    Driver method*/

    public static void main(String args[])
    {
        int arr[] = { 1, 2, 1, 3, 4, 2, 3 }, k = 4;
        countDistinct(arr, arr.length, k);
    }
}

/*Java program to find the maximum
possible sum of a window in one
array such that elements in same
window of other array are unique.*/

import java.util.HashSet;
import java.util.Set;
public class MaxPossibleSuminWindow
{

/*    Function to return maximum sum of window
    in A[] according to given constraints.*/

    static int returnMaxSum(int A[], int B[], int n)
    {

/*        Map is used to store elements
        and their counts.*/

        Set<Integer> mp = new HashSet<Integer>();

/*Initialize result*/

int result = 0;

/*        calculating the maximum possible
        sum for each subarray containing
        unique elements.*/

        int curr_sum = 0, curr_begin = 0;
        for (int i = 0; i < n; ++i)
        {

/*            Remove all duplicate
            instances of A[i] in
            current window.*/

            while (mp.contains(A[i]))
            {
                mp.remove(A[curr_begin]);
                curr_sum -= B[curr_begin];
                curr_begin++;
            }

/*            Add current instance of A[i]
            to map and to current sum.*/

            mp.add(A[i]);
            curr_sum += B[i];

/*            Update result if current
            sum is more.*/

            result = Integer.max(result, curr_sum);
        }
        return result;
    }

/*    Driver Code to test above method*/

    public static void main(String[] args)
    {
        int A[] = { 0, 1, 2, 3, 0, 1, 4 };
        int B[] = { 9, 8, 1, 2, 3, 4, 5 };
        int n = A.length;
        System.out.println(returnMaxSum(A, B, n));
    }
}

/*Sorting based Java implementation
to check whether the array
contains a set of contiguous
integers*/

import java.util.*;
class GFG {

/*    function to check whether
    the array contains a set
    of contiguous integers*/

    static boolean areElementsContiguous(int arr[],
                                             int n)
    {

/*       Sort the array*/

       Arrays.sort(arr);

/*       After sorting, check if
       current element is either
       same as previous or is
       one more.*/

       for (int i = 1; i < n; i++)
         if (arr[i] - arr[i-1] > 1)
              return false;
       return true;   
    }

/* Driver program to test above function */

