    }
}

/*Java implementation to
check whether the array
contains a set of
contiguous integers*/

import java.util.*;
class GFG {

/*    function to check
    whether the array
    contains a set of
    contiguous integers*/

    static boolean areElementsContiguous(int arr[],
                                         int n)
    {

/*        Find maximum and
        minimum elements.*/

        int max = Integer.MIN_VALUE;
        int min = Integer.MAX_VALUE;
        for(int i = 0; i < n; i++)
        {
            max = Math.max(max, arr[i]);
            min = Math.min(min, arr[i]);
        }
        int m = max - min + 1;

/*        There should be at least
        m elements in aaray to
        make them contiguous.*/

        if (m > n)
            return false;

/*        Create a visited array
        and initialize false.*/

        boolean  visited[] = new boolean[n];

/*        Mark elements as true.*/

        for (int i = 0; i < n; i++)   
           visited[arr[i] - min] = true;

/*        If any element is not
        marked, all elements
        are not contiguous.*/

        for (int i = 0; i < m; i++)
           if (visited[i] == false)
                return false;
        return true;
    }

/* Driver program  */

    public static void main(String[] args)
    {
        int arr[] = { 5, 2, 3, 6,
                      4, 4, 6, 6 };
        int n = arr.length;
        if (areElementsContiguous(arr, n))
            System.out.println("Yes");
        else
            System.out.println("No");
      }
}

/*Java implementation to check whether the array
contains a set of contiguous integers*/

import java.io.*;
import java.util.*;
class GFG {

/*    Function to check whether the array
    contains a set of contiguous integers*/

    static Boolean areElementsContiguous(int arr[], int n)
    {

/*        Storing elements of 'arr[]' in
        a hash table 'us'*/

        HashSet<Integer> us = new HashSet<Integer>();
        for (int i = 0; i < n; i++)
            us.add(arr[i]);

/*        As arr[0] is present in 'us'*/

        int count = 1;

/*        Starting with previous smaller
        element of arr[0]*/

        int curr_ele = arr[0] - 1;

/*        If 'curr_ele' is present in 'us'*/

        while (us.contains(curr_ele) == true) {

/*            increment count*/

            count++;

/*            update 'curr_ele"*/

            curr_ele--;
        }

/*        Starting with next greater
        element of arr[0]*/

        curr_ele = arr[0] + 1;

/*        If 'curr_ele' is present in 'us'*/

        while (us.contains(curr_ele) == true) {

/*            increment count*/

            count++;

/*            update 'curr_ele"*/

            curr_ele++;
        }

/*        Returns true if array contains a set of
        contiguous integers else returns false*/

        return (count == (us.size()));
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        int arr[] = { 5, 2, 3, 6, 4, 4, 6, 6 };
        int n = arr.length;
        if (areElementsContiguous(arr, n))
            System.out.println("Yes");
        else
            System.out.println("No");
    }
}

/*Java program to print subarray with sum as given sum*/

import java.util.*;
class GFG {

/*Function to print subarray with sum as given sum*/

    public static void subArraySum(int[] arr, int n, int sum) {

/*        cur_sum to keep track of cummulative sum till that point*/

        int cur_sum = 0;
        int start = 0;
        int end = -1;
        HashMap<Integer, Integer> hashMap = new HashMap<>();
        for (int i = 0; i < n; i++) {
            cur_sum = cur_sum + arr[i];

/*            check whether cur_sum - sum = 0, if 0 it means
            the sub array is starting from index 0- so stop*/

            if (cur_sum - sum == 0) {
                start = 0;
                end = i;
                break;
            }

/*            if hashMap already has the value, means we already
            have subarray with the sum - so stop*/

            if (hashMap.containsKey(cur_sum - sum)) {
                start = hashMap.get(cur_sum - sum) + 1;
                end = i;
                break;
            }

/*            if value is not present then add to hashmap*/

            hashMap.put(cur_sum, i);
        }

/*        if end is -1 : means we have reached end without the sum*/

        if (end == -1) {
            System.out.println("No subarray with given sum exists");
        } else {
            System.out.println("Sum found between indexes "
                            + start + " to " + end);
        }
    }

/*    Driver code*/

    public static void main(String[] args) {
        int[] arr = {10, 2, -2, -20, 10};
        int n = arr.length;
        int sum = -10;
        subArraySum(arr, n, sum);
    }
}

/*Java program to find minimum number
of insertions to make a string
palindrome*/

public class Palindrome {

/*    Function will return number of
    characters to be added*/

    static int minInsertion(String str)
    {

/*        To store string length*/

        int n = str.length();

/*        To store number of characters
        occurring odd number of times*/

        int res = 0;

/*        To store count of each
        character*/

        int[] count = new int[26];

/*        To store occurrence of each
        character*/

        for (int i = 0; i < n; i++)
            count[str.charAt(i) - 'a']++;

/*        To count characters with odd
        occurrence*/

        for (int i = 0; i < 26; i++) {
            if (count[i] % 2 == 1)
                res++;
        }

/*        As one character can be odd return
        res - 1 but if string is already
        palindrome return 0*/

        return (res == 0) ? 0 : res - 1;
    }

/*    Driver program*/

    public static void main(String[] args)
    {
        String str = "geeksforgeeks";
        System.out.println(minInsertion(str));
    }
}

/*Java program to find maximum difference
between frequency of any two element
such that element with greater frequency
is also greater in value.*/

import java.util.*;
class GFG
{

/*Return the maximum difference between
frequencies of any two elements such that
element with greater frequency is also
greater in value.*/

static int maxdiff(int arr[], int n)
{
    Map<Integer, Integer> freq = new HashMap<>();

/*    Finding the frequency of each element.*/

    for (int i = 0; i < n; i++)
        freq.put(arr[i],
        freq.get(arr[i]) == null ? 1 :
        freq.get(arr[i]) + 1);
    int ans = 0;
    for (int i = 0; i < n; i++)
    {
        for (int j = 0; j < n; j++)
        {

/*            finding difference such that element
            having greater frequency is also
            greater in value.*/

            if (freq.get(arr[i]) > freq.get(arr[j]) &&
                arr[i] > arr[j])
                ans = Math.max(ans, freq.get(arr[i]) -
                                    freq.get(arr[j]));
            else if (freq.get(arr[i]) < freq.get(arr[j]) &&
                    arr[i] < arr[j] )
                ans = Math.max(ans, freq.get(arr[j]) -
                                    freq.get(arr[i]));
        }
    }
    return ans;
}

/*Driver Code*/

public static void main(String[] args)
{
    int arr[] = { 3, 1, 3, 2, 3, 2 };
    int n = arr.length;
    System.out.println(maxdiff(arr, n));
}
}

/*Efficient Java program to find maximum
difference between frequency of any two
elements such that element with greater
frequency is also greater in value.*/

import java.util.*;
class GFG
{

/*  Return the maximum difference between
  frequencies of any two elements such that
  element with greater frequency is also
  greater in value.*/

  static int maxdiff(int arr[], int n)
  {
    HashMap<Integer,Integer> freq= new HashMap<>();
    int []dist = new int[n];

/*    Finding the frequency of each element.*/

    int j = 0;
    for (int i = 0; i < n; i++)
    {
      dist[j++] = arr[i];
      if (!freq.containsKey(arr[i]))
        freq.put(arr[i], 1);
      else
        freq.put(arr[i], freq.get(arr[i]) + 1);
    }

/*    Sorting the distinct element*/

    Arrays.sort(dist);
    int min_freq = n + 1;

/*    Iterate through all sorted distinct elements.
    For each distinct element, maintaining the
    element with minimum frequency than that
    element and also finding the maximum
    frequency difference*/

    int ans = 0;
    for (int i = 0; i < j; i++)
    {
      int cur_freq = freq.get(dist[i]);
      ans = Math.max(ans, cur_freq - min_freq);
      min_freq = Math.min(min_freq, cur_freq);
    }
    return ans;
  }

/*  Driven Program*/

  public static void main(String[] args)
  {
    int arr[] = { 3, 1, 3, 2, 3, 2 };
    int n = arr.length;
    System.out.print(maxdiff(arr, n) +"\n");
  }
}

/*JAVA Code for Difference between
highest and least frequencies
in an array*/

import java.util.*;
class GFG {
    static int findDiff(int arr[], int n)
    {

/*        sort the array*/

        Arrays.sort(arr);
        int count = 0, max_count = 0,
            min_count = n;
        for (int i = 0; i < (n - 1); i++) {

/*            checking consecutive elements*/

            if (arr[i] == arr[i + 1]) {
                count += 1;
                continue;
            }
            else {
                max_count = Math.max(max_count,
                                     count);
                min_count = Math.min(min_count,
                                     count);
                count = 0;
            }
        }
        return (max_count - min_count);
    }

/*    Driver program to test above function*/

    public static void main(String[] args)
    {
        int arr[] = { 7, 8, 4, 5, 4, 1,
                      1, 7, 7, 2, 5 };
        int n = arr.length;
        System.out.println(findDiff(arr, n));
    }
}

/*Java code to find the difference between highest
and least frequencies*/

import java.util.*;
class GFG
{
static int findDiff(int arr[], int n)
{

/*    Put all elements in a hash map*/

    Map<Integer,Integer> mp = new HashMap<>();
    for (int i = 0 ; i < n; i++)
    {
        if(mp.containsKey(arr[i]))
        {
            mp.put(arr[i], mp.get(arr[i])+1);
        }
        else
        {
            mp.put(arr[i], 1);
        }
    }

/*    Find counts of maximum and minimum
    frequent elements*/

    int max_count = 0, min_count = n;
    for (Map.Entry<Integer,Integer> x : mp.entrySet())
    {
        max_count = Math.max(max_count, x.getValue());
        min_count = Math.min(min_count, x.getValue());
    }
    return (max_count - min_count);
}

/*Driver code*/

public static void main(String[] args)
{
    int arr[] = { 7, 8, 4, 5, 4, 1, 1, 7, 7, 2, 5 };
    int n = arr.length;
    System.out.println(findDiff(arr, n));
}
}

/*java find maximum difference
of subset sum*/

import java .io.*;
public class GFG {

/*    function for maximum subset diff*/

    static int maxDiff(int []arr, int n)
    {
        int SubsetSum_1 = 0, SubsetSum_2 = 0;
        for (int i = 0; i <= n - 1; i++)
        {
            boolean isSingleOccurance = true;
            for (int j = i + 1; j <= n - 1; j++)
            {

/*                if frequency of any element
                is two make both equal to
                zero*/

                if (arr[i] == arr[j])
                {
                    isSingleOccurance = false;
                    arr[i] = arr[j] = 0;
                    break;
                }
            }
            if (isSingleOccurance)
            {
                if (arr[i] > 0)
                    SubsetSum_1 += arr[i];
                else
                    SubsetSum_2 += arr[i];
            }
        }
        return Math.abs(SubsetSum_1 - SubsetSum_2);
    }

/*    driver program*/

    static public void main (String[] args)
    {
        int []arr = { 4, 2, -3, 3, -2, -2, 8 };
        int n = arr.length;
        System.out.println("Maximum Difference = "
                               + maxDiff(arr, n));
    }
}

