public class GFG {

/*    function for maximum subset diff*/

    static int maxDiff(int []arr, int n)
    {
        int result = 0;

/*        sort the array*/

        Arrays.sort(arr);

/*        calculate the result*/

        for (int i = 0; i < n - 1; i++)
        {
            if (arr[i] != arr[i + 1])
                result += Math.abs(arr[i]);
            else
                i++;
        }

/*        check for last element*/

        if (arr[n - 2] != arr[n - 1])
            result += Math.abs(arr[n - 1]);

/*        return result*/

        return result;
    }

