/*Java find maximum
difference of subset sum*/

import java.util.*;
class GFG{

/*Function for maximum subset diff*/

public static int maxDiff(int arr[],
                          int n)
{
  HashMap<Integer,
          Integer> hashPositive = new HashMap<>();
  HashMap<Integer,
          Integer> hashNegative = new HashMap<>();
  int SubsetSum_1 = 0,
      SubsetSum_2 = 0;

/*  Construct hash for
  positive elements*/

  for (int i = 0; i <= n - 1; i++)
  {
    if (arr[i] > 0)
    {
      if(hashPositive.containsKey(arr[i]))
      {
        hashPositive.replace(arr[i],
        hashPositive.get(arr[i]) + 1);
      }
      else
      {
        hashPositive.put(arr[i], 1);
      }
    }
  }

/*  Calculate subset sum
  for positive elements*/

  for (int i = 0; i <= n - 1; i++)
  {
    if(arr[i] > 0 &&
       hashPositive.containsKey(arr[i]))
    {
      if(hashPositive.get(arr[i]) == 1)
      {
        SubsetSum_1 += arr[i];
      }
    }
  }

/*  Construct hash for
  negative elements*/

  for (int i = 0; i <= n - 1; i++)
  {
    if (arr[i] < 0)
    {
      if(hashNegative.containsKey(Math.abs(arr[i])))
      {
        hashNegative.replace(Math.abs(arr[i]),
        hashNegative.get(Math.abs(arr[i])) + 1);
      }
      else
      {
        hashNegative.put(Math.abs(arr[i]), 1);
      }
    }
  }

/*  Calculate subset sum for
  negative elements*/

  for (int i = 0; i <= n - 1; i++)
  {
    if (arr[i] < 0 &&
        hashNegative.containsKey(Math.abs(arr[i])))
    {
      if(hashNegative.get(Math.abs(arr[i])) == 1)
      {
        SubsetSum_2 += arr[i];
      }
    }
  }
  return Math.abs(SubsetSum_1 - SubsetSum_2);
}

/*Driver code*/

public static void main(String[] args)
{
  int arr[] = {4, 2, -3, 3,
               -2, -2, 8};
  int n = arr.length;
  System.out.print("Maximum Difference = " +
                    maxDiff(arr, n));
}
}

/*Java program to find minimum
range that contains exactly
k distinct numbers.*/

import java.util.*;
class GFG
{

/*Prints the minimum range
that contains exactly k
distinct numbers.*/

static void minRange(int arr[],
                     int n, int k)
{
    int l = 0, r = n;

/*    Consider every element
    as starting point.*/

    for (int i = 0; i < n; i++)
    {

/*        Find the smallest window
        starting with arr[i] and
        containing exactly k
        distinct elements.*/

        Set<Integer> s = new HashSet<Integer>();
        int j;
        for (j = i; j < n; j++)
        {
            s.add(arr[j]);
            if (s.size() == k)
            {
                if ((j - i) < (r - l))
                {
                    r = j;
                    l = i;
                }
                break;
            }
        }

/*        There are less than k
        distinct elements now,
        so no need to continue.*/

        if (j == n)
            break;
    }

/*    If there was no window
    with k distinct elements
    (k is greater than total
    distinct elements)*/

    if (l == 0 && r == n)
        System.out.println("Invalid k");
    else
        System.out.println(l + " " + r);
}

/*Driver code*/

public static void main(String args[])
{
    int arr[] = { 1, 2, 3, 4, 5 };
    int n = arr.length;
    int k = 3;
    minRange(arr, n, k);
}
}

/*Java program to find minimum range that
contains exactly k distinct numbers.*/

import java.util.*;
class GFG{

/*Prints the minimum range that contains exactly
k distinct numbers.*/

static void minRange(int arr[], int n, int k)
{

/*    Initially left and right side is -1 and -1,
    number of distinct elements are zero and
    range is n.*/

    int l = 0, r = n;

/*    Initialize right side*/

    int j = -1;
    HashMap<Integer, Integer> hm = new HashMap<>();
    for(int i = 0; i < n; i++)
    {
        while (j < n)
        {

/*            Increment right side.*/

            j++;

/*            If number of distinct elements less
            than k.*/

            if (j < n && hm.size() < k)
                hm.put(arr[j],
                       hm.getOrDefault(arr[j], 0) + 1);

/*            If distinct elements are equal to k
            and length is less than previous length.*/

            if (hm.size() == k &&
                 ((r - l) >= (j - i)))
            {
                l = i;
                r = j;
                break;
            }
        }

/*        If number of distinct elements less
        than k, then break.*/

        if (hm.size() < k)
            break;

/*        If distinct elements equals to k then
        try to increment left side.*/

        while (hm.size() == k)
        {
            if (hm.getOrDefault(arr[i], 0) == 1)
                hm.remove(arr[i]);
            else
                hm.put(arr[i],
                       hm.getOrDefault(arr[i], 0) - 1);

/*            Increment left side.*/

            i++;

/*            It is same as explained in above loop.*/

            if (hm.size() == k &&
                  (r - l) >= (j - i))
            {
                l = i;
                r = j;
            }
        }
        if (hm.getOrDefault(arr[i], 0) == 1)
            hm.remove(arr[i]);
        else
            hm.put(arr[i],
                hm.getOrDefault(arr[i], 0) - 1);
    }
    if (l == 0 && r == n)
        System.out.println("Invalid k");
    else
        System.out.println(l + " " + r);
}

/*Driver code*/

public static void main(String[] args)
{
    int arr[] = { 1, 1, 2, 2, 3, 3, 4, 5 };
    int n = arr.length;
    int k = 3;
    minRange(arr, n, k);
}
}

/*Java program to find longest subarray with
k or less distinct elements.*/

import java.util.*;
class GFG
{

/*function to print the longest sub-array*/

static void longest(int a[], int n, int k)
{
    int[] freq = new int[7];
    int start = 0, end = 0, now = 0, l = 0;
    for (int i = 0; i < n; i++)
    {

/*        mark the element visited*/

        freq[a[i]]++;

/*        if its visited first time, then increase
        the counter of distinct elements by 1*/

        if (freq[a[i]] == 1)
            now++;

/*        When the counter of distinct elements
        increases from k, then reduce it to k*/

        while (now > k)
        {

/*            from the left, reduce the number of
            time of visit*/

            freq[a[l]]--;

/*            if the reduced visited time element
            is not present in further segment
            then decrease the count of distinct
            elements*/

            if (freq[a[l]] == 0)
                now--;

/*            increase the subsegment mark*/

            l++;
        }

/*        check length of longest sub-segment
        when greater then previous best
        then change it*/

        if (i - l + 1 >= end - start + 1)
        {
            end = i;
            start = l;
        }
    }

/*    print the longest sub-segment*/

    for (int i = start; i <= end; i++)
        System.out.print(a[i]+" ");
}

/*Driver code*/

public static void main(String args[])
{
    int a[] = { 6, 5, 1, 2, 3, 2, 1, 4, 5 };
    int n = a.length;
    int k = 3;
    longest(a, n, k);
}
}

/*Java program to calculate 
the sum of f(a[i], aj])*/

import java.util.*;
public class GfG {

/*    Function to calculate the sum*/

    public static int sum(int a[], int n)
    {

/*        Map to keep a count of occurrences*/

        Map<Integer,Integer> cnt = new HashMap<Integer,Integer>();

/*        Traverse in the list from start to end
        number of times a[i] can be in a pair and
        to get the difference we subtract pre_sum*/

        int ans = 0, pre_sum = 0;
        for (int i = 0; i < n; i++) {
            ans += (i * a[i]) - pre_sum;
            pre_sum += a[i];

/*            If the (a[i]-1) is present then subtract
            that value as f(a[i], a[i]-1) = 0*/

            if (cnt.containsKey(a[i] - 1))
                ans -= cnt.get(a[i] - 1);

/*            If the (a[i]+1) is present then
            add that value as f(a[i], a[i]-1)=0
            here we add as a[i]-(a[i]-1)<0 which would
            have been added as negative sum, so we add
            to remove this pair from the sum value*/

            if (cnt.containsKey(a[i] + 1))
                ans += cnt.get(a[i] + 1);

/*            keeping a counter for every element*/

            if(cnt.containsKey(a[i])) {
                cnt.put(a[i], cnt.get(a[i]) + 1);
            }
            else {
                cnt.put(a[i], 1);
            }
        }
        return ans;
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int a[] = { 1, 2, 3, 1, 3 };
        int n = a.length;
        System.out.println(sum(a, n));
    }
}

/*Java program to find number
of pairs in an array such
that their XOR is 0*/

import java.util.*;
class GFG
{

/*    Function to calculate
    the count*/

    static int calculate(int a[], int n)
    {

/*        Sorting the list using
        built in function*/

        Arrays.sort(a);
        int count = 1;
        int answer = 0;

/*        Traversing through the
        elements*/

        for (int i = 1; i < n; i++)
        {
            if (a[i] == a[i - 1])
            {

/*                Counting frequency of each
                elements*/

                count += 1;
            }
            else
            {

/*                Adding the contribution of
                the frequency to the answer*/

                answer = answer + (count * (count - 1)) / 2;
                count = 1;
            }
        }
        answer = answer + (count * (count - 1)) / 2;
        return answer;
    }

/*    Driver Code*/

    public static void main (String[] args)
    {
        int a[] = { 1, 2, 1, 2, 4 };
        int n = a.length;

/*        Print the count*/

        System.out.println(calculate(a, n));
    }
}

/*Java program to find number of pairs
in an array such that their XOR is 0*/

import java.util.*;
class GFG
{

/*    Function to calculate the answer*/

    static int calculate(int a[], int n)
    {

/*        Finding the maximum of the array*/

        int maximum = Arrays.stream(a).max().getAsInt();

/*        Creating frequency array
        With initial value 0*/

        int frequency[] = new int[maximum + 1];

/*        Traversing through the array*/

        for (int i = 0; i < n; i++)
        {

/*            Counting frequency*/

            frequency[a[i]] += 1;
        }
        int answer = 0;

/*        Traversing through the frequency array*/

        for (int i = 0; i < (maximum) + 1; i++)
        {

/*            Calculating answer*/

            answer = answer + frequency[i] * (frequency[i] - 1);
        }
        return answer / 2;
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        int a[] = {1, 2, 1, 2, 4};
        int n = a.length;

/*        Function calling*/

        System.out.println(calculate(a, n));
    }
}

class LargestSubArray {

/*    This function Prints the starting and ending
    indexes of the largest subarray with equal
    number of 0s and 1s. Also returns the size
    of such subarray.*/

    int findSubArray(int arr[], int n)
    {
        int sum = 0;
        int maxsize = -1, startindex = 0;
        int endindex = 0;

/*        Pick a starting point as i*/

        for (int i = 0; i < n - 1; i++) {
            sum = (arr[i] == 0) ? -1 : 1;

/*            Consider all subarrays starting from i*/

            for (int j = i + 1; j < n; j++) {
                if (arr[j] == 0)
                    sum += -1;
                else
                    sum += 1;

/*                If this is a 0 sum subarray, then
                compare it with maximum size subarray
                calculated so far*/

                if (sum == 0 && maxsize < j - i + 1) {
                    maxsize = j - i + 1;
                    startindex = i;
                }
            }
        }
        endindex = startindex + maxsize - 1;
        if (maxsize == -1)
            System.out.println("No such subarray");
        else
            System.out.println(startindex + " to " + endindex);
        return maxsize;
    }

/* Driver program to test the above functions */

    public static void main(String[] args)
    {
        LargestSubArray sub;
        sub = new LargestSubArray();
        int arr[] = { 1, 0, 0, 1, 0, 1, 1 };
        int size = arr.length;
        sub.findSubArray(arr, size);
    }
}

/*Java implementation to count subarrays with
equal number of 1's and 0's*/

import java.util.*;
class GFG
{

/*function to count subarrays with
equal number of 1's and 0's*/

static int countSubarrWithEqualZeroAndOne(int arr[], int n)
{

/*    'um' implemented as hash table to store
    frequency of values obtained through
    cumulative sum*/

    Map<Integer,Integer> um = new HashMap<>();
    int curr_sum = 0;

/*    Traverse original array and compute cumulative
    sum and increase count by 1 for this sum
    in 'um'. Adds '-1' when arr[i] == 0*/

    for (int i = 0; i < n; i++) {
        curr_sum += (arr[i] == 0) ? -1 : arr[i];
        um.put(curr_sum, um.get(curr_sum)==null?1:um.get(curr_sum)+1);
    }
    int count = 0;

/*    traverse the hash table 'um'*/

    for (Map.Entry<Integer,Integer> itr : um.entrySet())
    {

/*        If there are more than one prefix subarrays
        with a particular sum*/

        if (itr.getValue() > 1)
            count += ((itr.getValue()* (itr.getValue()- 1)) / 2);
    }

/*    add the subarrays starting from 1st element and
    have equal number of 1's and 0's*/

    if (um.containsKey(0))
        count += um.get(0);

/*    required count of subarrays*/

    return count;
}

/*Driver program to test above*/

public static void main(String[] args)
{
    int arr[] = { 1, 0, 0, 1, 0, 1, 1 };
    int n = arr.length;
    System.out.println("Count = "
        + countSubarrWithEqualZeroAndOne(arr, n));
}
}

/*Java implementation to find the length of
longest subarray having count of 1's one
more than count of 0's*/

import java.util.*;
class GFG
{

/*function to find the length of longest
subarray having count of 1's one more
than count of 0's*/

static int lenOfLongSubarr(int arr[], int n)
{

/*    unordered_map 'um' implemented as
    hash table*/

    HashMap<Integer,
            Integer> um = new HashMap<Integer,
                                      Integer>();
    int sum = 0, maxLen = 0;

/*    traverse the given array*/

    for (int i = 0; i < n; i++)
    {

/*        consider '0' as '-1'*/

        sum += arr[i] == 0 ? -1 : 1;

/*        when subarray starts form index '0'*/

        if (sum == 1)
            maxLen = i + 1;

/*        make an entry for 'sum' if it is
        not present in 'um'*/

        else if (!um.containsKey(sum))
            um. put(sum, i);

/*        check if 'sum-1' is present in 'um'
        or not*/

        if (um.containsKey(sum - 1))
        {

/*            update maxLength*/

            if (maxLen < (i - um.get(sum - 1)))
                maxLen = i - um.get(sum - 1);
        }
    }

/*    required maximum length*/

    return maxLen;
}

/*Driver Code*/

public static void main(String[] args)
{
    int arr[] = { 0, 1, 1, 0, 0, 1 };
    int n = arr.length;
    System.out.println("Length = " +
               lenOfLongSubarr(arr, n));
}
}

/*Java program to print all
triplets in given array
that form Arithmetic
Progression*/

import java.io.*;
import java.util.*;
class GFG
{

/*    Function to print
    all triplets in
    given sorted array
    that forms AP*/

    static void printAllAPTriplets(int []arr,
                                   int n)
    {
        ArrayList<Integer> s =
                 new ArrayList<Integer>();
        for (int i = 0;
                 i < n - 1; i++)
        {
            for (int j = i + 1; j < n; j++)
            {

/*                Use hash to find if
                there is a previous
                element with difference
                equal to arr[j] - arr[i]*/

                int diff = arr[j] - arr[i];
                boolean exists =
                        s.contains(arr[i] - diff);
                if (exists)
                    System.out.println(arr[i] - diff +
                                        " " + arr[i] +
                                        " " + arr[j]);
            }
        s.add(arr[i]);
        }
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int []arr = {2, 6, 9, 12, 17,
                     22, 31, 32, 35, 42};
        int n = arr.length;
        printAllAPTriplets(arr, n);
    }
}

/*Java implementation to print
all the triplets in given array
that form Arithmetic Progression*/

import java.io.*;
class GFG
{

/*    Function to print all triplets in
    given sorted array that forms AP*/

    static void findAllTriplets(int arr[], int n)
    {
        for (int i = 1; i < n - 1; i++)
        {

/*            Search other two elements
            of AP with arr[i] as middle.*/

            for (int j = i - 1, k = i + 1; j >= 0 && k < n;)
            {

/*                if a triplet is found*/

                if (arr[j] + arr[k] == 2 * arr[i])
                {
                    System.out.println(arr[j] +" " +
                                       arr[i]+ " " + arr[k]);

/*                    Since elements are distinct,
                    arr[k] and arr[j] cannot form
                    any more triplets with arr[i]*/

                    k++;
                    j--;
                }

/*                If middle element is more move to
                higher side, else move lower side.*/

                else if (arr[j] + arr[k] < 2 * arr[i])
                    k++;        
                else
                    j--;        
            }
        }
    }

/*    Driver code*/

    public static void main (String[] args)
    {
        int arr[] = { 2, 6, 9, 12, 17,
                      22, 31, 32, 35, 42 };
        int n = arr.length;
        findAllTriplets(arr, n);
    }
}

/*Java program to count triplets with given
product m*/

class GFG {

/*    Method to count such triplets*/

    static int countTriplets(int arr[], int n, int m)
    {
        int count = 0;

/*        Consider all triplets and count if
        their product is equal to m*/

        for (int i = 0; i < n - 2; i++)
            for (int j = i + 1; j < n - 1; j++)
                for (int k = j + 1; k < n; k++)
                    if (arr[i] * arr[j] * arr[k] == m)
                        count++;
        return count;
    }

/*    Driver method*/

    public static void main(String[] args)
    {
        int arr[] = { 1, 4, 6, 2, 3, 8 };
        int m = 24;
        System.out.println(countTriplets(arr, arr.length, m));
    }
}

/*Java program to count triplets with given
product m*/

import java.util.HashMap;
class GFG {

/*    Method to count such triplets*/

    static int countTriplets(int arr[], int n, int m)
    {

/*        Store all the elements in a set*/

        HashMap<Integer, Integer> occ = new HashMap<Integer, Integer>(n);
        for (int i = 0; i < n; i++)
            occ.put(arr[i], i);
        int count = 0;

/*        Consider all pairs and check for a
        third number so their product is equal to m*/

        for (int i = 0; i < n - 1; i++) {
            for (int j = i + 1; j < n; j++) {

/*                Check if current pair divides m or not
                If yes, then search for (m / arr[i]*arr[j])*/

                if ((arr[i] * arr[j] <= m) && (arr[i] * arr[j] != 0) && (m % (arr[i] * arr[j]) == 0)) {
                    int check = m / (arr[i] * arr[j]);
                    occ.containsKey(check);

/*                    Check if the third number is present
                    in the map and it is not equal to any
                    other two elements and also check if
                    this triplet is not counted already
                    using their indexes*/

                    if (check != arr[i] && check != arr[j]
                        && occ.containsKey(check) && occ.get(check) > i
                        && occ.get(check) > j)
                        count++;
                }
            }
        }

/*        Return number of triplets*/

        return count;
    }

/*    Driver method*/

    public static void main(String[] args)
    {
        int arr[] = { 1, 4, 6, 2, 3, 8 };
        int m = 24;
        System.out.println(countTriplets(arr, arr.length, m));
    }
}

