having total distinct elements same as that
original array.*/

import java.util.HashMap;
class Test
{

/*    Method to calculate distinct sub-array*/

    static int countDistictSubarray(int arr[], int n)
    {

/*        Count distinct elements in whole array*/

        HashMap<Integer, Integer>  vis = new HashMap<Integer,Integer>(){
            @Override
            public Integer get(Object key) {
                if(!containsKey(key))
                    return 0;
                return super.get(key);
            }
        };
        for (int i = 0; i < n; ++i)
            vis.put(arr[i], 1);
        int k = vis.size();

/*        Reset the container by removing all elements*/

        vis.clear();

/*        Use sliding window concept to find
        count of subarrays having k distinct
        elements.*/

        int ans = 0, right = 0, window = 0;
        for (int left = 0; left < n; ++left)
        {
            while (right < n && window < k)
            {
                vis.put(arr[right], vis.get(arr[right]) + 1);
                if (vis.get(arr[right])== 1)
                    ++window;
                ++right;
            }

/*            If window size equals to array distinct
            element size, then update answer*/

            if (window == k)
                ans += (n - right + 1);

/*            Decrease the frequency of previous element
            for next sliding window*/

            vis.put(arr[left], vis.get(arr[left]) - 1);

/*            If frequency is zero then decrease the
            window size*/

            if (vis.get(arr[left]) == 0)
                    --window;
        }
        return ans;
    }

/*    Driver method*/

    public static void main(String args[])
    {
        int arr[] = {2, 1, 3, 2, 3};
        System.out.println(countDistictSubarray(arr, arr.length));
    }
}

/*Java program to find total
number of even-odd subarrays
present in given array*/

class GFG {

/*    function that returns the
    count of subarrays that
    contain equal number of
    odd as well as even numbers*/

    static int countSubarrays(int[] arr,
            int n) {

/*        initialize difference
        and answer with 0*/

        int difference = 0;
        int ans = 0;

/*        create two auxiliary hash
        arrays to count frequency
        of difference, one array
        for non-negative difference
        and other array for negative
        difference. Size of these
        two auxiliary arrays is 'n+1'
        because difference can
        reach maximum value 'n' as
        well as minimum value '-n'*/

/*        initialize these
        auxiliary arrays with 0*/

        int[] hash_positive = new int[n + 1];
        int[] hash_negative = new int[n + 1];

/*        since the difference is
        initially 0, we have to
        initialize hash_positive[0] with 1*/

        hash_positive[0] = 1;

/*        for loop to iterate
        through whole array
        (zero-based indexing is used)*/

        for (int i = 0; i < n; i++) {

/*            incrementing or decrementing
            difference based on
            arr[i] being even or odd,
            check if arr[i] is odd*/

            if ((arr[i] & 1) == 1) {
                difference++;
            } else {
                difference--;
            }

/*            adding hash value of 'difference'
            to our answer as all the previous
            occurrences of the same difference
            value will make even-odd subarray
            ending at index 'i'. After that,
            we will increment hash array for
            that 'difference' value for its
            occurrence at index 'i'. if
            difference is negative then use
            hash_negative*/

            if (difference < 0) {
                ans += hash_negative[-difference];
                hash_negative[-difference]++;

/*else use hash_positive*/

} 
            else {
                ans += hash_positive[difference];
                hash_positive[difference]++;
            }
        }

/*        return total number
        of even-odd subarrays*/

        return ans;
    }

/*    Driver code*/

    public static void main(String[] args) {
        int[] arr = new int[]{3, 4, 6, 8,
            1, 10, 5, 7};
        int n = arr.length;

/*        Printing total number
        of even-odd subarrays*/

        System.out.println("Total Number of Even-Odd"
                + " subarrays are "
                + countSubarrays(arr, n));
    }
}

/*Java program for Minimum number of
distinct elements after removing m items*/

import java.util.HashMap;
import java.util.Map;
import java.util.Map.Entry;
public class DistinctIds
{

/*    Function to find distintc id's*/

    static int distinctIds(int arr[], int n, int mi)
    {
        Map<Integer, Integer> m = new HashMap<Integer, Integer>();
        int count = 0;
        int size = 0;

/*        Store the occurrence of ids*/

        for (int i = 0; i < n; i++)
        {
            if (m.containsKey(arr[i]) == false)
            {
                m.put(arr[i], 1);
                size++;
            }
            else m.put(arr[i], m.get(arr[i]) + 1);
        }

/*        Start removing elements from the beginning*/

        for (Entry<Integer, Integer> mp:m.entrySet())
        {

/*            Remove if current value is less than
            or equal to mi*/

            if (mp.getKey() <= mi)
            {
                mi -= mp.getKey();
                count++;
            }

/*            Return the remaining size*/

            else return size - count;
        }
        return size - count;
    }

/*    Driver method to test above function*/

    public static void main(String[] args)
    {
        int arr[] = {2, 3, 1, 2, 3, 3};
        int m = 3;
        System.out.println(distinctIds(arr, arr.length, m));
    }
}

/*Java program to find largest consecutive 
numbers present in arr[].*/

import java.util.*;
class GFG
{
static int findLongestConseqSubseq(int arr[], int n)
{

/* We insert all the array elements into
    unordered set. */

    HashSet<Integer> S = new HashSet<Integer>();
    for (int i = 0; i < n; i++)
        S.add(arr[i]);

/*    check each possible sequence from the start
    then update optimal length*/

    int ans = 0;
    for (int i = 0; i < n; i++) 
    {

/*        if current element is the starting
        element of a sequence*/

        if(S.contains(arr[i])) 
        {

/*            Then check for next elements in the
            sequence*/

            int j = arr[i];

/*            increment the value of array element
            and repeat search in the set*/

            while (S.contains(j))
                j++;

/*            Update optimal length if this length
            is more. To get the length as it is 
            incremented one by one*/

            ans = Math.max(ans, j - arr[i]); 
        }
    }
    return ans;
}

/*Driver code*/

public static void main(String[] args) 
{
    int arr[] = {1, 94, 93, 1000, 5, 92, 78};
    int n = arr.length;
        System.out.println(findLongestConseqSubseq(arr, n));
}
}

/*Java Program to find the largest
such that d = a + b + c*/

import java.io.*;
import java.util.Arrays;
class GFG
{

/*function to find largest d*/

static int findLargestd(int []S, int n)
{
    boolean found = false;

/*    sort the array in
    ascending order*/

    Arrays.sort(S);

/*    iterating from backwards to
    find the required largest d*/

    for (int i = n - 1; i >= 0; i--)
    {
        for (int j = 0; j < n; j++)
        {

/*            since all four a, b, c,
            d should be distinct*/

            if (i == j)
                continue;
            for (int k = j + 1; k < n; k++)
            {
                if (i == k)
                    continue;
                for (int l = k + 1; l < n; l++)
                {
                    if (i == l)
                        continue;

/*                    if the current combination 
                    of j, k, l in the set is
                    equal to S[i] return this
                    value as this would be the
                    largest d since we are 
                    iterating in descending order*/

                    if (S[i] == S[j] + S[k] + S[l])
                    {
                        found = true;
                        return S[i];
                    }
                }
            }
        }
    }
    if (found == false)
        return Integer.MAX_VALUE;
    return -1;
}

/*Driver Code*/

public static void main(String []args)
{
    int []S = new int[]{ 2, 3, 5, 7, 12 };
    int n = S.length;
    int ans = findLargestd(S, n);
    if (ans == Integer.MAX_VALUE)
        System.out.println("No Solution");
    else
        System.out.println("Largest d such that " +
                         "a + " + "b + c = d is " +
                                             ans );
}
}

/*A hashing based Java program to find largest d
such that a + b + c = d.*/

import java.util.HashMap;
import java.lang.Math;

/*To store and retrieve indices pair i & j*/

class Indexes
{
    int i, j;
    Indexes(int i, int j)
    {
        this.i = i;
        this.j = j;
    }
    int getI()
    {
        return i;
    }
    int getJ()
    {
        return j;
    }
}
class GFG {

/*    The function finds four elements with given sum X*/

    static int findFourElements(int[] arr, int n)
    {
        HashMap<Integer, Indexes> map = new HashMap<>();

/*        Store sums (a+b) of all pairs (a,b) in a
        hash table*/

        for (int i = 0; i < n - 1; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                map.put(arr[i] + arr[j], new Indexes(i, j));
            }
        }
        int d = Integer.MIN_VALUE;

/*        Traverse through all pairs and find (d -c)
        is present in hash table*/

        for (int i = 0; i < n - 1; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                int abs_diff = Math.abs(arr[i] - arr[j]);

/*                If d - c is present in hash table,*/

                if (map.containsKey(abs_diff))
                {
                    Indexes indexes = map.get(abs_diff);

/*                    Making sure that all elements are
                    distinct array elements and an element
                    is not considered more than once.*/

                    if (indexes.getI() != i && indexes.getI() != j &&
                    indexes.getJ() != i && indexes.getJ() != j)
                    {
                        d = Math.max(d, Math.max(arr[i], arr[j]));
                    }
                }
            }
        }
        return d;
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = { 2, 3, 5, 7, 12 };
        int n = arr.length;
        int res = findFourElements(arr, n);
        if (res == Integer.MIN_VALUE)
            System.out.println("No Solution");
        else
            System.out.println(res);
    }
}

/*Java for finding sum of all
unique subarray sum*/

import java.util.*;
class GFG
{

/*function for finding grandSum*/

static int findSubarraySum(int []arr, int n)
{
    int res = 0;

/*    Go through all subarrays, compute sums
    and count occurrences of sums.*/

    HashMap<Integer,
            Integer> m = new HashMap<Integer,
                                     Integer>();
    for (int i = 0; i < n; i++)
    {
        int sum = 0;
        for (int j = i; j < n; j++)
        {
            sum += arr[j];
            if (m.containsKey(sum))
            {
                m.put(sum, m.get(sum) + 1);
            }
            else
            {
                m.put(sum, 1);
            }
        }
    }

/*    Print all those sums that appear
    once.*/

    for (Map.Entry<Integer,
                   Integer> x : m.entrySet())
        if (x.getValue() == 1)
            res += x.getKey();
    return res;
}

/*Driver code*/

public static void main(String[] args)
{
    int arr[] = { 3, 2, 3, 1, 4 };
    int n = arr.length;
    System.out.println(findSubarraySum(arr, n));
}
}

/*Java program to print n-th number in Recaman's
sequence*/

import java.io.*;
class GFG {

/*    Prints first n terms of Recaman sequence*/

    static void recaman(int n)
    {

/*        Create an array to store terms*/

        int arr[] = new int[n];

/*        First term of the sequence is always 0*/

        arr[0] = 0;
        System.out.print(arr[0]+" ,");

/*        Fill remaining terms using recursive
        formula.*/

        for (int i = 1; i < n; i++)
        {
            int curr = arr[i - 1] - i;
            int j;
            for (j = 0; j < i; j++)
            {

/*                If arr[i-1] - i is negative or
                already exists.*/

                if ((arr[j] == curr) || curr < 0)
                {
                    curr = arr[i - 1] + i;
                    break;
                }
            }
            arr[i] = curr;
            System.out.print(arr[i]+", ");
        }
    }

/*    Driver code*/

    public static void main (String[] args)
    {
        int n = 17;
        recaman(n);
    }
}

/*Java program to print n-th number
in Recaman's sequence*/

import java.util.*;
class GFG
{

/*Prints first n terms of Recaman sequence*/

static void recaman(int n)
{
    if (n <= 0)
    return;

/*    Print first term and store it in a hash*/

    System.out.printf("%d, ", 0);
    HashSet<Integer> s = new HashSet<Integer>();
    s.add(0);

/*    Print remaining terms using
    recursive formula.*/

    int prev = 0;
    for (int i = 1; i< n; i++)
    {
        int curr = prev - i;

/*        If arr[i-1] - i is negative or
        already exists.*/

        if (curr < 0 || s.contains(curr))
            curr = prev + i;
        s.add(curr);
        System.out.printf("%d, ", curr);
        prev = curr;
    }
}

/*Driver code*/

public static void main(String[] args)
{
    int n = 17;
    recaman(n);
}
}

/*Efficient Java program to count
Amicable pairs in an array.*/

import java.util.*;
class GFG
{

/*Calculate the sum
of proper divisors*/

static int sumOfDiv(int x)
{

/*    1 is a proper divisor*/

    int sum = 1;
    for (int i = 2; i <= Math.sqrt(x); i++)
    {
        if (x % i == 0)
        {
            sum += i;

/*            To handle perfect squares*/

            if (x / i != i)
                sum += x / i;
        }
    }
    return sum;
}

/*Check if pair is amicable*/

static boolean isAmicable(int a, int b)
{
    return (sumOfDiv(a) == b &&
            sumOfDiv(b) == a);
}

/*This function prints count
of amicable pairs present
in the input array*/

static int countPairs(int arr[], int n)
{

/*    Map to store the numbers*/

    HashSet<Integer> s = new HashSet<Integer>();
    int count = 0;
    for (int i = 0; i < n; i++)
        s.add(arr[i]);

/*    Iterate through each number,
    and find the sum of proper
    divisors and check if it's
    also present in the array*/

    for (int i = 0; i < n; i++)
    {
        if (s.contains(sumOfDiv(arr[i])))
        {

/*            It's sum of proper divisors*/

            int sum = sumOfDiv(arr[i]);
            if (isAmicable(arr[i], sum))
                count++;
        }
    }

/*    As the pairs are counted
    twice, thus divide by 2*/

    return count / 2;
}

/*Driver code*/

public static void main(String[] args)
{
    int arr1[] = { 220, 284, 1184,
                   1210, 2, 5 };
    int n1 = arr1.length;
    System.out.println(countPairs(arr1, n1));
    int arr2[] = { 2620, 2924, 5020,
                   5564, 6232, 6368 };
    int n2 = arr2.length;
    System.out.println(countPairs(arr2, n2));
}
}

/*Java program for finding maximum area
possible of a rectangle*/

import java.util.Arrays;
import java.util.Collections;
public class GFG
{

/*    function for finding max area*/

    static int findArea(Integer arr[], int n)
    {

/*        sort array in non-increasing order*/

        Arrays.sort(arr, Collections.reverseOrder());

/*        Initialize two sides of rectangle*/

        int[] dimension = { 0, 0 };

/*        traverse through array*/

        for (int i = 0, j = 0; i < n - 1 && j < 2;
                                           i++)

/*            if any element occurs twice
            store that as dimension*/

            if (arr[i] == arr[i + 1])
                dimension[j++] = arr[i++];

/*        return the product of dimensions*/

        return (dimension[0] * dimension[1]);
    }

/*    driver function*/

    public static void main(String args[])
    {
        Integer arr[] = { 4, 2, 1, 4, 6, 6, 2, 5 };
        int n = arr.length;
        System.out.println(findArea(arr, n));
    }
}

/*Java program for finding maximum
area possible of a rectangle*/

import java.util.HashSet;
import java.util.Set;
public class GFG
{

/*    function for finding max area*/

    static int findArea(int arr[], int n)
    {
        Set<Integer> s = new HashSet<>();

/*        traverse through array*/

        int first = 0, second = 0;
        for (int i = 0; i < n; i++) {

/*            If this is first occurrence of
            arr[i], simply insert and continue*/

            if (!s.contains(arr[i])) {
                s.add(arr[i]);
                continue;
            }

/*            If this is second (or more)
            occurrence, update first and
            second maximum values.*/

            if (arr[i] > first) {
                second = first;
                first = arr[i];
            } else if (arr[i] > second)
                second = arr[i];
        }

/*        return the product of dimensions*/

        return (first * second);
    }

/*    driver function*/

    public static void main(String args[])
    {
        int arr[] = { 4, 2, 1, 4, 6, 6, 2, 5 };
        int n = arr.length;
        System.out.println(findArea(arr, n));
    }
}

/*Java implementation to find length of longest
strict bitonic subsequence*/

import java.util.*;
class GfG
{

/*function to find length of longest
strict bitonic subsequence*/

static int longLenStrictBitonicSub(int arr[], int n)
{

/*    hash table to map the array element with the
    length of the longest subsequence of which
    it is a part of and is the last/first element of
    that subsequence*/

    HashMap<Integer, Integer> inc = new HashMap<Integer, Integer> ();
    HashMap<Integer, Integer> dcr = new HashMap<Integer, Integer> ();

/*    arrays to store the length of increasing and
    decreasing subsequences which end at them
    or start from them*/

    int len_inc[] = new int[n];
    int len_dcr[] = new int[n];

/*    to store the length of longest strict
    bitonic subsequence*/

    int longLen = 0;

/*    traverse the array elements
    from left to right*/

    for (int i = 0; i < n; i++)
    {

/*        initialize current length
        for element arr[i] as 0*/

        int len = 0;

/*        if 'arr[i]-1' is in 'inc'*/

        if (inc.containsKey(arr[i] - 1))
            len = inc.get(arr[i] - 1);

/*        update arr[i] subsequence length in 'inc'    
        and in len_inc[]*/

        len_inc[i] = len + 1;
        inc.put(arr[i], len_inc[i]);
    }

/*    traverse the array elements
    from right to left*/

    for (int i = n - 1; i >= 0; i--)
    {

/*        initialize current length
        for element arr[i] as 0*/

        int len = 0;

/*        if 'arr[i]-1' is in 'dcr'*/

        if (dcr.containsKey(arr[i] - 1))
            len = dcr.get(arr[i] - 1);

/*        update arr[i] subsequence length in 'dcr'
        and in len_dcr[]*/

        len_dcr[i] = len + 1;
        dcr.put(arr[i], len_dcr[i]);
    }

/*    calculating the length of all the strict
    bitonic subsequence*/

    for (int i = 0; i < n; i++)
        if (longLen < (len_inc[i] + len_dcr[i] - 1))
            longLen = len_inc[i] + len_dcr[i] - 1;

/*    required longest length strict
    bitonic subsequence*/

    return longLen;    
}

/*Driver code*/

public static void main(String[] args)
{
    int arr[] = {1, 5, 2, 3, 4, 5, 3, 2};
    int n = arr.length;
    System.out.println("Longest length strict " +
                            "bitonic subsequence = " +
                            longLenStrictBitonicSub(arr, n));
}
}

/*Java program to find last seen element in 
an array.*/

import java.util.*;
class GFG 
{

/*Returns last seen element in arr[]*/

static int lastSeenElement(int a[], int n)
{

/*    Store last occurrence index of 
    every element*/

    HashMap<Integer,
            Integer> hash = new HashMap<Integer,        
                                        Integer>();
    for (int i = 0; i < n; i++)
    {
        hash.put(a[i], i);
    }

/*    Find an element in hash with minimum 
    index value*/

    int res_ind = Integer.MAX_VALUE, res = 0;
    for (Map.Entry<Integer, 
                   Integer> x : hash.entrySet()) 
    {
        if (x.getValue() < res_ind)
        {
            res_ind = x.getValue();
            res = x.getKey();
        }   
    }
    return res;
}

/*Driver Code*/

public static void main(String[] args) 
{
    int a[] = { 2, 1, 2, 2, 4, 1 };
    int n = a.length;
    System.out.println(lastSeenElement(a, n));
}
}

/*Java program to rotate an array by
d elements*/

class RotateArray {

/*Function to left Rotate arr[] of
  size n by 1*/

    void leftRotatebyOne(int arr[], int n)
    {
        int i, temp;
        temp = arr[0];
        for (i = 0; i < n - 1; i++)
            arr[i] = arr[i + 1];
        arr[n-1] = temp;
    }

/*Function to left rotate arr[] of size n by d*/

    void leftRotate(int arr[], int d, int n)
    {
        for (int i = 0; i < d; i++)
            leftRotatebyOne(arr, n);
    }

/* utility function to print an array */

    void printArray(int arr[], int n)
    {
        for (int i = 0; i < n; i++)
            System.out.print(arr[i] + " ");
    }

/*    Driver program to test above functions*/

    public static void main(String[] args)
    {
        RotateArray rotate = new RotateArray();
        int arr[] = { 1, 2, 3, 4, 5, 6, 7 };
        rotate.leftRotate(arr, 2, 7);
        rotate.printArray(arr, 7);
    }
}

/*Java program to find max value of i*arr[i]*/

import java.util.Arrays;
class Test
{
    static int arr[] = new int[]{10, 1, 2, 3, 4, 5, 6, 7, 8, 9};

/*    Returns max possible value of i*arr[i]*/

    static int maxSum()
    {

/*        Find array sum and i*arr[i] with no rotation
Stores sum of arr[i]*/

int arrSum = 0;

/*Stores sum of i*arr[i]*/

int currVal = 0;  
        for (int i=0; i<arr.length; i++)
        {
            arrSum = arrSum + arr[i];
            currVal = currVal+(i*arr[i]);
        }

/*        Initialize result as 0 rotation sum*/

        int maxVal = currVal;

/*        Try all rotations one by one and find
        the maximum rotation sum.*/

        for (int j=1; j<arr.length; j++)
        {
            currVal = currVal + arrSum-arr.length*arr[arr.length-j];
            if (currVal > maxVal)
                maxVal = currVal;
        }

/*        Return result*/

        return maxVal;
    }

/*    Driver method to test the above function*/

    public static void main(String[] args)
    {
        System.out.println("Max sum is " + maxSum());
    }
}

/*A Naive Java program to find
maximum sum rotation*/

import java.util.*;
import java.io.*;
class GFG {

/*Returns maximum value of i*arr[i]*/

static int maxSum(int arr[], int n)
{

/*Initialize result*/

int res = Integer.MIN_VALUE;

/*Consider rotation beginning with i
for all possible values of i.*/

for (int i = 0; i < n; i++)
{

/*    Initialize sum of current rotation*/

    int curr_sum = 0;

/*    Compute sum of all values. We don't
    actually rotation the array, but compute
    sum by finding ndexes when arr[i] is
    first element*/

    for (int j = 0; j < n; j++)
    {
        int index = (i + j) % n;
        curr_sum += j * arr[index];
    }

/*    Update result if required*/

    res = Math.max(res, curr_sum);
}
return res;
}

/*Driver code*/

public static void main(String args[])
{
        int arr[] = {8, 3, 1, 2};
        int n = arr.length;
        System.out.println(maxSum(arr, n));
}
}

/*An efficient Java program to compute
maximum sum of i*arr[i]*/

import java.io.*;
class GFG {
    static int maxSum(int arr[], int n)
    {

/*        Compute sum of all array elements*/

        int cum_sum = 0;
        for (int i = 0; i < n; i++)
            cum_sum += arr[i];

/*        Compute sum of i*arr[i] for
        initial configuration.*/

        int curr_val = 0;
        for (int i = 0; i < n; i++)
            curr_val += i * arr[i];

/*        Initialize result*/

        int res = curr_val;

/*        Compute values for other iterations*/

        for (int i = 1; i < n; i++)
        {

/*            Compute next value using previous
            value in O(1) time*/

            int next_val = curr_val - (cum_sum -
                          arr[i-1]) + arr[i-1] *
                          (n-1);

/*            Update current value*/

            curr_val = next_val;

/*            Update result if required*/

            res = Math.max(res, next_val);
        }
        return res;
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = {8, 3, 1, 2};
        int n = arr.length;
        System.out.println(maxSum(arr, n));
    }
}

/*Java program to find number of
rotations in a sorted and rotated
array.*/

import java.util.*;
import java.lang.*;
import java.io.*;
class LinearSearch
{

/*    Returns count of rotations for an
    array which is first sorted in
    ascending order, then rotated*/

    static int countRotations(int arr[], int n)
    {

/*        We basically find index of minimum
        element*/

        int min = arr[0], min_index = -1;
        for (int i = 0; i < n; i++)
        {
            if (min > arr[i])
            {
                min = arr[i];
                min_index = i;
            }
        }
        return min_index;
    }

/*    Driver program to test above functions*/

    public static void main (String[] args)
    {
        int arr[] = {15, 18, 2, 3, 6, 12};
        int n = arr.length;
        System.out.println(countRotations(arr, n));
    }
}

/*Java implementation of left rotation of
an array K number of times*/

class LeftRotate
{

/*    Fills temp[] with two copies of arr[]*/

    static void preprocess(int arr[], int n,
                                   int temp[])
    {

/*        Store arr[] elements at i and i + n*/

        for (int i = 0; i<n; i++)
             temp[i] = temp[i + n] = arr[i];
    }

/*    Function to left rotate an array k time*/

    static void leftRotate(int arr[], int n, int k,
                                    int temp[])
    {

/*        Starting position of array after k
        rotations in temp[] will be k % n*/

        int start = k % n;

/*        Print array after k rotations*/

        for (int i = start; i < start + n; i++)
            System.out.print(temp[i] + " ");
        System.out.print("\n");
    }

/*    Driver program*/

    public static void main (String[] args)
    {
        int arr[] = {1, 3, 5, 7, 9};
        int n = arr.length;
        int temp[] = new int[2*n];
        preprocess(arr, n, temp);
        int k = 2;
        leftRotate(arr, n, k, temp);
        k = 3;
        leftRotate(arr, n, k, temp);
        k = 4;
        leftRotate(arr, n, k, temp);
    }
}

