/*A O(n) time and O(1) extra space Java program to
sort an array according to given indexes*/

import java.util.Arrays;
class Test
{
    static int arr[] = new int[]{50, 40, 70, 60, 90};
    static int index[] = new int[]{3,  0,  4,  1,  2};

/*    Method to reorder elements of arr[] according
    to index[]*/

    static void reorder()
    {

/*        Fix all elements one by one*/

        for (int i=0; i<arr.length; i++)
        {

/*            While index[i] and arr[i] are not fixed*/

            while (index[i] != i)
            {

/*                Store values of the target (or correct)
                position before placing arr[i] there*/

                int  oldTargetI  = index[index[i]];
                char oldTargetE  = (char)arr[index[i]];

/*                Place arr[i] at its target (or correct)
                position. Also copy corrected index for
                new position*/

                arr[index[i]] = arr[i];
                index[index[i]] = index[i];

/*                Copy old target values to arr[i] and
                index[i]*/

                index[i] = oldTargetI;
                arr[i]   = oldTargetE;
            }
        }
    }

/*    Driver method to test the above function*/

    public static void main(String[] args)
    {
        reorder();
        System.out.println("Reordered array is: ");
        System.out.println(Arrays.toString(arr));
        System.out.println("Modified Index array is:");
        System.out.println(Arrays.toString(index));
    }
}

/*Java code to reorder an array
according to given indices*/

class GFG{
static int heapSize;
public static void heapify(int arr[],
                           int index[], int i)
{
    int largest = i;

/*    left child in 0 based indexing*/

    int left = 2 * i + 1;

/*    right child in 1 based indexing*/

    int right = 2 * i + 2;

/*    Find largest index from root,
    left and right child*/

    if (left < heapSize &&
        index[left] > index[largest] )
    {
        largest = left;
    }
    if (right < heapSize &&
        index[right] > index[largest] )
    {
        largest = right;
    }
    if (largest != i)
    {

/*        swap arr whenever index is swapped*/

        int temp = arr[largest];
        arr[largest] = arr[i];
        arr[i] = temp;
        temp = index[largest];
        index[largest] = index[i];
        index[i] = temp;
        heapify(arr, index, largest);
    }
}
public static void heapSort(int arr[],
                            int index[], int n)
{

/*    Build heap*/

    for(int i = (n - 1) / 2 ; i >= 0 ; i--)
    {
        heapify(arr, index, i);
    }

/*    Swap the largest element of
    index(first element)
    with the last element*/

    for(int i = n - 1 ; i > 0 ; i--)
    {
        int temp = index[0];
        index[0] = index[i];
        index[i] = temp;

/*        swap arr whenever index is swapped*/

        temp = arr[0];
        arr[0] = arr[i];
        arr[i] = temp;
        heapSize--;
        heapify(arr, index, 0);
    }
}

/*Driver code*/

public static void main(String[] args)
{
    int arr[] = { 50, 40, 70, 60, 90 };
    int index[] = { 3, 0, 4, 1, 2 };
    int n = arr.length;
    heapSize = n;
    heapSort(arr, index, n);
    System.out.println("Reordered array is: ");
    for(int i = 0 ; i < n ; i++)
        System.out.print(arr[i] + " ");
    System.out.println();  
    System.out.println("Modified Index array is: ");
    for(int i = 0; i < n; i++)
        System.out.print(index[i] + " ");
}
}

/*Java program to Rearrange positive
and negative numbers in a array*/

import java.io.*;
class GFG {

/*    A utility function to print
    an array of size n*/

    static void printArray(int arr[], int n)
    {
        for (int i = 0; i < n; i++)
            System.out.print(arr[i] + " ");
        System.out.println();
    }

/*    Function to Rearrange positive and negative
    numbers in a array*/

    static void RearrangePosNeg(int arr[], int n)
    {
        int key, j;
        for (int i = 1; i < n; i++) {
            key = arr[i];

/*            if current element is positive
            do nothing*/

            if (key > 0)
                continue;

/* if current element is negative,
            shift positive elements of arr[0..i-1],
            to one position to their right */

            j = i - 1;
            while (j >= 0 && arr[j] > 0) {
                arr[j + 1] = arr[j];
                j = j - 1;
            }

/*            Put negative element at its right position*/

            arr[j + 1] = key;
        }
    }

/*    Driver program*/

    public static void main(String[] args)
    {
        int arr[] = { -12, 11, -13, -5, 6, -7, 5, -3, -6 };
        int n = arr.length;
        RearrangePosNeg(arr, n);
        printArray(arr, n);
    }
}

/*Java program to Rearrange positive and negative
numbers in a array*/

class GFG {

/* Function to print an array */

    static void printArray(int A[], int size)
    {
        for (int i = 0; i < size; i++)
            System.out.print(A[i] + " ");
        System.out.println("");
        ;
    }

/* Function to reverse an array. An array can be
reversed in O(n) time and O(1) space. */

    static void reverse(int arr[], int l, int r)
    {
        if (l < r) {
            arr = swap(arr, l, r);
            reverse(arr, ++l, --r);
        }
    }

/*    Merges two subarrays of arr[].
    First subarray is arr[l..m]
    Second subarray is arr[m+1..r]*/

    static void merge(int arr[], int l, int m, int r)
    {

/*Initial index of 1st subarray*/

int i = l;

/*Initial index of IInd*/

int j = m + 1; 
        while (i <= m && arr[i] < 0)
            i++;

/*        arr[i..m] is positive*/

        while (j <= r && arr[j] < 0)
            j++;

/*        arr[j..r] is positive
        reverse positive part of
        left sub-array (arr[i..m])*/

        reverse(arr, i, m);

/*        reverse negative part of
        right sub-array (arr[m+1..j-1])*/

        reverse(arr, m + 1, j - 1);

/*        reverse arr[i..j-1]*/

        reverse(arr, i, j - 1);
    }

/*    Function to Rearrange positive and negative
    numbers in a array*/

    static void RearrangePosNeg(int arr[], int l, int r)
    {
        if (l < r) {

/*            Same as (l+r)/2, but avoids overflow for
            large l and h*/

            int m = l + (r - l) / 2;

/*            Sort first and second halves*/

            RearrangePosNeg(arr, l, m);
            RearrangePosNeg(arr, m + 1, r);
            merge(arr, l, m, r);
        }
    }
    static int[] swap(int[] arr, int i, int j)
    {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        return arr;
    }

/* Driver code*/

    public static void main(String[] args)
    {
        int arr[] = { -12, 11, -13, -5, 6, -7, 5, -3, -6 };
        int arr_size = arr.length;
        RearrangePosNeg(arr, 0, arr_size - 1);
        printArray(arr, arr_size);
    }
}

/*A simple JAVA program to rearrange
contents of arr[] such that arr[j]
becomes j if arr[i] is j*/

class GFG {

/*    A simple method to rearrange
    'arr[0..n-1]' so that 'arr[j]'
    becomes 'i' if 'arr[i]' is 'j'*/

    static void rearrange(int arr[], int n)
    {
        for (int i = 0; i < n; i++) {

/*            retrieving old value and
            storing with the new one*/

            arr[arr[i] % n] += i * n;
        }
        for (int i = 0; i < n; i++) {

/*            retrieving new value*/

            arr[i] /= n;
        }
    }

/*    A utility function to print
    contents of arr[0..n-1]*/

    static void printArray(int arr[], int n)
    {
        for (int i = 0; i < n; i++) {
            System.out.print(arr[i] + " ");
        }
        System.out.println();
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = { 2, 0, 1, 4, 5, 3 };
        int n = arr.length;
        System.out.println("Given array is : ");
        printArray(arr, n);
        rearrange(arr, n);
        System.out.println("Modified array is :");
        printArray(arr, n);
    }
}

/*Java program to rearrange an array in minimum
maximum form*/

import java.util.Arrays;
public class GFG
{

/*    Prints max at first position, min at second position
    second max at third position, second min at fourth
    position and so on.*/

    static void rearrange(int[] arr, int n)
    {

/*        Auxiliary array to hold modified array*/

        int temp[] = arr.clone();

/*        Indexes of smallest and largest elements
        from remaining array.*/

        int small = 0, large = n - 1;

/*        To indicate whether we need to copy rmaining
        largest or remaining smallest at next position*/

        boolean flag = true;

/*        Store result in temp[]*/

        for (int i = 0; i < n; i++) {
            if (flag)
                arr[i] = temp[large--];
            else
                arr[i] = temp[small++];
            flag = !flag;
        }
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = new int[] { 1, 2, 3, 4, 5, 6 };
        System.out.println("Original Array ");
        System.out.println(Arrays.toString(arr));
        rearrange(arr, arr.length);
        System.out.println("Modified Array ");
        System.out.println(Arrays.toString(arr));
    }
}

/*Java program to rearrange an
array in minimum maximum form*/

public class Main {

/*    Prints max at first position, min at second
    position second max at third position, second
    min at fourth position and so on.*/

    public static void rearrange(int arr[], int n)
    {

/*        initialize index of first minimum and first
        maximum element*/

        int max_idx = n - 1, min_idx = 0;

/*        store maximum element of array*/

        int max_elem = arr[n - 1] + 1;

/*        traverse array elements*/

        for (int i = 0; i < n; i++) {

/*            at even index : we have to put
            maximum element*/

            if (i % 2 == 0) {
                arr[i] += (arr[max_idx] % max_elem) * max_elem;
                max_idx--;
            }

/*            at odd index : we have to put minimum element*/

            else {
                arr[i] += (arr[min_idx] % max_elem) * max_elem;
                min_idx++;
            }
        }

/*        array elements back to it's original form*/

        for (int i = 0; i < n; i++)
            arr[i] = arr[i] / max_elem;
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int arr[] = { 1, 2, 3, 4, 5, 6, 7, 8, 9 };
        int n = arr.length;
        System.out.println("Original Array");
        for (int i = 0; i < n; i++)
            System.out.print(arr[i] + " ");
        rearrange(arr, n);
        System.out.print("\nModified Array\n");
        for (int i = 0; i < n; i++)
            System.out.print(arr[i] + " ");
    }
}

/*Java program to rearrange an
array in minimum maximum form*/

public class Main {

/*    Prints max at first position, min at second
    position second max at third position, second
    min at fourth position and so on.*/

    public static void rearrange(int arr[], int n)
    {

/*        initialize index of first minimum and first
        maximum element*/

        int max_ele = arr[n - 1];
        int min_ele = arr[0];

/*        traverse array elements*/

        for (int i = 0; i < n; i++) {

/*            at even index : we have to put maximum element*/

            if (i % 2 == 0) {
                arr[i] = max_ele;
                max_ele -= 1;
            }

/*            at odd index : we have to put minimum element*/

            else {
                arr[i] = min_ele;
                min_ele += 1;
            }
        }
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int arr[] = { 1, 2, 3, 4, 5, 6, 7, 8, 9 };
        int n = arr.length;
        System.out.println("Original Array");
        for (int i = 0; i < n; i++)
            System.out.print(arr[i] + " ");
        rearrange(arr, n);
        System.out.print("\nModified Array\n");
        for (int i = 0; i < n; i++)
            System.out.print(arr[i] + " ");
    }
}

