/*Java program to Move All -ve Element At End
Without changing order Of Array Element*/

import java.util.Arrays;
class GFG {

/*    Moves all -ve element to end of array in
    same order.*/

    static void segregateElements(int arr[], int n)
    {

/*        Create an empty array to store result*/

        int temp[] = new int[n];

/*        Traversal array and store +ve element in
        temp array
index of temp*/

int j = 0; 
        for (int i = 0; i < n; i++)
            if (arr[i] >= 0)
                temp[j++] = arr[i];

/*        If array contains all positive or all
        negative.*/

        if (j == n || j == 0)
            return;

/*        Store -ve element in temp array*/

        for (int i = 0; i < n; i++)
            if (arr[i] < 0)
                temp[j++] = arr[i];

/*        Copy contents of temp[] to arr[]*/

        for (int i = 0; i < n; i++)
            arr[i] = temp[i];
    }

/*    Driver code*/

    public static void main(String arg[])
    {
        int arr[] = { 1, -1, -3, -2, 7, 5, 11, 6 };
        int n = arr.length;
        segregateElements(arr, n);
        for (int i = 0; i < n; i++)
            System.out.print(arr[i] + " ");
    }
}

/*Java code to rearrange an array such
that even index elements are smaller
and odd index elements are greater
than their next.*/

class GFG {

/*Rearrange*/

    static void rearrange(int arr[], int n)
    {
        int temp;
        for (int i = 0; i < n - 1; i++) {
            if (i % 2 == 0 && arr[i] > arr[i + 1]) {
                temp = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = temp;
            }
            if (i % 2 != 0 && arr[i] < arr[i + 1]) {
                temp = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = temp;
            }
        }
    }

/* Utility that prints out an array in
    a line */

    static void printArray(int arr[], int size)
    {
        for (int i = 0; i < size; i++)
            System.out.print(arr[i] + " ");
        System.out.println();
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = { 6, 4, 2, 1, 8, 3 };
        int n = arr.length;
        System.out.print("Before rearranging: \n");
        printArray(arr, n);
        rearrange(arr, n);
        System.out.print("After rearranging: \n");
        printArray(arr, n);
    }
}

/*Java program to rearrange positive
and negative numbers*/

import java.io.*;
import java.util.*;
class GFG
{

/*    Swap function*/

    static void swap(int[] a, int i, int j)
    {
        int temp = a[i];
        a[i] = a[j];
        a[j] = temp;
    }

/*    Print array function*/

    static void printArray(int[] a, int n)
    {
        for (int i = 0; i < n; i++)
            System.out.print(a[i] + " ");
        System.out.println();
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int[] arr = { 1, -3, 5, 6, -3, 6, 7, -4, 9, 10 };
        int n = arr.length;

/*        before modification*/

        printArray(arr, n);
        for (int i = 0; i < n; i++)
        {
            if (arr[i] >= 0 && i % 2 == 1)
            {

/*                out of order positive element*/

                for (int j = i + 1; j < n; j++)
                {
                    if (arr[j] < 0 && j % 2 == 0)
                    {

/*                        find out of order negative
                        element in remaining array*/

                        swap(arr, i, j);
                        break ;
                    }
                }
            }
            else if (arr[i] < 0 && i % 2 == 0)
            {

/*                out of order negative element*/

                for (int j = i + 1; j < n; j++)
                {
                    if (arr[j] >= 0 && j % 2 == 1)
                    {

/*                        find out of order positive
                        element in remaining array*/

                        swap(arr, i, j);
                        break;
                    }
                }
            }
        }

/*        after modification*/

        printArray(arr, n);
    }
}

