    {

/*It uses Tuned Quicksort with*/

Arrays.sort(arr);

/*        avg. case Time complexity = O(nLogn)*/

        int n = arr.length;
        int check = 0, count = 1;
        for (int i = 1; i <= n; i++) {
            if (count < 4) {
                if (check != arr[n - i]) {

