{
    int arr[] = { 2, -6, 3, 5, 1};
    int n = arr.length;
    findElements(arr, n);
}
}

/*Java program to find mean
and median of an array*/

import java.util.*;
class GFG
{

/*    Function for calculating mean*/

    public static double findMean(int a[], int n)
    {
        int sum = 0;
        for (int i = 0; i < n; i++)
            sum += a[i];
        return (double)sum / (double)n;
    }

/*    Function for calculating median*/

    public static double findMedian(int a[], int n)
    {

/*        First we sort the array*/

        Arrays.sort(a);

/*        check for even case*/

        if (n % 2 != 0)
            return (double)a[n / 2];
        return (double)(a[(n - 1) / 2] + a[n / 2]) / 2.0;
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int a[] = { 1, 3, 4, 2, 7, 5, 8, 6 };
        int n = a.length;

/*        Function call*/

        System.out.println("Mean = " + findMean(a, n));
        System.out.println("Median = " + findMedian(a, n));
    }
}

/*Java for printing smallest k numbers in order*/

import java.util.*;
import java.lang.*;
public class GfG {

/*    Function to print smallest k numbers
    in arr[0..n-1]*/

    public static void printSmall(int arr[], int n, int k)
    {

/*        For each arr[i] find whether
        it is a part of n-smallest
        with insertion sort concept*/

        for (int i = k; i < n; ++i) {

/*            Find largest from top n-element*/

            int max_var = arr[k - 1];
            int pos = k - 1;
            for (int j = k - 2; j >= 0; j--) {
                if (arr[j] > max_var) {
                    max_var = arr[j];
                    pos = j;
                }
            }

/*            If largest is greater than arr[i]
            shift all element one place left*/

            if (max_var > arr[i]) {
                int j = pos;
                while (j < k - 1) {
                    arr[j] = arr[j + 1];
                    j++;
                }

/*                make arr[k-1] = arr[i]*/

                arr[k - 1] = arr[i];
            }
        }

/*        print result*/

        for (int i = 0; i < k; i++)
            System.out.print(arr[i] + " ");
    }

/*    Driver function*/

    public static void main(String argc[])
    {
        int[] arr = { 1, 5, 8, 9, 6, 7, 3, 4, 2, 0 };
        int n = 10;
        int k = 5;
        printSmall(arr, n, k);
    }
}

/*Java code to print first k pairs with least
sum from two arrays.*/

import java.io.*;
class KSmallestPair
{

/*    Function to find k pairs with least sum such
    that one elemennt of a pair is from arr1[] and
    other element is from arr2[]*/

    static void kSmallestPair(int arr1[], int n1, int arr2[],
                                            int n2, int k)
    {
        if (k > n1*n2)
        {
            System.out.print("k pairs don't exist");
            return ;
        }

/*        Stores current index in arr2[] for
        every element of arr1[]. Initially
        all values are considered 0.
        Here current index is the index before
        which all elements are considered as
        part of output.*/

        int index2[] = new int[n1];
        while (k > 0)
        {

/*            Initialize current pair sum as infinite*/

            int min_sum = Integer.MAX_VALUE;
            int min_index = 0;

/*            To pick next pair, traverse for all
            elements of arr1[], for every element, find
            corresponding current element in arr2[] and
            pick minimum of all formed pairs.*/

            for (int i1 = 0; i1 < n1; i1++)
            {

/*                Check if current element of arr1[] plus
                element of array2 to be used gives
                minimum sum*/

                if (index2[i1] < n2 &&
                    arr1[i1] + arr2[index2[i1]] < min_sum)
                {

/*                    Update index that gives minimum*/

                    min_index = i1;

/*                    update minimum sum*/

                    min_sum = arr1[i1] + arr2[index2[i1]];
                }
            }
            System.out.print("(" + arr1[min_index] + ", " +
                            arr2[index2[min_index]]+ ") ");
            index2[min_index]++;
            k--;
        }
    }

/*    Driver code*/

    public static void main (String[] args)
    {
        int arr1[] = {1, 3, 11};
        int n1 = arr1.length;
        int arr2[] = {2, 4, 8};
        int n2 = arr2.length;
        int k = 4;
        kSmallestPair( arr1, n1, arr2, n2, k);
    }
}

/*Java program to find k-th absolute difference
between two elements*/

import java.util.Scanner;
import java.util.Arrays;
class GFG
{

/*    returns number of pairs with absolute
    difference less than or equal to mid */

    static int countPairs(int[] a, int n, int mid)
    {
        int res = 0, value;
        for(int i = 0; i < n; i++)
        {

/*            Upper bound returns pointer to position
            of next higher number than a[i]+mid in
            a[i..n-1]. We subtract (ub + i + 1) from
            this position to count */

            int ub = upperbound(a, n, a[i]+mid);
            res += (ub- (i-1));
        }
        return res;
    }

/*    returns the upper bound*/

    static int upperbound(int a[], int n, int value)
    {
        int low = 0;
        int high = n;
        while(low < high)
        {
            final int mid = (low + high)/2;
            if(value >= a[mid])
                low = mid + 1;
            else
                high = mid;
        }
    return low;
    }

/*    Returns k-th absolute difference*/

    static int kthDiff(int a[], int n, int k)
    {

/*        Sort array*/

        Arrays.sort(a);

/*        Minimum absolute difference*/

        int low = a[1] - a[0];
        for (int i = 1; i <= n-2; ++i)
            low = Math.min(low, a[i+1] - a[i]);

/*        Maximum absolute difference*/

        int high = a[n-1] - a[0];

/*        Do binary search for k-th absolute difference*/

        while (low < high)
        {
            int mid = (low + high) >> 1;
            if (countPairs(a, n, mid) < k)
                low = mid + 1;
            else
                high = mid;
        }
        return low;
    }

/*    Driver function to check the above functions*/

    public static void main(String args[])
    {
        Scanner s = new Scanner(System.in);
        int k = 3;
        int a[] = {1,2,3,4};
        int n = a.length;
        System.out.println(kthDiff(a, n, k));
    }
}

/*Java program to find smallest and second smallest elements*/

import java.io.*;
class SecondSmallest
{

/* Function to print first smallest and second smallest
      elements */

    static void print2Smallest(int arr[])
    {
        int first, second, arr_size = arr.length;

/* There should be atleast two elements */

        if (arr_size < 2)
        {
            System.out.println(" Invalid Input ");
            return;
        }
        first = second = Integer.MAX_VALUE;
        for (int i = 0; i < arr_size ; i ++)
        {

/* If current element is smaller than first
              then update both first and second */

            if (arr[i] < first)
            {
                second = first;
                first = arr[i];
            }

/* If arr[i] is in between first and second
               then update second  */

            else if (arr[i] < second && arr[i] != first)
                second = arr[i];
        }
        if (second == Integer.MAX_VALUE)
            System.out.println("There is no second" +
                               "smallest element");
        else
            System.out.println("The smallest element is " +
                               first + " and second Smallest" +
                               " element is " + second);
    }

/* Driver program to test above functions */

    public static void main (String[] args)
    {
        int arr[] = {12, 13, 1, 10, 34, 1};
        print2Smallest(arr);
    }
}

/*Java Program to compute sum of ranges for different range
queries.*/

import java.util.*;

/*Class to represent a query range*/

class Query{
    int L;
    int R;
    Query(int L, int R){
        this.L = L;
        this.R = R;
    }
}
class GFG
{

/*    Prints sum of all query ranges. m is number of queries
    n is the size of the array.*/

    static void printQuerySums(int a[], int n, ArrayList<Query> q, int m)
    {

/*        One by one compute sum of all queries*/

        for (int i=0; i<m; i++)
        {

/*            Left and right boundaries of current range*/

            int L = q.get(i).L, R = q.get(i).R;

/*            Compute sum of current query range*/

            int sum = 0;
            for (int j=L; j<=R; j++)
                sum += a[j];

/*            Print sum of current query range*/

            System.out.println("Sum of [" + L +
                           ", " + R + "] is "  + sum);
        }
    }

/*    Driver program*/

    public static void main(String argv[])
    {
        int a[] = {1, 1, 2, 1, 3, 4, 5, 2, 8};
        int n = a.length;
        ArrayList<Query> q = new ArrayList<Query>();
        q.add(new Query(0,4));
        q.add(new Query(1,3));
        q.add(new Query(2,4));
        int m = q.size();
        printQuerySums(a, n, q, m);
    }
}

/*Java program to demonstrate working of 
Square Root Decomposition.*/

import java.util.*;
class GFG 
{
static int MAXN = 10000;
static int SQRSIZE = 100;

/*original array*/

static int []arr = new int[MAXN];

/*decomposed array*/

static int []block = new int[SQRSIZE];

/*block size*/

static int blk_sz;

/*Time Complexity : O(1)*/

static void update(int idx, int val)
{
    int blockNumber = idx / blk_sz;
    block[blockNumber] += val - arr[idx];
    arr[idx] = val;
}

/*Time Complexity : O(sqrt(n))*/

static int query(int l, int r)
{
    int sum = 0;
    while (l < r && l % blk_sz != 0 && l != 0)
    {

/*        traversing first block in range*/

        sum += arr[l];
        l++;
    }
    while (l+blk_sz <= r)
    {

/*        traversing completely
        overlapped blocks in range*/

        sum += block[l / blk_sz];
        l += blk_sz;
    }
    while (l <= r)
    {

/*        traversing last block in range*/

        sum += arr[l];
        l++;
    }
    return sum;
}

/*Fills values in input[]*/

static void preprocess(int input[], int n)
{

/*    initiating block pointer*/

    int blk_idx = -1;

/*    calculating size of block*/

    blk_sz = (int) Math.sqrt(n);

/*    building the decomposed array*/

    for (int i = 0; i < n; i++)
    {
        arr[i] = input[i];
        if (i % blk_sz == 0)
        {

/*            entering next block
            incementing block pointer*/

            blk_idx++;
        }
        block[blk_idx] += arr[i];
    }
}

/*Driver code*/

public static void main(String[] args) 
{

/*    We have used separate array for input because
    the purpose of this code is to explain SQRT
    decomposition in competitive programming where
    we have multiple inputs.*/

    int input[] = {1, 5, 2, 4, 6, 1, 3, 5, 7, 10};
    int n = input.length;
    preprocess(input, n);
    System.out.println("query(3, 8) : " +
                        query(3, 8));
    System.out.println("query(1, 6) : " +
                        query(1, 6));
    update(8, 0);
    System.out.println("query(8, 8) : " + 
                        query(8, 8));
}
}

/*Java program to do range minimum query
using sparse table*/

import java.io.*;
class GFG {
    static int MAX =500;

/*    lookup[i][j] is going to store minimum
    value in arr[i..j]. Ideally lookup table
    size should not be fixed and should be
    determined using n Log n. It is kept
    constant to keep code simple.*/

    static int [][]lookup = new int[MAX][MAX];

/*    Fills lookup array lookup[][] in bottom up manner.*/

    static void buildSparseTable(int arr[], int n)
    {

/*        Initialize M for the intervals with length 1*/

        for (int i = 0; i < n; i++)
            lookup[i][0] = arr[i];

/*        Compute values from smaller to bigger intervals*/

        for (int j = 1; (1 << j) <= n; j++) {

/*            Compute minimum value for all intervals with
            size 2^j*/

            for (int i = 0; (i + (1 << j) - 1) < n; i++) {

/*                For arr[2][10], we compare arr[lookup[0][7]]
                and arr[lookup[3][10]]*/

                if (lookup[i][j - 1] <
                            lookup[i + (1 << (j - 1))][j - 1])
                    lookup[i][j] = lookup[i][j - 1];
                else
                    lookup[i][j] =
                            lookup[i + (1 << (j - 1))][j - 1];
            }
        }
    }

/*    Returns minimum of arr[L..R]*/

    static int query(int L, int R)
    {

/*        Find highest power of 2 that is smaller
        than or equal to count of elements in given
        range. For [2, 10], j = 3*/

        int j = (int)Math.log(R - L + 1);

/*        Compute minimum of last 2^j elements with first
        2^j elements in range.
        For [2, 10], we compare arr[lookup[0][3]] and
        arr[lookup[3][3]],*/

        if (lookup[L][j] <= lookup[R - (1 << j) + 1][j])
            return lookup[L][j];
        else
            return lookup[R - (1 << j) + 1][j];
    }

/*    Driver program*/

    public static void main (String[] args)
    {
        int a[] = { 7, 2, 3, 0, 5, 10, 3, 12, 18 };
        int n = a.length;
        buildSparseTable(a, n);
        System.out.println(query(0, 4));
        System.out.println(query(4, 7));
        System.out.println(query(7, 8));
    }
}

/*Java program to do range minimum query
using sparse table*/

import java.util.*;
class GFG
{
static final int MAX = 500;

/*lookup[i][j] is going to store GCD of
arr[i..j]. Ideally lookup table
size should not be fixed and should be
determined using n Log n. It is kept
constant to keep code simple.*/

static int [][]table = new int[MAX][MAX];

/*it builds sparse table.*/

static void buildSparseTable(int arr[],
                             int n)
{

/*    GCD of single element is
    element itself*/

    for (int i = 0; i < n; i++)
        table[i][0] = arr[i];

/*    Build sparse table*/

    for (int j = 1; j <= n; j++)
        for (int i = 0; i <= n - (1 << j); i++)
            table[i][j] = __gcd(table[i][j - 1],
                                table[i + (1 << (j - 1))][j - 1]);
}

/*Returns GCD of arr[L..R]*/

static int query(int L, int R)
{

/*    Find highest power of 2 that is
    smaller than or equal to count of
    elements in given range.For [2, 10], j = 3*/

    int j = (int)Math.log(R - L + 1);

/*    Compute GCD of last 2^j elements
    with first 2^j elements in range.
    For [2, 10], we find GCD of
    arr[lookup[0][3]] and arr[lookup[3][3]],*/

    return __gcd(table[L][j],
                 table[R - (1 << j) + 1][j]);
}
static int __gcd(int a, int b)
{
    return b == 0 ? a : __gcd(b, a % b);    
}

/*Driver Code*/

public static void main(String[] args)
{
    int a[] = { 7, 2, 3, 0, 5, 10, 3, 12, 18 };
    int n = a.length;
    buildSparseTable(a, n);
    System.out.print(query(0, 2) + "\n");
    System.out.print(query(1, 3) + "\n");
    System.out.print(query(4, 5) + "\n");
}
}

/*Java program to do range minimum query
in O(1) time with O(n*n) extra space
and O(n*n) preprocessing time.*/

import java.util.*;
class GFG {
    static int MAX = 500;

/*    lookup[i][j] is going to store index of
    minimum value in arr[i..j]*/

    static int[][] lookup = new int[MAX][MAX];

/*    Structure to represent a query range*/

    static class Query {
        int L, R;
        public Query(int L, int R)
        {
            this.L = L;
            this.R = R;
        }
    };

/*    Fills lookup array lookup[n][n] for
    all possible values of query ranges*/

    static void preprocess(int arr[], int n)
    {

/*        Initialize lookup[][] for
        the intervals with length 1*/

        for (int i = 0; i < n; i++)
            lookup[i][i] = i;

/*        Fill rest of the entries in bottom up manner*/

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++)

/*                To find minimum of [0,4],
                we compare minimum of
                arr[lookup[0][3]] with arr[4].*/

                if (arr[lookup[i][j - 1]] < arr[j])
                    lookup[i][j] = lookup[i][j - 1];
                else
                    lookup[i][j] = j;
        }
    }

/*    Prints minimum of given m query
    ranges in arr[0..n-1]*/

    static void RMQ(int arr[], int n, Query q[], int m)
    {

/*        Fill lookup table for
        all possible input queries*/

        preprocess(arr, n);

/*        One by one compute sum of all queries*/

        for (int i = 0; i < m; i++) {

/*            Left and right boundaries
            of current range*/

            int L = q[i].L, R = q[i].R;

/*            Print sum of current query range*/

            System.out.println("Minimum of [" + L + ", " + R
                               + "] is "
                               + arr[lookup[L][R]]);
        }
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        int a[] = { 7, 2, 3, 0, 5, 10, 3, 12, 18 };
        int n = a.length;
        Query q[] = { new Query(0, 4), new Query(4, 7),
                      new Query(7, 8) };
        int m = q.length;
        RMQ(a, n, q, m);
    }
}

/*Java program to do range minimum query
in O(1) time with O(n Log n) extra space
and O(n Log n) preprocessing time*/

import java.util.*;
class GFG {
    static int MAX = 500;

/*    lookup[i][j] is going to store index
    of minimum value in arr[i..j].
    Ideally lookup table size should not be fixed
    and should be determined using n Log n.
    It is kept constant to keep code simple.*/

    static int[][] lookup = new int[MAX][MAX];

/*    Structure to represent a query range*/

    static class Query {
        int L, R;
        public Query(int L, int R)
        {
            this.L = L;
            this.R = R;
        }
    };

/*    Fills lookup array lookup[][]
    in bottom up manner.*/

    static void preprocess(int arr[], int n)
    {

/*        Initialize M for the intervals
        with length 1*/

        for (int i = 0; i < n; i++)
            lookup[i][0] = i;

/*        Compute values from smaller
        to bigger intervals*/

        for (int j = 1; (1 << j) <= n; j++)
        {

/*            Compute minimum value for
            all intervals with size 2^j*/

            for (int i = 0;
                 (i + (1 << j) - 1) < n;
                 i++)
            {

/*                For arr[2][10], we compare
                arr[lookup[0][3]]
                and arr[lookup[3][3]]*/

                if (arr[lookup[i][j - 1]]
                    < arr[lookup[i + (1 << (j - 1))]
                                [j - 1]])
                    lookup[i][j] = lookup[i][j - 1];
                else
                    lookup[i][j]
                        = lookup[i + (1 << (j - 1))][j - 1];
            }
        }
    }

/*    Returns minimum of arr[L..R]*/

    static int query(int arr[], int L, int R)
    {

/*        For [2,10], j = 3*/

        int j = (int)Math.log(R - L + 1);

/*        For [2,10], we compare
        arr[lookup[0][3]]
        and arr[lookup[3][3]],*/

        if (arr[lookup[L][j]]
            <= arr[lookup[R - (1 << j) + 1][j]])
            return arr[lookup[L][j]];
        else
            return arr[lookup[R - (1 << j) + 1][j]];
    }

/*    Prints minimum of given m
    query ranges in arr[0..n-1]*/

    static void RMQ(int arr[], int n,
                    Query q[], int m)
    {

/*        Fills table lookup[n][Log n]*/

        preprocess(arr, n);

/*        One by one compute sum of all queries*/

        for (int i = 0; i < m; i++)
        {

/*            Left and right boundaries
            of current range*/

            int L = q[i].L, R = q[i].R;

/*            Print sum of current query range*/

            System.out.println("Minimum of ["
                               + L + ", " + R
                               + "] is "
                               + query(arr, L, R));
        }
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        int a[] = { 7, 2, 3, 0, 5, 10, 3, 12, 18 };
        int n = a.length;
        Query q[] = { new Query(0, 4), new Query(4, 7),
                      new Query(7, 8) };
        int m = q.length;
        RMQ(a, n, q, m);
    }
}

/*Java program to get updated array after
many array range add operation*/

import java.io.*;
class GFG {

/*    Utility method to add value val,
    to range [lo, hi]*/

    static void add(int arr[], int N, int lo, int hi,
                    int val)
    {
        arr[lo] += val;
        if (hi != N - 1)
            arr[hi + 1] -= val;
    }

/*    Utility method to get actual array from
    operation array*/

    static void updateArray(int arr[], int N)
    {

/*        convert array into prefix sum array*/

        for (int i = 1; i < N; i++)
            arr[i] += arr[i - 1];
    }

/*    method to print final updated array*/

    static void printArr(int arr[], int N)
    {
        updateArray(arr, N);
        for (int i = 0; i < N; i++)
            System.out.print("" + arr[i] + " ");
        System.out.print("\n");
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int N = 6;
        int arr[] = new int[N];

/*        Range add Queries*/

        add(arr, N, 0, 2, 100);
        add(arr, N, 1, 5, 100);
        add(arr, N, 2, 3, 100);
        printArr(arr, N);
    }
}

/*Java program for queries of GCD excluding
given range of elements.*/

import java.util.*;
class GFG {

/*Calculating GCD using euclid algorithm*/

static int GCD(int a, int b)
{
    if (b == 0)
    return a;
    return GCD(b, a % b);
}

/*Filling the prefix and suffix array*/

static void FillPrefixSuffix(int prefix[],
          int arr[], int suffix[], int n)
{

/*    Filling the prefix array following relation
    prefix(i) = GCD(prefix(i-1), arr(i))*/

    prefix[0] = arr[0];
    for (int i = 1; i < n; i++)
    prefix[i] = GCD(prefix[i - 1], arr[i]);

/*    Filling the suffix array following the
    relation suffix(i) = GCD(suffix(i+1), arr(i))*/

    suffix[n - 1] = arr[n - 1];
    for (int i = n - 2; i >= 0; i--)
    suffix[i] = GCD(suffix[i + 1], arr[i]);
}

/*To calculate gcd of the numbers outside range*/

static int GCDoutsideRange(int l, int r,
      int prefix[], int suffix[], int n) {

/*    If l=0, we need to tell GCD of numbers
    from r+1 to n*/

    if (l == 0)
    return suffix[r + 1];

/*    If r=n-1 we need to return the gcd of
    numbers from 1 to l*/

    if (r == n - 1)
    return prefix[l - 1];
    return GCD(prefix[l - 1], suffix[r + 1]);
}

/*Driver code*/

public static void main(String[] args) {
    int arr[] = {2, 6, 9};
    int n = arr.length;
    int prefix[] = new int[n];
    int suffix[] = new int[n];
    FillPrefixSuffix(prefix, arr, suffix, n);
    int l = 0, r = 0;
    System.out.println(GCDoutsideRange
             (l, r, prefix, suffix, n));
    l = 1;
    r = 1;
    System.out.println(GCDoutsideRange
             (l, r, prefix, suffix, n));
    l = 1;
    r = 2;
    System.out.println(GCDoutsideRange
             (l, r, prefix, suffix, n));
}
}

/*Number of elements less than or equal to a given
number in a given subarray and allowing update
operations.*/

class Test
{
    static final int MAX = 10001;

/*    updating the bit array of a valid block*/

    static void update(int idx, int blk, int val, int bit[][])
    {
        for (; idx<MAX; idx += (idx&-idx))
            bit[blk][idx] += val;
    }

/*    answering the query*/

    static int query(int l, int r, int k, int arr[], int blk_sz,
                                          int bit[][])
    {

/*        traversing the first block in range*/

        int sum = 0;
        while (l<r && l%blk_sz!=0 && l!=0)
        {
            if (arr[l] <= k)
                sum++;
            l++;
        }

/*        Traversing completely overlapped blocks in
        range for such blocks bit array of that block
        is queried*/

        while (l + blk_sz <= r)
        {
            int idx = k;
            for (; idx > 0 ; idx -= idx&-idx)
                sum += bit[l/blk_sz][idx];
            l += blk_sz;
        }

/*        Traversing the last block*/

        while (l <= r)
        {
            if (arr[l] <= k)
                sum++;
            l++;
        }
        return sum;
    }

/*    Preprocessing the array*/

    static void preprocess(int arr[], int blk_sz, int n, int bit[][])
    {
        for (int i=0; i<n; i++)
            update(arr[i], i/blk_sz, 1, bit);
    }
    static void preprocessUpdate(int i, int v, int blk_sz,
                          int arr[], int bit[][])
    {

/*        updating the bit array at the original
        and new value of array*/

        update(arr[i], i/blk_sz, -1, bit);
        update(v, i/blk_sz, 1, bit);
        arr[i] = v;
    }

/*    Driver method*/

    public static void main(String args[])
    {
        int arr[] = {5, 1, 2, 3, 4};

/*        size of block size will be equal to square root of n*/

        int blk_sz = (int) Math.sqrt(arr.length);

/*        initialising bit array of each block
        as elements of array cannot exceed 10^4 so size
        of bit array is accordingly*/

        int bit[][] = new int[blk_sz+1][MAX];
        preprocess(arr, blk_sz, arr.length, bit);
        System.out.println(query(1, 3, 1, arr, blk_sz, bit));
        preprocessUpdate(3, 10, blk_sz, arr, bit);
        System.out.println(query(3, 3, 4, arr, blk_sz, bit));
        preprocessUpdate(2, 1, blk_sz, arr, bit);
        preprocessUpdate(0, 2, blk_sz, arr, bit);
        System.out.println(query (0, 4, 5, arr, blk_sz, bit));
    }
}

/*Simple java program to count
number of elements with
values in given range.*/

import java.io.*;
class GFG
{

/*    function to count elements within given range*/

    static int countInRange(int arr[], int n, int x, int y)
    {

/*        initialize result*/

        int count = 0;
        for (int i = 0; i < n; i++) {

/*            check if element is in range*/

            if (arr[i] >= x && arr[i] <= y)
                count++;
        }
        return count;
    }

