        i = 9;
        j = 12;
        System.out.println ( countInRange(arr, n, i, j)) ;
    }
}

/*Java implementation of finding number
represented by binary subarray*/

import java.util.Arrays;
class GFG {

/*    Fills pre[]*/

    static void precompute(int arr[], int n, int pre[])
    {
        Arrays.fill(pre, 0);
        pre[n - 1] = arr[n - 1] * (int)(Math.pow(2, 0));
        for (int i = n - 2; i >= 0; i--)
            pre[i] = pre[i + 1] + arr[i] * (1 << (n - 1 - i));
    }

/*    returns the number represented by a binary
    subarray l to r*/

    static int decimalOfSubarr(int arr[], int l, int r,
                               int n, int pre[])
    {

/*        if r is equal to n-1 r+1 does not exist*/

        if (r != n - 1)
            return (pre[l] - pre[r + 1]) / (1 << (n - 1 - r));
        return pre[l] / (1 << (n - 1 - r));
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = { 1, 0, 1, 0, 1, 1 };
        int n = arr.length;
        int pre[] = new int[n];
        precompute(arr, n, pre);
        System.out.println(decimalOfSubarr(arr,
                                           2, 4, n, pre));
        System.out.println(decimalOfSubarr(arr,
                                           4, 5, n, pre));
    }
}

/*Java program to Count elements which
divides all numbers in range L-R*/

import java.io.*;
class GFG
{

/*function to count element
Time complexity O(n^2) worst case*/

static int answerQuery(int a[], int n,
                       int l, int r)
{

/*    answer for query*/

    int count = 0;

/*    0 based index*/

    l = l - 1;

/*    iterate for all elements*/

    for (int i = l; i < r; i++)
    {
        int element = a[i];
        int divisors = 0;

/*        check if the element divides
        all numbers in range*/

        for (int j = l; j < r; j++)
        {

/*            no of elements*/

            if (a[j] % a[i] == 0)
                divisors++;
            else
                break;
        }

/*        if all elements are divisible by a[i]*/

        if (divisors == (r - l))
            count++;
    }

/*    answer for every query*/

    return count;
}

/*Driver Code*/

public static void main (String[] args)
{
    int a[] = { 1, 2, 3, 5 };
    int n = a.length;
    int l = 1, r = 4;
    System.out.println( answerQuery(a, n, l, r));
    l = 2; r = 4;
    System.out.println( answerQuery(a, n, l, r));
}
}

/*Java program to find smallest integer X
such that sum of its XOR with range is
maximum.*/

import java.lang.Math;
class GFG {
    private static final int MAX = 2147483647;
    static int[][] one = new int[100001][32];

/*    Function to make prefix array which counts
    1's of each bit up to that number*/

    static void make_prefix(int A[], int n)
    {
        for (int j = 0; j < 32; j++)
            one[0][j] = 0;

/*        Making a prefix array which sums
        number of 1's up to that position*/

        for (int i = 1; i <= n; i++)
        {
            int a = A[i - 1];
            for (int j = 0; j < 32; j++)
            {
                int x = (int)Math.pow(2, j);

/*                If j-th bit of a number is set then
                add one to previously counted 1's*/

                if ((a & x) != 0)
                    one[i][j] = 1 + one[i - 1][j];
                else
                    one[i][j] = one[i - 1][j];
            }
        }
    }

/*    Function to find X*/

    static int Solve(int L, int R)
    {
        int l = L, r = R;
        int tot_bits = r - l + 1;

/*        Initially taking maximum
        value all bits 1*/

        int X = MAX;

/*        Iterating over each bit*/

        for (int i = 0; i < 31; i++)
        {

/*            get 1's at ith bit between the range
            L-R by subtracting 1's till
            Rth number - 1's till L-1th number*/

            int x = one[r][i] - one[l - 1][i];

/*            If 1's are more than or equal to 0's
            then unset the ith bit from answer*/

            if (x >= tot_bits - x)
            {
                int ith_bit = (int)Math.pow(2, i);

/*                Set ith bit to 0 by
                doing Xor with 1*/

                X = X ^ ith_bit;
            }
        }
        return X;
    }

/*    Driver program*/

    public static void main(String[] args)
    {
        int n = 5, q = 3;
        int A[] = { 210, 11, 48, 22, 133 };
        int L[] = { 1, 4, 2 }, R[] = { 3, 14, 4 };
        make_prefix(A, n);
        for (int j = 0; j < q; j++)
            System.out.println(Solve(L[j], R[j]));
    }
}

/*Java program to perform range queries
over range queries.*/

import java.util.*;
class GFG
{

/*    Function to execute type 1 query*/

    static void type1(int[] arr, int start, int limit)
    {

/*        incrementing the array by 1 for type
        1 queries*/

        for (int i = start; i <= limit; i++)
            arr[i]++;
    }

/*    Function to execute type 2 query*/

    static void type2(int[] arr, int[][] query,
                      int start, int limit)
    {
        for (int i = start; i <= limit; i++)
        {

/*            If the query is of type 1 function
            call to type 1 query*/

            if (query[i][0] == 1)
                type1(arr, query[i][1], query[i][2]);

/*            If the query is of type 2 recursive call
            to type 2 query*/

            else if (query[i][0] == 2)
                type2(arr, query, query[i][1],
                                  query[i][2]);
        }
    }

/*    Driver Code*/

    public static void main(String[] args)
    {

/*        Input size of array amd number of queries*/

        int n = 5, m = 5;
        int[] arr = new int[n + 1];

/*        Build query matrix*/

        int[] temp = { 1, 1, 2, 1, 4, 5, 2,
                       1, 2, 2, 1, 3, 2, 3, 4 };
        int[][] query = new int[6][4];
        int j = 0;
        for (int i = 1; i <= m; i++)
        {
            query[i][0] = temp[j++];
            query[i][1] = temp[j++];
            query[i][2] = temp[j++];
        }

/*        Perform queries*/

        for (int i = 1; i <= m; i++)
            if (query[i][0] == 1)
                type1(arr, query[i][1], query[i][2]);
            else if (query[i][0] == 2)
                type2(arr, query, query[i][1],
                                  query[i][2]);

/*        printing the result*/

        for (int i = 1; i <= n; i++)
            System.out.print(arr[i] + " ");
        System.out.println();
    }
}

/*Java program to perform range queries
over range queries.*/

import java.util.Arrays;
class GFG
{

/*    Function to create the record array*/

    static void record_sum(int record[], int l,
                           int r, int n, int adder)
    {
        for (int i = l; i <= r; i++)
        {
            record[i] += adder;
        }
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        int n = 5, m = 5;
        int arr[] = new int[n];

/*        Build query matrix*/

        Arrays.fill(arr, 0);
        int query[][] = {{1, 1, 2}, {1, 4, 5},
                         {2, 1, 2}, {2, 1, 3},
                         {2, 3, 4}};
        int record[] = new int[m];
        Arrays.fill(record, 0);
        for (int i = m - 1; i >= 0; i--)
        {

/*            If query is of type 2 then function
            call to record_sum*/

            if (query[i][0] == 2)
            {
                record_sum(record, query[i][1] - 1,
                                   query[i][2] - 1, m,
                                   record[i] + 1);
            }

/*            If query is of type 1 then
            simply add 1 to the record array*/

            else
            {
                record_sum(record, i, i, m, 1);
            }
        }

/*        for type 1 queries adding the contains of
        record array to the main array record array*/

        for (int i = 0; i < m; i++)
        {
            if (query[i][0] == 1)
            {
                record_sum(arr, query[i][1] - 1,
                                query[i][2] - 1,
                                n, record[i]);
            }
        }

/*        printing the array*/

        for (int i = 0; i < n; i++)
        {
            System.out.print(arr[i] + " ");
        }
    }
}

/*Java program to perform range queries over range
queries.*/

public class GFG {
    static final int max = 10000;

/*For prefix sum array*/

    static void update(int arr[], int l) {
        arr[l] += arr[l - 1];
    }

/*This function is used to apply square root
decomposition in the record array*/

    static void record_func(int block_size, int block[],
            int record[], int l, int r, int value) {

/*        traversing first block in range*/

        while (l < r && l % block_size != 0 && l != 0) {
            record[l] += value;
            l++;
        }

/*        traversing completely overlapped blocks in range*/

        while (l + block_size <= r + 1) {
            block[l / block_size] += value;
            l += block_size;
        }

/*        traversing last block in range*/

        while (l <= r) {
            record[l] += value;
            l++;
        }
    }

/*Function to print the resultant array*/

    static void print(int arr[], int n) {
        for (int i = 0; i < n; i++) {
            System.out.print(arr[i] + " ");
        }
    }

/*Driver code*/

    public static void main(String[] args) {
        int n = 5, m = 5;
        int arr[] = new int[n], record[] = new int[m];
        int block_size = (int) Math.sqrt(m);
        int block[] = new int[max];
        int command[][] = {{1, 1, 2}, {1, 4, 5},
        {2, 1, 2}, {2, 1, 3},
        {2, 3, 4}};
        for (int i = m - 1; i >= 0; i--) {

/*            If query is of type 2 then function
            call to record_func*/

            if (command[i][0] == 2) {
                int x = i / (block_size);
                record_func(block_size, block, record,
                        command[i][1] - 1, command[i][2] - 1,
                        (block[x] + record[i] + 1));

/*If query is of type 1 then simply add1 to the record array*/

} 
            else {
                record[i]++;
            }
        }

/*        Merging the value of the block in the record array*/

        for (int i = 0; i < m; i++) {
            int check = (i / block_size);
            record[i] += block[check];
        }
        for (int i = 0; i < m; i++) {

/*            If query is of type 1 then the array
            elements are over-written by the record
              array*/

            if (command[i][0] == 1) {
                arr[command[i][1] - 1] += record[i];
                if ((command[i][2] - 1) < n - 1) {
                    arr[(command[i][2])] -= record[i];
                }
            }
        }

/*        The prefix sum of the array*/

        for (int i = 1; i < n; i++) {
            update(arr, i);
        }

/*        Printing the resultant array*/

        print(arr, n);
    }
}

/*Java program to perform range queries over range
queries.*/

import java.io.*;
import java.util.*;
class GFG
{

/*  Updates a node in Binary Index Tree (BITree) at given index
  in BITree.  The given value 'val' is added to BITree[i] and
  all of its ancestors in tree.*/

  static void updateBIT(int BITree[], int n, int index, int val)
  {

/*    index in BITree[] is 1 more than the index in arr[]*/

    index = index + 1;

/*    Traverse all ancestors and add 'val'*/

    while (index <= n)
    {

/*      Add 'val' to current node of BI Tree*/

      BITree[index] = (val + BITree[index]);

/*      Update index to that of parent in update View*/

      index = (index + (index & (-index)));
    }
    return;
  }

/*  Constructs and returns a Binary Indexed Tree for given
  array of size n.*/

  static int[] constructBITree(int n)
  {

/*    Create and initialize BITree[] as 0*/

    int[] BITree = new int[n + 1];
    for (int i = 1; i <= n; i++) 
      BITree[i] = 0;
    return BITree;
  }

/*  Returns sum of arr[0..index]. This function assumes
  that the array is preprocessed and partial sums of
  array elements are stored in BITree[]*/

  static int getSum(int BITree[], int index)
  {
    int sum = 0;

/*    index in BITree[] is 1 more than the index in arr[]*/

    index = index + 1;

/*    Traverse ancestors of BITree[index]*/

    while (index > 0)
    {

/*      Add element of BITree to sum*/

      sum = (sum + BITree[index]);

/*      Move index to parent node in getSum View*/

      index -= index & (-index);
    }
    return sum;
  }

/*  Function to update the BITree*/

  static void update(int BITree[], int l, int r, int n, int val)
  {
    updateBIT(BITree, n, l, val);
    updateBIT(BITree, n, r + 1, -val);
    return;
  }

/*  Driver code*/

  public static void main (String[] args)
  {
    int n = 5, m = 5;
    int temp[] = { 1, 1, 2, 1, 4, 5, 2, 1, 2,
                  2, 1, 3, 2, 3, 4 };
    int[][] q = new int[6][3];
    int j = 0;
    for (int i = 1; i <= m; i++) {
      q[i][0] = temp[j++];
      q[i][1] = temp[j++];
      q[i][2] = temp[j++];
    }

/*    BITree for query of type 2*/

    int[] BITree = constructBITree(m);

/*    BITree for query of type 1*/

    int[] BITree2 = constructBITree(n);

/*    Input the queries in a 2D matrix*/
Scanner sc=new Scanner(System.in);
        for (int i = 1; i <= m; i++) 
        {
            q[i][0]=sc.nextInt();
            q[i][1]=sc.nextInt();
            q[i][2]=sc.nextInt();
        }

/*    If query is of type 2 then function call 
    to update with BITree*/

    for (int i = m; i >= 1; i--)        
      if (q[i][0] == 2)
        update(BITree, q[i][1] - 1, q[i][2] - 1, m, 1);
    for (int i = m; i >= 1; i--) {
      if (q[i][0] == 2) {
        int val = getSum(BITree, i - 1);
        update(BITree, q[i][1] - 1, q[i][2] - 1, m, val);
      }
    }

/*    If query is of type 1 then function call 
    to update with BITree2*/

    for (int i = m; i >= 1; i--) {        
      if (q[i][0] == 1) {
        int val = getSum(BITree, i - 1);
        update(BITree2, q[i][1] - 1, q[i][2] - 1,
               n, (val + 1));
      }
    }
    for (int i = 1; i <= n; i++) 
      System.out.print(getSum(BITree2, i - 1)+" ");
  }
}

/*Java program to determine if the element
exists for different range queries*/

import java.util.*;
class GFG 
{

/*Structure to represent a query range*/

static class Query
{
    int L, R, X;
    public Query(int L, int R, int X) 
    {
        this.L = L;
        this.R = R;
        this.X = X;
    }
};
static int maxn = 100;
static int []root = new int[maxn];

/*Find the root of the group containing
the element at index x*/

static int find(int x)
{
    if(x == root[x])
        return x;
    else
        return root[x] = find(root[x]);
}

/*merge the two groups containing elements
at indices x and y into one group*/

static void uni(int x, int y)
{
    int p = find(x), q = find(y);
    if (p != q) 
    {
        root[p] = root[q];
    }
}
static void initialize(int a[], int n, 
                       Query q[], int m)
{

/*    make n subsets with every
    element as its root*/

    for (int i = 0; i < n; i++)
        root[i] = i;

/*    consecutive elements equal in value are
    merged into one single group*/

    for (int i = 1; i < n; i++)
        if (a[i] == a[i - 1])
            uni(i, i - 1);
}

/*Driver code*/

public static void main(String args[])
{
    int a[] = { 1, 1, 5, 4, 5 };
    int n = a.length;
    Query q[] = { new Query(0, 2, 2 ), 
                  new Query( 1, 4, 1 ),
                  new Query( 2, 4, 5 ) };
    int m = q.length;
    initialize(a, n, q, m);
    for (int i = 0; i < m; i++)
    {
        int flag = 0;
        int l = q[i].L, r = q[i].R, x = q[i].X;
        int p = r;
        while (p >= l)
        {

/*            check if the current element in
            consideration is equal to x or not
            if it is equal, then x exists in the range*/

            if (a[p] == x)
            {
                flag = 1;
                break;
            }
            p = find(p) - 1;
        }

/*        Print if x exists or not*/

        if (flag != 0)
            System.out.println(x + " exists between [" + 
                               l + ", " + r + "] ");
        else
            System.out.println(x + " does not exist between [" + 
                               l + ", " + r + "] ");
    }
}
}

/* Java Program to answer Q queries to
find number of times an element x
appears x times in a Query subarray */

import java.util.HashMap;
import java.util.Map;
class GFG
{

/* Returns the count of number x with
frequency x in the subarray from
start to end */

static int solveQuery(int start, int end, int arr[])
{

/*    map for frequency of elements*/

    Map<Integer,Integer> mp = new HashMap<>();

/*    store frequency of each element
    in arr[start; end]*/

    for (int i = start; i <= end; i++)
        mp.put(arr[i],mp.get(arr[i]) == null?1:mp.get(arr[i])+1);

/*    Count elements with same frequency
    as value*/

    int count = 0;
    for (Map.Entry<Integer,Integer> entry : mp.entrySet())
        if (entry.getKey() == entry.getValue())
            count++;
    return count;
}

/*Driver code*/

public static void main(String[] args)
{
    int A[] = { 1, 2, 2, 3, 3, 3 };
    int n = A.length;

/*    2D array of queries with 2 columns*/

    int [][]queries = { { 0, 1 },
                        { 1, 1 },
                        { 0, 2 },
                        { 1, 3 },
                        { 3, 5 },
                        { 0, 5 } };

/*    calculating number of queries*/

    int q = queries.length;
    for (int i = 0; i < q; i++)
    {
        int start = queries[i][0];
        int end = queries[i][1];
        System.out.println("Answer for Query " + (i + 1)
            + " = " + solveQuery(start,
            end, A));
    }
}
}

/*Java program to count the number of
indexes in range L R such that
Ai = Ai+1*/

class GFG {

/*    function that answers every query
    in O(r-l)*/

    static int answer_query(int a[], int n,
                              int l, int r)
    {

/*        traverse from l to r and count
        the required indexes*/

        int count = 0;
        for (int i = l; i < r; i++)
            if (a[i] == a[i + 1])
                count += 1;
        return count;
    }

