                   answer_query(a, n, L, R));

/*        2nd query*/

        L = 0;
        R = 4;
        System.out.println(
                  answer_query(a, n, L, R));
    }
}

/*Java program to count
the number of indexes
in range L R such that
Ai=Ai+1*/

class GFG {
public static int N = 1000;

/*Array to store count
of index from 0 to
i that obey condition*/

static int prefixans[] = new int[1000];

/*precomputing prefixans[] array*/

public static void countIndex(int a[], int n)
{

/*    traverse to compute
    the prefixans[] array*/

    for (int i = 0; i < n; i++) {
        if (i + 1 < n && a[i] == a[i + 1])
            prefixans[i] = 1;
        if (i != 0)
            prefixans[i] += prefixans[i - 1];
    }
}

/*function that answers
every query in O(1)*/

public static int answer_query(int l, int r)
{
    if (l == 0)
        return prefixans[r - 1];
    else
        return prefixans[r - 1] -
               prefixans[l - 1];
}

/*Driver Code*/

public static void main(String args[])
{
    int a[] = {1, 2, 2, 2, 3, 3, 4, 4, 4};
    int n = 9;

/*    pre-computation*/

    countIndex(a, n);
    int L, R;

/*    1-st query*/

    L = 1;
    R = 8;
    System.out.println(answer_query(L, R));

/*    2nd query*/

    L = 0;
    R = 4;
    System.out.println(answer_query(L, R));
}
}

/*Java implementation of brute 
force solution. */

import java.util.LinkedHashSet;
class GFG
{

/*Function to check if the given 
number has repeated digit or not */

static int repeated_digit(int n) 
{
    LinkedHashSet<Integer> s = new LinkedHashSet<>();

/*    Traversing through each digit */

    while (n != 0) 
    {
        int d = n % 10;

/*        if the digit is present 
        more than once in the 
        number */

        if (s.contains(d))
        {

/*            return 0 if the number 
            has repeated digit */

            return 0;
        }
        s.add(d);
        n = n / 10;
    }

/*    return 1 if the number has 
    no repeated digit */

    return 1;
}

/*Function to find total number 
in the given range which has 
no repeated digit */

static int calculate(int L, int R) 
{
    int answer = 0;

/*    Traversing through the range */

    for (int i = L; i < R + 1; ++i) 
    {

/*        Add 1 to the answer if i has 
        no repeated digit else 0 */

        answer = answer + repeated_digit(i);
    }
    return answer;
}

/*Driver Code */

public static void main(String[] args) 
{
    int L = 1, R = 100;

/*    Calling the calculate */

    System.out.println(calculate(L, R));
}
}

