    static int MAX = 100;

/*    Prefix Array*/

    static Vector<Integer> Prefix = new Vector<>();

/*    Function to check if the given
    number has repeated digit or not*/

    static int repeated_digit(int n)
    {
        HashSet<Integer> a = new HashSet<>();
        int d;

/*        Traversing through each digit*/

        while (n != 0) 
        {
            d = n % 10;

/*            if the digit is present
            more than once in the
            number*/

            if (a.contains(d))

/*                return 0 if the number
                has repeated digit*/

                return 0;
            a.add(d);
            n /= 10;
        }

/*        return 1 if the number has no
        repeated digit*/

        return 1;
    }

/*    Function to pre calculate
    the Prefix array*/

    static void pre_calculations() 
    {
        Prefix.add(0);
        Prefix.add(repeated_digit(1));

/*        Traversing through the numbers
        from 2 to MAX*/

        for (int i = 2; i < MAX + 1; i++)

/*            Generating the Prefix array*/

            Prefix.add(repeated_digit(i) + Prefix.elementAt(i - 1));
    }

/*    Calclute Function*/

    static int calculate(int L, int R)
    {

/*        Answer*/

        return Prefix.elementAt(R) - Prefix.elementAt(L - 1);
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        int L = 1, R = 100;

/*        Pre-calculating the Prefix array.*/

        pre_calculations();

/*        Calling the calculate function
        to find the total number of number
        which has no repeated digit*/

        System.out.println(calculate(L, R));
    }
}

/*Java code to demonstrate Difference Array*/

class GFG {

/*    Creates a diff array D[] for A[] and returns
    it after filling initial values.*/

    static void initializeDiffArray(int A[], int D[])
    {
        int n = A.length;

/*    We use one extra space because
    update(l, r, x) updates D[r+1]*/

        D[0] = A[0];
        D[n] = 0;
        for (int i = 1; i < n; i++)
            D[i] = A[i] - A[i - 1];
    }

/*    Does range update*/

    static void update(int D[], int l, int r, int x)
    {
        D[l] += x;
        D[r + 1] -= x;
    }

/*    Prints updated Array*/

    static int printArray(int A[], int D[])
    {
        for (int i = 0; i < A.length; i++) {
            if (i == 0)
                A[i] = D[i];

/*            Note that A[0] or D[0] decides
            values of rest of the elements.*/

            else
                A[i] = D[i] + A[i - 1];
            System.out.print(A[i] + " ");
        }
        System.out.println();
        return 0;
    }

/*    Driver Code*/

    public static void main(String[] args)
    {

/*        Array to be updated*/

        int A[] = { 10, 5, 20, 40 };
        int n = A.length;

/*        Create and fill difference Array
        We use one extra space because
        update(l, r, x) updates D[r+1]*/

        int D[] = new int[n + 1];
        initializeDiffArray(A, D);

/*        After below update(l, r, x), the
        elements should become 20, 15, 20, 40*/

        update(D, 0, 1, 10);
        printArray(A, D);

/*        After below updates, the
        array should become 30, 35, 70, 60*/

        update(D, 1, 3, 20);
        update(D, 2, 2, 30);
        printArray(A, D);
    }
}

/*Java program to print largest contiguous array sum*/

import java.io.*;
import java.util.*;
class Kadane
{

    static int maxSubArraySum(int a[])
    {
        int size = a.length;
        int max_so_far = Integer.MIN_VALUE, max_ending_here = 0;
        for (int i = 0; i < size; i++)
        {
            max_ending_here = max_ending_here + a[i];
            if (max_so_far < max_ending_here)
                max_so_far = max_ending_here;
            if (max_ending_here < 0)
                max_ending_here = 0;
        }
        return max_so_far;
    }

/*Driver program to test maxSubArraySum*/

    public static void main (String[] args)
    {
        int [] a = {-2, -3, 4, -1, -2, 1, 5, -3};
        System.out.println("Maximum contiguous sum is " +
                                       maxSubArraySum(a));
    }
}

static int maxSubArraySum(int a[],int size)
{
    int max_so_far = a[0], max_ending_here = 0;
    for (int i = 0; i < size; i++)
    {
        max_ending_here = max_ending_here + a[i];
        if (max_ending_here < 0)
            max_ending_here = 0;

/* Do not compare for all
           elements. Compare only
           when max_ending_here > 0 */

        else if (max_so_far < max_ending_here)
            max_so_far = max_ending_here;
    }
    return max_so_far;
}

/*Java program to print largest contiguous
array sum*/

import java.io.*;
class GFG {
    static int maxSubArraySum(int a[], int size)
    {
    int max_so_far = a[0];
    int curr_max = a[0];
    for (int i = 1; i < size; i++)
    {
           curr_max = Math.max(a[i], curr_max+a[i]);
        max_so_far = Math.max(max_so_far, curr_max);
    }
    return max_so_far;
    }

