/*Java implementation of simple method to find
minimum difference between any pair*/

class GFG
{

/*    Returns minimum difference between any pair*/

    static int findMinDiff(int[] arr, int n)
    {

/*        Initialize difference as infinite*/

        int diff = Integer.MAX_VALUE;

/*        Find the min diff by comparing difference
        of all possible pairs in given array*/

        for (int i=0; i<n-1; i++)
            for (int j=i+1; j<n; j++)
                if (Math.abs((arr[i] - arr[j]) )< diff)
                    diff = Math.abs((arr[i] - arr[j]));

/*        Return min diff   */

        return diff;
    }

/*    Driver method to test the above function*/

    public static void main(String[] args)
    {
        int arr[] = new int[]{1, 5, 3, 19, 18, 25};
        System.out.println("Minimum difference is "+
                              findMinDiff(arr, arr.length));
    }
}

/*Java program to find minimum difference between
any pair in an unsorted array*/

import java.util.Arrays;
class GFG
{

/*    Returns minimum difference between any pair*/

    static int findMinDiff(int[] arr, int n)
    {

/*           Sort array in non-decreasing order*/

           Arrays.sort(arr);

/*           Initialize difference as infinite*/

           int diff = Integer.MAX_VALUE;

/*           Find the min diff by comparing adjacent
           pairs in sorted array*/

           for (int i=0; i<n-1; i++)
              if (arr[i+1] - arr[i] < diff)
                  diff = arr[i+1] - arr[i];

/*           Return min diff*/

           return diff;
    }

/*    Driver method to test the above function*/

    public static void main(String[] args)
    {
        int arr[] = new int[]{1, 5, 3, 19, 18, 25};
        System.out.println("Minimum difference is "+
                              findMinDiff(arr, arr.length));
    }
}

/*A Simple Java program to find longest common
subarray of two binary arrays with same sum*/

class Test
{
    static int arr1[] = new int[]{0, 1, 0, 1, 1, 1, 1};
    static int arr2[] = new int[]{1, 1, 1, 1, 1, 0, 1};

/*    Returns length of the longest common sum in arr1[]
    and arr2[]. Both are of same size n.*/

    static int longestCommonSum(int n)
    {

/*        Initialize result*/

        int maxLen = 0;

/*        One by one pick all possible starting points
        of subarrays*/

        for (int i=0; i<n; i++)
        {

/*           Initialize sums of current subarrays*/

           int sum1 = 0, sum2 = 0;

/*           Conider all points for starting with arr[i]*/

           for (int j=i; j<n; j++)
           {

/*               Update sums*/

               sum1 += arr1[j];
               sum2 += arr2[j];

/*               If sums are same and current length is
               more than maxLen, update maxLen*/

               if (sum1 == sum2)
               {
                 int len = j-i+1;
                 if (len > maxLen)
                    maxLen = len;
               }
           }
        }
        return maxLen;
    }

/*    Driver method to test the above function*/

    public static void main(String[] args)
    {
        System.out.print("Length of the longest common span with same sum is ");
        System.out.println(longestCommonSum(arr1.length));
    }
}

/*Java program to find largest subarray
with equal number of 0's and 1's.*/

import java.io.*;
import java.util.*;
class GFG
{

/*    Returns largest common subarray with equal
    number of 0s and 1s*/

    static int longestCommonSum(int[] arr1, int[] arr2, int n)
    {

/*        Find difference between the two*/

        int[] arr = new int[n];
        for (int i = 0; i < n; i++)
            arr[i] = arr1[i] - arr2[i];

/*        Creates an empty hashMap hM*/

        HashMap<Integer, Integer> hM = new HashMap<>();

/*Initialize sum of elements*/

int sum = 0;

/*Initialize result*/

int max_len = 0;

/*        Traverse through the given array*/

        for (int i = 0; i < n; i++)
        {

/*            Add current element to sum*/

            sum += arr[i];

/*            To handle sum=0 at last index*/

            if (sum == 0)
                max_len = i + 1;

/*            If this sum is seen before,
            then update max_len if required*/

            if (hM.containsKey(sum))
                max_len = Math.max(max_len, i - hM.get(sum));

/*Else put this sum in hash table*/

else 
                hM.put(sum, i);
        }
        return max_len;
    }

/*    Driver code*/

    public static void main(String args[])
    {
            int[] arr1 = {0, 1, 0, 1, 1, 1, 1};
            int[] arr2 = {1, 1, 1, 1, 1, 0, 1};
            int n = arr1.length;
            System.out.println(longestCommonSum(arr1, arr2, n));
    }
}

/*Java program to sort an array according absolute
difference with x.*/

import java.io.*;
import java.util.*;
class GFG
{

/*    Function to sort an array according absolute
    difference with x.*/

    static void rearrange(int[] arr, int n, int x)
    {
            TreeMap<Integer, ArrayList<Integer>> m =
                                    new TreeMap<>();

/*            Store values in a map with the difference
            with X as key*/

            for (int i = 0; i < n; i++)
            {
                int diff = Math.abs(x - arr[i]);
                if (m.containsKey(diff))
                {
                    ArrayList<Integer> al = m.get(diff);
                    al.add(arr[i]);
                    m.put(diff, al);
                }
                else
                {
                        ArrayList<Integer> al = new
                                       ArrayList<>();
                        al.add(arr[i]);
                        m.put(diff,al);
                }
            }

/*            Update the values of array*/

            int index = 0;
            for (Map.Entry entry : m.entrySet())
            {
                ArrayList<Integer> al = m.get(entry.getKey());
                for (int i = 0; i < al.size(); i++)
                        arr[index++] = al.get(i);
            }
    }

/*    Function to print the array*/

    static void printArray(int[] arr, int n)
    {
            for (int i = 0; i < n; i++)
                System.out.print(arr[i] + " ");
    }

/*    Driver code*/

    public static void main(String args[])
    {
            int[] arr = {10, 5, 3, 9 ,2};
            int n = arr.length;
            int x = 7;
            rearrange(arr, n, x);
            printArray(arr, n);
    }
}

/*Java implementation of naive method for sorting
an array in wave form.*/

import java.util.*;
class SortWave
{

/*    A utility method to swap two numbers.*/

    void swap(int arr[], int a, int b)
    {
        int temp = arr[a];
        arr[a] = arr[b];
        arr[b] = temp;
    }

/*    This function sorts arr[0..n-1] in wave form, i.e.,
    arr[0] >= arr[1] <= arr[2] >= arr[3] <= arr[4]..*/

    void sortInWave(int arr[], int n)
    {

/*        Sort the input array*/

        Arrays.sort(arr);

/*        Swap adjacent elements*/

        for (int i=0; i<n-1; i += 2)
            swap(arr, i, i+1);
    }

/*    Driver method*/

    public static void main(String args[])
    {
        SortWave ob = new SortWave();
        int arr[] = {10, 90, 49, 2, 1, 5, 23};
        int n = arr.length;
        ob.sortInWave(arr, n);
        for (int i : arr)
            System.out.print(i + " ");
    }
}

/*A O(n) Java program to sort an input array in wave form*/

class SortWave
{

/*    A utility method to swap two numbers.*/

    void swap(int arr[], int a, int b)
    {
        int temp = arr[a];
        arr[a] = arr[b];
        arr[b] = temp;
    }

/*    This function sorts arr[0..n-1] in wave form, i.e.,
    arr[0] >= arr[1] <= arr[2] >= arr[3] <= arr[4]....*/

    void sortInWave(int arr[], int n)
    {

/*        Traverse all even elements*/

        for (int i = 0; i < n; i+=2)
        {

/*            If current even element is smaller
            than previous*/

            if (i>0 && arr[i-1] > arr[i] )
                swap(arr, i-1, i);

/*            If current even element is smaller
            than next*/

            if (i<n-1 && arr[i] < arr[i+1] )
                swap(arr, i, i + 1);
        }
    }

/*    Driver program to test above function*/

    public static void main(String args[])
    {
        SortWave ob = new SortWave();
        int arr[] = {10, 90, 49, 2, 1, 5, 23};
        int n = arr.length;
        ob.sortInWave(arr, n);
        for (int i : arr)
            System.out.print(i+" ");
    }
}

/*Java program to test whether an array
can be sorted by swapping adjacent
elements using boolean array*/

class GFG
{

/*    Return true if array can be
    sorted otherwise false*/

    static int sortedAfterSwap(int[] A,
                            int[] B, int n)
    {
        int t = 0;
        for (int i = 0; i < n - 1; i++)
        {
            if (B[i] != 0)
            {
                if (A[i] != i + 1)
                    t = A[i];
                    A[i] = A[i + 1];
                    A[i + 1] = t;
            }
        }

/*        Check if array is sorted or not*/

        for (int i = 0; i < n; i++)
        {
            if (A[i] != i + 1)
                return 0;
        }
        return 1;
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        int[] A = { 1, 2, 5, 3, 4, 6 };
        int[] B = { 0, 1, 1, 1, 0 };
        int n = A.length;
        if (sortedAfterSwap(A, B, n) == 0)
            System.out.println("A can be sorted");
        else
            System.out.println("A can not be sorted");
    }
}

