/*Java program to find union and intersection
using similar Hashing Technique
without using any predefined Java Collections
Time Complexity best case & avg case = O(m+n)
Worst case = O(nlogn)
package com.arrays.math;*/

public class UnsortedIntersectionUnion {

/*    Prints intersection of arr1[0..n1-1] and
    arr2[0..n2-1]*/

    public void findPosition(int a[], int b[])
    {
        int v = (a.length + b.length);
        int ans[] = new int[v];
        int zero1 = 0;
        int zero2 = 0;
        System.out.print("Intersection : ");

/*        Iterate first array*/

        for (int i = 0; i < a.length; i++)
            zero1 = iterateArray(a, v, ans, i);

/*        Iterate second array*/

        for (int j = 0; j < b.length; j++)
            zero2 = iterateArray(b, v, ans, j);
        int zero = zero1 + zero2;
        placeZeros(v, ans, zero);
        printUnion(v, ans, zero);
    }

/*    Prints union of arr1[0..n1-1] and arr2[0..n2-1]*/

    private void printUnion(int v, int[] ans, int zero)
    {
        int zero1 = 0;
        System.out.print("\nUnion : ");
        for (int i = 0; i < v; i++) {
            if ((zero == 0 && ans[i] == 0)
                || (ans[i] == 0 && zero1 > 0))
                continue;
            if (ans[i] == 0)
                zero1++;
            System.out.print(ans[i] + ",");
        }
    }

/*placeZeroes function*/

    private void placeZeros(int v, int[] ans, int zero)
    {
        if (zero == 2) {
            System.out.println("0");
            int d[] = { 0 };
            placeValue(d, ans, 0, 0, v);
        }
        if (zero == 1) {
            int d[] = { 0 };
            placeValue(d, ans, 0, 0, v);
        }
    }

/*    Function to itreate array*/

    private int iterateArray(int[] a, int v, int[] ans,
                             int i)
    {
        if (a[i] != 0) {
            int p = a[i] % v;
            placeValue(a, ans, i, p, v);
        }
        else
            return 1;
        return 0;
    }

/*placeValue function*/

    private void placeValue(int[] a, int[] ans, int i,
                            int p, int v)
    {
        p = p % v;
        if (ans[p] == 0)
            ans[p] = a[i];
        else {
            if (ans[p] == a[i])
                System.out.print(a[i] + ",");
            else {

/*                Hashing collision happened increment
                position and do recursive call*/

                p = p + 1;
                placeValue(a, ans, i, p, v);
            }
        }
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int a[] = { 7, 1, 5, 2, 3, 6 };
        int b[] = { 3, 8, 6, 20, 7 };
        UnsortedIntersectionUnion uiu
            = new UnsortedIntersectionUnion();
        uiu.findPosition(a, b);
    }
}

/*Java implementation of the approach*/

import java.io.*;
class GFG {

/*    Utility function to print the contents of an array*/

    static void printArr(int arr[], int n)
    {
        for (int i = 0; i < n; i++)
            System.out.print(arr[i] + " ");
    }

/*    Function to sort the array of 0s, 1s and 2s*/

    static void sortArr(int arr[], int n)
    {
        int i, cnt0 = 0, cnt1 = 0, cnt2 = 0;

/*        Count the number of 0s, 1s and 2s in the array*/

        for (i = 0; i < n; i++) {
            switch (arr[i]) {
            case 0:
                cnt0++;
                break;
            case 1:
                cnt1++;
                break;
            case 2:
                cnt2++;
                break;
            }
        }

/*        Update the array*/

        i = 0;

/*        Store all the 0s in the beginning*/

        while (cnt0 > 0) {
            arr[i++] = 0;
            cnt0--;
        }

/*        Then all the 1s*/

        while (cnt1 > 0) {
            arr[i++] = 1;
            cnt1--;
        }

/*        Finally all the 2s*/

        while (cnt2 > 0) {
            arr[i++] = 2;
            cnt2--;
        }

/*        Print the sorted array*/

        printArr(arr, n);
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = { 0, 1, 1, 0, 1, 2, 1, 2, 0, 0, 0, 1 };
        int n = arr.length;
        sortArr(arr, n);
    }
}

/*Java code to count the number of
possible triangles using brute
force approach*/

import java.io.*;
import java.util.*;
class GFG
{

/*    Function to count all possible
    triangles with arr[] elements*/

    static int findNumberOfTriangles(int arr[], int n)
    {

/*        Count of triangles*/

        int count = 0;

/*        The three loops select three
        different values from array*/

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {

/*                The innermost loop checks for
                the triangle property*/

                for (int k = j + 1; k < n; k++)

/*                    Sum of two sides is greater
                    than the third*/

                    if (
                        arr[i] + arr[j] > arr[k]
                        && arr[i] + arr[k] > arr[j]
                        && arr[k] + arr[j] > arr[i])
                        count++;
            }
        }
        return count;
    }

/*    Driver code*/

     public static void main(String[] args)
    {
        int arr[] = { 10, 21, 22, 100, 101, 200, 300 };
        int size = arr.length;
        System.out.println( "Total number of triangles possible is "+
        findNumberOfTriangles(arr, size));
    }
}

/*Java program to count number of triangles that can be
formed from given array*/

import java.io.*;
import java.util.*;
class CountTriangles {

/*    Function to count all possible triangles with arr[]
    elements*/

    static int findNumberOfTriangles(int arr[])
    {
        int n = arr.length;

/*        Sort the array elements in non-decreasing order*/

        Arrays.sort(arr);

/*        Initialize count of triangles*/

        int count = 0;

/*        Fix the first element. We need to run till n-3 as
        the other two elements are selected from arr[i+1...n-1]*/

        for (int i = 0; i < n - 2; ++i) {

/*            Initialize index of the rightmost third element*/

            int k = i + 2;

/*            Fix the second element*/

            for (int j = i + 1; j < n; ++j) {

/* Find the rightmost element which is smaller
                than the sum of two fixed elements
                The important thing to note here is, we use
                the previous value of k. If value of arr[i] +
                arr[j-1] was greater than arr[k], then arr[i] +
                arr[j] must be greater than k, because the
                array is sorted. */

                while (k < n && arr[i] + arr[j] > arr[k])
                    ++k;

/* Total number of possible triangles that can be
                formed with the two fixed elements is k - j - 1.
                The two fixed elements are arr[i] and arr[j]. All
                elements between arr[j+1] to arr[k-1] can form a
                triangle with arr[i] and arr[j]. One is subtracted
                from k because k is incremented one extra in above
                while loop. k will always be greater than j. If j
                becomes equal to k, then above loop will increment
                k, because arr[k] + arr[i] is always/ greater than
                arr[k] */

                if (k > j)
                    count += k - j - 1;
            }
        }
        return count;
    }

/*Driver code*/

    public static void main(String[] args)
    {
        int arr[] = { 10, 21, 22, 100, 101, 200, 300 };
        System.out.println("Total number of triangles is " + findNumberOfTriangles(arr));
    }
}

/*Java implementation of the above approach*/

import java.util.*;
class GFG {

/*CountTriangles function*/

    static void CountTriangles(int[] A)
    {
        int n = A.length;
        Arrays.sort(A);
        int count = 0;
        for (int i = n - 1; i >= 1; i--) {
            int l = 0, r = i - 1;
            while (l < r) {
                if (A[l] + A[r] > A[i]) {

/*                    If it is possible with a[l], a[r]
                    and a[i] then it is also possible
                    with a[l+1]..a[r-1], a[r] and a[i]*/

                    count += r - l;

/*                    checking for more possible solutions*/

                    r--;
                }

/*if not possible check for higher values of arr[l]*/

else 
                {
                    l++;
                }
            }
        }
        System.out.print("No of possible solutions: " + count);
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        int[] A = { 4, 3, 5, 7, 6 };
        CountTriangles(A);
    }
}

/*Java program to finds number of pairs (x, y)
in an array such that x^y > y^x*/

import java.util.Arrays;
class Test {

/*    Function to return count of pairs with x as one
    element of the pair. It mainly looks for all values
    in Y[] where x ^ Y[i] > Y[i] ^ x*/

    static int count(int x, int Y[], int n, int NoOfY[])
    {

/*        If x is 0, then there cannot be any value in Y
        such that x^Y[i] > Y[i]^x*/

        if (x == 0)
            return 0;

/*        If x is 1, then the number of pais is equal to
        number of zeroes in Y[]*/

        if (x == 1)
            return NoOfY[0];

/*        Find number of elements in Y[] with values
        greater than x getting upperbound of x with
        binary search*/

        int idx = Arrays.binarySearch(Y, x);
        int ans;
        if (idx < 0) {
            idx = Math.abs(idx + 1);
            ans = Y.length - idx;
        }
        else {
            while (idx < n && Y[idx] == x) {
                idx++;
            }
            ans = Y.length - idx;
        }

/*        If we have reached here, then x must be greater
        than 1, increase number of pairs for y=0 and y=1*/

        ans += (NoOfY[0] + NoOfY[1]);

/*        Decrease number of pairs for x=2 and (y=4 or y=3)*/

        if (x == 2)
            ans -= (NoOfY[3] + NoOfY[4]);

/*        Increase number of pairs for x=3 and y=2*/

        if (x == 3)
            ans += NoOfY[2];
        return ans;
    }

/*    Function to returns count of pairs (x, y) such that
    x belongs to X[], y belongs to Y[] and x^y > y^x*/

    static long countPairs(int X[], int Y[], int m, int n)
    {

/*        To store counts of 0, 1, 2, 3 and 4 in array Y*/

        int NoOfY[] = new int[5];
        for (int i = 0; i < n; i++)
            if (Y[i] < 5)
                NoOfY[Y[i]]++;

/*        Sort Y[] so that we can do binary search in it*/

        Arrays.sort(Y);

/*Initialize result*/

long total_pairs = 0;

/*        Take every element of X and count pairs with it*/

        for (int i = 0; i < m; i++)
            total_pairs += count(X[i], Y, n, NoOfY);
        return total_pairs;
    }

/*    Driver method*/

    public static void main(String args[])
    {
        int X[] = { 2, 1, 6 };
        int Y[] = { 1, 5 };
        System.out.println(
            "Total pairs = "
            + countPairs(X, Y, X.length, Y.length));
    }
}

/*A simple Java program to
count pairs with difference k*/

import java.util.*;
import java.io.*;
class GFG {
    static int countPairsWithDiffK(int arr[],
                                    int n, int k)
    {
        int count = 0;

/*        Pick all elements one by one*/

        for (int i = 0; i < n; i++)
        {

/*            See if there is a pair
            of this picked element*/

            for (int j = i + 1; j < n; j++)
                if (arr[i] - arr[j] == k ||
                    arr[j] - arr[i] == k)
                    count++;
        }
        return count;
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int arr[] = { 1, 5, 3, 4, 2 };
        int n = arr.length;
        int k = 3;
        System.out.println("Count of pairs with given diff is "
                        + countPairsWithDiffK(arr, n, k));
    }
}

/* An efficient program to count pairs with difference k when the range
   numbers is small */

static int MAX=100000;
public static int countPairsWithDiffK(int arr[], int n, int k)
{

/*Initialize count*/

int count = 0;

/*    Initialize empty hashmap.*/

    boolean hashmap[MAX] = {false};

/*    Insert array elements to hashmap*/

    for (int i = 0; i < n; i++)
        hashmap[arr[i]] = true;
    for (int i = 0; i < n; i++)
    {
        int x = arr[i];
        if (x - k >= 0 && hashmap[x - k])
            count++;
        if (x + k < MAX && hashmap[x + k])
            count++;
        hashmap[x] = false;
    }
    return count;
}

import java.io.*;
class GFG {

static int BS(int[] arr, int X, int low)  {
        int high = arr.length - 1;
        int ans = arr.length;
        while(low <= high) {
            int mid = low + (high - low) / 2;
            if(arr[mid] >= X) {
                ans = mid;
                high = mid - 1;
            }
            else low = mid + 1;
        }
        return ans;
    }

static int countPairsWithDiffK(int[] arr, int N, int k) {
        int count = 0;
        Arrays.sort(arr);
        for(int i = 0 ; i < N ; ++i) {
            int X = BS(arr, arr[i] + k, i + 1);
            if(X != N) {
                int Y = BS(arr, arr[i] + k + 1, i + 1);
                count += Y - X;
            }
        }
        return count;
    }

public static void main (String[] args) {
        int arr[] = {1, 3, 5, 8, 6, 4, 6};
        int n = arr.length;
        int k = 2;
        System.out.println("Count of pairs with given diff is " +
                            countPairsWithDiffK(arr, n, k));
        }
}

import java.io.*;
class PairSum {

/*    Fills element in arr[] from its pair sum array pair[].
    n is size of arr[]*/

    static void constructArr(int arr[], int pair[], int n)
    {
        arr[0] = (pair[0]+pair[1]-pair[n-1]) / 2;
        for (int i=1; i<n; i++)
            arr[i] = pair[i-1]-arr[0];
    }

