        findMaxSubarraySum(A, B, n, m);
    }
}

/*Java Program implementation of the
above idea*/

import java.util.*;
class GFG
{

/*  Function to calculate the max sum of contigous
  subarray of B whose elements are not present in A*/

  static int findMaxSubarraySum(int A[], int B[])
  {
    HashMap<Integer, Integer> m = new HashMap<>();

/*    mark all the elements present in B*/

    for(int i = 0; i < B.length; i++)
    {
      m.put(B[i], 1);
    }

/*    initialize max_so_far with INT_MIN*/

    int max_so_far = Integer.MIN_VALUE;
    int currmax = 0;

/*    traverse the array A*/

    for(int i = 0; i < A.length; i++)
    {
      if(currmax < 0 || (m.containsKey(A[i]) && m.get(A[i]) == 1))
      {
        currmax = 0;
        continue;
      }
      currmax = Math.max(A[i], A[i] + currmax);

/*      if current max is greater than
      max so far then update max so far*/

      if(max_so_far < currmax)
      {
        max_so_far = currmax;
      }
    }
    return max_so_far;
  }

/*  Driver code*/

  public static void main(String[] args)
  {
    int a[] = { 3, 4, 5, -4, 6 };
    int b[] = { 1, 8, 5 };

/*    Function call*/

    System.out.println(findMaxSubarraySum(a, b));
  }
}

/*java program to find maximum
equilibrium sum.*/

import java.io.*;
class GFG {

/*    Function to find maximum
    equilibrium sum.*/

    static int findMaxSum(int []arr, int n)
    {
        int res = Integer.MIN_VALUE;
        for (int i = 0; i < n; i++)
        {
            int prefix_sum = arr[i];
            for (int j = 0; j < i; j++)
                prefix_sum += arr[j];
            int suffix_sum = arr[i];
            for (int j = n - 1; j > i; j--)
                suffix_sum += arr[j];
            if (prefix_sum == suffix_sum)
                res = Math.max(res, prefix_sum);
        }
        return res;
    }

/*    Driver Code*/

    public static void main (String[] args)
    {
        int arr[] = {-2, 5, 3, 1, 2, 6, -4, 2 };
        int n = arr.length;
        System.out.println(findMaxSum(arr, n));
    }
}

/*Java program to find maximum equilibrium sum.*/

import java.io.*;
public class GFG {

/*    Function to find maximum
    equilibrium sum.*/

    static int findMaxSum(int []arr, int n)
    {

/*        Array to store prefix sum.*/

        int []preSum = new int[n];

/*        Array to store suffix sum.*/

        int []suffSum = new int[n];

/*        Variable to store maximum sum.*/

        int ans = Integer.MIN_VALUE;

/*        Calculate prefix sum.*/

        preSum[0] = arr[0];
        for (int i = 1; i < n; i++)
            preSum[i] = preSum[i - 1] + arr[i];

/*        Calculate suffix sum and compare
        it with prefix sum. Update ans
        accordingly.*/

        suffSum[n - 1] = arr[n - 1];
        if (preSum[n - 1] == suffSum[n - 1])
            ans = Math.max(ans, preSum[n - 1]);
        for (int i = n - 2; i >= 0; i--)
        {
            suffSum[i] = suffSum[i + 1] + arr[i];
            if (suffSum[i] == preSum[i])
                ans = Math.max(ans, preSum[i]);
        }
        return ans;
    }

/*    Driver Code*/

    static public void main (String[] args)
    {
        int []arr = { -2, 5, 3, 1, 2, 6, -4, 2 };
        int n = arr.length;
        System.out.println( findMaxSum(arr, n));
    }
}

/*Java program to find maximum equilibrium
sum.*/

import java.lang.Math.*;
import java.util.stream.*;
class GFG {

/*    Function to find maximum equilibrium
    sum.*/

    static int findMaxSum(int arr[], int n)
    {
        int sum = IntStream.of(arr).sum();
        int prefix_sum = 0,
        res = Integer.MIN_VALUE;
        for (int i = 0; i < n; i++)
        {
            prefix_sum += arr[i];
            if (prefix_sum == sum)
                res = Math.max(res, prefix_sum);
            sum -= arr[i];
        }
        return res;
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        int arr[] = { -2, 5, 3, 1,
                    2, 6, -4, 2 };
        int n = arr.length;
        System.out.print(findMaxSum(arr, n));
    }
}

/*Java program to find equilibrium
index of an array*/

class EquilibriumIndex {

/* function to find the equilibrium index*/

 int equilibrium(int arr[], int n)
    {

/*initialize sum of whole array*/

int sum = 0;

/*initialize leftsum*/

int leftsum = 0;

/* Find sum of the whole array */

        for (int i = 0; i < n; ++i)
            sum += arr[i];
        for (int i = 0; i < n; ++i) {

/*sum is now right sum for index i*/

sum -= arr[i]; 
            if (leftsum == sum)
                return i;
            leftsum += arr[i];
        }

/* If no equilibrium index found, then return 0 */

        return -1;
    }

/*   Driver code*/

    public static void main(String[] args)
    {
        EquilibriumIndex equi = new EquilibriumIndex();
        int arr[] = { -7, 1, 5, 2, -4, 3, 0 };
        int arr_size = arr.length;
        System.out.println("First equilibrium index is " +
                          equi.equilibrium(arr, arr_size));
    }
}

/*Java program to find equilibrium
index of an array*/

class GFG{
static int equilibrium(int a[], int n)
{
    if (n == 1)
        return (0);
    int[] front = new int[n];
    int[] back = new int[n];

/*    Taking the prefixsum from front end array*/

    for (int i = 0; i < n; i++)
    {
        if (i != 0)
        {
            front[i] = front[i - 1] + a[i];
        }
        else
        {
            front[i] = a[i];
        }
    }

/*    Taking the prefixsum from back end of array*/

    for (int i = n - 1; i > 0; i--)
    {
        if (i <= n - 2)
        {
            back[i] = back[i + 1] + a[i];
        }
        else
        {
            back[i] = a[i];
        }
    }

/*    Checking for equilibrium index by
    compairing front and back sums*/

    for(int i = 0; i < n; i++)
    {
        if (front[i] == back[i])
        {
            return i;
        }
    }

/*    If no equilibrium index found,then return -1*/

    return -1;
}

/*Driver code*/

public static void main(String[] args)
{
    int arr[] = { -7, 1, 5, 2, -4, 3, 0 };
    int arr_size = arr.length;
    System.out.println("First Point of equilibrium " +
                       "is at index " +
                       equilibrium(arr, arr_size));
}
}

