/*Java program to find Majority 
element in an array*/

import java.io.*;
import java.util.*;
class GFG{

/*Function to find Majority element
in an array it returns -1 if there
is no majority element  */

public static int majorityElement(int[] arr, int n)
{

/*    Sort the array in O(nlogn)*/

    Arrays.sort(arr);
    int count = 1, max_ele = -1,
         temp = arr[0], ele = 0,
            f = 0;
    for(int i = 1; i < n; i++)
    {

/*        Increases the count if the
        same element occurs otherwise
        starts counting new element*/

        if (temp == arr[i])
        {
            count++;
        }
        else
        {
            count = 1;
            temp = arr[i];
        }

/*        Sets maximum count and stores
        maximum occured element so far
        if maximum count becomes greater
        than n/2 it breaks out setting
        the flag*/

        if (max_ele < count)
        {
            max_ele = count;
            ele = arr[i];
            if (max_ele > (n / 2))
            {
                f = 1;
                break;
            }
        }
    }

/*    Returns maximum occured element
    if there is no such element, returns -1*/

    return (f == 1 ? ele : -1);
}

/*Driver code*/

public static void main(String[] args)
{
    int arr[] = { 1, 1, 2, 1, 3, 5, 1 };
    int n = 7;

/*    Function calling*/

    System.out.println(majorityElement(arr, n));
}
}

/*Hashing based Java program
to find if there is a
majority element in input array.*/

import java.util.*;
import java.lang.*;
import java.io.*;
class Gfg
{

/*    Returns true if there is a
    majority element in a[]*/

    static boolean isMajority(int a[], int n)
    {

/*        Insert all elements
        in a hash table*/

        HashMap <Integer,Integer> mp = new
                            HashMap<Integer,Integer>();
        for (int i = 0; i < n; i++)
            if (mp.containsKey(a[i]))
                mp.put(a[i], mp.get(a[i]) + 1);
            else mp.put(a[i] , 1);

/*        Check if frequency of any
        element is n/2 or more.*/

        for (Map.Entry<Integer, Integer> x : mp.entrySet())
            if (x.getValue() >= n/2)
                return true;
        return false;
    }

/*    Driver code*/

    public static void main (String[] args)
    {
        int a[] = { 2, 3, 9, 2, 2 };
        int n = a.length;
        if (isMajority(a, n))
            System.out.println("Yes");
        else
            System.out.println("No");
    }
}

/*Naive solution to find if there is a
pair in A[0..N-1] with given sum.*/

import java.io.*;
class GFG {

    private static int isPairSum(int A[], int N, int X)
    {
        for (int i = 0; i < N; i++)
        {
            for (int j = 0; j < N; j++)
            {

/*                as equal i and j means same element*/

                if (i == j)
                    continue;

/*                pair exists*/

                if (A[i] + A[j] == X)
                    return true;

/*                as the array is sorted*/

                if (A[i] + A[j] > X)
                    break;
            }
        }

/*        No pair found with given sum.*/

        return 0;
    }
}

