/*Java program to find a triplet*/

class FindTriplet {

/*    returns true if there is triplet with sum equal
    to 'sum' present in A[]. Also, prints the triplet*/

    boolean find3Numbers(int A[], int arr_size, int sum)
    {
        int l, r;

/* Sort the elements */

        quickSort(A, 0, arr_size - 1);

/* Now fix the first element one by one and find the
           other two elements */

        for (int i = 0; i < arr_size - 2; i++) {

/*            To find the other two elements, start two index variables
            from two corners of the array and move them toward each
            other
index of the first element in the remaining elements*/

l = i + 1;

/*index of the last element*/

r = arr_size - 1; 
            while (l < r) {
                if (A[i] + A[l] + A[r] == sum) {
                    System.out.print("Triplet is " + A[i] + ", " + A[l] + ", " + A[r]);
                    return true;
                }
                else if (A[i] + A[l] + A[r] < sum)
                    l++;

/*A[i] + A[l] + A[r] > sum*/

else 
                    r--;
            }
        }

/*        If we reach here, then no triplet was found*/

        return false;
    }

/*partition function*/

    int partition(int A[], int si, int ei)
    {
        int x = A[ei];
        int i = (si - 1);
        int j;
        for (j = si; j <= ei - 1; j++) {
            if (A[j] <= x) {
                i++;
                int temp = A[i];
                A[i] = A[j];
                A[j] = temp;
            }
        }
        int temp = A[i + 1];
        A[i + 1] = A[ei];
        A[ei] = temp;
        return (i + 1);
    }

/* Implementation of Quick Sort
    A[] --> Array to be sorted
    si  --> Starting index
    ei  --> Ending index
     */

    void quickSort(int A[], int si, int ei)
    {
        int pi;

/* Partitioning index */

        if (si < ei) {
            pi = partition(A, si, ei);
            quickSort(A, si, pi - 1);
            quickSort(A, pi + 1, ei);
        }
    }

/*    Driver program to test above functions*/

    public static void main(String[] args)
    {
        FindTriplet triplet = new FindTriplet();
        int A[] = { 1, 4, 45, 6, 10, 8 };
        int sum = 22;
        int arr_size = A.length;
        triplet.find3Numbers(A, arr_size, sum);
    }
}

/*Java program to find a triplet using Hashing*/

import java.util.*;
class GFG {

/*    returns true if there is triplet
    with sum equal to 'sum' present
    in A[]. Also, prints the triplet*/

    static boolean find3Numbers(int A[],
                                int arr_size, int sum)
    {

/*        Fix the first element as A[i]*/

        for (int i = 0; i < arr_size - 2; i++) {

/*            Find pair in subarray A[i+1..n-1]
            with sum equal to sum - A[i]*/

            HashSet<Integer> s = new HashSet<Integer>();
            int curr_sum = sum - A[i];
            for (int j = i + 1; j < arr_size; j++) 
            {
                if (s.contains(curr_sum - A[j])) 
                {
                    System.out.printf("Triplet is %d, 
                                        %d, %d", A[i],
                                      A[j], curr_sum - A[j]);
                    return true;
                }
                s.add(A[j]);
            }
        }

/*        If we reach here, then no triplet was found*/

        return false;
    }

/* Driver code */

    public static void main(String[] args)
    {
        int A[] = { 1, 4, 45, 6, 10, 8 };
        int sum = 22;
        int arr_size = A.length;
        find3Numbers(A, arr_size, sum);
    }
}

/*Java implementation to
sort the given matrix*/

import java.io.*;
import java.util.*;
class GFG {
    static int SIZE = 10;

/*    function to sort the given matrix*/

    static void sortMat(int mat[][], int n)
    {

/*        temporary matrix of size n^2*/

        int temp[] = new int[n * n];
        int k = 0;

/*        copy the elements of matrix
        one by one into temp[]*/

        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                temp[k++] = mat[i][j];

/*        sort temp[]*/

        Arrays.sort(temp);

/*        copy the elements of temp[]
        one by one in mat[][]*/

        k = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                mat[i][j] = temp[k++];
    }

/*    function to print the given matrix*/

    static void printMat(int mat[][], int n)
    {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++)
                System.out.print( mat[i][j] + " ");
            System.out.println();
        }
    }

/*    Driver program to test above*/

    public static void main(String args[])
    {
        int mat[][] = { { 5, 4, 7 },
                        { 1, 3, 8 },
                        { 2, 9, 6 } };
        int n = 3;
        System.out.println("Original Matrix:");
        printMat(mat, n);
        sortMat(mat, n);
        System.out.println("Matrix After Sorting:");
        printMat(mat, n);
    }
}

/*Java program toto generate all possible subarrays/subArrays
  Complexity- O(n^3) */
*/
class Test
{
    static int arr[] = new int[]{1, 2, 3, 4};

/*    Prints all subarrays in arr[0..n-1]*/

    static void subArray( int n)
    {

/*        Pick starting point*/

        for (int i=0; i <n; i++)
        {

/*            Pick ending point*/

            for (int j=i; j<n; j++)
            {

/*                Print subarray between current starting
                and ending points*/

                for (int k=i; k<=j; k++)
                    System.out.print(arr[k]+" ");
            }
        }
    }

/*    Driver method to test the above function*/

    public static void main(String[] args)
    {
        System.out.println("All Non-empty Subarrays");
        subArray(arr.length);
    }
}

/*  Java code to generate all possible subsequences.
    Time Complexity O(n * 2^n) */

import java.math.BigInteger;
class Test
{
    static int arr[] = new int[]{1, 2, 3, 4};
    static void printSubsequences(int n)
    {

/* Number of subsequences is (2**n -1)*/

        int opsize = (int)Math.pow(2, n);

/* Run from counter 000..1 to 111..1*/

        for (int counter = 1; counter < opsize; counter++)
        {
            for (int j = 0; j < n; j++)
            {

/* Check if jth bit in the counter is set
                    If set then print jth element from arr[] */

                if (BigInteger.valueOf(counter).testBit(j))
                    System.out.print(arr[j]+" ");
            }
            System.out.println();
        }
    }

/*    Driver method to test the above function*/

    public static void main(String[] args)
    {
        System.out.println("All Non-empty Subsequences");
        printSubsequences(arr.length);
    }
}

class ProductArray {

/* Function to print product array
for a given array arr[] of size n */

    void productArray(int arr[], int n)
    {

/*        Base case*/

        if (n == 1) {
            System.out.print("0");
            return;
        }
        int i, temp = 1;

/* Allocate memory for the product array */

        int prod[] = new int[n];

/* Initialize the product array as 1 */

        for (int j = 0; j < n; j++)
            prod[j] = 1;

/* In this loop, temp variable contains product of
           elements on left side excluding arr[i] */

        for (i = 0; i < n; i++) {
            prod[i] = temp;
            temp *= arr[i];
        }

/* Initialize temp to 1 for product on right side */

        temp = 1;

/* In this loop, temp variable contains product of
           elements on right side excluding arr[i] */

        for (i = n - 1; i >= 0; i--) {
            prod[i] *= temp;
            temp *= arr[i];
        }

/* print the constructed prod array */

        for (i = 0; i < n; i++)
            System.out.print(prod[i] + " ");
        return;
    }

/* Driver program to test above functions */

    public static void main(String[] args)
    {
        ProductArray pa = new ProductArray();
        int arr[] = { 10, 3, 5, 6, 2 };
        int n = arr.length;
        System.out.println("The product array is : ");
        pa.productArray(arr, n);
    }
}

