    {
        long prod = 1;
        long flag = 0;

/*        product of all elements*/

        for (int i = 0; i < n; i++) {

/*            counting number of elements
            which have value
            0*/

            if (a[i] == 0)
                flag++;
            else
                prod *= a[i];
        }

/*        creating a new array of size n*/

        long arr[] = new long[n];
        for (int i = 0; i < n; i++) {

/*            if number of elements in
            array with value 0
            is more than 1 than each
            value in new array
            will be equal to 0*/

            if (flag > 1) {
                arr[i] = 0;
            }

/*            if no element having value
            0 than we will
            insert product/a[i] in new array*/

            else if (flag == 0)
                arr[i] = (prod / a[i]);

/*            if 1 element of array having
            value 0 than all
            the elements except that index
            value , will be
            equal to 0*/

            else if (flag == 1 && a[i] != 0) {
                arr[i] = 0;
            }

/*            if(flag == 1 && a[i] == 0)*/

            else
                arr[i] = prod;
        }
        return arr;
    }

/*    Driver Code*/

    public static void main(String args[])
        throws IOException
    {
        int n = 5;
        int[] array = { 10, 3, 5, 6, 2 };
        Solution ob = new Solution();
        long[] ans = new long[n];
        ans = ob.productExceptSelf(array, n);
        for (int i = 0; i < n; i++) {
            System.out.print(ans[i] + " ");
        }
    }
}

class AreConsecutive
{

/* The function checks if the array elements are consecutive
       If elements are consecutive, then returns true, else returns
       false */

    boolean areConsecutive(int arr[], int n)
    {
        if (n < 1)
            return false;

/* 1) Get the minimum element in array */

        int min = getMin(arr, n);

/* 2) Get the maximum element in array */

        int max = getMax(arr, n);

/* 3) max - min + 1 is equal to n,  then only check all elements */

        if (max - min + 1 == n)
        {

/* Create a temp array to hold visited flag of all elements.
               Note that, calloc is used here so that all values are initialized
               as false */

            boolean visited[] = new boolean[n];
            int i;
            for (i = 0; i < n; i++)
            {

/* If we see an element again, then return false */

                if (visited[arr[i] - min] != false)
                    return false;

/* If visited first time, then mark the element as visited */

                visited[arr[i] - min] = true;
            }

/* If all elements occur once, then return true */

            return true;
        }

/*if (max - min  + 1 != n)*/

return false; 
    }

/* UTILITY FUNCTIONS */

    int getMin(int arr[], int n)
    {
        int min = arr[0];
        for (int i = 1; i < n; i++)
        {
            if (arr[i] < min)
                min = arr[i];
        }
        return min;
    }
    int getMax(int arr[], int n)
    {
        int max = arr[0];
        for (int i = 1; i < n; i++)
        {
            if (arr[i] > max)
                max = arr[i];
        }
        return max;
    }

/* Driver program to test above functions */

    public static void main(String[] args)
    {
        AreConsecutive consecutive = new AreConsecutive();
        int arr[] = {5, 4, 2, 3, 1, 6};
        int n = arr.length;
        if (consecutive.areConsecutive(arr, n) == true)
            System.out.println("Array elements are consecutive");
        else
            System.out.println("Array elements are not consecutive");
    }
}

class AreConsecutive
{

/* The function checks if the array elements are consecutive
       If elements are consecutive, then returns true, else returns
       false */

    boolean areConsecutive(int arr[], int n)
    {
        if (n < 1)
            return false;

/* 1) Get the minimum element in array */

        int min = getMin(arr, n);

/* 2) Get the maximum element in array */

        int max = getMax(arr, n);

/* 3) max-min+1 is equal to n then only check all elements */

        if (max - min + 1 == n)
        {
            int i;
            for (i = 0; i < n; i++)
            {
                int j;
                if (arr[i] < 0)
                    j = -arr[i] - min;
                else
                    j = arr[i] - min;

/*                if the value at index j is negative then
                there is repitition*/

                if (arr[j] > 0)
                    arr[j] = -arr[j];
                else
                    return false;
            }

