/*Java program to print all
primes smaller than or equal to
n using Sieve of Eratosthenes*/

class SieveOfEratosthenes {
    void sieveOfEratosthenes(int n)
    {

/*        Create a boolean array
        "prime[0..n]" and
        initialize all entries
        it as true. A value in
        prime[i] will finally be
        false if i is Not a
        prime, else true.*/

        boolean prime[] = new boolean[n + 1];
        for (int i = 0; i <= n; i++)
            prime[i] = true;
        for (int p = 2; p * p <= n; p++)
        {

/*            If prime[p] is not changed, then it is a
            prime*/

            if (prime[p] == true)
            {

/*                Update all multiples of p*/

                for (int i = p * p; i <= n; i += p)
                    prime[i] = false;
            }
        }

/*        Print all prime numbers*/

        for (int i = 2; i <= n; i++)
        {
            if (prime[i] == true)
                System.out.print(i + " ");
        }
    }

/*    Driver Code*/

    public static void main(String args[])
    {
        int n = 30;
        System.out.print(
            "Following are the prime numbers ");
        System.out.println("smaller than or equal to " + n);
        SieveOfEratosthenes g = new SieveOfEratosthenes();
        g.sieveOfEratosthenes(n);
    }
}

/*Java program to print the
Number which has the maximum
number of distinct prime
factors of numbers in range
m to n*/

import java.io.*;
class GFG
{

/*Function to return
the maximum number*/

static int maximumNumberDistinctPrimeRange(int m,
                                           int n)
{

/*    array to store the
    number of distinct primes*/

    long factorCount[] = new long[n + 1];

/*    true if index 'i'
    is a prime*/

    boolean prime[] = new boolean[n + 1];

/*    initializing the number
    of factors to 0 and*/

    for (int i = 0; i <= n; i++)
    {
        factorCount[i] = 0;

/*Used in Sieve*/

prime[i] = true; 
    }
    for (int i = 2; i <= n; i++)
    {

/*        condition works only when
        'i' is prime, hence for
        factors of all prime number,
        the prime status is changed to false*/

        if (prime[i] == true)
        {

/*            Number is prime*/

            factorCount[i] = 1;

/*            number of factor of
            a prime number is 1*/

            for (int j = i * 2; j <= n; j += i)
            {

/*                incrementing factorCount
                all the factors of i*/

                factorCount[j]++;

/*                and changing prime
                status to false*/

                prime[j] = false;
            }
        }
    }

/*    Initialize the max and num*/

    int max = (int)factorCount[m];
    int num = m;

/*    Gets the maximum number*/

    for (int i = m; i <= n; i++)
    {

/*        Gets the maximum number*/

        if (factorCount[i] > max)
        {
            max = (int)factorCount[i];
            num = i;
        }
    }
    return num;
}

/*Driver code*/

public static void main (String[] args)
{
int m = 4, n = 6;

/*Calling function*/

System.out.println(maximumNumberDistinctPrimeRange(m, n));
}
}

/*Java program to find lexicographic rank
of a string*/

import java.io.*;
import java.util.*;
class GFG {

/*    A utility function to find factorial of n*/

    static int fact(int n)
    {
        return (n <= 1) ? 1 : n * fact(n - 1);
    }

/*    A utility function to count smaller
    characters on right of arr[low]*/

    static int findSmallerInRight(String str, int low,
                                  int high)
    {
        int countRight = 0, i;
        for (i = low + 1; i <= high; ++i)
            if (str.charAt(i) < str.charAt(low))
                ++countRight;
        return countRight;
    }

/*    A function to find rank of a string in
    all permutations of characters*/

    static int findRank(String str)
    {
        int len = str.length();
        int mul = fact(len);
        int rank = 1;
        int countRight;
        for (int i = 0; i < len; ++i) {
            mul /= len - i;

/*            count number of chars smaller
            than str[i] from str[i+1] to
            str[len-1]*/

            countRight = findSmallerInRight(str, i, len - 1);
            rank += countRight * mul;
        }
        return rank;
    }

/*    Driver program to test above function*/

    public static void main(String[] args)
    {
        String str = "string";
        System.out.println(findRank(str));
    }
}

/*Program to calculate C(n, k) in java*/

class BinomialCoefficient {

/*    Returns value of Binomial Coefficient C(n, k)*/

    static int binomialCoeff(int n, int k)
    {
        int res = 1;

/*        Since C(n, k) = C(n, n-k)*/

        if (k > n - k)
            k = n - k;

/*        Calculate value of
        [n * (n-1) *---* (n-k+1)] / [k * (k-1) *----* 1]*/

        for (int i = 0; i < k; ++i) {
            res *= (n - i);
            res /= (i + 1);
        }
        return res;
    }

/* Driver program to test above function*/

    public static void main(String[] args)
    {
        int n = 8;
        int k = 2;
        System.out.println("Value of C(" + n + ", " + k + ") "
                           + "is"
                           + " " + binomialCoeff(n, k));
    }
}

/*Java code for Pascal's Triangle*/

import java.io.*;
class GFG {

/*binomialCoeff*/


    static int binomialCoeff(int n, int k)
    {
        int res = 1;
        if (k > n - k)
        k = n - k;
        for (int i = 0; i < k; ++i)
        {
            res *= (n - i);
            res /= (i + 1);
        }
        return res;
    }

/*    Function to print first
    n lines of Pascal's Triangle*/

    static void printPascal(int n)
    {

/*    Iterate through every line
    and print entries in it*/

    for (int line = 0; line < n; line++)
    {

/*        Every line has number of
        integers equal to line number*/

        for (int i = 0; i <= line; i++)
        System.out.print(binomialCoeff
                        (line, i)+" ");
        System.out.println();
    }
    }

/*    Driver code*/

    public static void main(String args[])
    {
    int n = 7;
    printPascal(n);
    }
}

/*java program for Pascal's Triangle*/

import java.io.*;
class GFG {

/*A O(n^2) time and O(n^2) extra
space method for Pascal's Triangle*/

public static void printPascal(int n)
{

/*An auxiliary array to store generated pascal triangle values*/

int[][] arr = new int[n][n];

/*Iterate through every line and print integer(s) in it*/

for (int line = 0; line < n; line++)
{

/*    Every line has number of integers equal to line number*/

    for (int i = 0; i <= line; i++)
    {

/*    First and last values in every row are 1*/

    if (line == i || i == 0)
        arr[line][i] = 1;

/*Other values are sum of values just above and left of above*/

else 
        arr[line][i] = arr[line-1][i-1] + arr[line-1][i];
    System.out.print(arr[line][i]);
    }
    System.out.println("");
}
}
}

/*Driver code*/

    public static void main (String[] args) {
        int n = 5;
        printPascal(n);
    }

