/*Java efficient program to calculate
e raise to the power x*/

import java.io.*;
class GFG
{

/*    Function returns approximate value of e^x
    using sum of first n terms of Taylor Series*/

    static float exponential(int n, float x)
    {

/*        initialize sum of series*/

        float sum = 1;
        for (int i = n - 1; i > 0; --i )
            sum = 1 + x * sum / i;
        return sum;
    }

/*    driver program*/

    public static void main (String[] args)
    {
        int n = 10;
        float x = 1;
        System.out.println("e^x = "+exponential(n,x));
    }
}

/*Program to print all prime factors*/

import java.io.*;
import java.lang.Math;
class GFG
{

/*    A function to print all prime factors
    of a given number n*/

    public static void primeFactors(int n)
    {

/*        Print the number of 2s that divide n*/

        while (n%2==0)
        {
            System.out.print(2 + " ");
            n /= 2;
        }

/*        n must be odd at this point.  So we can
        skip one element (Note i = i +2)*/

        for (int i = 3; i <= Math.sqrt(n); i+= 2)
        {

/*            While i divides n, print i and divide n*/

            while (n%i == 0)
            {
                System.out.print(i + " ");
                n /= i;
            }
        }

/*        This condition is to handle the case whien
        n is a prime number greater than 2*/

        if (n > 2)
            System.out.print(n);
    }

/* Driver code */

    public static void main (String[] args)
    {
        int n = 315;
        primeFactors(n);
    }
}

/*Java program to print all combination of size r in an array of size n*/

import java.io.*;
class Combination {

/*    The main function that prints all combinations of size r
    in arr[] of size n. This function mainly uses combinationUtil()*/

    static void printCombination(int arr[], int n, int r)
    {

/*        A temporary array to store all combination one by one*/

        int data[]=new int[r];

/*        Print all combination using temprary array 'data[]'*/

        combinationUtil(arr, data, 0, n-1, 0, r);
    }

/* arr[]  ---> Input Array
    data[] ---> Temporary array to store current combination
    start & end ---> Staring and Ending indexes in arr[]
    index  ---> Current index in data[]
    r ---> Size of a combination to be printed */

    static void combinationUtil(int arr[], int data[], int start,
                                int end, int index, int r)
    {

/*        Current combination is ready to be printed, print it*/

        if (index == r)
        {
            for (int j=0; j<r; j++)
                System.out.print(data[j]+" ");
            System.out.println("");
            return;
        }

/*        replace index with all possible elements. The condition
        "end-i+1 >= r-index" makes sure that including one element
        at index will make a combination with remaining elements
        at remaining positions*/

        for (int i=start; i<=end && end-i+1 >= r-index; i++)
        {
            data[index] = arr[i];
            combinationUtil(arr, data, i+1, end, index+1, r);
        }
    }

/*Driver function to check for above function*/

    public static void main (String[] args) {
        int arr[] = {1, 2, 3, 4, 5};
        int r = 3;
        int n = arr.length;
        printCombination(arr, n, r);
    }
}

/*Java program to print all combination of size r in an array of size n*/

import java.io.*;
class Combination {

/*    The main function that prints all combinations of size r
    in arr[] of size n. This function mainly uses combinationUtil()*/

    static void printCombination(int arr[], int n, int r)
    {

/*        A temporary array to store all combination one by one*/

        int data[]=new int[r];

/*        Print all combination using temprary array 'data[]'*/

        combinationUtil(arr, n, r, 0, data, 0);
    }

/* arr[]  ---> Input Array
    data[] ---> Temporary array to store current combination
    start & end ---> Staring and Ending indexes in arr[]
    index  ---> Current index in data[]
    r ---> Size of a combination to be printed */

    static void combinationUtil(int arr[], int n, int r, int index,
                                int data[], int i)
    {

/*        Current combination is ready to be printed, print it*/

        if (index == r)
        {
            for (int j=0; j<r; j++)
                System.out.print(data[j]+" ");
            System.out.println("");
        return;
        }

/*        When no more elements are there to put in data[]*/

        if (i >= n)
        return;

/*        current is included, put next at next location*/

        data[index] = arr[i];
        combinationUtil(arr, n, r, index+1, data, i+1);

/*        current is excluded, replace it with next (Note that
        i+1 is passed, but index is not changed)*/

        combinationUtil(arr, n, r, index, data, i+1);
    }

/*Driver function to check for above function*/

    public static void main (String[] args) {
        int arr[] = {1, 2, 3, 4, 5};
        int r = 3;
        int n = arr.length;
        printCombination(arr, n, r);
    }
}

/*Java program to count
trailing 0s in n!*/

import java.io.*;
class GFG
{

/*    Function to return trailing
    0s in factorial of n*/

    static int findTrailingZeros(int n)
    {

/*        Initialize result*/

        int count = 0;

/*        Keep dividing n by powers
        of 5 and update count*/

        for (int i = 5; n / i >= 1; i *= 5)
            count += n / i;
        return count;
    }

/*    Driver Code*/

    public static void main (String[] args)
    {
        int n = 100;
        System.out.println("Count of trailing 0s in " +
                                           n +"! is " +
                                 findTrailingZeros(n));
    }
}

class CatalnNumber {

/*    A recursive function to find nth catalan number*/

    int catalan(int n)
    {

/*        Base case*/

        if (n <= 1)
        {
            return 1;
        }

/*    catalan(n) is sum of
    catalan(i)*catalan(n-i-1)*/

        int res = 0;
        for (int i = 0; i < n; i++)
        {
            res += catalan(i)
                * catalan(n - i - 1);
        }
        return res;
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        CatalnNumber cn = new CatalnNumber();
        for (int i = 0; i < 10; i++)
        {
            System.out.print(cn.catalan(i) + " ");
        }
    }
}

/*    A dynamic programming based function to find nth
    Catalan number*/
class GFG {
    static int catalanDP(int n)
    {

/*        Table to store results of subproblems*/

        int catalan[] = new int[n + 2];

/*        Initialize first two values in table*/

        catalan[0] = 1;
        catalan[1] = 1;

/*        Fill entries in catalan[]
        using recursive formula*/

        for (int i = 2; i <= n; i++) {
            catalan[i] = 0;
            for (int j = 0; j < i; j++) {
                catalan[i]
                    += catalan[j] * catalan[i - j - 1];
            }
        }

/*        Return last entry*/

        return catalan[n];
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        for (int i = 0; i < 10; i++) {
            System.out.print(catalanDP(i) + " ");
        }
    }
}

/*Java program for nth Catalan Number*/

class GFG {

/*    Returns value of Binomial Coefficient C(n, k)*/

    static long binomialCoeff(int n, int k)
    {
        long res = 1;

/*        Since C(n, k) = C(n, n-k)*/

        if (k > n - k) {
            k = n - k;
        }

/*        Calculate value of [n*(n-1)*---*(n-k+1)] /
        [k*(k-1)*---*1]*/

        for (int i = 0; i < k; ++i) {
            res *= (n - i);
            res /= (i + 1);
        }
        return res;
    }

/*    A Binomial coefficient based function
      to find nth catalan number in O(n) time*/

    static long catalan(int n)
    {

/*        Calculate value of 2nCn*/

        long c = binomialCoeff(2 * n, n);

/*        return 2nCn/(n+1)*/

        return c / (n + 1);
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        for (int i = 0; i < 10; i++) {
            System.out.print(catalan(i) + " ");
        }
    }
}

