import java.util.*;
class GFG{
static void printString(int n)
{
    int []arr = new int[10000];
    int i = 0;

/*    Step 1: Converting to number
    assuming 0 in number system*/

    while (n > 0)
    {
        arr[i] = n % 26;
        n = n / 26;
        i++;
    }

/*    Step 2: Getting rid of 0, as 0 is
    not part of number system*/

    for(int j = 0; j < i - 1; j++)
    {
        if (arr[j] <= 0)
        {
            arr[j] += 26;
            arr[j + 1] = arr[j + 1] - 1;
        }
    }
    for(int j = i; j >= 0; j--)
    {
        if (arr[j] > 0)
            System.out.print(
                (char)('A' + arr[j] - 1));
    }
    System.out.println();
}

/*Driver code*/

public static void main(String[] args)
{
    printString(26);
    printString(51);
    printString(52);
    printString(80);
    printString(676);
    printString(702);
    printString(705);
}
}

/*Java program to check if a given
instance of 8 puzzle is solvable or not*/

class GFG
{

/*A utility function to count
inversions in given array 'arr[]'*/

static int getInvCount(int[][] arr)
{
    int inv_count = 0;
    for (int i = 0; i < 3 - 1; i++)
        for (int j = i + 1; j < 3; j++)

/*            Value 0 is used for empty space*/

            if (arr[j][i] > 0 &&
                            arr[j][i] > arr[i][j])
                inv_count++;
    return inv_count;
}

/*This function returns true
if given 8 puzzle is solvable.*/

static boolean isSolvable(int[][] puzzle)
{

/*    Count inversions in given 8 puzzle*/

    int invCount = getInvCount(puzzle);

/*    return true if inversion count is even.*/

    return (invCount % 2 == 0);
}

/* Driver code */

public static void main (String[] args)
{
    int[][] puzzle = {{1, 8, 2},{0, 4, 3},{7, 6, 5}};
    if(isSolvable(puzzle))
        System.out.println("Solvable");
    else
    System.out.println("Not Solvable");
}
}

/*Java code to Count Distinct
Non-Negative Integer Pairs
(x, y) that Satisfy the
inequality x*x + y*y < n*/

import java.io.*;
class GFG
{

/*    This function counts number
    of pairs (x, y) that satisfy
    the inequality x*x + y*y < n.*/

    static int countSolutions(int n)
    {
        int res = 0;
        for (int x = 0; x * x < n; x++)
            for (int y = 0; x * x + y * y < n; y++)
                res++;
        return res;
    }

/*    Driver program*/

    public static void main(String args[])
    {
        System.out.println ( "Total Number of distinct Non-Negative pairs is "
                                                        +countSolutions(6));
    }
}

/*java program for implementation
of Bisection Method for
solving equations*/

import java.io.*;
class GFG {
    static int MAX_ITER = 1000000;

/*    An example function whose
    solution is determined using
    Bisection Method. The function
    is x^3 - x^2 + 2*/

    static double func(double x)
    {
        return (x * x * x - x * x + 2);
    }

/*    Prints root of func(x)
    in interval [a, b]*/

    static void regulaFalsi(double a, double b)
    {
        if (func(a) * func(b) >= 0)
        {
            System.out.println("You have not assumed right a and b");
        }

/*        Initialize result*/

        double c = a;
        for (int i = 0; i < MAX_ITER; i++)
        {

/*            Find the point that touches x axis*/

            c = (a * func(b) - b * func(a))
                 / (func(b) - func(a));

/*            Check if the above found point is root*/

            if (func(c) == 0)
                break;

/*            Decide the side to repeat the steps*/

            else if (func(c) * func(a) < 0)
                b = c;
            else
                a = c;
        }
        System.out.println("The value of root is : " + (int)c);
    }

/*    Driver program*/

    public static void main(String[] args)
    {

/*        Initial values assumed*/

        double a = -200, b = 300;
        regulaFalsi(a, b);
    }
}

/*Java code to find the element
that occur only once*/

class GFG {

/*    Method to find the element that occur only once*/

    static int getSingle(int arr[], int n)
    {
        int ones = 0, twos = 0;
        int common_bit_mask;
        for (int i = 0; i < n; i++) {

/*"one & arr[i]" gives the bits that are there in
            both 'ones' and new element from arr[]. We
            add these bits to 'twos' using bitwise OR*/

            twos = twos | (ones & arr[i]);

/*"one & arr[i]" gives the bits that are
            there in both 'ones' and new element from arr[].
            We add these bits to 'twos' using bitwise OR*/

            ones = ones ^ arr[i];

/* The common bits are those bits which appear third time
            So these bits should not be there in both 'ones' and 'twos'.
            common_bit_mask contains all these bits as 0, so that the bits can
            be removed from 'ones' and 'twos'*/

            common_bit_mask = ~(ones & twos);

/*Remove common bits (the bits that appear third time) from 'ones'*/

            ones &= common_bit_mask;

/*Remove common bits (the bits that appear third time) from 'twos'*/

            twos &= common_bit_mask;
        }
        return ones;
    }

/*    Driver method*/

    public static void main(String args[])
    {
        int arr[] = { 3, 3, 2, 3 };
        int n = arr.length;
        System.out.println("The element with single occurrence is " + getSingle(arr, n));
    }
}

/*Java code to find the element
that occur only once*/

class GFG {
    static final int INT_SIZE = 32;
    static int getSingle(int arr[], int n)
    {

/*        Initialize result*/

        int result = 0;
        int x, sum;

/*        Iterate through every bit*/

        for (int i = 0; i < INT_SIZE; i++) {

/*            Find sum of set bits at ith position in all
            array elements*/

            sum = 0;
            x = (1 << i);
            for (int j = 0; j < n; j++) {
                if ((arr[j] & x) == 0)
                    sum++;
            }

/*            The bits with sum not multiple of 3, are the
            bits of element with single occurrence.*/

            if ((sum % 3) != 0)
                result |= x;
        }
        return result;
    }

/*    Driver method*/

    public static void main(String args[])
    {
        int arr[] = { 12, 1, 12, 3, 12, 1, 1, 2, 3, 2, 2, 3, 7 };
        int n = arr.length;
        System.out.println("The element with single occurrence is " + getSingle(arr, n));
    }
}

/*A simple program to count set bits
in all numbers from 1 to n.*/

class GFG{

/*    Returns count of set bits present
      in all numbers from 1 to n*/

    static int countSetBits( int n)
    {

/*        initialize the result*/

        int bitCount = 0;
        for (int i = 1; i <= n; i++)
            bitCount += countSetBitsUtil(i);
        return bitCount;
    }

/*    A utility function to count set bits
    in a number x*/

    static int countSetBitsUtil( int x)
    {
        if (x <= 0)
            return 0;
        return (x % 2 == 0 ? 0 : 1) +
               countSetBitsUtil(x / 2);
    }

/*    Driver program*/

    public static void main(String[] args)
    {
        int n = 4;
        System.out.print("Total set bit count is ");
        System.out.print(countSetBits(n));
    }
}

public class GFG {
    static int countSetBits(int n)
    {
        int i = 0;

/*        ans store sum of set bits from 0 to n*/

        int ans = 0;

/*        while n greater than equal to 2^i*/

        while ((1 << i) <= n) {

/*            This k will get flipped after
            2^i iterations*/

            boolean k = false;

/*            change is iterator from 2^i to 1*/

            int change = 1 << i;

/*            This will loop from 0 to n for
            every bit position*/

            for (int j = 0; j <= n; j++) {
                if (k == true)
                    ans += 1;
                else
                    ans += 0;
                if (change == 1) {

/*                    When change = 1 flip the bit*/

                    k = !k;

/*                    again set change to 2^i*/

                    change = 1 << i;
                }
                else {
                    change--;
                }
            }

/*            increment the position*/

            i++;
        }
        return ans;
    }

/*    Driver program*/

    public static void main(String[] args)
    {
        int n = 17;
        System.out.println(countSetBits(n));
    }
}

/*Java Program for above approach*/

public class UniqueNumbers {

/*    This function sets the values of
    *x and *y to non-repeating elements
    in an array arr[] of size n*/

    public static void UniqueNumbers2(int[] arr,int n)
    {
        int sum =0;
        for(int i = 0;i<n;i++)
        {

/*            Xor  all the elements of the array
            all the elements occuring twice will
            cancel out each other remaining
            two unnique numbers will be xored*/

            sum = (sum^arr[i]);
        }

/*        Bitwise & the sum with it's 2's Complement
        Bitwise & will give us the sum containing
        only the rightmost set bit*/

        sum = (sum&-sum);

/*        sum1 and sum2 will contains 2 unique
        elements elements initialized with 0 box
        number xored with 0 is number itself*/

        int sum1 = 0;
        int sum2 = 0;

/*        traversing the array again*/

        for(int i = 0;i<arr.length;i++)
        {

/*            Bitwise & the arr[i] with the sum
            Two possibilities either result == 0
            or result > 0*/

            if((arr[i]&sum) > 0)
            {

/*                if result > 0 then arr[i] xored
                with the sum1*/

                sum1 = (sum1^arr[i]);
            }
            else
            {

/*                if result == 0 then arr[i]
                xored with sum2*/

                sum2 = (sum2^arr[i]);
            }
        }

/*        print the the two unique numbers*/

        System.out.println("The non-repeating elements are "+
                                          sum1+" and "+sum2);
    }

/*Driver Code*/

    public static void main(String[] args)
    {
        int[] arr = new int[]{2, 3, 7, 9, 11, 2, 3, 11};
        int n = arr.length;
        UniqueNumbers2(arr,n);
    }
}

/*Java program to find the element occurring
