class OddOccurrence {

/*    function to find the element occurring odd
    number of times*/

    static int getOddOccurrence(int arr[], int arr_size)
    {
        int i;
        for (i = 0; i < arr_size; i++) {
            int count = 0;
            for (int j = 0; j < arr_size; j++) {
                if (arr[i] == arr[j])
                    count++;
            }
            if (count % 2 != 0)
                return arr[i];
        }
        return -1;
    }

/*    driver code*/

    public static void main(String[] args)
    {
        int arr[] = new int[]{ 2, 3, 5, 4, 5, 2, 4, 3, 5, 2, 4, 4, 2 };
        int n = arr.length;

/*        Function calling*/

        System.out.println(getOddOccurrence(arr, n));
    }
}

/*Java program to find the element occurring odd
number of times*/

import java.io.*;
import java.util.HashMap;
class OddOccurrence
{

/*    function to find the element occurring odd
    number of times*/

    static int getOddOccurrence(int arr[], int n)
    {
        HashMap<Integer,Integer> hmap = new HashMap<>();

/*        Putting all elements into the HashMap*/

        for(int i = 0; i < n; i++)
        {
            if(hmap.containsKey(arr[i]))
            {
                int val = hmap.get(arr[i]);

/*                If array element is already present then
                increase the count of that element.*/

                hmap.put(arr[i], val + 1);
            }
            else

/*                if array element is not present then put
                element into the HashMap and initialize
                the count to one.*/

                hmap.put(arr[i], 1);
        }

/*        Checking for odd occurrence of each element present
        in the HashMap*/

        for(Integer a:hmap.keySet())
        {
            if(hmap.get(a) % 2 != 0)
                return a;
        }
        return -1;
    }

/*    driver code   */

    public static void main(String[] args)
    {
        int arr[] = new int[]{2, 3, 5, 4, 5, 2, 4, 3, 5, 2, 4, 4, 2};
        int n = arr.length;
        System.out.println(getOddOccurrence(arr, n));
    }
}

/*Java implementation of the approach*/

class GFG {

/*    Lookup table*/

    static int[] BitsSetTable256 = new int[256];

/*    Function to initialise the lookup table*/

    public static void initialize()
    {

/*        To initially generate the
        table algorithmically*/

        BitsSetTable256[0] = 0;
        for (int i = 0; i < 256; i++) {
            BitsSetTable256[i] = (i & 1) + BitsSetTable256[i / 2];
        }
    }

/*    Function to return the count
    of set bits in n*/

    public static int countSetBits(int n)
    {
        return (BitsSetTable256[n & 0xff]
                + BitsSetTable256[(n >> 8) & 0xff]
                + BitsSetTable256[(n >> 16) & 0xff]
                + BitsSetTable256[n >> 24]);
    }

/*    Driver code*/

    public static void main(String[] args)
    {

/*        Initialise the lookup table*/

        initialize();
        int n = 9;
        System.out.print(countSetBits(n));
    }
}

public class GFG
{

/*  Check each bit in a number is set or not
  and return the total count of the set bits.*/

  static int countSetBits(int N)
  {
    int count = 0;

/*    (1 << i) = pow(2, i)*/

    for (int i = 0; i < 4 * 8; i++)
    {
      if ((N & (1 << i)) != 0)
        count++;
    }
    return count;
  }

/*  Driver code*/

  public static void main(String[] args)
  {
    int N = 15;
    System.out.println(countSetBits(N));
  }
}

