/*Java program to find the maximum repeating number*/

import java.io.*;

class MaxRepeating {

/*    Returns maximum repeating element in arr[0..n-1].
    The array elements are in range from 0 to k-1*/

    static int maxRepeating(int arr[], int n, int k)
    {

/*        Iterate though input array, for every element
        arr[i], increment arr[arr[i]%k] by k*/

        for (int i = 0; i< n; i++)
            arr[(arr[i]%k)] += k;

/*        Find index of the maximum repeating element*/

        int max = arr[0], result = 0;
        for (int i = 1; i < n; i++)
        {
            if (arr[i] > max)
            {
                max = arr[i];
                result = i;
            }
        }

/*        Return index of the maximum element*/

        return result;
    }

/*Driver function to check for above function*/

    public static void main (String[] args)
    {

        int arr[] = {2, 3, 3, 5, 3, 4, 1, 7};
        int n = arr.length;
        int k=8;
        System.out.println("Maximum repeating element is: " +
                           maxRepeating(arr,n,k));
    }
}

/*Simple Java program to find
smallest greater element in
whole array for every element.*/

import java.io.*;

class GFG
{
static void smallestGreater(int arr[],
                            int n)
{
    for (int i = 0; i < n; i++)
    {

/*        Find the closest greater
        element for arr[j] in
        the entire array.*/

        int diff = Integer.MAX_VALUE;
        int closest = -1;
        for (int j = 0; j < n; j++)
        {
            if (arr[i] < arr[j] &&
                arr[j] - arr[i] < diff)
            {
                diff = arr[j] - arr[i];
                closest = j;        
            }
        }

/*        Check if arr[i] is largest*/

        if(closest == -1)
        System.out.print( "_ " );
        else
        System.out.print(arr[closest] + " ");
    }
}

/*Driver code*/

public static void main (String[] args)
{
    int ar[] = {6, 3, 9, 8, 10,
                2, 1, 15, 7};
    int n = ar.length;
    smallestGreater(ar, n);
}
}

/*Efficient Java program to
find smallest greater element
in whole array for every element.*/

import java.util.*;
class GFG{

static void smallestGreater(int arr[],
                            int n)
{
  HashSet<Integer> s = new HashSet<>();
  for (int i = 0; i < n; i++)
    s.add(arr[i]);
  Vector<Integer> newAr = new Vector<>();
  for (int p : s)
  {
    newAr.add(p);
  }

  for (int i = 0; i < n; i++)
  {
    int temp = lowerBound(newAr, 0,
                          newAr.size(),
                          arr[i]);
    if (temp  < n)
      System.out.print(newAr.get(temp) + " ");
    else
      System.out.print("_ ");
  }
}

/*lowerbound function*/

static int lowerBound(Vector<Integer> vec,
                      int low, int high,
                      int element)
{
  int[] array = new int[vec.size()];
  int k = 0;
  for (Integer val : vec)
  {
    array[k] = val;
    k++;
  }
  while (low < high)
  {
    int middle = low +
                 (high - low) / 2;
    if (element > array[middle])
    {
      low = middle + 1;
    } else
    {
      high = middle;
    }
  }

  return low+1;
}

/*Driver code*/

public static void main(String[] args)
{
  int ar[] = {6, 3, 9, 8,
              10, 2, 1, 15, 7};
  int n = ar.length;
  smallestGreater(ar, n);
}
}

/*Java to find positions of zeroes flipping which
produces maximum number of consecutive 1's*/

class Test
{
    static int arr[] = new int[]{1, 0, 0, 1, 1, 0, 1, 0, 1, 1};

/*    m is maximum of number zeroes allowed to flip*/

    static void findZeroes(int m)
    {

/*        Left and right indexes of current window*/

        int wL = 0, wR = 0;

/*        Left index and size of the widest window*/

        int bestL = 0, bestWindow = 0;

/*        Count of zeroes in current window*/

        int zeroCount = 0;

/*        While right boundary of current window doesn't cross
        right end*/

        while (wR < arr.length)
        {

/*            If zero count of current window is less than m,
            widen the window toward right*/

            if (zeroCount <= m)
            {
                if (arr[wR] == 0)
                zeroCount++;
                wR++;
            }

/*            If zero count of current window is more than m,
            reduce the window from left*/

            if (zeroCount > m)
            {
                if (arr[wL] == 0)
                zeroCount--;
                wL++;
            }

/*            Update widest window if this window size is more*/

            if ((wR-wL > bestWindow) && (zeroCount<=m))
            {
                bestWindow = wR-wL;
                bestL = wL;
            }
        }

/*        Print positions of zeroes in the widest window*/

        for (int i=0; i<bestWindow; i++)
        {
            if (arr[bestL+i] == 0)
            System.out.print(bestL+i + " ");
        }
    }

/*    Driver method to test the above function*/

    public static void main(String[] args)
    {
        int m = 2;
        System.out.println("Indexes of zeroes to be flipped are ");

        findZeroes(m);
    }
}

/*Java program to count number of strictly
increasing subarrays*/



class Test
{
    static int arr[] = new int[]{1, 2, 2, 4};

    static int countIncreasing(int n)
    {

/*        Initialize count of subarrays as 0*/

        int cnt = 0;

/*        Pick starting point*/

        for (int i=0; i<n; i++)
        {

/*            Pick ending point*/

            for (int j=i+1; j<n; j++)
            {
                if (arr[j] > arr[j-1])
                    cnt++;

/*                If subarray arr[i..j] is not strictly
                increasing, then subarrays after it , i.e.,
                arr[i..j+1], arr[i..j+2], .... cannot
                be strictly increasing*/

                else
                    break;
            }
        }
        return cnt;
    }

/*    Driver method to test the above function*/

    public static void main(String[] args)
    {
        System.out.println("Count of strictly increasing subarrays is " +
                                               countIncreasing(arr.length));
    }
}

/*Java program to count number of strictly
increasing subarrays*/



class Test
{
    static int arr[] = new int[]{1, 2, 2, 4};

    static int countIncreasing(int n)
    {

/*Initialize result*/

int cnt = 0;

/*        Initialize length of current increasing
        subarray*/

        int len = 1;

/*        Traverse through the array*/

        for (int i=0; i < n-1; ++i)
        {

/*            If arr[i+1] is greater than arr[i],
            then increment length*/

            if (arr[i + 1] > arr[i])
                len++;

/*            Else Update count and reset length*/

            else
            {
                cnt += (((len - 1) * len) / 2);
                len = 1;
            }
        }

/*        If last length is more than 1*/

        if (len > 1)
            cnt += (((len - 1) * len) / 2);

        return cnt;
    }

/*    Driver method to test the above function*/

    public static void main(String[] args)
    {
        System.out.println("Count of strictly increasing subarrays is " +
                                               countIncreasing(arr.length));
    }
}

/*java to find maximum group difference*/

import java.util.Arrays;

public class GFG {

/*    utility function for array sum*/

    static long arraySum(int arr[], int n)
    {
        long sum = 0;
        for (int i = 0; i < n; i++)
            sum = sum + arr[i];

        return sum;
    }

/*    function for finding maximum group
    difference of array*/

    static long maxDiff (int arr[], int n, int k)
    {

/*        sort the array*/

        Arrays.sort(arr);

/*        find array sum*/

        long arraysum = arraySum(arr, n);

/*        difference for k-smallest
        diff1 = (arraysum-k_smallest)-k_smallest*/

        long diff1 = Math.abs(arraysum -
                            2 * arraySum(arr, k));

/*        reverse array for finding sum of
        1st k-largest*/

        int end = arr.length - 1;
        int start = 0;
        while (start < end)
        {
            int temp = arr[start];
            arr[start] = arr[end];
            arr[end] = temp;
            start++;
            end--;
        }

/*        difference for k-largest
        diff2 = (arraysum-k_largest)-k_largest*/

        long diff2 = Math.abs(arraysum -
                            2 * arraySum(arr, k));

/*        return maximum difference value*/

        return(Math.max(diff1, diff2));

    }

/*driver program*/


    public static void main(String args[]) {
        int arr[] = {1, 7, 4, 8, -1, 5, 2, 1};
        int n = arr.length;
        int k = 3;

        System.out.println("Maximum Difference = "
                            + maxDiff(arr, n, k));

    }
}

/*Java program to find minimum number
of elements to add so that its
median equals x.*/

import java.util.*;
import java.lang.*;

class GFG {

    public static int minNumber(int a[],
                           int n, int x)
    {
        int l = 0, h = 0, e = 0;
        for (int i = 0; i < n; i++)
        {

/*            no. of elements equals to
            x, that is, e.*/

            if (a[i] == x)
                e++;

/*            no. of elements greater
            than x, that is, h.*/

            else if (a[i] > x)
                h++;

/*            no. of elements smaller
            than x, that is, l.*/

            else if (a[i] < x)
                l++;
        }

        int ans = 0;
        if (l > h)
            ans = l - h;
        else if (l < h)
            ans = h - l - 1;

/*        subtract the no. of elements
        that are equal to x.*/

        return ans + 1 - e;
    }

/*    Driven Program*/

    public static void main(String[] args)
    {
        int x = 10;
        int a[] = { 10, 20, 30 };
        int n = a.length;
        System.out.println(
                      minNumber(a, n, x));
    }
}

/*Java Program to solve range query on array
whose each element is XOR of index value
and previous element.*/


import java.io.*;

class GFG {

/*    function return derived formula value.*/

    static int fun(int x)
    {
        int y = (x / 4) * 4;

/*        finding xor value of range [y...x]*/

        int ans = 0;

        for (int i = y; i <= x; i++)
            ans ^= i;

        return ans;
    }

/*    function to solve query for l and r.*/

    static int query(int x)
    {

/*        if l or r is 0.*/

        if (x == 0)
            return 0;

        int k = (x + 1) / 2;

/*        finding x is divisible by 2 or not.*/

        return ((x %= 2) != 0) ? 2 * fun(k) :
                   ((fun(k - 1) * 2) ^ (k & 1));
    }

    static void allQueries(int q, int l[], int r[])
    {
        for (int i = 0; i < q; i++)
            System.out.println((query(r[i]) ^
                               query(l[i] - 1))) ;
    }

/*    Driven Program*/

    public static void main (String[] args) {

        int q = 3;
        int []l = { 2, 2, 5 };
        int []r = { 4, 8, 9 };

        allQueries(q, l, r);

    }
}

/*Java program to check whether a subarray is in
mountain form or not*/

class SubArray
{

/*    Utility method to construct left and right array*/

    static void preprocess(int arr[], int N, int left[], int right[])
    {

/*        initialize first left index as that index only*/

        left[0] = 0;
        int lastIncr = 0;

        for (int i = 1; i < N; i++)
        {

/*            if current value is greater than previous,
            update last increasing*/

            if (arr[i] > arr[i - 1])
                    lastIncr = i;
            left[i] = lastIncr;
        }

/*        initialize last right index as that index only*/

        right[N - 1] = N - 1;
        int firstDecr = N - 1;

        for (int i = N - 2; i >= 0; i--)
        {

/*            if current value is greater than next,
            update first decreasing*/

            if (arr[i] > arr[i + 1])
                    firstDecr = i;
            right[i] = firstDecr;
        }
    }

/*    method returns true if arr[L..R] is in mountain form*/

    static boolean isSubarrayMountainForm(int arr[], int left[],
                                    int right[], int L, int R)
    {

/*        return true only if right at starting range is
        greater than left at ending range*/

        return (right[L] >= left[R]);
    }

/*    Driver Code*/


    public static void main(String[] args)
    {
        int arr[] = {2, 3, 2, 4, 4, 6, 3, 2};
        int N = arr.length;
        int left[] = new int[N];
        int right[] = new int[N];
        preprocess(arr, N, left, right);
        int L = 0;
        int R = 2;

        if (isSubarrayMountainForm(arr, left, right, L, R))
            System.out.println("Subarray is in mountain form");
        else
            System.out.println("Subarray is not in mountain form");

        L = 1;
        R = 3;

        if (isSubarrayMountainForm(arr, left, right, L, R))
            System.out.println("Subarray is in mountain form");
        else
            System.out.println("Subarray is not in mountain form");
    }
}

/*Java program to find sum between two indexes
when there is no update.*/


import java.util.*;
import java.lang.*;

class GFG {
    public static void preCompute(int arr[], int n,
                                  int pre[])
    {
        pre[0] = arr[0];
        for (int i = 1; i < n; i++)
            pre[i] = arr[i] + pre[i - 1];
    }

/*    Returns sum of elements in arr[i..j]
    It is assumed that i <= j*/

    public static int rangeSum(int i, int j, int pre[])
    {
        if (i == 0)
            return pre[j];

        return pre[j] - pre[i - 1];
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = { 1, 2, 3, 4, 5 };
        int n = arr.length;

        int pre[] = new int[n];

/*Function call*/


        preCompute(arr, n, pre);
        System.out.println(rangeSum(1, 3, pre));
        System.out.println(rangeSum(2, 4, pre));
    }
}

/*Java program to find number of prime numbers in a 
subarray and performing updates*/

import java.io.*;
import java.util.*;

class GFG
{
    static int MAX = 1000 ;
    static void sieveOfEratosthenes(boolean isPrime[])
    {
        isPrime[1] = false;
        for (int p = 2; p * p <= MAX; p++)
        {

/*            If prime[p] is not changed, then
            it is a prime*/

            if (isPrime[p] == true)
            {

/*                Update all multiples of p*/

                for (int i = p * 2; i <= MAX; i += p)
                    isPrime[i] = false;
            }
        }
    }

/*    A utility function to get the middle index from corner indexes.*/

    static int getMid(int s, int e) { return s + (e - s) / 2; }

/*  A recursive function to get the number of primes in a given range
     of array indexes. The following are parameters for this function.

    st    --> Pointer to segment tree
    index --> Index of current node in the segment tree. Initially
              0 is passed as root is always at index 0
    ss & se  --> Starting and ending indexes of the segment represented
                  by current node, i.e., st[index]
    qs & qe  --> Starting and ending indexes of query range */


    static int queryPrimesUtil(int[] st, int ss, int se, int qs, int qe, int index)
    {

/*        If segment of this node is a part of given range, then return
        the number of primes in the segment      */

        if (qs <= ss && qe >= se)
        return st[index];

/*        If segment of this node is outside the given range*/

        if (se < qs || ss > qe)
            return 0;

/*        If a part of this segment overlaps with the given range*/

        int mid = getMid(ss, se);
        return queryPrimesUtil(st, ss, mid, qs, qe, 2 * index + 1) +
          queryPrimesUtil(st, mid + 1, se, qs, qe, 2 * index + 2);
    }

/* A recursive function to update the nodes which have the given 
   index in their range. The following are parameters
    st, si, ss and se are same as getSumUtil()
    i    --> index of the element to be updated. This index is 
             in input array.
   diff --> Value to be added to all nodes which have i in range */


   static void updateValueUtil(int[] st, int ss, int se, int i, int diff, int si)
   {

/*        Base Case: If the input index lies outside the range of
        this segment*/

        if (i < ss || i > se)
            return;

/*        If the input index is in range of this node, then update
        the value of the node and its children*/

        st[si] = st[si] + diff;
        if (se != ss) {
            int mid = getMid(ss, se);
            updateValueUtil(st, ss, mid, i, diff, 2 * si + 1);
            updateValueUtil(st, mid + 1, se, i, diff, 2 * si + 2);
        }
    }

/*    The function to update a value in input array and segment tree.
    It uses updateValueUtil() to update the value in segment tree*/


    static void updateValue(int arr[], int[] st, int n,
                            int i, int new_val, boolean isPrime[])
    {

/*        Check for erroneous input index*/

        if (i < 0 || i > n - 1) {
            System.out.println("Invalid Input");
            return;
        }
        int diff = 0;
        int oldValue;

        oldValue = arr[i];

/*        Update the value in array*/

        arr[i] = new_val;

/*        Case 1: Old and new values both are primes*/

        if (isPrime[oldValue] && isPrime[new_val])
            return;

/*        Case 2: Old and new values both non primes*/

        if ((!isPrime[oldValue]) && (!isPrime[new_val]))
            return;

/*        Case 3: Old value was prime, new value is non prime*/

        if (isPrime[oldValue] && !isPrime[new_val])
        {
            diff = -1;
        }

/*        Case 4: Old value was non prime, new_val is prime*/

        if (!isPrime[oldValue] && isPrime[new_val])
        {
            diff = 1;
        }

/*        Update the values of nodes in segment tree*/

        updateValueUtil(st, 0, n - 1, i, diff, 0);
    }

/*    Return number of primes in range from index qs (query start) to
    qe (query end).  It mainly uses queryPrimesUtil()*/

    static void queryPrimes(int[] st, int n, int qs, int qe)
    {
        int primesInRange = queryPrimesUtil(st, 0, n - 1, qs, qe, 0);
        System.out.println("Number of Primes in subarray from " +
                           qs + " to " + qe + " = " + primesInRange);
    }

/*    A recursive function that constructs Segment Tree 
    for array[ss..se].
    si is index of current node in segment tree st*/

    static int constructSTUtil(int arr[], int ss, int se,
                               int[] st, int si, boolean isPrime[])
    {

/*        If there is one element in array, check if it
        is prime then store 1 in the segment tree else
        store 0 and return*/

        if (ss == se) {

/*            if arr[ss] is prime*/

            if (isPrime[arr[ss]]) 
                st[si] = 1;        
            else
                st[si] = 0;

            return st[si];
        }

/*        If there are more than one elements, then recur 
        for left and right subtrees and store the sum 
        of the two values in this node*/

        int mid = getMid(ss, se);
        st[si] = constructSTUtil(arr, ss, mid, st, si * 2 + 1, isPrime) + 
                constructSTUtil(arr, mid + 1, se, st, si * 2 + 2, isPrime);
        return st[si];
    }

/* Function to construct segment tree from given array. 
   This function allocates memory for segment tree and
   calls constructSTUtil() to fill the allocated memory */

   static int[] constructST(int arr[], int n, boolean isPrime[])
   {

/*       Allocate memory for segment tree*/

/*        Height of segment tree*/

        int x = (int)(Math.ceil(Math.log(n)/Math.log(2)));

/*        Maximum size of segment tree*/

        int max_size = 2 * (int)Math.pow(2, x) - 1;  
        int[] st = new int[max_size];

/*        Fill the allocated memory st*/

        constructSTUtil(arr, 0, n - 1, st, 0, isPrime);

/*        Return the constructed segment tree*/

        return st;
   }

/*  Driver code*/

    public static void main (String[] args)
    {
        int arr[] = { 1, 2, 3, 5, 7, 9 };
        int n = arr.length;

/* Preprocess all primes till MAX.
       Create a boolean array "isPrime[0..MAX]".
       A value in prime[i] will finally be false 
       if i is Not a prime, else true. */

        boolean[] isPrime = new boolean[MAX + 1];
        Arrays.fill(isPrime, Boolean.TRUE);
        sieveOfEratosthenes(isPrime);

/*        Build segment tree from given array*/

        int[] st = constructST(arr, n, isPrime);

/*        Query 1: Query(start = 0, end = 4)*/

        int start = 0;
        int end = 4;
        queryPrimes(st, n, start, end);

/*        Query 2: Update(i = 3, x = 6), i.e Update 
        a[i] to x*/

        int i = 3;
        int x = 6;
        updateValue(arr, st, n, i, x, isPrime);

/*        uncomment to see array after update
        for(int i = 0; i < n; i++) cout << arr[i] << " ";*/

/*        Query 3: Query(start = 0, end = 4)*/

        start = 0;
        end = 4;
        queryPrimes(st, n, start, end);
    }
}

/*Java program to solve three types of queries.*/

import java.io.*;
import java.util.*;
import java.util.Arrays;

class GFG{

static Scanner sc= new Scanner(System.in);

/*Vector of 1000 elements,
all set to 0*/

static int twos[] = new int[1000];

/*Vector of 1000 elements,
all set to 0*/

static int fives[] = new int[1000];

static int sum = 0;

/*Function to check number of
trailing zeros in multiple of 2*/

static int returnTwos(int val)
{
    int count = 0;
    while (val % 2 == 0 && val != 0)
    {
        val = val / 2;
        count++;
    }
    return count;
}

/*Function to check number of
trailing zeros in multiple of 5*/

static int returnFives(int val)
{
    int count = 0;
    while (val % 5 == 0 && val != 0)
    {
        val = val / 5;
        count++;
    }
    return count;
}

/*Function to solve the queries received*/

static void solve_queries(int arr[], int n)
{
    int type = sc.nextInt();

/*    If the query is of type 1.*/

    if (type == 1)
    {
        int ql = sc.nextInt();
        int qr = sc.nextInt();
        int x = sc.nextInt();

/*        Counting the number of
        zeros in the given value of x*/

        int temp = returnTwos(x);
        int temp1 = returnFives(x);

        for(int i = ql - 1; i < qr; i++)
        {

/*            The value x has been multiplied
            to their respective indices*/

            arr[i] = arr[i] * x;

/*            The value obtained above has been
            added to their respective vectors*/

            twos[i] += temp;
            fives[i] += temp1;
        }
    }

/*    If the query is of type 2.*/

    if (type == 2)
    {
        int ql = sc.nextInt();
        int qr = sc.nextInt();
        int y = sc.nextInt();

/*        Counting the number of
        zero in the given value of x*/

        int temp = returnTwos(y);
        int temp1 = returnFives(y);

        for(int i = ql - 1; i < qr; i++)
        {

/*            The value y has been replaced
            to their respective indices*/

            arr[i] = (i - ql + 2) * y;

/*            The value obtained above has been
            added to their respective vectors*/

            twos[i] = returnTwos(i - ql + 2) + temp;
            fives[i] = returnFives(i - ql + 2) + temp1;
        }
    }

/*    If the query is of type 2*/

    if (type == 3)
    {
        int ql = sc.nextInt();
        int qr = sc.nextInt();
        int sumtwos = 0;
        int sumfives = 0;

        for(int i = ql - 1; i < qr; i++)
        {

/*            As the number of trailing zeros for
            each case has been found for each array
            element then we simply add those to
            the respective index to a variable*/

            sumtwos += twos[i];
            sumfives += fives[i];
        }

/*        Compare the number of zeros
        obtained in the multiples of five and two
        consider the minimum of them and add them*/

        sum += Math.min(sumtwos, sumfives);
    }
}

/*Driver code*/

public static void main(String[] args)
{

/*    Input the Size of array
    and number of queries*/

    int n = sc.nextInt();
    int m = sc.nextInt();

    int arr[] = new int[n];
    for(int i = 0; i < n; i++)
    {
        arr[i] = sc.nextInt();
        twos[i] = returnTwos(arr[i]);
        fives[i] = returnFives(arr[i]);
    }

/*    Running the while loop
    for m number of queries*/

    while (m-- != 0)
    {
        solve_queries(arr, n);
    }
    System.out.println(sum);
}
}

/*Java program to find floor value
of mean in range l to r*/

public class Main {

/*    To find mean of range in l to r*/

    static int findMean(int arr[], int l, int r)
    {

/*        Both sum and count are
        initialize to 0*/

        int sum = 0, count = 0;

/*        To calculate sum and number
        of elements in range l to r*/

        for (int i = l; i <= r; i++) {
            sum += arr[i];
            count++;
        }

/*        Calculate floor value of mean*/

        int mean = (int)Math.floor(sum / count);

/*        Returns mean of array
        in range l to r*/

        return mean;
    }

/*    Driver program to test findMean()*/

    public static void main(String[] args)
    {
        int arr[] = { 1, 2, 3, 4, 5 };
        System.out.println(findMean(arr, 0, 2));
        System.out.println(findMean(arr, 1, 3));
        System.out.println(findMean(arr, 0, 4));
    }
}

/*Java program to find floor value
of mean in range l to r*/

public class Main {
public static final int MAX = 1000005;
    static int prefixSum[] = new int[MAX];

/*    To calculate prefixSum of array*/

    static void calculatePrefixSum(int arr[], int n)
    {

/*        Calculate prefix sum of array*/

        prefixSum[0] = arr[0];
        for (int i = 1; i < n; i++)
            prefixSum[i] = prefixSum[i - 1] + arr[i];
    }

/*    To return floor of mean
    in range l to r*/

    static int findMean(int l, int r)
    {
        if (l == 0)
           return (int)Math.floor(prefixSum[r] / (r + 1));

/*        Sum of elements in range l to
        r is prefixSum[r] - prefixSum[l-1]
        Number of elements in range
        l to r is r - l + 1*/

        return (int)Math.floor((prefixSum[r] -
                prefixSum[l - 1]) / (r - l + 1));
    }

/*    Driver program to test above functions*/

    public static void main(String[] args)
    {
        int arr[] = { 1, 2, 3, 4, 5 };
        int n = arr.length;
        calculatePrefixSum(arr, n);
        System.out.println(findMean(1, 2));
        System.out.println(findMean(1, 3));
        System.out.println(findMean(1, 4));
    }
}

/*Java program to find modified array
after executing m commands/queries*/

import java.util.Arrays;

class GFG {

/*    Update function for every command*/

    static void updateQuery(int arr[], int n,
                  int q, int l, int r, int k)
    {

/*        If q == 0, add 'k' and '-k'
        to 'l-1' and 'r' index*/

        if (q == 0){
            arr[l-1] += k;
            arr[r] += -k;
        }

/*        If q == 1, add '-k' and 'k'
        to 'l-1' and 'r' index*/

        else{
            arr[l-1] += -k;
            arr[r] += k;
        }

        return;
    }

/*    Function to generate the final
    array after executing all
    commands*/

    static void generateArray(int arr[], int n)
    {

/*        Generate final array with the
        help of DP concept*/

        for (int i = 1; i < n; ++i)
            arr[i] += arr[i-1];

    }

/*    driver code*/

    public static void main(String arg[])
    {
        int n = 5;
        int arr[] = new int[n+1];
        Arrays.fill(arr, 0);

        int q = 0, l = 1, r = 3, k = 2;
        updateQuery(arr, n, q, l, r, k);

        q = 1 ; l = 3; r = 5; k = 3;
        updateQuery(arr, n, q, l, r, k);

        q = 0 ; l = 2; r = 5; k = 1;
        updateQuery(arr, n, q, l, r, k);

/*        Generate final array*/

        generateArray(arr, n);

/*        Printing the final modified array*/

        for (int i = 0; i < n; ++i)
            System.out.print(arr[i]+" ");
    }
}

/*Product in range Queries in O(N)*/

import java.io.*;

class GFG
{

/*    Function to calculate
    Product in the given range.*/

    static int calculateProduct(int []A, int L,
                                int R, int P)
    {

/*        As our array is 0 based as
        and L and R are given as 1
        based index.*/

        L = L - 1;
        R = R - 1;

        int ans = 1;
        for (int i = L; i <= R; i++)
        {
            ans = ans * A[i];
            ans = ans % P;
        }

        return ans;
    }

/*    Driver code*/

    static public void main (String[] args)
    {
        int []A = { 1, 2, 3, 4, 5, 6 };
        int P = 229;
        int L = 2, R = 5;
        System.out.println(
            calculateProduct(A, L, R, P));

        L = 1;
        R = 3;
        System.out.println(
            calculateProduct(A, L, R, P));
    }
}

/*Java program to find Product
in range Queries in O(1)*/

class GFG
{

static int MAX = 100;
int pre_product[] = new int[MAX];
int inverse_product[] = new int[MAX];

/*Returns modulo inverse of a
with respect to m using extended
Euclid Algorithm Assumption: a
and m are coprimes,
i.e., gcd(a, m) = 1*/

int modInverse(int a, int m)
{
    int m0 = m, t, q;
    int x0 = 0, x1 = 1;

    if (m == 1)
        return 0;

    while (a > 1)
    {

/*        q is quotient*/

        q = a / m;

        t = m;

/*        m is remainder now,
        process same as
        Euclid's algo*/

        m = a % m;
        a = t;

        t = x0;

        x0 = x1 - q * x0;

        x1 = t;
    }

/*    Make x1 positive*/

    if (x1 < 0)
        x1 += m0;

    return x1;
}

/*calculating pre_product array*/

void calculate_Pre_Product(int A[],
                           int N, int P)
{
    pre_product[0] = A[0];

    for (int i = 1; i < N; i++)
    {
        pre_product[i] = pre_product[i - 1] *
                                        A[i];
        pre_product[i] = pre_product[i] % P;
    }
}

/*Cacluating inverse_product array.*/

void calculate_inverse_product(int A[],
                               int N, int P)
{
    inverse_product[0] = modInverse(pre_product[0],
                                                P);

    for (int i = 1; i < N; i++)
        inverse_product[i] = modInverse(pre_product[i],
                                                     P);
}

/*Function to calculate Product
in the given range.*/

int calculateProduct(int A[], int L,
                     int R, int P)
{

/*    As our array is 0 based as and
    L and R are given as 1 based index.*/

    L = L - 1;
    R = R - 1;
    int ans;

    if (L == 0)
        ans = pre_product[R];
    else
        ans = pre_product[R] *
              inverse_product[L - 1];

    return ans;
}

/*Driver code*/

public static void main(String[] s)
{
    GFG d = new GFG();

/*    Array*/

    int A[] = { 1, 2, 3, 4, 5, 6 };

/*    Prime P*/

    int P = 113;

/*    Calculating PreProduct and
    InverseProduct*/

    d.calculate_Pre_Product(A, A.length, P);
    d.calculate_inverse_product(A, A.length,
                                         P);

/*    Range [L, R] in 1 base index*/

    int L = 2, R = 5;
    System.out.println(d.calculateProduct(A, L,
                                          R, P));
    L = 1;
    R = 3;
    System.out.println(d.calculateProduct(A, L,
                                          R, P));

}
}

/*Java program to answer queries for
count of primes in given range.*/

import java.util.*;

class GFG {

static final int MAX = 10000;

/*prefix[i] is going to store count
of primes till i (including i).*/

static int prefix[] = new int[MAX + 1];

static void buildPrefix() {

/*    Create a boolean array "prime[0..n]". A
    value in prime[i] will finally be false
    if i is Not a prime, else true.*/

    boolean prime[] = new boolean[MAX + 1];
    Arrays.fill(prime, true);

    for (int p = 2; p * p <= MAX; p++) {

/*    If prime[p] is not changed, then
    it is a prime*/

    if (prime[p] == true) {

/*        Update all multiples of p*/

        for (int i = p * 2; i <= MAX; i += p)
        prime[i] = false;
    }
    }

/*    Build prefix array*/

    prefix[0] = prefix[1] = 0;
    for (int p = 2; p <= MAX; p++) {
    prefix[p] = prefix[p - 1];
    if (prime[p])
        prefix[p]++;
    }
}

/*Returns count of primes in range
from L to R (both inclusive).*/

static int query(int L, int R)
{
    return prefix[R] - prefix[L - 1];
}

/*Driver code*/

public static void main(String[] args) {

    buildPrefix();
    int L = 5, R = 10;
    System.out.println(query(L, R));

    L = 1; R = 10;
    System.out.println(query(L, R));
}
}

/*Java program to find modified array
after m range toggle operations.*/

class GFG
{

/*function for toggle*/

static void command(boolean arr[],
                    int a, int b)
{
    arr[a] ^= true;
    arr[b + 1] ^= true;
}

/*function for final processing of array*/

static void process(boolean arr[], int n)
{
    for (int k = 1; k <= n; k++)
    {
        arr[k] ^= arr[k - 1];
    }
}

/*function for printing result*/

static void result(boolean arr[], int n)
{
    for (int k = 1; k <= n; k++)
    {
        if(arr[k] == true)
            System.out.print("1" + " ");
        else
            System.out.print("0" + " ");
    }
}

/*Driver Code*/

public static void main(String args[])
{
    int n = 5, m = 3;
    boolean arr[] = new boolean[n + 2];

/*    function call for toggle*/

    command(arr, 1, 5);
    command(arr, 2, 5);
    command(arr, 3, 5);

/*    process array*/

    process(arr, n);

/*    print result*/

    result(arr, n);
}
}

/*A Java program to check if any two intervals overlap*/

import java.io.*;
import java.lang.*;
import java.util.*;

class GFG{

/*An interval has start time and end time*/

static class Interval
{
    int start;
    int end;

    public Interval(int start, int end)
    {
        super();
        this.start = start;
        this.end = end;
    }
};

/*Function to check if any two intervals overlap*/

static boolean isIntersect(Interval arr[], int n)
{

/*    Sort intervals in increasing order of start time*/

    Arrays.sort(arr, (i1, i2) -> {
        return i1.start - i2.start;
    });

/*    In the sorted array, if start time of an interval
    is less than end of previous interval, then there
    is an overlap*/

    for(int i = 1; i < n; i++)
        if (arr[i - 1].end > arr[i].start)
            return true;

/*    If we reach here, then no overlap*/

    return false;
}

/*Driver code*/

public static void main(String[] args)
{
    Interval arr1[] = { new Interval(1, 3),
                        new Interval(7, 9),
                        new Interval(4, 6),
                        new Interval(10, 13) };
    int n1 = arr1.length;

    if (isIntersect(arr1, n1))
        System.out.print("Yes\n");
    else
        System.out.print("No\n");

    Interval arr2[] = { new Interval(6, 8),
                        new Interval(1, 3),
                        new Interval(2, 4),
                        new Interval(4, 7) };
    int n2 = arr2.length;

    if (isIntersect(arr2, n2))
        System.out.print("Yes\n");
    else
        System.out.print("No\n");
}
}

/*A Java program to check if any two intervals overlap*/

class GFG
{

/*An interval has start time and end time*/

static class Interval
{
    int start;
    int end;
    public Interval(int start, int end)
    {
        super();
        this.start = start;
        this.end = end;
    }
};

/*Function to check if any two intervals overlap*/

static boolean isIntersect(Interval arr[], int n)
{

    int max_ele = 0;

/*    Find the overall maximum element*/

    for (int i = 0; i < n; i++)
    {
        if (max_ele < arr[i].end)
            max_ele = arr[i].end;
    }

/*    Initialize an array of size max_ele*/

    int []aux = new int[max_ele + 1];
    for (int i = 0; i < n; i++)
    {

/*        starting point of the interval*/

        int x = arr[i].start;

/*        end point of the interval*/

        int y = arr[i].end;
        aux[x]++;
        aux[y ]--;
    }
    for (int i = 1; i <= max_ele; i++)
    {

/*        Calculating the prefix Sum*/

        aux[i] += aux[i - 1];

/*        Overlap*/

        if (aux[i] > 1)
            return true;
    }

/*    If we reach here, then no Overlap*/

    return false;
}

/*Driver program*/

public static void main(String[] args)
{
    Interval arr1[] = { new Interval(1, 3), new Interval(7, 9),
                       new Interval(4, 6), new Interval(10, 13) };
    int n1 = arr1.length;

    if(isIntersect(arr1, n1))
        System.out.print("Yes\n");
    else
        System.out.print("No\n");

    Interval arr2[] = { new Interval(6, 8), new Interval(1, 3),
                        new Interval(2, 4), new Interval(4, 7) };
    int n2 = arr2.length;
    if(isIntersect(arr2, n2))
        System.out.print("Yes\n");
    else
        System.out.print("No\n");
}
}

/*Java implementation to increment values in the
given range by a value d for multiple queries*/

class GFG
{

/*    structure to store the (start, end)
    index pair for each query*/

    static class query
    {
        int start, end;

        query(int start, int end)
        {
            this.start = start;
            this.end = end;
        }
    }

/*    function to increment values in the given range
    by a value d for multiple queries*/

    public static void incrementByD(int[] arr, query[] q_arr,
                                    int n, int m, int d)
    {
        int[] sum = new int[n];

/*        for each (start, end) index pair, perform
        the following operations on 'sum[]'*/

        for (int i = 0; i < m; i++)
        {

/*            increment the value at index 'start'
            by the given value 'd' in 'sum[]'*/

            sum[q_arr[i].start] += d;

/*            if the index '(end+1)' exists then
            decrement the value at index '(end+1)'
            by the given value 'd' in 'sum[]'*/

            if ((q_arr[i].end + 1) < n)
                sum[q_arr[i].end + 1] -= d;
        }

/*        Now, perform the following operations:
        accumulate values in the 'sum[]' array and
        then add them to the corresponding indexes
        in 'arr[]'*/

        arr[0] += sum[0];
        for (int i = 1; i < n; i++)
        {
            sum[i] += sum[i - 1];
            arr[i] += sum[i];
        }
    }

/*    function to print the elements of the given array*/

    public static void printArray(int[] arr, int n)
    {
        for (int i = 0; i < n; i++)
            System.out.print(arr[i] + " ");
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int[] arr = { 3, 5, 4, 8, 6, 1 };
        query[] q_arr = new query[5];
        q_arr[0] = new query(0, 3);
        q_arr[1] = new query(4, 5);
        q_arr[2] = new query(1, 4);
        q_arr[3] = new query(0, 1);
        q_arr[4] = new query(2, 5);
        int n = arr.length;
        int m = q_arr.length;
        int d = 2;
        System.out.println("Original Array:");
        printArray(arr, n);

/*        modifying the array for multiple queries*/

        incrementByD(arr, q_arr, n, m, d);
        System.out.println("\nModified Array:");
        printArray(arr, n);
    }
}

/*Java code Queries on XOR of
greatest odd divisor of the range*/

import java.io.*;

class GFG
{

/*    Precompute the prefix XOR of greatest
    odd divisor*/

    static void prefixXOR(int arr[], int preXOR[], int n)
    {

/*        Finding the Greatest Odd divisor*/

        for (int i = 0; i < n; i++)
        {
            while (arr[i] % 2 != 1)
                arr[i] /= 2;

            preXOR[i] = arr[i];
        }

/*        Finding prefix XOR*/

        for (int i = 1; i < n; i++)
            preXOR[i] = preXOR[i - 1] ^ preXOR[i];
    }

/*    Return XOR of the range*/

    static int query(int preXOR[], int l, int r)
    {
        if (l == 0)
            return preXOR[r];
        else
            return preXOR[r] ^ preXOR[l - 1];
    }

/*    Driven Program*/

    public static void main (String[] args)
    {
        int arr[] = { 3, 4, 5 };
        int n = arr.length;

        int preXOR[] = new int[n];
        prefixXOR(arr, preXOR, n);

        System.out.println(query(preXOR, 0, 2)) ;
        System.out.println (query(preXOR, 1, 2));


    }
}

/*Java code to find number of distinct numbers 
in a subarray */

import java.io.*;
import java.util.*;

class GFG 
{
    static int MAX = 1000001;

/*    structure to store queries*/

    static class Query 
    {
        int l, r, idx;
    }

/*    updating the bit array*/

    static void update(int idx, int val, 
                        int bit[], int n) 
    {
        for (; idx <= n; idx += idx & -idx)
            bit[idx] += val;
    }

/*    querying the bit array*/

    static int query(int idx, int bit[], int n) 
    {
        int sum = 0;
        for (; idx > 0; idx -= idx & -idx)
            sum += bit[idx];
        return sum;
    }

    static void answeringQueries(int[] arr, int n, 
                                Query[] queries, int q)
    {

/*        initialising bit array*/

        int[] bit = new int[n + 1];
        Arrays.fill(bit, 0);

/*        holds the rightmost index of any number
        as numbers of a[i] are less than or equal to 10^6*/

        int[] last_visit = new int[MAX];
        Arrays.fill(last_visit, -1);

/*        answer for each query*/

        int[] ans = new int[q];
        int query_counter = 0;
        for (int i = 0; i < n; i++) 
        {

/*            If last visit is not -1 update -1 at the
            idx equal to last_visit[arr[i]]*/

            if (last_visit[arr[i]] != -1)
                update(last_visit[arr[i]] + 1, -1, bit, n);

/*            Setting last_visit[arr[i]] as i and updating
            the bit array accordingly*/

            last_visit[arr[i]] = i;
            update(i + 1, 1, bit, n);

/*            If i is equal to r of any query store answer
            for that query in ans[]*/

            while (query_counter < q && queries[query_counter].r == i) 
            {
                ans[queries[query_counter].idx] = 
                        query(queries[query_counter].r + 1, bit, n)
                        - query(queries[query_counter].l, bit, n);
                query_counter++;
            }
        }

/*        print answer for each query*/

        for (int i = 0; i < q; i++)
            System.out.println(ans[i]);
    }

/*    Driver Code*/

    public static void main(String[] args) 
    {
        int a[] = { 1, 1, 2, 1, 3 };
        int n = a.length;
        Query[] queries = new Query[3];
        for (int i = 0; i < 3; i++)
            queries[i] = new Query();
        queries[0].l = 0;
        queries[0].r = 4;
        queries[0].idx = 0;
        queries[1].l = 1;
        queries[1].r = 3;
        queries[1].idx = 1;
        queries[2].l = 2;
        queries[2].r = 4;
        queries[2].idx = 2;
        int q = queries.length;
        Arrays.sort(queries, new Comparator<Query>() 
        {
            public int compare(Query x, Query y)
            {
                if (x.r < y.r)
                    return -1;
                else if (x.r == y.r)
                    return 0;
                else
                    return 1;
            }
        });
        answeringQueries(a, n, queries, q);
    }
}

/*Java program to calculate the number
pairs satisfying th condition*/

import java.util.*;

class GFG
{

/*function to calculate the number of pairs*/

static int countPairs(int a[], int n, int x, int k)
{
    Arrays.sort(a);

/*    traverse through all elements*/

    int ans = 0;
    for (int i = 0; i < n; i++)
    {

/*        current number's divisor*/

        int d = (a[i] - 1) / x;

/*        use binary search to find the element
        after k multiples of x*/

        int it1 = Arrays.binarySearch(a,
                    Math.max((d + k) * x, a[i]));

/*        use binary search to find the element
        after k+1 multiples of x so that we get
        the answer bu subtracting*/

        int it2 = Arrays.binarySearch(a,
                    Math.max((d + k + 1) * x, a[i])) ;

/*        the difference of index will be the answer*/

        ans += it1 - it2;
    }
    return ans;
}

/*Driver code*/

public static void main(String[] args)
{
    int []a = { 1, 3, 5, 7 };
    int n = a.length;
    int x = 2, k = 1;

/*    function call to get the number of pairs*/

    System.out.println(countPairs(a, n, x, k));
}
}

/*Java program to find Probability
of a random pair being the maximum
weighted pair*/

import java.io.*;

class GFG {

/*    Function to return probability*/

    static double probability(int a[], int b[],
                            int size1,int size2)
    {

/*        Count occurrences of maximum
        element in A[]*/

        int max1 = Integer.MIN_VALUE,  count1 = 0;
        for (int i = 0; i < size1; i++) {
            if (a[i] > max1) {
                max1 = a[i];
                count1 = 1;
            }
            else if (a[i] == max1) {
                count1++;
            }
        }

/*        Count occurrences of maximum
        element in B[]*/

        int max2 = Integer.MIN_VALUE, count2 = 0;
        for (int i = 0; i < size2; i++) {
            if (b[i] > max2) {
                max2 = b[i];
                count2 = 1;
            }
            else if (b[i] == max2) {
                count2++;
            }
        }

/*        Returning probability*/

        return (double)(count1 * count2) / (size1 * size2);
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int a[] = { 1, 2, 3 };
        int b[] = { 1, 3, 3 };

        int size1 = a.length;
        int size2 = b.length;

        System.out.println(probability(a, b,
                            size1, size2));
    }
}

/*Java code for counting minimum
de-arrangements present in an array.*/

import java.util.*;
import java.lang.*;
import java.util.Arrays;

public class GeeksforGeeks{

/*    function to count Dearrangement*/

    public static int countDe(int arr[], int n){
        int v[] = new int[n];

/*        create a copy of original array*/

        for(int i = 0; i < n; i++)
            v[i] = arr[i];

/*        sort the array*/

        Arrays.sort(arr);

/*        traverse sorted array for
        counting mismatches*/

        int count1 = 0;
        for (int i = 0; i < n; i++)
            if (arr[i] != v[i])
            count1++;

/*        reverse the sorted array*/

        Collections.reverse(Arrays.asList(arr));

/*        traverse reverse sorted array
        for counting mismatches*/

        int count2 = 0;
        for (int i = 0; i < n; i++)
            if (arr[i] != v[i])    
                count2++;

/*        return minimum mismatch count*/

        return (Math.min (count1, count2));
    }

/*    driver code*/

    public static void main(String argc[]){
        int arr[] = {5, 9, 21, 17, 13};
        int n = 5;
        System.out.println("Minimum Dearrangement = "+
                            countDe(arr, n));
    }
}

/*Java program to calculate minimum
product of a pair*/

import java.util.*;

class GFG {

/*    Function to calculate minimum product
    of pair*/

    static int printMinimumProduct(int arr[], int n)
    {

/*        Initialize first and second
        minimums. It is assumed that the
        array has at least two elements.*/

        int first_min = Math.min(arr[0], arr[1]);
        int second_min = Math.max(arr[0], arr[1]);

/*        Traverse remaining array and keep
        track of two minimum elements (Note
        that the two minimum elements may
        be same if minimum element appears
        more than once)
        more than once)*/

        for (int i = 2; i < n; i++)
        {
           if (arr[i] < first_min)
           {
              second_min = first_min;
              first_min = arr[i];
           }
           else if (arr[i] < second_min)
              second_min = arr[i];
        }

        return first_min * second_min;
    }

/* Driver program to test above function */

    public static void main(String[] args)
    {
        int a[] = { 11, 8 , 5 , 7 , 5 , 100 };
        int n = a.length;
        System.out.print(printMinimumProduct(a,n));

    }
}

/*Java program to count number of ways we can
form triplets with minimum product.*/

import java.util.Arrays;

class GFG {

/*    function to calculate number of triples*/

    static long noOfTriples(long arr[], int n)
    {

/*        Sort the array*/

        Arrays.sort(arr);

/*        Count occurrences of third element*/

        long count = 0;
        for (int i = 0; i < n; i++)
            if (arr[i] == arr[2])
                count++;

/*        If all three elements are same (minimum
        element appears at least 3 times). Answer
        is nC3.*/

        if (arr[0] == arr[2])
            return (count - 2) * (count - 1) *
                                      (count) / 6;

/*        If minimum element appears once.
        Answer is nC2.*/

        else if (arr[1] == arr[2])
            return (count - 1) * (count) / 2;

/*        Minimum two elements are distinct.
        Answer is nC1.*/

        return count;
    }

/*    driver code*/

    public static void main(String arg[])
    {

        long arr[] = { 1, 3, 3, 4 };
        int n = arr.length;

        System.out.print(noOfTriples(arr, n));
    }
}

/*Java program to check whether reversing a
sub array make the array sorted or not*/


import java.util.Arrays;

class GFG {

/*Return true, if reversing the subarray will
sort the array, else return false.*/

    static boolean checkReverse(int arr[], int n) {

/*        Copying the array.*/

        int temp[] = new int[n];
        for (int i = 0; i < n; i++) {
            temp[i] = arr[i];
        }

/*        Sort the copied array.*/

        Arrays.sort(temp);

/*        Finding the first mismatch.*/

        int front;
        for (front = 0; front < n; front++) {
            if (temp[front] != arr[front]) {
                break;
            }
        }

/*        Finding the last mismatch.*/

        int back;
        for (back = n - 1; back >= 0; back--) {
            if (temp[back] != arr[back]) {
                break;
            }
        }

/*        If whole array is sorted*/

        if (front >= back) {
            return true;
        }

/*        Checking subarray is decreasing or not.*/

        do {
            front++;
            if (arr[front - 1] < arr[front]) {
                return false;
            }
        } while (front != back);

        return true;
    }

/*Driven Program*/

    public static void main(String[] args) {

        int arr[] = {1, 2, 5, 4, 3};
        int n = arr.length;

        if (checkReverse(arr, n)) {
            System.out.print("Yes");
        } else {
            System.out.print("No");
        }
    }

}

/*Java program to find minimum
increment/decrement operations
to make array elements same.*/

import java.util.Arrays;
import java.io.*;

class GFG
{
static int MinOperation(int a[],
                        int b[],
                        int n)
{

/*    sorting both arrays
    in ascending order*/

    Arrays.sort(a);
    Arrays.sort(b);

/*    variable to store
    the final result*/

    int result = 0;

/*    After sorting both arrays
    Now each array is in non-
    decreasing order. Thus,
    we will now compare each
    element of the array and
    do the increment or decrement
    operation depending upon the
    value of array b[].*/

    for (int i = 0; i < n; ++i)
    {
        if (a[i] > b[i])
            result = result +
                     Math.abs(a[i] - b[i]);

        else if (a[i] < b[i])
            result = result +
                     Math.abs(a[i] - b[i]);
    }

    return result;
}

/*Driver code*/

public static void main (String[] args)
{
    int a[] = {3, 1, 1};
    int b[] = {1, 2, 2};
    int n = a.length;
    System.out.println(MinOperation(a, b, n));
}
}

/*Java program to sort all elements except
given subarray.*/

import java.util.Arrays;
import java.io.*;

public class GFG {

/*    Sort whole array a[] except elements in
    range a[l..r]*/

    public static void sortExceptUandL(int a[],
                           int l, int u, int n)
    {

/*        Copy all those element that need
        to be sorted to an auxiliary
        array b[]*/

        int b[] = new int[n - (u - l + 1)];

        for (int i = 0; i < l; i++)
            b[i] = a[i];
        for (int i = u+1; i < n; i++)
            b[l + (i - (u+1))] = a[i];

/*        sort the array b*/

        Arrays.sort(b);

/*        Copy sorted elements back to a[]*/

        for (int i = 0; i < l; i++)
            a[i] = b[i];
        for (int i = u+1; i < n; i++)
            a[i] = b[l + (i - (u+1))];
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int a[] = { 5, 4, 3, 12, 14, 9 };
        int n = a.length;
        int l = 2, u = 4;

        sortExceptUandL(a, l, u, n);

        for (int i = 0; i < n; i++)
            System.out.print(a[i] + " ");
    }
}

/*Java program to sort all elements except
element at index k.*/

import java.util.Arrays;

class GFG {

    static int sortExceptK(int arr[], int k, int n)
    {

/*        Move k-th element to end*/

        int temp = arr[k];
        arr[k] = arr[n-1];
        arr[n-1] = temp;

/*        Sort all elements except last*/

        Arrays.sort(arr, 0, n-1);

/*        Store last element (originally k-th)*/

        int last = arr[n-1];

/*        Move all elements from k-th to one
        position ahead.*/

        for (int i = n-1; i > k; i--)
        arr[i] = arr[i-1];

/*        Restore k-th element*/

        arr[k] = last;
        return 0;
    }

/*    Driver code*/

    public static void main (String[] args)
    {
        int a[] = {10, 4, 11, 7, 6, 20 };
        int k = 2;
        int n = a.length;

        sortExceptK(a, k, n);

        for (int i = 0; i < n; i++)
            System.out.print(a[i] + " ");
    }
}

import java.io.*;

class GFG {
    public static int minswaps(int arr[], int n)
    {
        int count = 0;
        int num_unplaced_zeros = 0;

        for (int index = n - 1; index >= 0; index--)
        {
            if (arr[index] == 0)
                num_unplaced_zeros += 1;
            else
                count += num_unplaced_zeros;
        }
        return count;
    }

