/*Java code to find count of Pairs with
difference less than K.*/

import java.io.*;
import java.util.Arrays;

class GFG
{
    static int countPairs(int a[], int n, int k)
    {

/*        to sort the array.*/

        Arrays.sort(a);

        int res = 0;
        for (int i = 0; i < n; i++)
        {

/*            Keep incrementing result while
            subsequent elements are within
            limits.*/

            int j = i + 1;
            while (j < n && a[j] - a[i] < k)
            {
                res++;
                j++;
            }
        }
        return res;
    }

/*    Driver code*/

    public static void main (String[] args)
    {
        int a[] = {1, 10, 4, 2};
        int k = 3;
        int n = a.length;
        System.out.println(countPairs(a, n, k));
    }
}

/*Java implementation of above approach*/

import java.util.*;

class solution
{

/*Returns count of maximum pairs that caan
be formed from a[] and b[] under given
constraints.*/

static int findMaxPairs(int a[], int b[], int n, int k)
{

/*Sorting the first array.*/

Arrays.sort(a);

/*Sorting the second array.*/

Arrays.sort(b);

/*    To keep track of visited elements of b[]*/

    boolean []flag = new boolean[n];
    Arrays.fill(flag,false);

/*    For every element of a[], find a pair
    for it and break as soon as a pair is
    found.*/

    int result = 0;
    for (int i=0; i<n; i++)
    {
        for (int j=0; j<n; j++)
        {
            if (Math.abs(a[i]-b[j])<=k && flag[j]==false)
            {

/*                Increasing the count if a pair is formed.*/

                result++;

/* Making the corresponding flag array
                element as 1 indicating the element
                in the second array element has
                been used. */

                flag[j] = true;

/*                We break the loop to make sure an
                element of a[] is used only once.*/

                break;
            }
        }
    }
    return result;
}

/*Driver code*/

public static void main(String args[])
{
    int[] a = {10, 15, 20};
    int[] b = {17, 12, 24};
    int n = a.length;
    int k = 3;
    System.out.println(findMaxPairs(a, b, n, k));

}
}

/*Java program for Maximizing Unique Pairs
from two arrays*/

import java.util.*;

class GFG
{

/*Returns count of maximum pairs that caan
be formed from a[] and b[] under given
constraints.*/

static int findMaxPairs(int a[], int b[],
                        int n, int k)
{

/*Sorting the first array.*/

Arrays.sort(a);

/*Sorting the second array.*/

Arrays.sort(b); 

    int result = 0;
    for (int i = 0, j = 0; i < n && j < n;)
    {
        if (Math.abs(a[i] - b[j]) <= k)
        {
            result++;

/*            Increasing array pointer of
            both the first and the second array.*/

            i++;
            j++;
        }

/*        Increasing array pointer
        of the second array.*/

        else if(a[i] > b[j])
            j++;

/*        Increasing array pointer
        of the first array.*/

        else
            i++;
    }
    return result;
}

/*Driver code*/

public static void main(String args[])
{
    int a[] = {10, 15, 20};
    int b[] = {17, 12, 24};
    int n = a.length;
    int k = 3;
    System.out.println(findMaxPairs(a, b, n, k));
}
}

/*java implementation to find the sum
of minimum absolute difference of
each array element*/

import java.*;
import java.util.Arrays;

public class GFG {

/*    function to find the sum of
    minimum absolute difference*/

    static int sumOfMinAbsDifferences(
                         int arr[] ,int n)
    {

/*        sort the given array*/

        Arrays.sort(arr);

/*        initialize sum*/

        int sum = 0;

/*        min absolute difference for
        the 1st array element*/

        sum += Math.abs(arr[0] - arr[1]);

/*        min absolute difference for
        the last array element*/

        sum += Math.abs(arr[n-1] - arr[n-2]);

/*        find min absolute difference for
        rest of the array elements and
        add them to sum*/

        for (int i = 1; i < n - 1; i++)
            sum +=
            Math.min(Math.abs(arr[i] - arr[i-1]),
                    Math.abs(arr[i] - arr[i+1]));

/*        required sum*/

        return sum;
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int arr[] = {5, 10, 1, 4, 8, 7};
        int n = arr.length;

        System.out.println( "Sum = "
        + sumOfMinAbsDifferences(arr, n));
    }
}

/*Recursive approach to check if an
