/*Java program to find Noble elements
in an array.*/

import java.util.ArrayList;

class GFG {

/*    Returns a Noble integer if present,
    else returns -1.*/

    public static int nobleInteger(int arr[])
    {
        int size = arr.length;
        for (int i = 0; i < size; i++ )
        {
            int count = 0;
            for (int j = 0; j < size; j++)
                if (arr[i] < arr[j])
                    count++;

/*            If count of greater elements
            is equal to arr[i]*/

            if (count == arr[i])
                return arr[i];
        }
        return -1;
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int [] arr = {10, 3, 20, 40, 2};
        int res = nobleInteger(arr);
        if (res != -1)
            System.out.println("The noble "
                     + "integer is "+ res);
        else
            System.out.println("No Noble "
                        + "Integer Found");
    }
}

/*Java program to find Noble elements
in an array.*/

import java.util.Arrays;

public class Main
{

/*    Returns a Noble integer if present,
    else returns -1.*/

    public static int nobleInteger(int arr[])
    {
        Arrays.sort(arr);

/*        Return a Noble element if present
        before last.*/

        int n = arr.length;
        for (int i=0; i<n-1; i++)
        {
            if (arr[i] == arr[i+1])
                continue;

/*            In case of duplicates, we
            reach last occurrence here.*/

            if (arr[i] == n-i-1)
                return arr[i];
        }

        if (arr[n-1] == 0)
            return arr[n-1];

        return -1;
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int [] arr = {10, 3, 20, 40, 2};
        int res = nobleInteger(arr);
        if (res != -1)
            System.out.println("The noble integer is "+ res);
        else
            System.out.println("No Noble Integer Found");
    }
}

/*Java program to find minimum sum of
absolute differences of two arrays.*/

import java.util.Arrays;

class MinSum
{

/*    Returns minimum possible pairwise
    absolute difference of two arrays.*/

    static long findMinSum(long a[], long b[], long n)
    {

/*        Sort both arrays*/

        Arrays.sort(a);
        Arrays.sort(b);

/*        Find sum of absolute differences*/

        long sum = 0 ;
        for (int i = 0; i < n; i++)
            sum = sum + Math.abs(a[i] - b[i]);

        return sum;
    }

/*    Driver code*/

    public static void main(String[] args)
    {

/*        Both a[] and b[] must be of same size.*/

        long a[] = {4, 1, 8, 7};
        long b[] = {2, 3, 6, 5};
        int n = a.length;
        System.out.println(findMinSum(a, b, n));
    }   
}

/*Java program to check if a given array
can form arithmetic progression*/

import java.util.Arrays;

class GFG {

/*    Returns true if a permutation of
    arr[0..n-1] can form arithmetic
    progression*/

    static boolean checkIsAP(int arr[], int n)
    {
        if (n == 1)
            return true;

/*        Sort array*/

        Arrays.sort(arr);

/*        After sorting, difference between
        consecutive elements must be same.*/

        int d = arr[1] - arr[0];
        for (int i = 2; i < n; i++)
            if (arr[i] - arr[i-1] != d)
                return false;

        return true;
    }

/*    driver code*/

    public static void main (String[] args)
    {
        int arr[] = { 20, 15, 5, 0, 10 };
        int n = arr.length;

        if(checkIsAP(arr, n))
            System.out.println("Yes");
        else
            System.out.println("No");
    }
}

/*Java program to find maximum product of
a subset.*/

class GFG {

    static int minProductSubset(int a[], int n)
    {
        if (n == 1)
            return a[0];

/*        Find count of negative numbers,
        count of zeros, maximum valued
        negative number, minimum valued
        positive number and product of
        non-zero numbers*/

        int negmax = Integer.MIN_VALUE;
        int posmin = Integer.MAX_VALUE;
        int count_neg = 0, count_zero = 0;
        int product = 1;

        for (int i = 0; i < n; i++) {

/*            if number is zero,count it
            but dont multiply*/

            if (a[i] == 0) {
                count_zero++;
                continue;
            }

/*            count the negative numbers
            and find the max negative number*/

            if (a[i] < 0) {
                count_neg++;
                negmax = Math.max(negmax, a[i]);
            }

/*            find the minimum positive number*/

            if (a[i] > 0 && a[i] < posmin)
                posmin = a[i];

            product *= a[i];
        }

/*        if there are all zeroes
        or zero is present but no
        negative number is present*/

        if (count_zero == n
            || (count_neg == 0 && count_zero > 0))
            return 0;

/*        If there are all positive*/

        if (count_neg == 0)
            return posmin;

/*        If there are even number except
        zero of negative numbers*/

        if (count_neg % 2 == 0 && count_neg != 0) {

/*            Otherwise result is product of
            all non-zeros divided by maximum
            valued negative.*/

            product = product / negmax;
        }

        return product;
    }

/*    main function*/

    public static void main(String[] args)
    {

        int a[] = { -1, -1, -2, 4, 3 };
        int n = 5;

        System.out.println(minProductSubset(a, n));
    }
}

/*Java Code to find no. of Ways of choosing
a pair with maximum difference*/

import java.util.*;

class GFG {

    static int countPairs(int a[], int n)
    {

/*        To find minimum and maximum of
        the array*/

        int mn = Integer.MAX_VALUE;
        int mx = Integer.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            mn = Math.min(mn, a[i]);
            mx = Math.max(mx, a[i]);
        }

/*        to find the count of minimum and
        maximum elements*/

        int c1 = 0;

/*Count variables*/

int c2 = 0; 
        for (int i = 0; i < n; i++) {
            if (a[i] == mn)
                c1++;
            if (a[i] == mx)
                c2++;
        }

/*        condition for all elements equal*/

        if (mn == mx)
            return n * (n - 1) / 2;
        else
            return c1 * c2;
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int a[] = { 3, 2, 1, 1, 3 };
        int n = a.length;
        System.out.print(countPairs(a, n));
    }
}

/*Java program to rotate
a linked list counter clock wise*/

import java.util.*;

class GFG{

/* Link list node */

static class Node {

    int data;
    Node next;
};
static  Node head = null;

/*This function rotates a linked list
counter-clockwise and updates the
head. The function assumes that k is
smaller than size of linked list.*/

static void rotate( int k)
{
    if (k == 0)
        return;

/*    Let us understand the below
    code for example k = 4 and
    list = 10.20.30.40.50.60.*/

    Node current = head;

/*    Traverse till the end.*/

    while (current.next != null)
        current = current.next;

    current.next = head;
    current = head;

/*    traverse the linked list to k-1 position which
    will be last element for rotated array.*/

    for (int i = 0; i < k - 1; i++)
        current = current.next;

/*    update the head_ref and last element pointer to null*/

    head = current.next;
    current.next = null;
}

/* UTILITY FUNCTIONS */

/* Function to push a node */

static void push(int new_data)
{

/* allocate node */

    Node new_node = new Node();

/* put in the data */

    new_node.data = new_data;

/* link the old list off the new node */

    new_node.next = head;

/* move the head to point to the new node */

    head = new_node;
}

/* Function to print linked list */

static void printList(Node node)
{
    while (node != null)
    {
        System.out.print(node.data + " ");
        node = node.next;
    }
}

/* Driver code*/

public static void  main(String[] args)
{

/* Start with the empty list */

/*    create a list 10.20.30.40.50.60*/

    for (int i = 60; i > 0; i -= 10)
        push( i);

    System.out.print("Given linked list \n");
    printList(head);
    rotate( 4);

    System.out.print("\nRotated Linked list \n");
    printList(head);
}
}

/*Java Program to check if a given linked list of strings
form a palindrome*/


import java.util.Scanner;

/*Linked List node*/

class Node
{
    String data;
    Node next;

    Node(String d)
    {
        data = d;
        next = null;
    }
}

class LinkedList_Palindrome
{
    Node head;

/*    A utility function to check if str is palindrome
    or not*/

    boolean isPalidromeUtil(String str)
    {
        int length = str.length();

/*        Match characters from beginning and
        end.*/

        for (int i=0; i<length/2; i++)
            if (str.charAt(i) != str.charAt(length-i-1))
                return false;

        return true;
    }

/*    Returns true if string formed by linked
    list is palindrome*/

    boolean isPalindrome()
    {
        Node node = head;

/*        Append all nodes to form a string*/

        String str = "";
        while (node != null)
        {
            str = str.concat(node.data);
            node = node.next;
        }

/*        Check if the formed string is palindrome*/

        return isPalidromeUtil(str);
    }

/* Driver program to test above function*/

    public static void main(String[] args)
    {
        LinkedList_Palindrome list = new LinkedList_Palindrome();
        list.head = new Node("a");
        list.head.next = new Node("bc");
        list.head.next.next = new Node("d");
        list.head.next.next.next = new Node("dcb");
        list.head.next.next.next.next = new Node("a");

        System.out.println(list.isPalindrome());

    }
}

/*Java program to merge k sorted
arrays of size n each*/

import java.io.*;

/*A Linked List node*/

class Node
{
  int data;
  Node next;

/*  Utility function to create a new node.*/

  Node(int key)
  {
    data = key;
    next = null;
  }
}
class GFG {

  static Node head;
  static Node temp;

/* Function to print nodes in
   a given linked list */

  static void printList(Node node)
  {
    while(node != null)
    {
      System.out.print(node.data + " ");

      node = node.next;
    }
    System.out.println();
  }

/*  The main function that
  takes an array of lists
  arr[0..last] and generates
  the sorted output*/

  static Node mergeKLists(Node arr[], int last)
  {

/*    Traverse form second list to last*/

    for (int i = 1; i <= last; i++)
    {
      while(true)
      {

/*        head of both the lists,
        0 and ith list. */

        Node head_0 = arr[0];
        Node head_i = arr[i];

/*        Break if list ended*/

        if (head_i == null)
          break;

/*        Smaller than first element*/

        if(head_0.data >= head_i.data)
        {
          arr[i] = head_i.next;
          head_i.next = head_0;
          arr[0] = head_i;
        }
        else
        {

/*          Traverse the first list*/

          while (head_0.next != null)
          {

/*            Smaller than next element*/

            if (head_0.next.data >= head_i.data)
            {
              arr[i] = head_i.next;
              head_i.next = head_0.next;
              head_0.next = head_i;
              break;
            }

/*            go to next node*/

            head_0 = head_0.next;

/*            if last node*/

            if (head_0.next == null)
            {
              arr[i] = head_i.next;
              head_i.next = null;
              head_0.next = head_i;
              head_0.next.next = null;
              break;
            }
          }
        }
      }
    }
    return arr[0];
  }

/*  Driver program to test
  above functions */

  public static void main (String[] args)
  {

/*    Number of linked lists*/

    int k = 3;

/*    Number of elements in each list*/

    int n = 4;

/*    an array of pointers storing the
    head nodes of the linked lists*/


    Node[] arr = new Node[k];

    arr[0] = new Node(1);
    arr[0].next = new Node(3);
    arr[0].next.next = new Node(5);
    arr[0].next.next.next = new Node(7);

    arr[1] = new Node(2);
    arr[1].next = new Node(4);
    arr[1].next.next = new Node(6);
    arr[1].next.next.next = new Node(8);

    arr[2] = new Node(0);
    arr[2].next = new Node(9);
    arr[2].next.next = new Node(10);
    arr[2].next.next.next = new Node(11);

/*    Merge all lists*/

    head = mergeKLists(arr, k - 1);
    printList(head);

  }
}

/*Java implementation to
insert a node after the
nth node from the end*/

class GfG
{

/*structure of a node*/

static class Node
{
    int data;
    Node next;
}

/*function to get a new node*/

static Node getNode(int data)
{

/*    allocate memory for the node*/

    Node newNode = new Node();

/*    put in the data*/

    newNode.data = data;
    newNode.next = null;
    return newNode;
}

/*function to insert a node after
the nth node from the end*/

static void insertAfterNthNode(Node head,
                            int n, int x)
{

/*    if list is empty*/

    if (head == null)
        return;

/*    get a new node for the value 'x'*/

    Node newNode = getNode(x);

/*    Initializing the slow
    and fast pointers*/

    Node slow_ptr = head;
    Node fast_ptr = head;

/*    move 'fast_ptr' to point to the
    nth node from the beginning*/

    for (int i = 1; i <= n - 1; i++)
        fast_ptr = fast_ptr.next;

/*    iterate until 'fast_ptr' points 
    to the last node*/

    while (fast_ptr.next != null)
    {

/*        move both the pointers to the
        respective next nodes*/

        slow_ptr = slow_ptr.next;
        fast_ptr = fast_ptr.next;
    }

/*    insert the 'newNode' by making the
    necessary adjustment in the links*/

    newNode.next = slow_ptr.next;
    slow_ptr.next = newNode;
}

/*function to print the list*/

static void printList(Node head)
{
    while (head != null)
    {
        System.out.print(head.data + " ");
        head = head.next;
    }
}

/*Driver code*/

public static void main(String[] args)
{

/*    Creating list 1->3->4->5*/

    Node head = getNode(1);
    head.next = getNode(3);
    head.next.next = getNode(4);
    head.next.next.next = getNode(5);

    int n = 4, x = 2;
    System.out.println("Original Linked List: ");
    printList(head);

    insertAfterNthNode(head, n, x);
    System.out.println();
    System.out.println("Linked List After Insertion: ");
    printList(head);
}
}

/*Java program to rotate a linked list block wise*/

import java.util.*;
class GFG
{

/* Link list node */

static class Node
{
    int data;
    Node next;
};
static Node tail;

/*Recursive function to rotate one block*/

static Node rotateHelper(Node blockHead,
                        Node blockTail,
                        int d,
                        int k)
{
    if (d == 0)
        return blockHead;

/*    Rotate Clockwise*/

    if (d > 0)
    {
        Node temp = blockHead;
        for (int i = 1; temp.next.next!=null &&
                        i < k - 1; i++)
            temp = temp.next;
        blockTail.next = blockHead;
        tail = temp;
        return rotateHelper(blockTail, temp,
                            d - 1,  k);
    }

/*    Rotate anti-Clockwise*/

    if (d < 0)
    {
        blockTail.next = blockHead;
        tail = blockHead;
        return rotateHelper(blockHead.next,
                blockHead, d + 1,  k);
    }
    return blockHead;
}

/*Function to rotate the linked list block wise*/

static Node rotateByBlocks(Node head,
                                int k, int d)
{

/*    If length is 0 or 1 return head*/

    if (head == null || head.next == null)
        return head;

/*    if degree of rotation is 0, return head*/

    if (d == 0)
        return head;

    Node temp = head;
    tail = null;

/*    Traverse upto last element of this block*/

    int i;
    for (i = 1; temp.next != null && i < k; i++)
        temp = temp.next;

/*    storing the first node of next block*/

    Node nextBlock = temp.next;

/*    If nodes of this block are less than k.
    Rotate this block also*/

    if (i < k)
        head = rotateHelper(head, temp, d % k,
                                   i);
    else
        head = rotateHelper(head, temp, d % k,
                                    k);

/*    Append the new head of next block to
    the tail of this block*/

    tail.next = rotateByBlocks(nextBlock, k,
                                    d % k);

/*    return head of updated Linked List*/

    return head;
}

/* UTILITY FUNCTIONS */

/* Function to push a node */

static Node push(Node head_ref, int new_data)
{
    Node new_node = new Node();
    new_node.data = new_data;
    new_node.next = head_ref;
    head_ref = new_node;
    return head_ref;

}

/* Function to print linked list */

static void printList(Node node)
{
    while (node != null)
    {
        System.out.print(node.data + " ");
        node = node.next;
    }
}

/* Driver code*/

public static void main(String[] args)
{

/* Start with the empty list */

    Node head = null;

/*    create a list 1.2.3.4.5.
    6.7.8.9.null*/

    for (int i = 9; i > 0; i -= 1)
        head = push(head, i);
    System.out.print("Given linked list \n");
    printList(head);

/*    k is block size and d is number of
    rotations in every block.*/

    int k = 3, d = 2;
    head = rotateByBlocks(head, k, d);
    System.out.print("\nRotated by blocks Linked list \n");
    printList(head);
}
}

/*Java program to print corner node at each level in a binary tree*/


import java.util.*;

/* A binary tree node has key, pointer to left
   child and a pointer to right child */

class Node 
{
    int key;
    Node left, right;

    public Node(int key) 
    {
        this.key = key;
        left = right = null;
    }
}

class BinaryTree 
{
    Node root;

/* Function to print corner node at each level */

    void printCorner(Node root)
    {

/*          star node is for keeping track of levels*/

        Queue<Node> q = new LinkedList<Node>();

/*        pushing root node and star node*/

        q.add(root);

/*        Do level order traversal of Binary Tree*/

        while (!q.isEmpty()) 
        {

/*            n is the no of nodes in current Level*/

            int n = q.size();
            for(int i = 0 ; i < n ; i++){
            Node temp = q.peek();
            q.poll();

/*            If it is leftmost corner value or rightmost corner value then print it*/

            if(i==0 || i==n-1)
                System.out.print(temp.key + "  ");

/*            push the left and right children of the temp node*/

            if (temp.left != null) 
                q.add(temp.left); 
            if (temp.right != null) 
                q.add(temp.right); 
        }
        }

    }

/*    Driver program to test above functions*/

    public static void main(String[] args) 
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(15);
        tree.root.left = new Node(10);
        tree.root.right = new Node(20);
        tree.root.left.left = new Node(8);
        tree.root.left.right = new Node(12);
        tree.root.right.left = new Node(16);
        tree.root.right.right = new Node(25);

        tree.printCorner(tree.root);
    }
}

/*Java Program to print binary tree in 2D*/

class GFG
{

static final int COUNT = 10;

/*A binary tree node*/

static class Node
{
    int data;
    Node left, right;

/* Constructor that allocates a new node with the
    given data and null left and right pointers. */

    Node(int data)
    {
        this.data = data;
        this.left = null;
        this.right = null;
    }
};

/*Function to print binary tree in 2D
It does reverse inorder traversal*/

static void print2DUtil(Node root, int space)
{

/*    Base case*/

    if (root == null)
        return;

/*    Increase distance between levels*/

    space += COUNT;

/*    Process right child first*/

    print2DUtil(root.right, space);

/*    Print current node after space
    count*/

    System.out.print("\n");
    for (int i = COUNT; i < space; i++)
        System.out.print(" ");
    System.out.print(root.data + "\n");

/*    Process left child*/

    print2DUtil(root.left, space);
}

/*Wrapper over print2DUtil()*/

static void print2D(Node root)
{

/*    Pass initial space count as 0*/

    print2DUtil(root, 0);
}

/*Driver code*/

public static void main(String args[])
{
    Node root = new Node(1);
    root.left = new Node(2);
    root.right = new Node(3);

    root.left.left = new Node(4);
    root.left.right = new Node(5);
    root.right.left = new Node(6);
    root.right.right = new Node(7);

    root.left.left.left = new Node(8);
    root.left.left.right = new Node(9);
    root.left.right.left = new Node(10);
    root.left.right.right = new Node(11);
    root.right.left.left = new Node(12);
    root.right.left.right = new Node(13);
    root.right.right.left = new Node(14);
    root.right.right.right = new Node(15);

    print2D(root);
}
}

/*Java program to print left view of Binary
Tree*/

import java.util.*;

public class PrintRightView {

/*    Binary tree node*/

    private static class Node {
        int data;
        Node left, right;

        public Node(int data)
        {
            this.data = data;
            this.left = null;
            this.right = null;
        }
    }

/*    function to print left view of binary tree*/

    private static void printLeftView(Node root)
    {
        if (root == null)
            return;

        Queue<Node> queue = new LinkedList<>();
        queue.add(root);

        while (!queue.isEmpty()) {

/*            number of nodes at current level*/

            int n = queue.size();

/*            Traverse all nodes of current level*/

            for (int i = 1; i <= n; i++) {
                Node temp = queue.poll();

/*                Print the left most element at
                the level*/

                if (i == 1)
                    System.out.print(temp.data + " ");

/*                Add left node to queue*/

                if (temp.left != null)
                    queue.add(temp.left);

/*                Add right node to queue*/

                if (temp.right != null)
                    queue.add(temp.right);
            }
        }
    }

/*    Driver code*/

    public static void main(String[] args)
    {

/*        construct binary tree as shown in
        above diagram*/

        Node root = new Node(10);
        root.left = new Node(2);
        root.right = new Node(3);
        root.left.left = new Node(7);
        root.left.right = new Node(8);
        root.right.right = new Node(15);
        root.right.left = new Node(12);
        root.right.right.left = new Node(14);

        printLeftView(root);
    }
}

/*Java program for the above approach*/

import java.io.*;
import java.lang.*;
import java.util.*;

public class GFG {

/*    Function to print the matrix*/

    static void print(int mat[][])
    {

/*        Iterate over the rows*/

        for (int i = 0; i < mat.length; i++) {

/*            Iterate over the columns*/

            for (int j = 0; j < mat[0].length; j++)

/*                Print the value*/

                System.out.print(mat[i][j] + " ");

            System.out.println();
        }
    }

/*    Function to perform the swapping of
    matrix elements in clockwise manner*/

    static void performSwap(int mat[][], int i, int j)
    {
        int N = mat.length;

/*        Stores the last row*/

        int ei = N - 1 - i;

/*        Stores the last column*/

        int ej = N - 1 - j;

/*        Perform the swaps*/

        int temp = mat[i][j];
        mat[i][j] = mat[ej][i];
        mat[ej][i] = mat[ei][ej];
        mat[ei][ej] = mat[j][ei];
        mat[j][ei] = temp;
    }

/*    Function to rotate non - diagonal
    elements of the matrix K times in
    clockwise direction*/

    static void rotate(int mat[][], int N, int K)
    {

/*        Update K to K % 4*/

        K = K % 4;

/*        Iterate until K is positive*/

        while (K-- > 0) {

/*            Iterate each up to N/2-th row*/

            for (int i = 0; i < N / 2; i++) {

/*                Iterate each column
                from i to N - i - 1*/

                for (int j = i; j < N - i - 1; j++) {

/*                    Check if the element
                    at i, j is not a
                    diagonal element*/

                    if (i != j && (i + j) != N - 1) {

/*                        Perform the swapping*/

                        performSwap(mat, i, j);
                    }
                }
            }
        }

/*        Print the matrix*/

        print(mat);
    }

/*    Driver Code*/

    public static void main(String[] args)
    {

        int K = 5;
        int mat[][] = {
            { 1, 2, 3, 4 },
            { 6, 7, 8, 9 },
            { 11, 12, 13, 14 },
            { 16, 17, 18, 19 },
        };

        int N = mat.length;
        rotate(mat, N, K);
    }
}

/*Java program for the above approach*/

import java.util.*;

class GFG{

/*Function to find the maximum sum of
consecutive 0s present at the start
and end of a string present in any
of the rotations of the given string*/

static void findMaximumZeros(String str, int n)
{

/*    Check if all the characters
    in the string are 0*/

    int c0 = 0;

/*    Iterate over characters
    of the string*/

    for(int i = 0; i < n; ++i)
    {
        if (str.charAt(i) == '0')
            c0++;
    }

/*    If the frequency of '1' is 0*/

    if (c0 == n)
    {

/*        Print n as the result*/

        System.out.print(n);
        return;
    }

/*    Concatenate the string
    with itself*/

    String s = str + str;

/*    Stores the required result*/

    int mx = 0;

/*    Generate all rotations of the string*/

    for(int i = 0; i < n; ++i)
    {

/*        Store the number of consecutive 0s
        at the start and end of the string*/

        int cs = 0;
        int ce = 0;

/*        Count 0s present at the start*/

        for(int j = i; j < i + n; ++j)
        {
            if (s.charAt(j) == '0')
                cs++;
            else
                break;
        }

/*        Count 0s present at the end*/

        for(int j = i + n - 1; j >= i; --j)
        {
            if (s.charAt(j) == '0')
                ce++;
            else
                break;
        }

/*        Calculate the sum*/

        int val = cs + ce;

/*        Update the overall
        maximum sum*/

        mx = Math.max(val, mx);
    }

/*    Print the result*/

    System.out.print(mx);
}

/*Driver Code*/

public static void main(String[] args)
{

/*    Given string*/

    String s = "1001";

/*    Store the size of the string*/

    int n = s.length();

    findMaximumZeros(s, n);
}
}

/*Java program for the above approach*/

import java.util.*;

class GFG{

/*Function to find the maximum sum of
consecutive 0s present at the start
and end of any rotation of the string str*/

static void findMaximumZeros(String str, int n)
{

/*    Stores the count of 0s*/

    int c0 = 0;
    for(int i = 0; i < n; ++i)
    {
        if (str.charAt(i) == '0')
            c0++;
    }

/*    If the frequency of '1' is 0*/

    if (c0 == n)
    {

/*        Print n as the result*/

        System.out.print(n);
        return;
    }

/*    Stores the required sum*/

    int mx = 0;

/*    Find the maximum consecutive
    length of 0s present in the string*/

    int cnt = 0;

    for(int i = 0; i < n; i++)
    {
        if (str.charAt(i) == '0')
            cnt++;
        else
        {
            mx = Math.max(mx, cnt);
            cnt = 0;
        }
    }

/*    Update the overall maximum sum*/

    mx = Math.max(mx, cnt);

/*    Find the number of 0s present at
    the start and end of the string*/

    int start = 0, end = n - 1;
    cnt = 0;

/*    Update the count of 0s at the start*/

    while (str.charAt(start) != '1' && start < n)
    {
        cnt++;
        start++;
    }

/*    Update the count of 0s at the end*/

    while (str.charAt(end) != '1' && end >= 0)
    {
        cnt++;
        end--;
    }

/*    Update the maximum sum*/

    mx = Math.max(mx, cnt);

/*    Print the result*/

    System.out.println(mx);
}

/*Driver Code*/

public static void main (String[] args)
{

/*    Given string*/

    String s = "1001";

/*    Store the size of the string*/

    int n = s.length();

    findMaximumZeros(s, n);
}
}

