import java.util.*;
class GFG
{

/*Function to find the maximum value
possible by rotations of digits of N*/

static void findLargestRotation(int num)
{

/*    Store the required result*/

    int ans = num;

/*    Store the number of digits*/

    int len = (int)Math.floor(((int)Math.log10(num)) + 1);
    int x = (int)Math.pow(10, len - 1);

/*    Iterate over the range[1, len-1]*/

    for (int i = 1; i < len; i++) {

/*        Store the unit's digit*/

        int lastDigit = num % 10;

/*        Store the remaining number*/

        num = num / 10;

/*        Find the next rotation*/

        num += (lastDigit * x);

/*        If the current rotation is
        greater than the overall
        answer, then update answer*/

        if (num > ans) {
            ans = num;
        }
    }

/*    Print the result*/

    System.out.print(ans);
}

/*Driver Code*/

public static void main(String[] args)
{
    int N = 657;
    findLargestRotation(N);
}
}

/*Java program for the above approach*/

import java.util.*;

class GFG{

/*Function to count minimum anti-
clockwise rotations required to
sort the array in non-increasing order*/

static void minMovesToSort(int arr[], int N)
{

/*    Stores count of arr[i + 1] > arr[i]*/

    int count = 0;

/*    Store last index of arr[i+1] > arr[i]*/

    int index = 0;

/*    Traverse the given array*/

    for(int i = 0; i < N - 1; i++)
    {

/*        If the adjacent elements are
        in increasing order*/

        if (arr[i] < arr[i + 1])
        {

/*            Increment count*/

            count++;

/*            Update index*/

            index = i;
        }
    }

/*    Print the result according
    to the following conditions*/

    if (count == 0)
    {
        System.out.print("0");
    }
    else if (count == N - 1)
    {
        System.out.print(N - 1);
    }
    else if (count == 1 &&
            arr[0] <= arr[N - 1])
    {
        System.out.print(index + 1);
    }

/*    Otherwise, it is not
    possible to sort the array*/

    else
    {
        System.out.print("-1");
    }
}

/*Driver Code*/

public static void main(String[] args)
{

/*    Given array*/

    int[] arr = { 2, 1, 5, 4, 2 };
    int N = arr.length;

/*    Function Call*/

    minMovesToSort(arr, N);
}
}

/*Java program to implement
