/*Java program to find Bitwise OR of two
equal halves of an array after performing
K right circular shifts*/

import java.util.*;

class GFG{

static int MAX = 100005;

/*Array for storing
the segment tree*/

static int []seg = new int[4 * MAX];

/*Function to build the segment tree*/

static void build(int node, int l,
                  int r, int a[])
{
    if (l == r)
        seg[node] = a[l];

    else
    {
        int mid = (l + r) / 2;

        build(2 * node, l, mid, a);
        build(2 * node + 1, mid + 1, r, a);

        seg[node] = (seg[2 * node] |
                     seg[2 * node + 1]);
    }
}

/*Function to return the OR
of elements in the range [l, r]*/

static int query(int node, int l, int r,
                 int start, int end, int a[])
{

/*    Check for out of bound condition*/

    if (l > end || r < start)
        return 0;

    if (start <= l && r <= end)
        return seg[node];

/*    Find middle of the range*/

    int mid = (l + r) / 2;

/*    Recurse for all the elements in array*/

    return ((query(2 * node, l, mid,
                   start, end, a)) |
            (query(2 * node + 1, mid + 1,
                   r, start, end, a)));
}

/*Function to find the OR sum*/

static void orsum(int a[], int n,
                  int q, int k[])
{

/*    Function to build the segment Tree*/

    build(1, 0, n - 1, a);

/*    Loop to handle q queries*/

    for(int j = 0; j < q; j++)
    {

/*        Effective number of
        right circular shifts*/

        int i = k[j] % (n / 2);

/*        Calculating the OR of
        the two halves of the
        array from the segment tree*/

/*        OR of second half of the
        array [n/2-i, n-1-i]*/

        int sec = query(1, 0, n - 1,
                        n / 2 - i,
                        n - i - 1, a);

/*        OR of first half of the array
        [n-i, n-1]OR[0, n/2-1-i]*/

        int first = (query(1, 0, n - 1, 0,
                           n / 2 - 1 - i, a) |
                     query(1, 0, n - 1,
                           n - i, n - 1, a));

        int temp = sec + first;

/*        Print final answer to the query*/

        System.out.print(temp + "\n");
    }
}

/*Driver Code*/

public static void main(String[] args)
{

    int a[] = { 7, 44, 19, 86, 65, 39, 75, 101 };
    int n = a.length;
    int q = 2;

    int k[] = { 4, 2 };

    orsum(a, n, q, k);
}
}

/*Java program of the above approach*/

import java.util.*;
class GFG{

/*Function that prints maximum
equal elements*/

static void maximumEqual(int a[],
                         int b[], int n)
{

/*    Vector to store the index
    of elements of array b*/

    int store[] = new int[(int) 1e5];

/*    Storing the positions of
    array B*/

    for (int i = 0; i < n; i++)
    {
        store[b[i]] = i + 1;
    }

/*    frequency array to keep count
    of elements with similar
    difference in distances*/

    int ans[] = new int[(int) 1e5];

/*    Iterate through all element in arr1[]*/

    for (int i = 0; i < n; i++)
    {

/*        Calculate number of
        shift required to
        make current element
        equal*/

        int d = Math.abs(store[a[i]] - (i + 1));

/*        If d is less than 0*/

        if (store[a[i]] < i + 1)
        {
            d = n - d;
        }

/*        Store the frequency
        of current diff*/

        ans[d]++;
    }

    int finalans = 0;

/*    Compute the maximum frequency
    stored*/

    for (int i = 0; i < 1e5; i++)
        finalans = Math.max(finalans,
                            ans[i]);

/*    Printing the maximum number
    of equal elements*/

    System.out.print(finalans + "\n");
}

/*Driver Code*/

public static void main(String[] args)
{

/*    Given two arrays*/

    int A[] = { 6, 7, 3, 9, 5 };
    int B[] = { 7, 3, 9, 5, 6 };

    int size = A.length;

/*    Function Call*/

    maximumEqual(A, B, size);
}
}

/*Java Program to count the minimum
number of circular rotations required
to obtain a given numeric Strings
avoiding a set of blocked Strings*/

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.Queue;

class GFG
{
  static int minCircularRotations(String target,
                                  ArrayList<String> blocked,
                                  int N)
  {
    String start = "";
    for (int i = 0; i < N; i++)
    {
      start += '0';
    }

    HashSet<String> avoid = new HashSet<>();
    for (int i = 0; i < blocked.size(); i++)
      avoid.add(blocked.get(i));

/*to be avoided
If the starting String needs */

    if (avoid.contains(start))
      return -1;

/*to be avoided
If the final String needs */

    if (avoid.contains(target))
      return -1;
    Queue<String> qu = new LinkedList<>();
    qu.add(start);

/*    Variable to store count of rotations*/

    int count = 0;

/*    BFS Approach*/

    while (!qu.isEmpty())
    {
      count++;

/*of the queue
Store the current size */

      int size = qu.size();
      for (int j = 0; j < size; j++)
      {
        StringBuilder st = new StringBuilder(qu.poll());

/*        Traverse the String*/

        for (int i = 0; i < N; i++)
        {
          char ch = st.charAt(i);

/*current character
Increase the */

          st.setCharAt(i, (char) (st.charAt(i) + 1));

/*          Circular rotation*/

          if (st.charAt(i) > '9')
            st.setCharAt(i, '0');

/*          If target is reached*/

          if (st.toString().equals(target))
            return count;

/*          If the String formed
          is not one to be avoided*/

          if (!avoid.contains(st.toString()))
            qu.add(st.toString());

/*          Add it to the list of
          Strings to be avoided
          to prevent visiting
          already visited states*/

          avoid.add(st.toString());

/*          Decrease the current
          value by 1 and repeat
          the similar checkings*/

          st.setCharAt(i, (char) (ch - 1));
          if (st.charAt(i) < '0')
            st.setCharAt(i, '9');
          if (st.toString().equals(target))
            return count;
          if (!avoid.contains(st.toString()))
            qu.add(st.toString());
          avoid.add(st.toString());

/*          Restore the original
          character*/

          st.setCharAt(i, ch);
        }
      }
    }
    return -1;
  }

/*  Driver code*/

  public static void main(String[] args)
  {
    int N = 4;
    String target = "7531";
    ArrayList<String> blocked =
      new ArrayList<>(Arrays.asList("1543",
