/*Java implementation of the approach*/

class GFG
{

/*Function that returns true if the array
can be made increasing or decreasing
after rotating it in any direction*/

static boolean isPossible(int a[], int n)
{

/*    If size of the array is less than 3*/

    if (n <= 2)
        return true;

    int flag = 0;

/*    Check if the array is already decreasing*/

    for (int i = 0; i < n - 2; i++)
    {
        if (!(a[i] > a[i + 1] &&
              a[i + 1] > a[i + 2]))
        {
            flag = 1;
            break;
        }
    }

/*    If the array is already decreasing*/

    if (flag == 0)
        return true;

    flag = 0;

/*    Check if the array is already increasing*/

    for (int i = 0; i < n - 2; i++)
    {
        if (!(a[i] < a[i + 1] &&
              a[i + 1] < a[i + 2]))
        {
            flag = 1;
            break;
        }
    }

/*    If the array is already increasing*/

    if (flag == 0)
        return true;

/*    Find the indices of the minimum
    && the maximum value*/

    int val1 = Integer.MAX_VALUE, mini = -1,
        val2 = Integer.MIN_VALUE, maxi = 0;
    for (int i = 0; i < n; i++)
    {
        if (a[i] < val1)
        {
            mini = i;
            val1 = a[i];
        }
        if (a[i] > val2)
        {
            maxi = i;
            val2 = a[i];
        }
    }

    flag = 1;

/*    Check if we can make array increasing*/

    for (int i = 0; i < maxi; i++)
    {
        if (a[i] > a[i + 1])
        {
            flag = 0;
            break;
        }
    }

/*    If the array is increasing upto max index
    && minimum element is right to maximum*/

    if (flag == 1 && maxi + 1 == mini)
    {
        flag = 1;

/*        Check if array increasing again or not*/

        for (int i = mini; i < n - 1; i++)
        {
            if (a[i] > a[i + 1])
            {
                flag = 0;
                break;
            }
        }
        if (flag == 1)
            return true;
    }

    flag = 1;

/*    Check if we can make array decreasing*/

    for (int i = 0; i < mini; i++)
    {
        if (a[i] < a[i + 1])
        {
            flag = 0;
            break;
        }
    }

/*    If the array is decreasing upto min index
    && minimum element is left to maximum*/

    if (flag == 1 && maxi - 1 == mini)
    {
        flag = 1;

/*        Check if array decreasing again or not*/

        for (int i = maxi; i < n - 1; i++)
        {
            if (a[i] < a[i + 1])
            {
                flag = 0;
                break;
            }
        }
        if (flag == 1)
            return true;
    }

/*    If it is not possible to make the
    array increasing or decreasing*/

    return false;
}

/*Driver code*/

public static void main(String args[])
{
    int a[] = { 4, 5, 6, 2, 3 };
    int n = a.length;

    if (isPossible(a, n))
        System.out.println( "Yes");
    else
        System.out.println( "No");
}
}

/*Java implementation of the approach*/

class GFG
{

/*Function to return the count of rotated
Strings which have more number of vowels in
the first half than the second half*/

static int cntRotations(String s, int n)
{

/*    Create a new String*/

    String str = s + s;

/*    Pre array to store count of all vowels*/

    int pre[]=new int[2 * n] ;

/*    Compute the prefix array*/

    for (int i = 0; i < 2 * n; i++)
    {
        if (i != 0)
            pre[i] += pre[i - 1];

        if (str.charAt(i) == 'a' || str.charAt(i) == 'e' ||
            str.charAt(i) == 'i' || str.charAt(i) == 'o' ||
            str.charAt(i) == 'u')
        {
            pre[i]++;
        }
    }

/*    To store the required answer*/

    int ans = 0;

/*    Find all rotated Strings*/

    for (int i = n - 1; i < 2 * n - 1; i++)
    {

/*        Right and left index of the String*/

        int r = i, l = i - n;

/*        x1 stores the number of vowels
        in the rotated String*/

        int x1 = pre[r];
        if (l >= 0)
            x1 -= pre[l];
        r = i - n / 2;

/*        Left stores the number of vowels
        in the first half of rotated String*/

        int left = pre[r];
        if (l >= 0)
            left -= pre[l];

/*        Right stores the number of vowels
        in the second half of rotated String*/

        int right = x1 - left;

/*        If the count of vowels in the first half
        is greater than the count in the second half*/

        if (left > right)
        {
            ans++;
        }
    }

/*    Return the required answer*/

    return ans;
}

/*Driver code*/

public static void main(String args[])
{
    String s = "abecidft";
    int n = s.length();

    System.out.println( cntRotations(s, n));
}
}

/*Java implementation of the above approach*/

import java.util.*;
class GFG
{
static int size = 2;

/*Function to perform the required
queries on the given string*/

static void performQueries(String str, int n,
                           int queries[][], int q)
{

/*    Pointer pointing to the current
    starting character of the string*/

    int ptr = 0;

/*    For every query*/

    for (int i = 0; i < q; i++)
    {

/*        If the query is to rotate the string*/

        if (queries[i][0] == 1)
        {

/*            Update the pointer pointing to the
            starting character of the string*/

            ptr = (ptr + queries[i][1]) % n;
        }
        else
        {
            int k = queries[i][1];

/*            Index of the kth character in the
            current rotation of the string*/

            int index = (ptr + k - 1) % n;

/*            Print the kth character*/

            System.out.println(str.charAt(index));
        }
    }
}

/*Driver code*/

public static void main(String[] args)
{
    String str = "abcdefgh";
    int n = str.length();

    int queries[][] = { { 1, 2 }, { 2, 2 },
                        { 1, 4 }, { 2, 7 } };
    int q = queries.length;

    performQueries(str, n, queries, q);
}
}

/*Java implementation of the approach*/

class GFG
{

/*Function to return the count of digits of n*/

static int numberOfDigits(int n)
{
    int cnt = 0;
    while (n > 0)
    {
        cnt++;
        n /= 10;
    }
    return cnt;
}

/*Function to print the left shift numbers*/

static void cal(int num)
{
    int digits = numberOfDigits(num);
    int powTen = (int) Math.pow(10, digits - 1);

    for (int i = 0; i < digits - 1; i++)
    {
        int firstDigit = num / powTen;

/*        Formula to calculate left shift
        from previous number*/

        int left = ((num * 10) + firstDigit) -
                    (firstDigit * powTen * 10);

        System.out.print(left + " ");

/*        Update the original number*/

        num = left;
    }
}

/*Driver Code*/

public static void main(String[] args)
{
    int num = 1445;
    cal(num);
}
}

