/*Java program to Generating numbers that 
are divisor of their right-rotations  */


public class GFG {

/*    Function to check if N is a 
    divisor of its right-rotation*/

    static boolean rightRotationDivisor(int N)
    {
        int lastDigit = N % 10;
        int rightRotation = (int)(lastDigit * Math.pow(10 ,(int)(Math.log10(N))) 
                        + Math.floor(N / 10)); 
        return (rightRotation % N == 0);
    }

/*    Function to generate m-digit 
    numbers which are divisor of 
    their right-rotation */

    static void generateNumbers(int m)
    {
        for (int i= (int)Math.pow(10,(m - 1)); i < Math.pow(10 , m);i++) 
            if (rightRotationDivisor(i))
                System.out.println(i);
     }

/*    Driver code*/

    public static void main(String args[])
    {
        int m = 3;
        generateNumbers(m);

    }

}

/*Java program to Generating numbers that
are divisor of their right-rotations*/

import java.util.*;
import java.io.*;

class GFG
{

/*    Function to generate m-digit
    numbers which are divisor of
    their right-rotation*/

    static void generateNumbers(int m)
    {
            ArrayList<Integer> numbers = new ArrayList<>();
            int k_max, x;

            for (int y = 0; y < 10; y++)
            {

                k_max = (int)(Math.pow(10,m-2) * (10 * y + 1)) /
                                (int)(Math.pow(10, m-1) + y);

                for (int k = 1; k <= k_max; k++)
                {
                        x = (int)(y*(Math.pow(10,m-1)-k)) / (10 * k -1);

                        if ((int)(y*(Math.pow(10,m-1)-k)) % (10 * k -1) == 0)
                            numbers.add(10 * x + y);
                }

            }

            Collections.sort(numbers);
            for (int i = 0; i < numbers.size(); i++)
                System.out.println(numbers.get(i));
    }

/*    Driver code*/

    public static void main(String args[])
    {
            int m = 3;
            generateNumbers(m);
    }
}

/*Java program to check if an
array is sorted and rotated
clockwise*/

import java.io.*;

class GFG {

/*    Function to check if an array is
    sorted and rotated clockwise*/

    static void checkIfSortRotated(int arr[], int n)
    {
        int minEle = Integer.MAX_VALUE;
        int maxEle = Integer.MIN_VALUE;

        int minIndex = -1;

/*        Find the minimum element
        and it's index*/

        for (int i = 0; i < n; i++) {
            if (arr[i] < minEle) {
                minEle = arr[i];
                minIndex = i;
            }
        }

        boolean flag1 = true;

/*        Check if all elements before
        minIndex are in increasing order*/

        for (int i = 1; i < minIndex; i++) {
            if (arr[i] < arr[i - 1]) {
                flag1 = false;
                break;
            }
        }

        boolean flag2 = true;

/*        Check if all elements after
        minIndex are in increasing order*/

        for (int i = minIndex + 1; i < n; i++) {
            if (arr[i] < arr[i - 1]) {
                flag2 = false;
                break;
            }
        }

/*        check if the minIndex is 0, i.e the first element
        is the smallest , which is the case when array is
        sorted but not rotated.*/

        if (minIndex == 0) {
            System.out.print("NO");
            return;
        }

/*        Check if last element of the array
        is smaller than the element just
        before the element at minIndex
        starting element of the array
        for arrays like [3,4,6,1,2,5] - not sorted
        circular array*/

        if (flag1 && flag2 && (arr[n - 1] < arr[0]))
            System.out.println("YES");
        else
            System.out.print("NO");
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = { 3, 4, 5, 1, 2 };

        int n = arr.length;

/*        Function Call*/

        checkIfSortRotated(arr, n);
    }
}

import java.io.*;

class GFG {

/*    Function to check if an array is
    Sorted and rotated clockwise*/

    static boolean checkIfSortRotated(int arr[], int n)
    {

/*        Initializing two variables x,y as zero.*/

        int x = 0, y = 0;

/*        Traversing array 0 to last element.
        n-1 is taken as we used i+1.*/

        for (int i = 0; i < n - 1; i++) {
            if (arr[i] < arr[i + 1])
                x++;
            else
                y++;
        }

/*        If till now both x,y are greater
        then 1 means array is not sorted.
        If both any of x,y is zero means
        array is not rotated.*/

        if (x == 1 || y == 1) {

/*            Checking for last element with first.*/

            if (arr[n - 1] < arr[0])
                x++;
            else
                y++;

/*            Checking for final result.*/

            if (x == 1 || y == 1)
                return true;
        }

/*        If still not true then definetly false.*/

        return false;
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = { 5, 1, 2, 3, 4 };

        int n = arr.length;

/*        Function Call*/

        boolean x = checkIfSortRotated(arr, n);
        if (x == true)
            System.out.println("YES");
        else
            System.out.println("NO");
    }
}

